String _getPresidentCardRank(String card) => card.substring(0, card.length - 1);

int _getPresidentCardValue(String card, bool isRevolutionActive) {
  final rank = _getPresidentCardRank(card);
  if (isRevolutionActive) {
    return _presidentCardValuesRevolution[rank]!;
  }
  return _presidentCardValues[rank]!;
}

int _comparePresidentCards(String a, String b, bool isRevolutionActive) =>
    _getPresidentCardValue(
      a,
      isRevolutionActive,
    ).compareTo(_getPresidentCardValue(b, isRevolutionActive));

enum HandRank {
  highCard,
  onePair,
  twoPair,
  threeOfAKind,
  straight,
  flush,
  fullHouse,
  fourOfAKind,
  straightFlush,
  royalFlush,
}

class PokerCard implements Comparable<PokerCard> {
  final String suit;
  final String rank;
  final int value;

  PokerCard(String cardStr)
    : suit = cardStr.substring(1),
      rank = cardStr.substring(0, 1),
      value = _getRankValue(cardStr.substring(0, 1));

  static int _getRankValue(String rank) {
    const rankValues = {'T': 10, 'J': 11, 'Q': 12, 'K': 13, 'A': 14};
    return rankValues[rank] ?? int.tryParse(rank) ?? 0;
  }

  @override
  int compareTo(PokerCard other) => other.value.compareTo(value); // Descending order

  @override
  String toString() => '$rank$suit';
}

class PokerHand implements Comparable<PokerHand> {
  final HandRank rank;
  final List<int> kickerValues; // Values of the 5 cards making the hand

  PokerHand(this.rank, this.kickerValues);

  @override
  int compareTo(PokerHand other) {
    if (rank.index != other.rank.index) {
      return rank.index.compareTo(other.rank.index); // Higher rank wins
    }

    for (int i = 0; i < kickerValues.length; i++) {
      if (kickerValues[i] != other.kickerValues[i]) {
        return kickerValues[i].compareTo(other.kickerValues[i]);
      }
    }
    return 0; // It's a tie
  }

  @override
  String toString() => '${rank.name} with kickers: $kickerValues';
}

class PokerHandEvaluator {
  static PokerHand evaluateHand(List<String> sevenCardsStr) {
    final List<PokerCard> sevenCards =
        sevenCardsStr.map((c) => PokerCard(c)).toList();

    final combinations = _getCombinations(sevenCards, 5);

    PokerHand? bestHand;
    for (final combo in combinations) {
      final hand = _evaluateFiveCards(combo);
      if (bestHand == null || hand.compareTo(bestHand) > 0) {
        bestHand = hand;
      }
    }
    return bestHand!;
  }

  static List<List<T>> _getCombinations<T>(List<T> list, int length) {
    if (length == 0) return [[]];
    if (list.isEmpty) return [];

    final T head = list.first;
    final List<T> tail = list.sublist(1);

    final withoutHead = _getCombinations(tail, length);
    final withHead =
        _getCombinations(
          tail,
          length - 1,
        ).map((combo) => [head, ...combo]).toList();

    return [...withHead, ...withoutHead];
  }

  static PokerHand _evaluateFiveCards(List<PokerCard> fiveCards) {
    fiveCards.sort(); // Tri descendant par valeur (14 -> 2)

    List<int> values = fiveCards.map((c) => c.value).toList();
    final suits = fiveCards.map((c) => c.suit).toList();
    final isFlush = suits.toSet().length == 1;

    // Détection Quinte As-Bas (Wheel: 5-4-3-2-A)
    bool isWheelStraight =
        values.contains(14) &&
        values.contains(2) &&
        values.contains(3) &&
        values.contains(4) &&
        values.contains(5);

    bool isStraight = isWheelStraight || _isStraight(values);

    // Rétablir la bonne hiérarchie de kickers pour la Wheel (5 est la carte haute, As vaut 1)
    if (isWheelStraight) {
      values = [5, 4, 3, 2, 1];
    }

    if (isStraight && isFlush) {
      if (values[0] == 14 && !isWheelStraight) {
        return PokerHand(HandRank.royalFlush, values);
      }
      return PokerHand(HandRank.straightFlush, values);
    }

    final rankCounts = _getRankCounts(values);
    final counts = rankCounts.values.toList()..sort((a, b) => b.compareTo(a));

    if (counts[0] == 4) {
      // Four of a kind
      final fourValue = rankCounts.entries.firstWhere((e) => e.value == 4).key;
      final kicker = values.firstWhere((v) => v != fourValue);
      return PokerHand(HandRank.fourOfAKind, [
        fourValue,
        fourValue,
        fourValue,
        fourValue,
        kicker,
      ]);
    }

    if (counts[0] == 3 && counts[1] == 2) {
      // Full House
      final threeValue = rankCounts.entries.firstWhere((e) => e.value == 3).key;
      final twoValue = rankCounts.entries.firstWhere((e) => e.value == 2).key;
      return PokerHand(HandRank.fullHouse, [
        threeValue,
        threeValue,
        threeValue,
        twoValue,
        twoValue,
      ]);
    }

    if (isFlush) return PokerHand(HandRank.flush, values);
    if (isStraight) return PokerHand(HandRank.straight, values);

    if (counts[0] == 3) {
      // Three of a kind
      final threeValue = rankCounts.entries.firstWhere((e) => e.value == 3).key;
      final kickers = values.where((v) => v != threeValue).toList();
      return PokerHand(HandRank.threeOfAKind, [
        threeValue,
        threeValue,
        threeValue,
        ...kickers,
      ]);
    }

    if (counts[0] == 2 && counts[1] == 2) {
      // Two Pair
      final pairs =
          rankCounts.entries
              .where((e) => e.value == 2)
              .map((e) => e.key)
              .toList()
            ..sort((a, b) => b.compareTo(a));
      final kicker = values.firstWhere((v) => v != pairs[0] && v != pairs[1]);
      return PokerHand(HandRank.twoPair, [
        pairs[0],
        pairs[0],
        pairs[1],
        pairs[1],
        kicker,
      ]);
    }

    if (counts[0] == 2) {
      // One Pair
      final pairValue = rankCounts.entries.firstWhere((e) => e.value == 2).key;
      final kickers = values.where((v) => v != pairValue).toList();
      return PokerHand(HandRank.onePair, [pairValue, pairValue, ...kickers]);
    }

    return PokerHand(HandRank.highCard, values);
  }

  static bool _isStraight(List<int> sortedValues) {
    if (sortedValues.toSet().containsAll({14, 2, 3, 4, 5})) return true;

    for (int i = 0; i < sortedValues.length - 1; i++) {
      if (sortedValues[i] != sortedValues[i + 1] + 1) return false;
    }
    return true;
  }

  static Map<int, int> _getRankCounts(List<int> values) {
    final counts = <int, int>{};
    for (final value in values) {
      counts[value] = (counts[value] ?? 0) + 1;
    }
    return counts;
  }
}

class MultiplayerTeamSelectionDialog extends StatefulWidget {
  final String gameCode;
  final Map<String, dynamic> players;
  final Map<int, List<String>>
  initialTeams; // ModifiÃƒÂ© pour accepter plusieurs ÃƒÂ©quipes
  final String gameName;
  final int minTeams;

  const MultiplayerTeamSelectionDialog({
    Key? key,
    required this.gameCode,
    required this.players,
    required this.initialTeams,
    required this.gameName,
    this.minTeams = 2,
  }) : super(key: key);

  @override
  _MultiplayerTeamSelectionDialogState createState() =>
      _MultiplayerTeamSelectionDialogState();
}

class _MultiplayerTeamSelectionDialogState
    extends State<MultiplayerTeamSelectionDialog> {
  late List<String> unassignedPlayers;
  late Map<int, List<String>> teams;
  final FirebaseService _firebaseService = FirebaseService();

  final List<Color> teamColors = [
    Colors.redAccent,
    Colors.blueAccent,
    Colors.greenAccent,
    Colors.orangeAccent,
    Colors.purpleAccent,
    Colors.cyanAccent,
  ];

  @override
  void initState() {
    super.initState();
    teams = Map<int, List<String>>.from(widget.initialTeams);

    if (teams.isEmpty) {
      for (int i = 0; i < widget.minTeams; i++) {
        teams[i] = [];
      }
    }

    final allAssigned = teams.values.expand((playerList) => playerList).toSet();
    unassignedPlayers =
        widget.players.keys.where((pId) => !allAssigned.contains(pId)).toList();
  }

  void _addTeam() {
    setState(() {
      if (teams.length < 6) {
        // Limite ÃƒÂ  6 ÃƒÂ©quipes pour l'UI
        teams[teams.length] = [];
      }
    });
  }

  void _removeLastTeam() {
    setState(() {
      if (teams.length > widget.minTeams) {
        int lastTeamKey = teams.keys.last;
        List<String>? playersToUnassign = teams[lastTeamKey];
        if (playersToUnassign != null) {
          unassignedPlayers.addAll(playersToUnassign);
        }
        teams.remove(lastTeamKey);
      }
    });
  }

  void _assignPlayer(String playerId, int teamIndex) {
    setState(() {
      unassignedPlayers.remove(playerId);

      for (var team in teams.values) {
        team.remove(playerId);
      }
      teams[teamIndex]?.add(playerId);
    });
  }

  void _unassignPlayer(String playerId, int fromTeamIndex) {
    setState(() {
      teams[fromTeamIndex]?.remove(playerId);
      if (!unassignedPlayers.contains(playerId)) {
        unassignedPlayers.add(playerId);
      }
    });
  }

  void _autoBalance() {
    setState(() {
      List<String> all = widget.players.keys.toList()..shuffle();
      unassignedPlayers.clear();
      teams.forEach(
        (key, value) => value.clear(),
      ); // Vider toutes les ÃƒÂ©quipes
      for (int i = 0; i < all.length; i++) {
        int teamIndex = i % teams.length;
        teams[teamIndex]?.add(all[i]);
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    bool canConfirm = unassignedPlayers.isEmpty;

    return AlertDialog(
      title: Text("Ãƒâ€°quipes pour ${widget.gameName}"),
      content: Container(
        width: double.maxFinite,
        height: 500, // AugmentÃƒÂ© pour l'UI
        child: Column(
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                ElevatedButton.icon(
                  icon: Icon(Icons.sync),
                  label: Text("Ãƒâ€°quilibrer"),
                  onPressed: _autoBalance,
                ),
                ElevatedButton.icon(
                  icon: Icon(Icons.add),
                  label: Text("Ãƒâ€°quipe"),
                  onPressed: _addTeam,
                ),
                if (teams.length > widget.minTeams)
                  ElevatedButton.icon(
                    icon: Icon(Icons.remove),
                    label: Text("Retirer"),
                    onPressed: _removeLastTeam,
                  ),
              ],
            ),
            SizedBox(height: 10),
            Expanded(
              child: SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children:
                      teams.entries.map((entry) {
                        int teamIndex = entry.key;
                        List<String> teamPlayers = entry.value;
                        return _buildTeamColumn(
                          "Ãƒâ€°quipe ${teamIndex + 1}",
                          teamPlayers,
                          teamIndex,
                          teamColors[teamIndex % teamColors.length],
                        );
                      }).toList(),
                ),
              ),
            ),
            Divider(),
            Text("Joueurs non assignÃƒÂ©s (${unassignedPlayers.length})"),
            Expanded(
              flex: 0, // Taille minimale pour le Wrap
              child: SingleChildScrollView(
                child: Wrap(
                  spacing: 6,
                  children:
                      unassignedPlayers
                          .map(
                            (pId) => ActionChip(
                              label: Text(
                                widget.players[pId]?['name'] ?? '...',
                              ),
                              onPressed: () {
                                var smallestTeam = teams.entries.reduce(
                                  (a, b) =>
                                      a.value.length < b.value.length ? a : b,
                                );
                                _assignPlayer(pId, smallestTeam.key);
                              },
                            ),
                          )
                          .toList(),
                ),
              ),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(),
          child: Text("Annuler"),
        ),
        ElevatedButton(
          onPressed:
              canConfirm
                  ? () {
                    _firebaseService.updateTeams(widget.gameCode, teams);
                    Navigator.of(context).pop();
                  }
                  : null,
          child: Text("Confirmer les ÃƒÂ©quipes"),
        ),
      ],
    );
  }

  Widget _buildTeamColumn(
    String title,
    List<String> team,
    int teamIndex,
    Color color,
  ) {
    return Container(
      width: 200, // Largeur fixe pour chaque colonne
      margin: EdgeInsets.all(4),
      decoration: BoxDecoration(
        border: Border.all(color: color.withOpacity(0.5)),
        borderRadius: BorderRadius.circular(8),
      ),
      child: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Text(
              title,
              style: TextStyle(color: color, fontWeight: FontWeight.bold),
            ),
          ),
          Expanded(
            child: ListView(
              children:
                  team
                      .map(
                        (pId) => ListTile(
                          title: Text(
                            widget.players[pId]?['name'] ?? '...',
                            overflow: TextOverflow.ellipsis,
                          ),
                          trailing: IconButton(
                            icon: Icon(Icons.undo, size: 18),
                            onPressed: () => _unassignPlayer(pId, teamIndex),
                          ),
                        ),
                      )
                      .toList(),
            ),
          ),
        ],
      ),
    );
  }
}

// Modèle pour une entrée d'historique IA
class AiThemeHistoryItem {
  final String id;
  String title;
  String prompt;
  String gameType;
  List<String> words;
  final DateTime createdAt;

  AiThemeHistoryItem({
    required this.id,
    required this.title,
    required this.prompt,
    required this.gameType,
    required this.words,
    required this.createdAt,
  });

  Map<String, dynamic> toMap() => {
    'title': title,
    'prompt': prompt,
    'gameType': gameType,
    'words': words,
    'createdAt': Timestamp.fromDate(createdAt),
  };

  factory AiThemeHistoryItem.fromDoc(DocumentSnapshot doc) {
    final data = doc.data() as Map<String, dynamic>? ?? {};
    return AiThemeHistoryItem(
      id: doc.id,
      title: data['title'] ?? 'Thème IA',
      prompt: data['prompt'] ?? '',
      gameType: data['gameType'] ?? '',
      words: List<String>.from(data['words'] ?? []),
      createdAt: (data['createdAt'] as Timestamp?)?.toDate() ?? DateTime.now(),
    );
  }
}

class FirebaseService {
  final FirebaseFirestore _db = FirebaseFirestore.instance;

  /// Retourne le nombre idéal d'éléments générés selon le jeu
  static int getAiWordCountForGame(String gameType) {
    switch (gameType) {
      case 'Codenames':
        return 35; // 25 requis pour la grille + réserve
      case 'Time\'s Up':
      case 'Pictionary':
      case 'Devine Tête':
        return 40;
      case 'Just One':
        return 20; // 13 cartes pour une partie complète + réserve
      case 'Infiltré & Mr. White':
        return 20; // 20 paires "MotCivil:MotInfiltré"
      case 'Taboo':
        return 25; // 25 cartes "MotCible:Interdit1,Interdit2,Interdit3,Interdit4,Interdit5"
      case 'Petit Bac':
      case 'La Patate Chaude':
      case 'Le Jeu des Catégories':
        return 20; // 20 catégories thématiques
      case 'Gribouillis':
        return 15; // 15 phrases de départ amusantes à dessiner
      case 'Cadavre Exquis':
        return 15; // 15 débuts de récits / univers inspirants
      case 'Le Dilemme':
        return 20; // 20 dilemmes au format "OptionA ou OptionB"
      case 'Action ou Vérité':
      case 'Jeu de la Pièce':
      case 'On se passe un objet rapidement':
      case 'Blanc Manger Coco':
      case 'Le Juge':
      case 'Le Menteur':
      case 'Qui Pourrait le Plus ?':
      case 'Synonyme ou Banni':
      case 'Le Roi des Mèmes':
        return 25;
      default:
        return 30;
    }
  }

  /// Instructions système personnalisées envoyées à la Cloud Function selon le jeu
  static String formatAiPromptForGame(String gameType, String userPrompt) {
    switch (gameType) {
      case 'Infiltré & Mr. White':
        return "Génère des paires de mots proches au format 'MotCivil:MotInfiltré'. Thème : $userPrompt";
      case 'Taboo':
        return "Génère des cartes Taboo au format 'MotCible:Interdit1,Interdit2,Interdit3,Interdit4,Interdit5'. Thème : $userPrompt";
      case 'Petit Bac':
      case 'La Patate Chaude':
      case 'Le Jeu des Catégories':
        return "Génère des catégories originales et amusantes à faire deviner. Thème : $userPrompt";
      case 'Gribouillis':
        return "Génère des phrases courtes, visuelles et loufoques à faire dessiner (ex: 'Un dinosaure qui mange une glace'). Thème : $userPrompt";
      case 'Cadavre Exquis':
        return "Génère des phrases d'accroche ou univers d'écriture originaux. Thème : $userPrompt";
      case 'Le Dilemme':
        return "Génère des dilemmes cornéliens au format 'OptionA ou OptionB' (ex: 'Pouvoir voler ou Être invisible'). Thème : $userPrompt";
      case 'Action ou Vérité':
        return "Génère un mélange de défis (actions) et questions indiscrètes (vérités). Thème : $userPrompt";
      case 'Jeu de la Pièce':
      case 'On se passe un objet rapidement':
        return "Génère des questions directes, amusantes et piquantes. Thème : $userPrompt";
      case 'Blanc Manger Coco':
        return "Génère des phrases courtes à trou (contenant '_____') pour le jeu. Thème : $userPrompt";
      case 'Le Juge':
        return "Génère des questions amusantes sur un joueur (utilise le tag '{player}'). Thème : $userPrompt";
      case 'Qui Pourrait le Plus ?':
        return "Génère des situations courtes commençant par une action. Thème : $userPrompt";
      case 'Le Roi des Mèmes':
        return "Génère des situations humoristiques et amorces de légendes de mèmes. Thème : $userPrompt";
      default:
        return "Génère une liste de mots/expressions pour le jeu $gameType sur le thème : $userPrompt";
    }
  }

  /// Enregistre un pack généré par l'IA directement dans Firestore
  Future<String> saveAiThemeToFirebase({
    required String uid,
    required String prompt,
    required String gameType,
    required List<String> words,
    String? title,
    String? existingDocId,
  }) async {
    final colRef = _db.collection('users').doc(uid).collection('ai_history');

    // Titre automatique généré si aucun titre fourni
    String autoTitle = title ?? '';
    if (autoTitle.trim().isEmpty) {
      if (prompt.trim().isNotEmpty) {
        autoTitle = prompt.trim();
        if (autoTitle.length > 28)
          autoTitle = "${autoTitle.substring(0, 28)}...";
      } else if (words.isNotEmpty) {
        autoTitle = "Pack ${words.take(2).join(', ')}";
      } else {
        autoTitle = "Thème $gameType";
      }
    }

    if (existingDocId != null && existingDocId.isNotEmpty) {
      await colRef.doc(existingDocId).set({
        'title': autoTitle,
        'prompt': prompt,
        'gameType': gameType,
        'words': words,
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
      return existingDocId;
    } else {
      final docRef = await colRef.add({
        'title': autoTitle,
        'prompt': prompt,
        'gameType': gameType,
        'words': words,
        'createdAt': FieldValue.serverTimestamp(),
      });
      return docRef.id;
    }
  }

  /// Écoute en temps réel de l'historique Firebase filtré par jeu
  Stream<List<AiThemeHistoryItem>> getAiHistoryStream(
    String uid,
    String gameType,
  ) {
    return _db
        .collection('users')
        .doc(uid)
        .collection('ai_history')
        .where('gameType', isEqualTo: gameType)
        .orderBy('createdAt', descending: true)
        .snapshots()
        .map(
          (snap) =>
              snap.docs.map((doc) => AiThemeHistoryItem.fromDoc(doc)).toList(),
        );
  }

  /// Suppression d'un thème sur Firebase
  Future<void> deleteAiThemeFromFirebase(String uid, String docId) async {
    await _db
        .collection('users')
        .doc(uid)
        .collection('ai_history')
        .doc(docId)
        .delete();
  }

  /// Sauvegarde ou met à jour un pack IA dans l'historique de l'utilisateur (rétro-compatibilité)
  Future<String> saveAiThemeHistory({
    required String uid,
    required String prompt,
    required String gameType,
    required List<String> words,
    String? title,
    String? existingId,
  }) => saveAiThemeToFirebase(
    uid: uid,
    prompt: prompt,
    gameType: gameType,
    words: words,
    title: title,
    existingDocId: existingId,
  );

  /// Récupère le flux d'historique filtré pour un utilisateur et optionnellement par jeu (rétro-compatibilité)
  Stream<List<AiThemeHistoryItem>> getAiThemeHistoryStream(
    String uid, {
    String? gameType,
  }) {
    if (gameType != null && gameType.isNotEmpty) {
      return getAiHistoryStream(uid, gameType);
    }
    return _db
        .collection('users')
        .doc(uid)
        .collection('ai_history')
        .orderBy('createdAt', descending: true)
        .snapshots()
        .map(
          (snap) =>
              snap.docs.map((doc) => AiThemeHistoryItem.fromDoc(doc)).toList(),
        );
  }

  /// Supprime une entrée d'historique (rétro-compatibilité)
  Future<void> deleteAiThemeHistory(String uid, String historyId) =>
      deleteAiThemeFromFirebase(uid, historyId);

  // =========================================================================
  // ⚡ MOTEUR D'XP ET CALCUL DU BONUS DE VITESSE DYNAMIQUE
  // =========================================================================

  /// Récupère l'ID du joueur dont c'est actuellement le tour
  static String? getCurrentPlayerId(Map<String, dynamic> gameData) {
    final gameType = gameData['gameType'] ?? '';
    final playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    if (gameType == 'Uno') {
      final unoOrder = List<String>.from(
        gameData['unoPlayerOrder'] ?? playerOrder,
      );
      final idx = (gameData['unoCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < unoOrder.length) return unoOrder[idx];
    } else if (gameType == 'Mille Bornes') {
      final idx =
          (gameData['milleBornesCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < playerOrder.length) return playerOrder[idx];
    } else if (gameType == 'Petits Chevaux') {
      final idx = (gameData['petitsChevauxCurrentIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < playerOrder.length) return playerOrder[idx];
    } else {
      final idx = (gameData['currentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (idx >= 0 && idx < playerOrder.length) return playerOrder[idx];
    }
    return gameData['currentPlayerId'] as String?;
  }

  /// Détecte si le joueur dont c'est le tour est un robot / ordi
  static bool isCurrentPlayerBot(Map<String, dynamic> gameData) {
    final curId = getCurrentPlayerId(gameData);
    if (curId == null) return false;
    final players = gameData['players'] as Map<String, dynamic>?;
    if (players != null && players[curId] is Map) {
      final pData = players[curId] as Map;
      if (pData['isBot'] == true || pData['replacedByBot'] == true) return true;
    }
    final botPlayers = gameData['botPlayers'] as Map<String, dynamic>?;
    if (botPlayers != null && botPlayers[curId] == true) return true;
    return false;
  }

  /// Récupère la durée effective du timer selon le jeu, ses réglages et son état
  static int getEffectiveTurnTimer(Map<String, dynamic> gameData) {
    // 0. Si le joueur actuel est un ordinateur (bot), le délai de réflexion est fixé à 5 secondes
    if (isCurrentPlayerBot(gameData)) {
      return 5;
    }

    // 1. Si le chrono a été désactivé par l'hôte
    final bool useTimer = gameData['useTimer'] ?? true;
    if (!useTimer) return 0;

    final String gameType = gameData['gameType'] ?? '';
    final int? customTurnTimer =
        (gameData['turnTimerSeconds'] as num?)?.toInt();

    // 2. Si une durée personnalisée globale a été définie (> 0)
    if (customTurnTimer != null && customTurnTimer > 0) {
      // Cas particuliers avec réglages spécifiques qui priment si configurés
      if (gameType == 'La Patate Chaude' &&
          gameData['hotPotatoUseGlobalTimer'] == true) {
        return (gameData['hotPotatoGlobalDuration'] as num?)?.toInt() ?? 60;
      }
      if (gameType == 'Petit Bac' && gameData['petitBacTime'] != null) {
        return (gameData['petitBacTime'] as num).toInt();
      }
      return customTurnTimer;
    }

    // 3. Durées par défaut spécifiques selon le type de jeu
    switch (gameType) {
      case 'Petit Bac':
        return (gameData['petitBacTime'] as num?)?.toInt() ?? 120;
      case 'Pictionary':
        return 90;
      case 'Devine Tête':
      case 'Taboo':
        return 60;
      case 'La Patate Chaude':
        return gameData['hotPotatoUseGlobalTimer'] == true
            ? ((gameData['hotPotatoGlobalDuration'] as num?)?.toInt() ?? 60)
            : 30;
      case 'Photo Roulette':
        return (gameData['photoRouletteTime'] as num?)?.toInt() ?? 5;
      case "Time's Up":
        return (gameData['currentRoundTime'] as num?)?.toInt() ?? 30;
      case 'Infiltré & Mr. White':
      case 'Loup-Garou':
      case 'Poker':
      case 'Uno':
      case 'Zéro Pointé':
      case 'Big Two':
      case 'Mille Bornes':
      case 'Rami':
      case 'Belote':
      case 'Yams':
      case 'Skull':
      case 'Blokus':
      case 'Petits Chevaux':
      case 'Jeu de Dames':
      case 'Dominoes':
      case 'Zombie!':
      case 'Blanc Manger Coco':
      case 'Qui Pourrait le Plus ?':
      case 'Le Juge':
      case 'Le Menteur':
      case 'Synonyme ou Banni':
      case 'Le Roi des Mêmes':
      default:
        return 30;
    }
  }

  /// Calcul du bonus de rapidité (+1 à +10 XP) basé sur le temps serveur et la durée réelle
  static int calculateSpeedBonus(
    Timestamp? turnStartTime, {
    required int effectiveTimerSeconds,
  }) {
    // Si pas de timestamp, ou chrono désactivé (<= 0) -> aucun bonus de vitesse
    if (turnStartTime == null || effectiveTimerSeconds <= 0) return 0;

    final int elapsedMs = max(
      0,
      DateTime.now().millisecondsSinceEpoch -
          turnStartTime.millisecondsSinceEpoch,
    );
    final double elapsedSeconds = (elapsedMs / 1000.0).clamp(
      0.0,
      effectiveTimerSeconds.toDouble(),
    );

    // Pourcentage du temps consommé par le joueur
    final double percentElapsed =
        (elapsedSeconds / effectiveTimerSeconds) * 100.0;

    if (percentElapsed <= 10.0)
      return 10; // 0% - 10%  -> +10 XP (Réflexe Éclair)
    if (percentElapsed <= 20.0) return 9; // 11% - 20% -> +9 XP (Ultra-Rapide)
    if (percentElapsed <= 30.0) return 8; // 21% - 30% -> +8 XP (Très Rapide)
    if (percentElapsed <= 40.0) return 7; // 31% - 40% -> +7 XP (Vif)
    if (percentElapsed <= 50.0) return 6; // 41% - 50% -> +6 XP (Bon tempo)
    if (percentElapsed <= 60.0) return 5; // 51% - 60% -> +5 XP (Calculé)
    if (percentElapsed <= 70.0) return 4; // 61% - 70% -> +4 XP (Stratégique)
    if (percentElapsed <= 80.0) return 3; // 71% - 80% -> +3 XP (Réfléchi)
    if (percentElapsed <= 90.0) return 2; // 81% - 90% -> +2 XP (In Extremis)
    return 1; // 91% - 100% -> +1 XP (Sur le fil)
  }

  /// Vérifie si le tour en cours a réellement dépassé la durée impartie
  static bool _isTurnTimedOut(
    Map<String, dynamic> gameData, {
    int? customDuration,
  }) {
    final turnStartTime = (gameData['turnStartTime'] as Timestamp?)?.toDate();
    if (turnStartTime == null) return false;
    final int duration = customDuration ?? getEffectiveTurnTimer(gameData);
    if (duration <= 0) return false;
    final int elapsed = DateTime.now().difference(turnStartTime).inSeconds;
    return elapsed >= (duration - 1);
  }

  /// Crédite l'XP au joueur en appliquant dynamiquement le bonus selon le jeu et ses réglages
  void creditPlayerXp(
    Transaction transaction,
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
    String playerId,
    int baseAmount, {
    bool applySpeedBonus = true,
  }) {
    if (baseAmount <= 0) return;

    final players = Map<String, dynamic>.from(gameData['players'] ?? {});

    // Si le joueur est un bot ou a été remplacé par un bot, il ne gagne rien (aucun XP)
    if (players[playerId]?['isBot'] == true ||
        players[playerId]?['replacedByBot'] == true ||
        gameData['botPlayers']?[playerId] == true) {
      return;
    }
    final authUid = players[playerId]?['authUid'] ?? playerId;
    final turnStartTime = gameData['turnStartTime'] as Timestamp?;

    // Détection automatique de la durée du timer réelle
    final int effectiveTimer = getEffectiveTurnTimer(gameData);

    int totalXp = baseAmount;
    if (applySpeedBonus && turnStartTime != null && effectiveTimer > 0) {
      totalXp += calculateSpeedBonus(
        turnStartTime,
        effectiveTimerSeconds: effectiveTimer,
      );
    }

    // 1. Mise à jour de la session de jeu
    transaction.update(gameRef, {
      'players.$playerId.xp': FieldValue.increment(totalXp),
    });

    // 2. Mise à jour du profil utilisateur persistant
    final userDocRef = _db.collection('users').doc(authUid);
    transaction.set(userDocRef, {
      'xp': FieldValue.increment(totalXp),
    }, SetOptions(merge: true));
  }

  // 1. Cadavre Exquis : Nombre de mots tapés en direct
  Future<void> updateCadavreTypingCount(
    String gameCode,
    String playerId,
    int wordCount,
  ) async {
    final ref = FirebaseDatabase.instance.ref('games/$gameCode/cadavre_typing');
    if (wordCount <= 0) {
      await ref.remove();
    } else {
      await ref.set({
        'playerId': playerId,
        'wordCount': wordCount,
        'timestamp': ServerValue.timestamp,
      });
    }
