      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (!players.containsKey(playerId)) return;
      final playerName = players[playerId]?['name'] ?? 'Joueur';

      Map<String, dynamic> updates = {
        'players.$playerId.isBot': true,
        'players.$playerId.replacedByBot': true,
        'botPlayers.$playerId': true,
        'pendingBotReplacement': FieldValue.delete(),
        'inactiveTurnCounts.$playerId': 0,
        'gameLog': FieldValue.arrayUnion([
          "🤖 $playerName a été exclu et remplacé par l'ordinateur. L'IA jouera à son tour (le joueur ne gagne rien).",
        ]),
      };

      // Si c'est actuellement le tour de ce joueur, réinitialiser turnStartTime pour donner 5s au bot
      final curPlayerId = getCurrentPlayerId(gameData);
      if (curPlayerId == playerId) {
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> handleTurnTimeout(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;
      if (!_isTurnTimedOut(gameData)) return;

      final playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
      final currentPlayerIndex = gameData['currentPlayerIndex'] ?? -1;
      if (playerOrder.isEmpty ||
          currentPlayerIndex == -1 ||
          currentPlayerIndex >= playerOrder.length)
        return;

      final timedOutPlayerId = playerOrder[currentPlayerIndex];
      final gameType = gameData['gameType'] ?? '';
      final bool isSocialGame = GameData.isSocialOpinionGame(gameType);

      // 1. Gestion de l'inactivité (Strike / Expulsion après 3 timers)
      if (await _incrementInactiveCountAndCheckExpulsion(
        transaction,
        gameRef,
        gameData,
        timedOutPlayerId,
      )) {
        return; // Alerte admin déclenchée
      }

      String playerName =
          gameData['players'][timedOutPlayerId]?['name'] ?? 'Joueur';

      // 2. Si c'est un jeu social / opinion / créatif : PAS DE COUP AUTOMATIQUE !
      if (isSocialGame) {
        // Cas particulier Infiltré & Mr. White : avancer de joueur sans indice bidon
        if (gameData['gameType'] == 'Infiltré & Mr. White' &&
            gameData['currentPhase'] == 'clue_giving') {
          var playerData = Map<String, dynamic>.from(
            gameData['playerData'] ?? {},
          );
          int findNextActivePlayer(int currentIndex) {
            int nextIndex = (currentIndex + 1) % playerOrder.length;
            int loopGuard = 0;
            while (playerData[playerOrder[nextIndex]]?['status'] != 'active' &&
                loopGuard < playerOrder.length) {
              nextIndex = (nextIndex + 1) % playerOrder.length;
              loopGuard++;
            }
            if (loopGuard >= playerOrder.length) return -1;
            return nextIndex;
          }

          int nextIndex = findNextActivePlayer(currentPlayerIndex);
          Map<String, dynamic> playerClues = Map<String, dynamic>.from(
            gameData['playerClues'] ?? {},
          );
          int activePlayerCount =
              playerData.values.where((p) => p['status'] == 'active').length;
          bool isLastPlayer =
              (nextIndex == -1 || nextIndex <= currentPlayerIndex);

          Map<String, dynamic> updates = {
            'turnLog': FieldValue.arrayUnion([
              "⚠️ $playerName n'a pas donné d'indice (Jeu d'opinion). Tour passé.",
            ]),
            'turnStartTime': FieldValue.serverTimestamp(),
          };

          if (isLastPlayer || playerClues.length >= activePlayerCount) {
            updates['currentPhase'] = 'voting';
            updates['votes'] = {};
            updates['turnLog'] = FieldValue.arrayUnion([
              "La phase de vote a commencé !",
            ]);
          } else {
            updates['currentPlayerIndex'] = nextIndex;
          }
          transaction.update(gameRef, updates);
          return;
        }

        // Pour tous les autres jeux d'opinion : tour passé sans coup auto
        int nextPlayerIndex = (currentPlayerIndex + 1) % playerOrder.length;
        transaction.update(gameRef, {
          'currentPlayerIndex': nextPlayerIndex,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            "⚠️ $playerName n'a pas répondu (Jeu d'opinion). Tour sauté sans action automatique.",
          ]),
        });
        return;
      }

      // 3. Logique par défaut pour les autres jeux (Passer au joueur suivant simplement)
      int nextPlayerIndex = (currentPlayerIndex + 1) % playerOrder.length;
      transaction.update(gameRef, {
        'currentPlayerIndex': nextPlayerIndex,
        'turnStartTime': FieldValue.serverTimestamp(),
        'gameLog': FieldValue.arrayUnion([
          "$playerName n'a pas joué à temps. Son tour est passé.",
        ]),
      });
    });
  }

  Future<void> handleVotingTimeout(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      // MODIFICATION : VÃƒÂ©rification de roundState OU currentPhase (pour InfiltrÃƒÂ©)
      bool isVoting =
          gameData['roundState'] == 'voting' ||
          gameData['currentPhase'] == 'voting';

      if (gameData['gameState'] != 'playing' || !isVoting) return;
      if (!_isTurnTimedOut(gameData)) return;

      final players = Map<String, dynamic>.from(gameData['players']);
      final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});
      final gameType = gameData['gameType'];

      if (gameType == 'Le Juge') {
        // Pour Le Juge, seul le juge doit voter (sélectionner la réponse gagnante)
        final judgeId =
            gameData['currentTargetPlayerId'] ??
            gameData['judgeId'] ??
            gameData['currentPlayerId'];
        if (judgeId != null && !votes.containsKey(judgeId)) {
          await _incrementInactiveCountAndCheckExpulsion(
            transaction,
            gameRef,
            gameData,
            judgeId,
          );
        }
      } else {
        for (var pId in players.keys) {
          if (!votes.containsKey(pId)) {
            await _incrementInactiveCountAndCheckExpulsion(
              transaction,
              gameRef,
              gameData,
              pId,
            );
          }
        }
      }
    });

    // AprÃƒÂ¨s la transaction (si des joueurs ont ÃƒÂ©tÃƒÂ© expulsÃƒÂ©s ou non), on force le calcul des votes
    final gameRef = _db.collection('games').doc(gameCode);
    var updatedGameData = (await gameRef.get()).data() as Map<String, dynamic>;

    // MODIFICATION : Prise en charge du comptage pour InfiltrÃƒÂ©
    if (updatedGameData['roundState'] == 'voting') {
      await _tallyVotes(gameRef, updatedGameData);
    } else if (updatedGameData['gameType'] == 'Infiltré & Mr. White' &&
        updatedGameData['currentPhase'] == 'voting') {
      // Force la rÃƒÂ©solution du vote avec les votes actuels
      var votes = Map<String, dynamic>.from(updatedGameData['votes'] ?? {});
      var playerData = Map<String, dynamic>.from(
        updatedGameData['playerData'] ?? {},
      );

      if (votes.isEmpty) {
        // Personne n'a votÃƒÂ©, passer au prochain tour sans ÃƒÂ©limination
        await gameRef.update({
          'currentPhase': 'turn_result',
          'eliminatedThisTurn': [],
          'turnLog': FieldValue.arrayUnion([
            "Personne n'a votÃƒÂ©. Aucun joueur ÃƒÂ©liminÃƒÂ©.",
          ]),
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      } else {
        // Compter les votes existants
        Map<String, int> voteCounts = {};
        votes.forEach(
          (_, targetId) =>
              voteCounts[targetId as String] = (voteCounts[targetId] ?? 0) + 1,
        );

        int maxVotes = 0;
        List<String> tiedPlayers = [];
        voteCounts.forEach((player, count) {
          if (count > maxVotes) {
            maxVotes = count;
            tiedPlayers = [player];
          } else if (count == maxVotes) {
            tiedPlayers.add(player);
          }
        });

        String? eliminatedPlayerId =
            tiedPlayers.isNotEmpty ? tiedPlayers.first : null;
        await gameRef.update({
          'currentPhase': 'turn_result',
          'eliminatedThisTurn':
              eliminatedPlayerId != null ? [eliminatedPlayerId] : [],
          'turnLog': FieldValue.arrayUnion([
            "Le temps de vote est ÃƒÂ©coulÃƒÂ© !",
          ]),
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    } else if (updatedGameData['gameType'] == 'Le Juge' &&
        updatedGameData['roundState'] == 'voting') {
      // Forcer la résolution pour Le Juge via _tallyVotes si non fait
      await _tallyVotes(gameRef, updatedGameData);
    }
  }

  Future<void> handleHostActionTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    var gameData = gameSnap.data() as Map<String, dynamic>;

    if (gameData['gameState'] != 'playing' ||
        gameData['roundState'] != 'result')
      return;

    final gameType = gameData['gameType'];
    switch (gameType) {
      case 'Dobble':
        await nextDobbleRound(gameCode);
        break;
      case 'La Patate Chaude':
        await nextHotPotatoRound(gameCode);
        break;
      case 'Pictionary':
        await nextPictionaryRound(gameCode);
        break;
      case 'Just One':
        await nextJustOneRound(gameCode);
        break;
      case 'Skull':
        await nextSkullRound(gameCode);
        break;
      case 'Président':
        await nextPresidentRound(gameCode);
        break;

      default:
        await nextRound(gameCode);
        break;
    }
  }

  // --- LOGIQUE YAMS ---
  Future<void> _startYamsRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();

    Map<String, Map<String, int>> scores = {};
    for (String pId in playerIds) {
      scores[pId] = {};
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'playing_turn',
      'yamsPlayerOrder': playerIds,
      'yamsCurrentPlayerId': playerIds.first,
      'yamsDice': [],
      'yamsHeldDice': [false, false, false, false, false],
      'yamsRollsLeft': 3,
      'yamsScores': scores,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': ["La partie de Yams commence !"],
    });
  }

  Future<void> yamsRollDice(
    String gameCode,
    String playerId, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (!isAuto) {
        _verifyPlayerAuth(gameData, playerId);
      }

      if (gameData['yamsCurrentPlayerId'] != playerId) {
        throw Exception("Ce n'est pas votre tour.");
      }
      final int rollsLeft = gameData['yamsRollsLeft'] ?? 3;
      if (rollsLeft <= 0) {
        throw Exception("Plus de lancers disponibles.");
      }

      List<int> currentDice = List<int>.from(
        gameData['yamsDice'] ?? [0, 0, 0, 0, 0],
      );
      final List<bool> heldDice = List<bool>.from(
        gameData['yamsHeldDice'] ?? [false, false, false, false, false],
      );
      final List<bool> effectiveHeld =
          (rollsLeft == 3) ? [false, false, false, false, false] : heldDice;
      final rand = Random();

      for (int i = 0; i < 5; i++) {
        if (!effectiveHeld[i] || currentDice[i] == 0 || rollsLeft == 3) {
          currentDice[i] = rand.nextInt(6) + 1;
        }
      }

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        1,
        applySpeedBonus: true,
      );

      transaction.update(gameRef, {
        'yamsDice': currentDice,
        'yamsHeldDice': effectiveHeld,
        'yamsRollsLeft': rollsLeft - 1,
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    });
  }

  Future<void> yamsToggleHold(
    String gameCode,
    String playerId,
    int index,
  ) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['yamsCurrentPlayerId'] != playerId) return;
      if (gameData['yamsRollsLeft'] == 3) return;

      List<bool> heldDice = List<bool>.from(gameData['yamsHeldDice']);
      heldDice[index] = !heldDice[index];
      transaction.update(gameRef, {'yamsHeldDice': heldDice});
    });
  }

  // --- YAMS ---
  Future<void> yamsScoreCategory(
    String gameCode,
    String playerId,
    String category, {
    bool isAuto = false,
  }) async {
    if (!isAuto) {
      final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
      if (currentAuthUid == null) throw Exception("Non authentifié.");
    }

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (!isAuto) {
        _verifyPlayerAuth(gameData, playerId);
      }

      if (gameData['yamsCurrentPlayerId'] != playerId) {
        throw Exception("Ce n'est pas votre tour.");
      }
      if (gameData['yamsRollsLeft'] == 3 && !isAuto) {
        throw Exception("Vous devez lancer les dés avant de marquer.");
      }

      final rawScores = Map<String, dynamic>.from(gameData['yamsScores'] ?? {});
      final myScores = Map<String, dynamic>.from(rawScores[playerId] ?? {});

      if (myScores.containsKey(category)) {
        throw Exception("Catégorie déjà complétée.");
      }

      final dice = List<int>.from(gameData['yamsDice'] ?? []);
      final score = dice.length == 5 ? calculateYamsScore(dice, category) : 0;
      myScores[category] = score;
      rawScores[playerId] = myScores;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final isGameOver = players.keys.every(
        (pId) => (rawScores[pId] as Map?)?.length == 13,
      );

      final playerOrder = List<String>.from(
        gameData['yamsPlayerOrder'] ?? players.keys.toList(),
      );
      final nextPlayerId =
          playerOrder[(playerOrder.indexOf(playerId) + 1) % playerOrder.length];

      if (!isAuto) {
        int rollsLeft = (gameData['yamsRollsLeft'] as num?)?.toInt() ?? 3;
        int xpBase = 8; // Catégorie simple (As à Six)

        if (category == 'Grande Suite' && score == 40 && rollsLeft == 2) {
          final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
          if (currentAuthUid != null) {
            _db.collection('users').doc(currentAuthUid).set({
              'unlockedBadges.yams_full_suite': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        }

        if (category == 'Yams') {
          xpBase = 75; // YAMS complet
        } else if (category == 'Grande Suite' || category == 'Petite Suite') {
          xpBase = 35;
        } else if (category == 'Full') {
          xpBase = 25;
        } else if (category == 'Brelan' || category == 'Carré') {
          xpBase = 15;
        }

        // Bonus de 20 XP si la combinaison a été validée dès le premier jet de dés
        if (rollsLeft == 2 && score > 0) {
          xpBase += 20;
        }

        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          xpBase,
          applySpeedBonus: true,
        );
      }

      final updates = <String, dynamic>{
        'yamsScores': rawScores,
        'yamsCurrentPlayerId': nextPlayerId,
        'yamsDice': [],
        'yamsHeldDice': [false, false, false, false, false],
        'yamsRollsLeft': 3,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (isGameOver) {
        final Map<String, int> finalScores = {};
        for (final pId in players.keys) {
          final pScores = Map<String, dynamic>.from(rawScores[pId] ?? {});
          final upperSum = [
            'As',
            'Deux',
            'Trois',
            'Quatre',
            'Cinq',
            'Six',
          ].fold<int>(
            0,
            (sum, cat) => sum + ((pScores[cat] as num?)?.toInt() ?? 0),
          );
          final bonus = upperSum >= 63 ? 35 : 0;
          if (upperSum >= 63) {
            _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
              'unlockedBadges.yams_bonus_sup': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              pId,
              40, // Prime 63 points
              applySpeedBonus: false,
            );
          }
          final total =
              pScores.values.fold<int>(
                0,
                (sum, val) => sum + ((val as num?)?.toInt() ?? 0),
              ) +
              bonus;
          finalScores[pId] = total;
        }

        final winnerId =
            finalScores.entries.reduce((a, b) => a.value > b.value ? a : b).key;
        updates['gameState'] = 'gameOver';
        updates['gameWinner'] = winnerId;
        updates['yamsFinalScores'] = finalScores;
        updates['gameEndReason'] =
            "Grille de Yams complétée par tous les joueurs !";
      }

      transaction.update(gameRef, updates);
    });
  }

  int calculateYamsScore(List<int> dice, String category) {
    Map<int, int> counts = {};
    for (int d in dice) counts[d] = (counts[d] ?? 0) + 1;
    int sum = dice.fold(0, (a, b) => a + b);
    List<int> sortedDice = List.from(dice)..sort();

    switch (category) {
      case 'As':
        return counts[1] ?? 0;
      case 'Deux':
        return (counts[2] ?? 0) * 2;
      case 'Trois':
        return (counts[3] ?? 0) * 3;
      case 'Quatre':
        return (counts[4] ?? 0) * 4;
      case 'Cinq':
        return (counts[5] ?? 0) * 5;
      case 'Six':
        return (counts[6] ?? 0) * 6;
      case 'Brelan':
        return counts.values.any((c) => c >= 3) ? sum : 0;
      case 'Carré':
        return counts.values.any((c) => c >= 4) ? sum : 0;
      case 'Full':
        // 3 identiques + 2 identiques (ou 5 identiques)
        return (counts.values.contains(3) && counts.values.contains(2)) ||
                counts.values.contains(5)
            ? 25
            : 0;
      case 'Petite Suite':
        bool hasSmall =
            [1, 2, 3, 4].every((e) => sortedDice.contains(e)) ||
            [2, 3, 4, 5].every((e) => sortedDice.contains(e)) ||
            [3, 4, 5, 6].every((e) => sortedDice.contains(e));
        return hasSmall ? 30 : 0;
      case 'Grande Suite':
        bool hasLarge =
            [1, 2, 3, 4, 5].every((e) => sortedDice.contains(e)) ||
            [2, 3, 4, 5, 6].every((e) => sortedDice.contains(e));
        return hasLarge ? 40 : 0;
      case 'Yams':
        return counts.values.contains(5) ? 50 : 0;
      case 'Chance':
        return sum;
      default:
        return 0;
    }
  }

  // 19. TIMEOUT YAMS
  Future<void> handleYamsTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final data = snap.data() as Map<String, dynamic>;
    if (data['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(data)) return;

    final currentPlayerId = data['yamsCurrentPlayerId'];
    if (currentPlayerId == null) return;
    final playerName =
        data['players']?[currentPlayerId]?['name'] ?? 'Un joueur';
    final rollsLeft = (data['yamsRollsLeft'] as num?)?.toInt() ?? 3;
    final dice = List<int>.from(data['yamsDice'] ?? []);

    if (rollsLeft == 3) {
      await notifyAutoPlay(gameRef, playerName, actionDetails: "lance les dés");
      await yamsRollDice(gameCode, currentPlayerId, isAuto: true);
    } else if (dice.isNotEmpty) {
      final rawScores = Map<String, dynamic>.from(data['yamsScores'] ?? {});
      final myScores = Map<String, dynamic>.from(
        rawScores[currentPlayerId] ?? {},
      );

      const categories = [
        'Chance',
        'As',
        'Deux',
        'Trois',
        'Quatre',
        'Cinq',
        'Six',
        'Brelan',
        'Carré',
        'Full',
        'Petite Suite',
        'Grande Suite',
        'Yams',
      ];
      for (String cat in categories) {
        if (!myScores.containsKey(cat)) {
          await notifyAutoPlay(
            gameRef,
            playerName,
            actionDetails: "catégorie $cat",
          );
          await yamsScoreCategory(gameCode, currentPlayerId, cat, isAuto: true);
          break;
        }
      }
    }
  }

  Future<void> startCadavreExquis(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final playerIds = List<String>.from(gameData['playerOrder']);
    final variant = gameData['cadavreVariant'] ?? 'classic';
    final passingMode = gameData['cadavrePassingMode'] ?? 'single';

    int totalSteps = variant == 'classic' ? 5 : playerIds.length;

    Map<String, dynamic> papers = {};
    int numPapers = passingMode == 'single' ? 1 : playerIds.length;
    for (int i = 0; i < numPapers; i++) {
      papers[i.toString()] = {'steps': []};
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'playing',
      'papers': papers,
      'currentRound': 0,
      'currentPlayerIndex': 0,
      'totalStepsPerPaper': totalSteps,
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> submitCadavreExquisStep(
    String gameCode,
    String playerId,
    String rawText, {
    bool isAuto = false,
  }) async {
    if (!isAuto) {
      final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
      if (currentAuthUid == null) throw Exception("Non authentifié.");
    }

    final cleanText = sanitizeUserInput(rawText, maxLength: 80);
    if (cleanText.isEmpty) throw Exception("Texte requis.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'playing') return;

      if (!isAuto) {
        _verifyPlayerAuth(gameData, playerId);
      }

      List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      int currentPlayerIndex = (gameData['currentPlayerIndex'] ?? 0) as int;
      int currentRound = (gameData['currentRound'] ?? 0) as int;
      int totalSteps = (gameData['totalStepsPerPaper'] ?? 5) as int;
      String passingMode = gameData['cadavrePassingMode'] ?? 'single';

      if (playerOrder.isEmpty ||
          currentPlayerIndex >= playerOrder.length ||
          playerOrder[currentPlayerIndex] != playerId) {
        throw Exception("Ce n'est pas votre tour d'écrire.");
      }

      int paperIndex =
          (passingMode == 'single')
              ? 0
              : ((currentPlayerIndex - currentRound + playerOrder.length) %
                  playerOrder.length);

      Map<String, dynamic> papers = Map<String, dynamic>.from(
        gameData['papers'] ?? {},
      );
      Map<String, dynamic> paper = Map<String, dynamic>.from(
        papers[paperIndex.toString()] ?? {'steps': []},
      );
      List<dynamic> steps = List<dynamic>.from(paper['steps'] ?? []);

      steps.add({
        'authorId': playerId,
        'text': cleanText,
        'round': currentRound,
        'playerIndex': currentPlayerIndex,
      });
      paper['steps'] = steps;
      papers[paperIndex.toString()] = paper;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final updates = <String, dynamic>{'papers': papers};

      if (passingMode == 'single') {
        // En mode feuille unique : chaque mot est 1 étape globale
        if (steps.length >= totalSteps) {
          updates['roundState'] = 'results';
          updates['gameState'] = 'gameOver';
          for (var pId in players.keys) {
            _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
              'badgeProgress.cadavre_master': FieldValue.increment(1),
            }, SetOptions(merge: true));
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              pId,
              30,
              applySpeedBonus: false,
            );
          }
        } else {
          updates['currentPlayerIndex'] =
              (currentPlayerIndex + 1) % playerOrder.length;
          updates['currentRound'] = steps.length;
          updates['turnStartTime'] = FieldValue.serverTimestamp();
        }
      } else {
        // En mode feuilles multiples (tournante)
        int nextPlayerIndex = currentPlayerIndex + 1;
        int nextRound = currentRound;

        if (nextPlayerIndex >= playerOrder.length) {
          nextPlayerIndex = 0;
          nextRound++;
        }

        if (nextRound >= totalSteps) {
          updates['roundState'] = 'results';
          updates['gameState'] = 'gameOver';
          for (var pId in players.keys) {
            _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
              'badgeProgress.cadavre_master': FieldValue.increment(1),
            }, SetOptions(merge: true));
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              pId,
              30,
              applySpeedBonus: false,
            );
          }
        } else {
          updates['currentPlayerIndex'] = nextPlayerIndex;
          updates['currentRound'] = nextRound;
          updates['turnStartTime'] = FieldValue.serverTimestamp();
        }
      }

      if (!isAuto) {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          10,
          applySpeedBonus: true,
        );
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> submitCadavreExquisStepSecure(
    String gameCode,
    String playerId,
    String rawText,
  ) => submitCadavreExquisStep(gameCode, playerId, rawText);

  // 1. TIMEOUT UNO (CORRIGÉ & ROBUSTE)
  Future<void> handleUnoTimeout(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;
      if (gameData['gameState'] != 'playing') return;

      final playerOrder = List<String>.from(gameData['unoPlayerOrder'] ?? []);
      final currentIndex =
          (gameData['unoCurrentPlayerIndex'] as num?)?.toInt() ?? 0;
      if (playerOrder.isEmpty || currentIndex >= playerOrder.length) return;

      final playerId = playerOrder[currentIndex];
      final playerName = gameData['players']?[playerId]?['name'] ?? 'Joueur';
      final hands = Map<String, dynamic>.from(gameData['unoPlayerHands'] ?? {});
      final myHand = List<String>.from(hands[playerId] ?? []);
      final discardPile = List<String>.from(gameData['unoDiscardPile'] ?? []);
      final String topCard =
          discardPile.isNotEmpty ? discardPile.last : 'red-0';
      final String? wildColor = gameData['unoWildColorChosen'];
      final int direction = (gameData['unoDirection'] as num?)?.toInt() ?? 1;

      final bool drawActionDone = gameData['unoDrawActionDone'] == true;
      final String? lastDrawn = gameData['unoLastDrawnCard'] as String?;
      int nextIndex =
          (currentIndex + direction + playerOrder.length) % playerOrder.length;

      if (drawActionDone) {
        // Le joueur a déjà pioché manuellement pendant son tour
        if (lastDrawn != null &&
            myHand.contains(lastDrawn) &&
            GameData.canPlayUnoCard(lastDrawn, topCard, wildColor)) {
          myHand.remove(lastDrawn);
          discardPile.add(lastDrawn);
          hands[playerId] = myHand;
          transaction.update(gameRef, {
            'unoPlayerHands': hands,
            'unoDiscardPile': discardPile,
            'unoCurrentPlayerIndex': nextIndex,
            'unoDrawActionDone': false,
            'unoLastDrawnCard': null,
            'turnStartTime': FieldValue.serverTimestamp(),
            'gameLog': FieldValue.arrayUnion([
              "⏱️ $playerName n'a pas joué à temps (Carte $lastDrawn posée).",
            ]),
          });
        } else {
          // Passe son tour sans repiocher
          transaction.update(gameRef, {
            'unoCurrentPlayerIndex': nextIndex,
            'unoDrawActionDone': false,
            'unoLastDrawnCard': null,
            'turnStartTime': FieldValue.serverTimestamp(),
            'gameLog': FieldValue.arrayUnion([
              "⏱️ $playerName n'a pas joué à temps (Tour passé).",
            ]),
          });
        }
        return;
      }

      String playable = myHand.firstWhere(
        (c) => GameData.canPlayUnoCard(c, topCard, wildColor),
        orElse: () => '',
      );

      if (playable.isNotEmpty) {
        myHand.remove(playable);
        discardPile.add(playable);
        hands[playerId] = myHand;

        transaction.update(gameRef, {
          'unoPlayerHands': hands,
          'unoDiscardPile': discardPile,
          'unoCurrentPlayerIndex': nextIndex,
          'unoDrawActionDone': false,
          'unoLastDrawnCard': null,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            "⏱️ $playerName n'a pas joué à temps (Carte $playable posée).",
          ]),
        });
      } else {
        List<String> deck = List<String>.from(gameData['unoDeck'] ?? []);
        if (deck.isNotEmpty) {
          myHand.add(deck.removeAt(0));
          hands[playerId] = myHand;
        }
        transaction.update(gameRef, {
          'unoPlayerHands': hands,
          'unoDeck': deck,
          'unoCurrentPlayerIndex': nextIndex,
          'unoDrawActionDone': false,
          'unoLastDrawnCard': null,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            "⏱️ $playerName n'a pas joué à temps (Pioche et passe son tour).",
          ]),
        });
      }
    });
  }

  Future<void> handlePokerTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    var gameData = gameSnap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(gameData)) return;
    final phase = gameData['phase'] as String?;
    if (phase == 'hand_over') {
      // Auto-advance: deal next hand
      await _startPokerHand(gameRef, gameData);
      return;
    }
    List<String> playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    int currentPlayerIndex =
        (gameData['currentPlayerIndex'] as num? ?? 0).toInt();
    if (currentPlayerIndex >= playerOrder.length) return;
    String timedOutPlayerId = playerOrder[currentPlayerIndex];
    var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    if (playerData[timedOutPlayerId]?['status'] != 'active') return;
    final playerName =
        playerData[timedOutPlayerId]?['name'] ??
        gameData['players']?[timedOutPlayerId]?['name'] ??
        'Un joueur';
    await notifyAutoPlay(
      gameRef,
      playerName,
      actionDetails: "se couche (fold)",
    );
    // Auto-fold by calling the normal poker action
    await pokerAction(gameCode, timedOutPlayerId, 'fold', isAuto: true);
  }

  Future<void> handleZeroPointeTimeout(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;
      if (!_isTurnTimedOut(gameData)) return;

      final timedOutPlayerId = gameData['currentPlayerId'];
      if (timedOutPlayerId == null) return;

      if (await _incrementInactiveCountAndCheckExpulsion(
        transaction,
        gameRef,
        gameData,
        timedOutPlayerId,
      )) {
        return;
      }

      await _drawAndDiscardZeroPointeLogic(
        transaction,
        gameRef,
        gameData,
        timedOutPlayerId,
      );
    });
  }

  Future<void> _drawAndDiscardZeroPointeLogic(
    Transaction transaction,
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
    String playerId,
  ) async {
    var deck = List<int>.from(gameData['deck'] ?? []);
    var discardPile = List<int>.from(gameData['discardPile'] ?? []);
    var grids = Map<String, dynamic>.from(gameData['playerGrids'] ?? {});
    var playerGrid =
        (grids[playerId] as List)
            .map((e) => Map<String, dynamic>.from(e as Map))
            .toList();

    if (deck.isNotEmpty) {
      discardPile.add(deck.removeAt(0));
    }

    int? indexToReveal;
    for (int i = 0; i < playerGrid.length; i++) {
      if (playerGrid[i]['revealed'] == false &&
          playerGrid[i]['value'] != -100) {
        indexToReveal = i;
        break;
      }
    }
    if (indexToReveal != null) {
      playerGrid[indexToReveal]['revealed'] = true;
      grids[playerId] = playerGrid;
    }

    transaction.update(gameRef, {
      'deck': deck,
      'discardPile': discardPile,
      'playerGrids': grids,
      'gameLog': FieldValue.arrayUnion([
        "${gameData['players'][playerId]?['name'] ?? 'Un joueur'} a pioché, défaussé et révélé une carte.",
      ]),
    });

    await _processZeroPointeTurnEnd(transaction, gameRef, gameData, playerId);
  }

  Future<void> _processZeroPointeTurnEnd(
    Transaction transaction,
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
    String playerId,
  ) async {
    var grids = Map<String, dynamic>.from(gameData['playerGrids'] ?? {});
    var playerGrid =
        (grids[playerId] as List)
            .map((e) => Map<String, dynamic>.from(e as Map))
            .toList();
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});

    for (int col = 0; col < 4; col++) {
      int card1Index = col;
      int card2Index = col + 4;
      int card3Index = col + 8;
      if (playerGrid[card1Index]['value'] != -100 &&
          playerGrid[card1Index]['revealed'] == true &&
          playerGrid[card2Index]['revealed'] == true &&
          playerGrid[card3Index]['revealed'] == true &&
          playerGrid[card1Index]['value'] == playerGrid[card2Index]['value'] &&
          playerGrid[card1Index]['value'] == playerGrid[card3Index]['value']) {
        playerGrid[card1Index]['value'] = -100;
        playerGrid[card2Index]['value'] = -100;
        playerGrid[card3Index]['value'] = -100;

        // Débloquer le badge pour le joueur
        final authUid = players[playerId]?['authUid'] ?? playerId;
        _db.collection('users').doc(authUid).set({
          'unlockedBadges.skyjo_col_cancel': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          25,
          applySpeedBonus: false,
        );
      }
    }
    grids[playerId] = playerGrid;

    bool allCardsRevealed = playerGrid.every(
      (card) => card['revealed'] == true || card['value'] == -100,
    );
    if (allCardsRevealed) {
      Map<String, int> roundScores = {};
      int lowestScoreInRound = 999;

      players.keys.forEach((pId) {
        List<Map<String, dynamic>> currentGrid =
            (grids[pId] as List)
                .map((card) => Map<String, dynamic>.from(card as Map))
                .toList();
        for (var card in currentGrid) {
          card['revealed'] = true;
        }
        grids[pId] = currentGrid;
      });

      players.keys.forEach((pId) {
        int score = 0;
        (grids[pId] as List).forEach((card) {
          if ((card as Map)['value'] != -100) {
            score += ((card as Map)['value'] as num).toInt();
          }
        });
        roundScores[pId] = score;
        if (score < lowestScoreInRound) {
          lowestScoreInRound = score;
        }
      });

      final roundEnderId = playerId;
      if ((roundScores[roundEnderId] ?? 0) > lowestScoreInRound) {
        roundScores[roundEnderId] = (roundScores[roundEnderId]! + 10);
      }
      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        20,
        applySpeedBonus: false,
      );

      var totalScores = Map<String, dynamic>.from(
        gameData['totalScores'] ?? {},
      );
      roundScores.forEach((pId, score) {
        totalScores[pId] = (totalScores[pId] ?? 0) + score;
        if (score < 0) {
          _db.collection('users').doc(players[pId]?['authUid'] ?? pId).set({
            'unlockedBadges.skyjo_negative': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }
      });

      Map<String, dynamic> updates = {
        'roundState': 'round_end',
        'roundEnderId': roundEnderId,
        'playerGrids': grids,
        'roundScores': roundScores,
        'totalScores': totalScores,
        'gameLog': FieldValue.arrayUnion([
          "${players[playerId]?['name'] ?? 'Un joueur'} a retourné toutes ses cartes ! Fin de la manche.",
        ]),
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      bool isGameOver = totalScores.values.any(
        (score) => (score as num) >= (gameData['targetScore'] ?? 100),
      );

      if (isGameOver) {
        String? gameWinnerId;
        int finalLowestScore = 9999;
        totalScores.forEach((pId, score) {
          int s = (score as num).toInt();
          if (s < finalLowestScore) {
            finalLowestScore = s;
            gameWinnerId = pId;
          }
        });
        updates.addAll({
          'gameState': 'gameOver',
          'gameWinner': gameWinnerId,
          'gameEndReason':
              gameWinnerId != null
                  ? "${players[gameWinnerId]?['name'] ?? 'Joueur'} gagne avec le score le plus bas !"
                  : "Fin de la partie !",
        });
      }

      transaction.update(gameRef, updates);
    } else {
      var playerOrder = List<String>.from(gameData['playerOrder']);
      int currentIndex = playerOrder.indexOf(playerId);
      int nextIndex = (currentIndex + 1) % playerOrder.length;
      transaction.update(gameRef, {
        'currentPlayerId': playerOrder[nextIndex],
        'roundState': 'player_turn',
        'playerGrids': grids,
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    }
  }

