  Future<void> playerReadyForPhotoRoulette(
    String gameCode,
    String playerId,
    List<String> photoUrls,
  ) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;

      var gameData = gameSnap.data() as Map<String, dynamic>;

      Map<String, dynamic> readyPlayers = Map.from(
        gameData['readyPlayers'] ?? {},
      );
      readyPlayers[playerId] = true;

      Map<String, dynamic> allPhotosMap = Map.from(gameData['photos'] ?? {});
      List<dynamic> currentPhotos = List.from(allPhotosMap[playerId] ?? []);
      currentPhotos.addAll(photoUrls);
      allPhotosMap[playerId] = currentPhotos.toSet().toList();

      final allPlayers = Map.from(gameData['players'] ?? {});

      Map<String, dynamic> updates = {
        'photos.$playerId': FieldValue.arrayUnion(photoUrls),
        'readyPlayers.$playerId': true,
      };

      // Si tous les joueurs sont prêts
      if (allPlayers.isNotEmpty && readyPlayers.length >= allPlayers.length) {
        List<Map<String, String>> availablePhotos = [];
        allPhotosMap.forEach((ownerId, photoList) {
          for (var url in photoList) {
            availablePhotos.add({'url': url as String, 'ownerId': ownerId});
          }
        });

        if (availablePhotos.isEmpty) {
          updates['roundState'] = 'gameOver';
        } else {
          availablePhotos.shuffle();
          final nextPhoto = availablePhotos.first;

          updates.addAll({
            'roundState': 'showing_photo',
            'currentRound': 1,
            'currentPhoto': nextPhoto,
            'playedPhotos': [nextPhoto['url']],
            'votes': {},
            'roundResults': null,
            'roundStartTime': FieldValue.serverTimestamp(),
          });
        }
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> startNextPhotoRouletteRound(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;

      var gameData = gameSnap.data() as Map<String, dynamic>;
      Map<String, dynamic> allPhotosMap = Map.from(gameData['photos'] ?? {});
      List<dynamic> playedPhotos = List.from(gameData['playedPhotos'] ?? []);

      List<Map<String, String>> availablePhotos = [];
      allPhotosMap.forEach((ownerId, photoList) {
        for (var url in photoList) {
          if (!playedPhotos.contains(url)) {
            availablePhotos.add({'url': url as String, 'ownerId': ownerId});
          }
        }
      });

      if (availablePhotos.isEmpty ||
          playedPhotos.length >=
              (gameData['photoRouletteSettings']['rounds'] ?? 15)) {
        transaction.update(gameRef, {'roundState': 'gameOver'});
      } else {
        availablePhotos.shuffle();
        final nextPhoto = availablePhotos.first;

        transaction.update(gameRef, {
          'roundState': 'showing_photo',
          'currentRound': FieldValue.increment(1),
          'currentPhoto': nextPhoto,
          'playedPhotos': FieldValue.arrayUnion([nextPhoto['url']]),
          'votes': {}, // RÃƒÂ©initialiser les votes
          'roundResults': null, // RÃƒÂ©initialiser les rÃƒÂ©sultats
          'roundStartTime': FieldValue.serverTimestamp(),
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });
  }

  Future<void> submitPhotoRouletteVote(
    String gameCode,
    String voterId,
    String votedForId,
  ) async {
    final gameRef = _db.collection('games').doc(gameCode);

    await _db.runTransaction((transaction) async {
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['roundState'] != 'showing_photo') return;

      final Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      final Map<String, dynamic> votes = Map<String, dynamic>.from(
        gameData['votes'] ?? {},
      );

      // Enregistrement du vote avec horodatage milliseconde précis
      final now = DateTime.now();
      votes[voterId] = {
        'votedFor': votedForId,
        'timestamp': now.millisecondsSinceEpoch,
      };

      transaction.update(gameRef, {'votes': votes});

      // Si tout le monde a voté, on dépouille immédiatement dans la même transaction
      if (votes.length >= players.length) {
        final String correctOwnerId = gameData['currentPhoto']['ownerId'];
        final Timestamp? roundStartTime =
            gameData['roundStartTime'] as Timestamp?;
        final int timePerPhoto =
            (gameData['turnTimerSeconds'] as num?)?.toInt() ?? 5;
        const int maxPoints = 1000;

        final Map<String, dynamic> updates = {
          'roundState': 'results',
          'roundResultsTimestamp': FieldValue.serverTimestamp(),
        };
        final Map<String, Map<String, dynamic>> roundResults = {};

        votes.forEach((vId, vData) {
          final bool wasCorrect = (vData['votedFor'] == correctOwnerId);
          int score = 0;

          if (wasCorrect && roundStartTime != null) {
            final int voteTimeMs = (vData['timestamp'] as num).toInt();
            final double elapsedSeconds =
                (voteTimeMs - roundStartTime.millisecondsSinceEpoch) / 1000.0;
            final double timeFactor = (elapsedSeconds / timePerPhoto).clamp(
              0.0,
              1.0,
            );
            score = (maxPoints * (1.0 - timeFactor)).round();

            updates['players.$vId.score'] = FieldValue.increment(score);

            // Attribution XP
            final int xpBase = 10;
            final int speedBonus = (10 * (1.0 - timeFactor)).round().clamp(
              1,
              10,
            );
            final int totalXp = xpBase + speedBonus;

            updates['players.$vId.xp'] = FieldValue.increment(totalXp);
            final authUid = players[vId]?['authUid'] ?? vId;
            final userRef = _db.collection('users').doc(authUid);
            transaction.set(userRef, {
              'xp': FieldValue.increment(totalXp),
            }, SetOptions(merge: true));

            if (elapsedSeconds <= 2.0) {
              transaction.set(userRef, {
                'unlockedBadges.photo_roulette_fast':
                    FieldValue.serverTimestamp(),
              }, SetOptions(merge: true));
            }
            transaction.set(userRef, {
              'badgeProgress.photo_roulette_perfect': FieldValue.increment(1),
            }, SetOptions(merge: true));
          }

          roundResults[vId] = {'correct': wasCorrect, 'score': score};
        });

        updates['roundResults'] = roundResults;
        transaction.update(gameRef, updates);
      }
    });
  }

  Future<void> _tallyPhotoRouletteVotes(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final votes = Map<String, dynamic>.from(gameData['votes']);
    final String correctOwnerId = gameData['currentPhoto']['ownerId'];
    final Timestamp roundStartTime = gameData['roundStartTime'] as Timestamp;
    final int timePerPhoto = gameData['turnTimerSeconds'] ?? 5;
    final int maxPoints = 1000; // Score max pour une rÃƒÂ©ponse instantanÃƒÂ©e

    Map<String, dynamic> updates = {
      'roundState': 'results',
      'roundResultsTimestamp': FieldValue.serverTimestamp(),
    };

    Map<String, Map<String, dynamic>> roundResults = {};

    votes.forEach((voterId, voteData) {
      bool wasCorrect = (voteData['votedFor'] == correctOwnerId);
      int score = 0;

      if (wasCorrect) {
        final int voteTimeMs =
            (voteData['timestamp'] is Timestamp)
                ? (voteData['timestamp'] as Timestamp).millisecondsSinceEpoch
                : (voteData['timestamp'] as num?)?.toInt() ??
                    roundStartTime.millisecondsSinceEpoch;

        final double elapsedSeconds =
            (voteTimeMs - roundStartTime.millisecondsSinceEpoch) / 1000.0;

        final double timeFactor = (elapsedSeconds / timePerPhoto).clamp(
          0.0,
          1.0,
        );
        score = (maxPoints * (1.0 - timeFactor)).round();

        updates['players.$voterId.score'] = FieldValue.increment(score);

        // 6. photo_roulette_fast (Deviné en moins de 2 secondes)
        if (elapsedSeconds <= 2.0) {
          final voterAuth =
              (gameData['players']?[voterId]?['authUid']) ?? voterId;
          _db.collection('users').doc(voterAuth).set({
            'unlockedBadges.photo_roulette_fast': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }

        // 7. photo_roulette_perfect (Progression de bonnes réponses)
        final voterAuth =
            (gameData['players']?[voterId]?['authUid']) ?? voterId;
        _db.collection('users').doc(voterAuth).set({
          'badgeProgress.photo_roulette_perfect': FieldValue.increment(1),
        }, SetOptions(merge: true));

        final int effectiveTimer = getEffectiveTurnTimer(gameData);
        final int speedBonus = calculateSpeedBonus(
          roundStartTime,
          effectiveTimerSeconds: effectiveTimer,
        );
        final int photoXp = 10 + speedBonus;
        updates['players.$voterId.xp'] = FieldValue.increment(photoXp);
        _db.collection('users').doc(voterAuth).set({
          'xp': FieldValue.increment(photoXp),
        }, SetOptions(merge: true));
      }

      roundResults[voterId] = {
        'correct': wasCorrect,
        'score': score, // On stocke le score du tour
      };
    });

    updates['roundResults'] = roundResults;
    await gameRef.update(updates);
  }

  Future<void> handlePhotoRouletteTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot gameSnap = await gameRef.get();

    if (gameSnap.exists && gameSnap.get('roundState') == 'showing_photo') {
      final data = gameSnap.data() as Map<String, dynamic>;
      if (data['gameState'] != 'playing') return;
      if (!_isTurnTimedOut(
        data,
        customDuration: (data['turnTimerSeconds'] as num?)?.toInt() ?? 5,
      ))
        return;
      await _tallyPhotoRouletteVotes(gameRef, data);
    }
  }

  Future<void> updatePictionaryDrawing(
    String gameCode,
    String drawingContent,
    int strokeCount,
  ) async {
    // SECURITE : Verification d'authentification
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifie.");

    // SECURITE : Verification que l'appelant est bien le dessinateur actuel
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    final gameData = gameSnap.data() as Map<String, dynamic>;

    final players = (gameData['players'] as Map<String, dynamic>?) ?? {};
    final currentDrawerId = gameData['currentDrawingPlayerId'];
    if (currentDrawerId == null) throw Exception("Aucun dessinateur actif.");

    final drawerAuthUid =
        players[currentDrawerId]?['authUid'] ?? currentDrawerId;
    if (currentAuthUid != drawerAuthUid) {
      throw Exception("Seul le dessinateur actif peut modifier le dessin.");
    }

    // SECURITE : Verification de la limite de traits cote serveur
    final bool only30Strokes = gameData['pictionaryOnly30Strokes'] ?? false;
    if (only30Strokes && strokeCount > 30) {
      throw Exception("Limite de 30 traits depassee.");
    }

    // Utilisation de Firebase Realtime Database pour eviter les limites de Firestore
    await FirebaseDatabase.instance.ref('games/$gameCode/pictionary').set({
      'drawing': drawingContent,
      'strokeCount': strokeCount,
      'timestamp': ServerValue.timestamp,
    });
  }

