  Future<void> shootBatailleNavale(
    String gameCode,
    String playerId,
    int targetIndex, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    if (targetIndex < 0 || targetIndex >= 100) {
      throw Exception("Cible hors de la grille.");
    }

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['roundState'] != 'playing' ||
          gameData['currentPlayerId'] != playerId) {
        throw Exception("Ce n'est pas votre tour.");
      }

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (!isAuto &&
          (players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
      List<String> playerIds = playerData.keys.toList();
      String opponentId = playerIds.firstWhere((id) => id != playerId);

      var shooterData = Map<String, dynamic>.from(playerData[playerId] ?? {});
      var opponentData = Map<String, dynamic>.from(
        playerData[opponentId] ?? {},
      );

      var enemyGrid = List<String>.from(
        shooterData['enemyGrid'] ?? List.filled(100, 'unknown'),
      );
      var opponentGrid = List<int>.from(
        opponentData['myGrid'] ?? List.filled(100, 0),
      );
      var opponentShips = Map<String, dynamic>.from(
        opponentData['shipsPlaced'] ?? {},
      );

      if (enemyGrid[targetIndex] != 'unknown') {
        throw Exception("Case déjà ciblée.");
      }

      String result = 'miss';
      if (opponentGrid[targetIndex] != 0) {
        result = 'hit';
        int shipId = opponentGrid[targetIndex];

        for (var entry in opponentShips.entries) {
          var ship = Map<String, dynamic>.from(entry.value);
          if (ship['id'] == shipId) {
            ship['hits'] = (ship['hits'] as int) + 1;
            if (ship['hits'] >= ship['area']) {
              ship['sunk'] = true;
              result = 'sunk';
              for (int i = 0; i < 100; i++) {
                if (opponentGrid[i] == shipId) enemyGrid[i] = 'sunk';
              }
            }
            opponentShips[entry.key] = ship;
            break;
          }
        }
        if (result == 'sunk') {
          opponentData['shipsSunk'] =
              (opponentData['shipsSunk'] as int? ?? 0) + 1;
        }
      }

      enemyGrid[targetIndex] = result;
      int xpBase = 2; // Tir à l'eau
      if (enemyGrid.where((cell) => cell != 'unknown').length == 1 &&
          (result == 'hit' || result == 'sunk')) {
        xpBase = 50; // Sniper 1er coup
        if (!isAuto && currentAuthUid != null) {
          _db.collection('users').doc(currentAuthUid).set({
            'unlockedBadges.naval_sniper': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));
        }
      } else if (result == 'sunk') {
        xpBase = 25; // Coulé
      } else if (result == 'hit') {
        xpBase = 10; // Touché
      }
      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        xpBase,
        applySpeedBonus: true,
      );
      shooterData['enemyGrid'] = enemyGrid;
      opponentData['shipsPlaced'] = opponentShips;
      playerData[playerId] = shooterData;
      playerData[opponentId] = opponentData;

      Map<String, dynamic> updates = {'playerData': playerData};

      if ((opponentData['shipsSunk'] ?? 0) >=
          GameData.batailleNavaleShips.length) {
        if ((shooterData['shipsSunk'] as int? ?? 0) == 0) {
          if (currentAuthUid != null) {
            _db.collection('users').doc(currentAuthUid).set({
              'unlockedBadges.naval_clean_sheet': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          } else {
            _db
                .collection('users')
                .doc(players[playerId]?['authUid'] ?? playerId)
                .set({
                  'unlockedBadges.naval_clean_sheet':
                      FieldValue.serverTimestamp(),
                }, SetOptions(merge: true));
          }
        }
        int winXp = 40;
        int myLostShips = (shooterData['shipsSunk'] as int? ?? 0);
        if (myLostShips <= 1) {
          winXp += 50; // Victoire Parfaite (perdu 1 navire ou moins)
        }
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          winXp,
          applySpeedBonus: false,
        );
        updates.addAll({
          'gameState': 'gameOver',
          'roundState': 'gameOver',
          'gameWinner': playerId,
          'players.$playerId.score': FieldValue.increment(1),
          'gameEndReason':
              '${shooterData['name']} a coulé toute la flotte adverse !',
        });
      } else {
        String nextPlayerId =
            (result == 'hit' || result == 'sunk') ? playerId : opponentId;
        String logMessage =
            (result == 'hit' || result == 'sunk')
                ? "${shooterData['name']} a tiré en ${(targetIndex ~/ 10) + 1}-${(targetIndex % 10) + 1} : $result. Bravo, vous rejouez !"
                : "${shooterData['name']} a tiré en ${(targetIndex ~/ 10) + 1}-${(targetIndex % 10) + 1} : $result. Au tour de ${opponentData['name']}.";

        updates.addAll({
          'currentPlayerId': nextPlayerId,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([logMessage]),
        });
      }
      transaction.update(gameRef, updates);
    });
  }

  Future<void> _startRamiRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerIds = players.keys.toList()..shuffle();
    final int handSize = playerIds.length == 2 ? 10 : 7;

    List<String> deck = GameData.generateRamiDeck(playerIds.length);
    Map<String, List<String>> hands = {};
    Map<String, List<dynamic>> melds = {};
    Map<String, int> totalScores = Map<String, int>.from(
      gameData['ramiTotalScores'] ?? {},
    );

    for (var pId in playerIds) {
      hands[pId] = [];
      for (int i = 0; i < handSize && deck.isNotEmpty; i++) {
        hands[pId]!.add(deck.removeAt(0));
      }
      melds[pId] = [];
      totalScores[pId] = totalScores[pId] ?? 0;
    }

    List<String> discard = [];
    if (deck.isNotEmpty) {
      discard.add(deck.removeAt(0));
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'playing_turn',
      'playerOrder': playerIds,
      'ramiCurrentPlayerId': playerIds.first,
      'ramiPlayerHands': hands,
      'ramiMelds': melds,
      'ramiStock': deck,
      'ramiDiscard': discard,
      'ramiTotalScores': totalScores,
      'ramiRoundOver': false,
      'ramiHasDrawn': false,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': FieldValue.arrayUnion([
        "La manche de Rami commence ! C'est au tour de ${players[playerIds.first]?['name'] ?? 'Joueur'}.",
      ]),
    });
  }

  Future<void> ramiAction(
    String gameCode,
    String playerId,
    String action, {
    List<String>? cards,
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameState'] != 'playing' ||
          gameData['ramiRoundOver'] == true)
        return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (!isAuto) {
        final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
        if (currentAuthUid != voterAuthUid) {
          throw Exception("Action non autorisée.");
        }
      }

      if (gameData['ramiCurrentPlayerId'] != playerId) return;

      Map<String, dynamic> playerHands = Map.from(gameData['ramiPlayerHands']);
      List<String> myHand = List.from(playerHands[playerId]);
      List<String> stock = List.from(gameData['ramiStock']);
      List<String> discard = List.from(gameData['ramiDiscard']);
      Map<String, dynamic> melds = Map.from(gameData['ramiMelds']);
      List<dynamic> myMelds = List.from(melds[playerId]);
      bool hasDrawn = gameData['ramiHasDrawn'] ?? false;

      if (action == 'draw_stock' || action == 'draw_discard') {
        if (hasDrawn) throw Exception("Vous avez déjà pioché.");
        if (action == 'draw_stock') {
          if (stock.isEmpty) {
            if (discard.length > 1) {
              String topDiscard = discard.removeLast();
              stock.addAll(discard..shuffle());
              discard = [topDiscard];
            } else
              throw Exception("Plus de cartes !");
          }
          myHand.add(stock.removeAt(0));
        } else {
          if (discard.isEmpty) throw Exception("Défausse vide.");
          myHand.add(discard.removeLast());
        }
        playerHands[playerId] = myHand;
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          2,
          applySpeedBonus: true,
        );
        transaction.update(gameRef, {
          'ramiPlayerHands': playerHands,
          'ramiStock': stock,
          'ramiDiscard': discard,
          'ramiHasDrawn': true,
        });
        return;
      }

      if (!hasDrawn) throw Exception("Vous devez d'abord piocher une carte.");

      if (action == 'meld') {
        if (cards == null || cards.length < 3) {
          throw Exception("Il faut au moins 3 cartes pour étaler.");
        }
        if (cards.toSet().length != cards.length) {
          throw Exception(
            "Tentative de triche : vous ne pouvez pas utiliser la même carte deux fois dans une combinaison.",
          );
        }
        for (String c in cards) {
          if (!myHand.contains(c)) {
            throw Exception("Carte manquante dans votre main.");
          }
        }
        if (!GameData.isValidRamiMeld(cards)) {
          throw Exception("Combinaison invalide selon les règles du Rami !");
        }

        for (String c in cards) myHand.remove(c);
        myMelds.add(cards);
        playerHands[playerId] = myHand;
        melds[playerId] = myMelds;
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          15,
          applySpeedBonus: true,
        );
        transaction.update(gameRef, {
          'ramiPlayerHands': playerHands,
          'ramiMelds': melds,
        });
        return;
      }

      if (action == 'discard') {
        if (!hasDrawn && !isAuto) {
          throw Exception("Vous devez d'abord piocher une carte.");
        }
        if (cards == null || cards.length != 1)
          throw Exception("Défaussez exactement 1 carte.");
        String cardToDiscard = cards[0];
        if (!myHand.contains(cardToDiscard))
          throw Exception("Carte non trouvée.");

        myHand.remove(cardToDiscard);
        discard.add(cardToDiscard);

        if (myHand.isEmpty) {
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            playerId,
            35,
            applySpeedBonus: true,
          );
          final targetAuth =
              (gameData['players'] as Map?)?[playerId]?['authUid'] ?? playerId;
          _db.collection('users').doc(targetAuth).set({
            'unlockedBadges.rami_gin': FieldValue.serverTimestamp(),
          }, SetOptions(merge: true));

          Map<String, dynamic> totalScores = Map.from(
            gameData['ramiTotalScores'],
          );
          Map<String, dynamic> players = Map.from(gameData['players']);

          players.keys.forEach((pId) {
            if (pId != playerId) {
              List<String> pHand = List.from(playerHands[pId]);
              int penalty = pHand.fold(0, (sum, c) {
                String rank = c
                    .split('_')[0]
                    .substring(0, c.split('_')[0].length - 1);
                return sum + (GameData.ramiCardValues[rank] ?? 0);
              });
              totalScores[pId] = (totalScores[pId] ?? 0) + penalty;
            }
          });

          int targetScore = gameData['ramiTargetScore'] ?? 100;
          bool gameOver = totalScores.values.any(
            (score) => score >= targetScore,
          );

          transaction.update(gameRef, {
            'ramiPlayerHands': playerHands,
            'ramiDiscard': discard,
            'ramiTotalScores': totalScores,
            'ramiRoundOver': true,
            'roundState': 'round_end',
            'gameLog': FieldValue.arrayUnion([
              "${players[playerId]['name']} a gagné la manche !",
            ]),
            if (gameOver) ...{
              'gameState': 'gameOver',
              'gameWinner':
                  totalScores.entries
                      .reduce((a, b) => a.value < b.value ? a : b)
                      .key,
              'gameEndReason': "Score cible atteint !",
            },
          });
          return;
        }

        List<String> playerOrder = List.from(gameData['playerOrder']);
        int nextIndex =
            (playerOrder.indexOf(playerId) + 1) % playerOrder.length;
        playerHands[playerId] = myHand;
        transaction.update(gameRef, {
          'ramiPlayerHands': playerHands,
          'ramiDiscard': discard,
          'ramiCurrentPlayerId': playerOrder[nextIndex],
          'ramiHasDrawn': false,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });
  }

  Future<void> handleRamiTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final data = snap.data() as Map<String, dynamic>;
    if (data['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(data)) return;

    final currentPlayerId = data['ramiCurrentPlayerId'];
    if (currentPlayerId == null) return;
    final playerName =
        data['players']?[currentPlayerId]?['name'] ?? 'Un joueur';
    final hasDrawn = data['ramiHasDrawn'] ?? false;

    // Si le joueur n'a pas pioché, on pioche automatiquement d'abord !
    if (!hasDrawn) {
      await notifyAutoPlay(
        gameRef,
        playerName,
        actionDetails: "pioche automatique",
      );
      await ramiAction(gameCode, currentPlayerId, 'draw_stock', isAuto: true);
    }

    final updatedSnap = await gameRef.get();
    if (!updatedSnap.exists) return;
    final updatedData = updatedSnap.data() as Map<String, dynamic>;
    final hand = List<String>.from(
      updatedData['ramiPlayerHands']?[currentPlayerId] ?? [],
    );

    if (hand.isNotEmpty) {
      await notifyAutoPlay(
        gameRef,
        playerName,
        actionDetails: "défausse automatique",
      );
      await ramiAction(
        gameCode,
        currentPlayerId,
        'discard',
        cards: [hand.last],
        isAuto: true,
      );
    }
  }

  // --- LOGIQUE PETITS CHEVAUX (Plateau Circulaire) ---
  Future<void> startPetitsChevaux(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();

    // Protection : 2v2 nÃ©cessite 4 joueurs
    bool isTeamMode = gameData['petitsChevauxTeamMode'] ?? false;
    if (playerIds.length != 4) isTeamMode = false;

    Map<String, dynamic> positions = {};
    Map<String, int> consecutiveSixes = {};
    for (String pId in playerIds) {
      positions[pId] = [-1, -1, -1, -1];
      consecutiveSixes[pId] = 0;
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'rolling',
      'petitsChevauxPositions': positions,
      'petitsChevauxPlayerOrder': playerIds,
      'petitsChevauxCurrentIndex': 0,
      'petitsChevauxDice': 0,
      'petitsChevauxHasRolled': false,
      'petitsChevauxTeamMode': isTeamMode, // On s'assure de l'enregistrer ici
      'petitsChevauxConsecutiveSixes': consecutiveSixes,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': [
        isTeamMode ? "La partie 2v2 commence !" : "La partie commence !",
      ],
    });
  }

  Future<void> rollDicePetitsChevaux(
    String gameCode,
    String playerId, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (!isAuto) {
        _verifyPlayerAuth(gameData, playerId);
      }

      final playerOrder = List<String>.from(
        gameData['petitsChevauxPlayerOrder'] ?? [],
      );
      final currentIndex = gameData['petitsChevauxCurrentIndex'] ?? 0;
      if (playerOrder.isEmpty || playerOrder[currentIndex] != playerId) {
        throw Exception("Ce n'est pas votre tour.");
      }
      if (gameData['petitsChevauxHasRolled'] == true) {
        throw Exception("Dés déjà lancés pour ce tour.");
      }

      final dice = Random().nextInt(6) + 1;
      final consecutiveSixes = Map<String, dynamic>.from(
        gameData['petitsChevauxConsecutiveSixes'] ?? {},
      );
      if (dice == 6) {
        consecutiveSixes[playerId] = (consecutiveSixes[playerId] ?? 0) + 1;
      } else {
        consecutiveSixes[playerId] = 0;
      }

      final positions = Map<String, dynamic>.from(
        gameData['petitsChevauxPositions'] ?? {},
      );
      final List<int> myPawns = List<int>.from(
        positions[playerId] ?? [-1, -1, -1, -1],
      );
      final bool isTeamMode = gameData['petitsChevauxTeamMode'] ?? false;
      final int myIdx = playerOrder.indexOf(playerId);

      // Vérifier si AU MOINS UN coup est possible
      bool hasValidMove = false;

      // 1. Vérification sur mes propres pions
      for (int p in myPawns) {
        if (p == -1 && (dice == 1 || dice == 6)) {
          hasValidMove = true;
          break;
        } else if (p >= 0 && (p + dice <= 56)) {
          hasValidMove = true;
          break;
        }
      }

      // 2. Vérification sur les pions de l'allié en mode 2v2
      if (!hasValidMove && isTeamMode && playerOrder.length == 4) {
        final String allyId = playerOrder[(myIdx + 2) % 4];
        final List<int> allyPawns = List<int>.from(
          positions[allyId] ?? [-1, -1, -1, -1],
        );
        for (int p in allyPawns) {
          if (p == -1 && (dice == 1 || dice == 6)) {
            hasValidMove = true;
            break;
          } else if (p > 50 && (p + dice <= 56)) {
            hasValidMove = true;
            break;
          }
        }
      }

      final playerName = gameData['players']?[playerId]?['name'] ?? 'Joueur';

      if (!hasValidMove) {
        // Aucun coup possible -> Passage automatique immédiat au joueur suivant
        int nextIndex = (currentIndex + 1) % playerOrder.length;
        transaction.update(gameRef, {
          'petitsChevauxDice': dice,
          'petitsChevauxHasRolled': false,
          'petitsChevauxCurrentIndex': nextIndex,
          'petitsChevauxConsecutiveSixes': consecutiveSixes,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            "🎲 $playerName a fait un $dice mais aucun pion ne peut avancer. Tour passé automatiquement !",
          ]),
        });
      } else {
        // Coup possible -> Le joueur choisit son pion
        transaction.update(gameRef, {
          'petitsChevauxDice': dice,
          'petitsChevauxHasRolled': true,
          'petitsChevauxConsecutiveSixes': consecutiveSixes,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });
  }

  Future<void> movePawnPetitsChevaux(
    String gameCode,
    String playerId,
    String targetOwnerId,
    int pawnIndex, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;

      // SÉCURITÉ AUTH
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (!isAuto &&
          (players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      List<String> playerOrder = List<String>.from(
        gameData['petitsChevauxPlayerOrder'],
      );
      int currentIndex = gameData['petitsChevauxCurrentIndex'];
      if (playerOrder[currentIndex] != playerId) {
        throw Exception("Ce n'est pas votre tour.");
      }

      // VÉRIFICATION OBLIGATOIRE DU LANCER
      if (gameData['petitsChevauxHasRolled'] != true ||
          (gameData['petitsChevauxDice'] ?? 0) <= 0) {
        throw Exception("Vous devez d'abord lancer le dé.");
      }

      bool isTeamMode = gameData['petitsChevauxTeamMode'] ?? false;
      int myPlayerIdx = playerOrder.indexOf(playerId);
      int targetPlayerIdx = playerOrder.indexOf(targetOwnerId);

      bool isTeammate =
          isTeamMode &&
          (playerId != targetOwnerId) &&
          (myPlayerIdx % 2 == targetPlayerIdx % 2);

      if (playerId != targetOwnerId && !isTeammate) {
        throw Exception(
          "Vous ne pouvez pas déplacer le pion d'un adversaire !",
        );
      }

      Map<String, dynamic> allPositions = Map<String, dynamic>.from(
        gameData['petitsChevauxPositions'],
      );
      List<int> targetPositions = List<int>.from(allPositions[targetOwnerId]);
      int currentPos = targetPositions[pawnIndex];
      int dice = gameData['petitsChevauxDice'];

      if (isTeammate) {
        if (currentPos == -1 && (dice != 1 && dice != 6)) {
          throw Exception(
            "Il faut un 1 ou un 6 pour sortir le pion d'un allié.",
          );
        } else if (currentPos >= 0 && currentPos <= 50) {
          throw Exception(
            "Vous ne pouvez aider un allié que pour sortir ou dans l'escalier final.",
          );
        }
      }

      bool captured = false;
      int newPos = currentPos;
      final List<int> startOffsets = [0, 13, 39, 26];
      int targetStartOffset = startOffsets[targetPlayerIdx];

      // 1. Sortie d'écurie
      if (currentPos == -1) {
        if (dice != 6 && dice != 1) {
          throw Exception("Il faut un 6 ou un 1 pour sortir de l'écurie.");
        }
        newPos = 0;
        int myAbsPos = targetStartOffset;

        for (int i = 0; i < playerOrder.length; i++) {
          String otherId = playerOrder[i];
          int otherStartOffset = startOffsets[i];
          List<int> otherPos = List<int>.from(allPositions[otherId]);
          for (int pIdx = 0; pIdx < 4; pIdx++) {
            int p = otherPos[pIdx];
            if (p >= 0 && p <= 50) {
              int otherAbsPos = (p + otherStartOffset) % 52;
              if (otherAbsPos == myAbsPos) {
                if (otherId == targetOwnerId ||
                    (isTeamMode && (i % 2 == targetPlayerIdx % 2))) {
                  throw Exception("Case de départ occupée par votre équipe.");
                } else {
                  // Capture autorisée sur sa propre case de départ
                  otherPos[pIdx] = -1;
                  allPositions[otherId] = otherPos;
                  captured = true;
                }
              }
            }
          }
        }
        targetPositions[pawnIndex] = newPos;
      } else {
        // 2. Déplacement normal sur piste ou escalier
        newPos = currentPos + dice;

        if (currentPos <= 50 && newPos > 50) {
          int overshoot = newPos - 50;
          newPos = 50 + overshoot;
          if (newPos > 56) {
            throw Exception("Lancer trop élevé pour entrer dans l'escalier.");
          }
        } else if (currentPos > 50) {
          if (newPos > 56) {
            throw Exception("Lancer trop élevé pour atteindre le centre.");
          }
        }

        if (newPos <= 50) {
          int myAbsPos = (newPos + targetStartOffset) % 52;
          const List<int> starSquares = [8, 21, 34, 47];

          for (int i = 0; i < playerOrder.length; i++) {
            String otherId = playerOrder[i];
            int otherStartOffset = startOffsets[i];
            List<int> otherPos = List<int>.from(allPositions[otherId]);

            for (int pIdx = 0; pIdx < 4; pIdx++) {
              int p = otherPos[pIdx];
              if (p >= 0 && p <= 50) {
                int otherAbsPos = (p + otherStartOffset) % 52;
                if (myAbsPos == otherAbsPos) {
                  if (otherId == targetOwnerId ||
                      (isTeamMode && (i % 2 == targetPlayerIdx % 2))) {
                    throw Exception("Case occupée par votre équipe.");
                  }
                  if (starSquares.contains(myAbsPos) ||
                      myAbsPos == otherStartOffset) {
                    throw Exception(
                      "Case refuge protégée. Capture impossible.",
                    );
                  }
                  otherPos[pIdx] = -1;
                  allPositions[otherId] = otherPos;
                  captured = true;
                }
              }
            }
          }
        }
        targetPositions[pawnIndex] = newPos;
      }

      allPositions[targetOwnerId] = targetPositions;

      Map<String, dynamic> consecutiveSixes = Map<String, dynamic>.from(
        gameData['petitsChevauxConsecutiveSixes'] ?? {},
      );
      int mySixes = consecutiveSixes[playerId] ?? 0;
      bool reachedFinish = newPos == 56;
      bool extraTurn = (dice == 6 || captured || reachedFinish);

      if (captured) {
        _db.collection('users').doc(currentAuthUid).set({
          'badgeProgress.ludo_capture_3': FieldValue.increment(1),
        }, SetOptions(merge: true));
      }

      if (mySixes == 2) {
        _db.collection('users').doc(currentAuthUid).set({
          'unlockedBadges.ludo_six_streak': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }

      int xpBase = (newPos == 56) ? 25 : (captured ? 20 : 5);
      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        xpBase,
        applySpeedBonus: true,
      );

      Map<String, dynamic> updates = {
        'petitsChevauxPositions': allPositions,
        'petitsChevauxHasRolled': false,
        'petitsChevauxDice': 0, // Reset systématique du dé
      };

      // Vérification de Victoire
      bool won = false;
      if (isTeamMode) {
        String allyId = playerOrder[(myPlayerIdx + 2) % 4];
        List<int> myPos = List<int>.from(allPositions[playerId]);
        List<int> allyPos = List<int>.from(allPositions[allyId]);
        if ((myPos.where((p) => p == 56).length +
                allyPos.where((p) => p == 56).length) >=
            4) {
          won = true;
        }
      } else {
        if (targetPositions.every((pos) => pos == 56)) won = true;
      }

      if (won) {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          40,
          applySpeedBonus: false,
        );
        updates['players.$playerId.score'] = FieldValue.increment(1);
        if (isTeamMode) {
          String allyId = playerOrder[(myPlayerIdx + 2) % 4];
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            allyId,
            40,
            applySpeedBonus: false,
          );
          updates['players.$allyId.score'] = FieldValue.increment(1);
        }
        updates['gameState'] = 'gameOver';
        updates['gameWinner'] = playerId;
        updates['gameEndReason'] = "${players[playerId]['name']} a gagné !";
        transaction.update(gameRef, updates);
        return;
      }

      if (mySixes >= 3) {
        targetPositions[pawnIndex] = -1;
        allPositions[targetOwnerId] = targetPositions;
        consecutiveSixes[playerId] = 0;
        updates['petitsChevauxPositions'] = allPositions;
        updates['petitsChevauxConsecutiveSixes'] = consecutiveSixes;
        updates['petitsChevauxCurrentIndex'] =
            (currentIndex + 1) % playerOrder.length;
        updates['turnStartTime'] = FieldValue.serverTimestamp();
        transaction.update(gameRef, updates);
        return;
      }

      updates['petitsChevauxConsecutiveSixes'] = consecutiveSixes;
      if (extraTurn) {
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      } else {
        updates['petitsChevauxCurrentIndex'] =
            (currentIndex + 1) % playerOrder.length;
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> passTurnPetitsChevaux(
    String gameCode,
    String playerId, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (!isAuto &&
          (players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      List<String> playerOrder = List<String>.from(
        gameData['petitsChevauxPlayerOrder'],
      );
      int currentIndex = gameData['petitsChevauxCurrentIndex'];
      if (playerOrder[currentIndex] != playerId) return;

      // Reset du compteur de 6 si le joueur passe son tour
      Map<String, dynamic> consecutiveSixes = Map<String, dynamic>.from(
        gameData['petitsChevauxConsecutiveSixes'] ?? {},
      );
      consecutiveSixes[playerId] = 0;

      transaction.update(gameRef, {
        'petitsChevauxCurrentIndex': (currentIndex + 1) % playerOrder.length,
        'petitsChevauxHasRolled': false,
        'petitsChevauxDice': 0,
        'petitsChevauxConsecutiveSixes': consecutiveSixes,
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    });
  }

  Future<void> _startDominoesRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();

    // GÃ©nÃ©rer le jeu complet (28 tuiles)
    List<String> fullDeck = [];
    for (int i = 0; i <= 6; i++) {
      for (int j = i; j <= 6; j++) {
        fullDeck.add('$i-$j');
      }
    }
    fullDeck.shuffle();

    // Distribuer 7 tuiles par joueur
    Map<String, List<String>> hands = {};
    for (String pId in playerIds) {
      hands[pId] = [];
      for (int i = 0; i < 7; i++) {
        if (fullDeck.isNotEmpty) hands[pId]!.add(fullDeck.removeAt(0));
      }
    }

    String mode = gameData['dominoesMode'] ?? 'pioche';
    List<String> boneyard = (mode == 'pioche') ? fullDeck : [];

    // Trouver qui commence : le double le plus Ã©levÃ©
    int startIndex = 0;
    int highestDouble = -1;
    for (int i = 0; i < playerIds.length; i++) {
      for (String tile in hands[playerIds[i]]!) {
        final parts = tile.split('-');
        if (parts[0] == parts[1]) {
          int val = int.parse(parts[0]);
          if (val > highestDouble) {
            highestDouble = val;
            startIndex = i;
          }
        }
      }
    }

    // Si aucun double, le premier joueur commence
    // (highestDouble == -1 signifie aucun double â†’ startIndex reste 0)

    Map<String, int> scores = Map<String, int>.from(
      gameData['dominoesScores'] ?? {},
    );
    for (String pId in playerIds) {
      scores.putIfAbsent(pId, () => 0);
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'playing_turn',
      'dominoesBoneyard': boneyard,
      'dominoesPlayerHands': hands,
      // CORRECTION : chaÃ®ne = liste de maps {tile, matchEnd, side}
      // pour savoir dans quel sens chaque tuile est posÃ©e
      'dominoesBoardChain': [],
      'dominoesOpenEnds':
          [], // [leftEnd, rightEnd] â€” toujours 2 valeurs max (ou 4 avec spinner)
      'dominoesScores': scores,
      'dominoesCurrentPlayerIndex': startIndex,
      'dominoesPlayerOrder': playerIds,
      'dominoesSpinnerPlayed': false,
      'dominoesPassedPlayers': [],
      'dominoesRoundOver': false,
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // playDominoesTile
  //   matchEnd : l'extrÃ©mitÃ© sur laquelle le joueur pose la tuile.
  //              -1 si c'est le premier domino (plateau vide).
  //   side     : 'left' | 'right' | 'top' | 'bottom'
  //              indique oÃ¹ la tuile est ajoutÃ©e sur la chaÃ®ne.
  //              Le client le calcule et l'envoie pour l'affichage.
  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  Future<void> playDominoesTile(
    String gameCode,
    String playerId,
    String tile,
    int matchEnd,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      final gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing' ||
          gameData['dominoesRoundOver'] == true) {
        throw Exception("La partie n'est pas en cours.");
      }

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if ((players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final playerOrder = List<String>.from(gameData['dominoesPlayerOrder']);
      final int currentIndex = gameData['dominoesCurrentPlayerIndex'];
      if (playerOrder[currentIndex] != playerId) {
        throw Exception("Ce n'est pas votre tour !");
      }

      final hands = Map<String, dynamic>.from(gameData['dominoesPlayerHands']);
      final myHand = List<String>.from(hands[playerId] ?? []);
      if (!myHand.contains(tile)) {
        throw Exception("Ce domino n'est pas dans votre main.");
      }

      final parts = tile.split('-');
      final int a = int.parse(parts[0]);
      final int b = int.parse(parts[1]);
      final bool isDouble = (a == b);

      final boardChain = List<dynamic>.from(gameData['dominoesBoardChain']);
      List<int> openEnds = List<int>.from(gameData['dominoesOpenEnds']);

      // VÉRIFICATION STRICTE DE COMPATIBILITÉ TUILE / EXTRÉMITÉ
      if (boardChain.isNotEmpty) {
        if (!openEnds.contains(matchEnd)) {
          throw Exception(
            "Extrémité non disponible sur le plateau ($openEnds).",
          );
        }
        if (a != matchEnd && b != matchEnd) {
          throw Exception(
            "La tuile $tile ne possède pas la valeur $matchEnd requise.",
          );
        }
      }

      bool spinnerPlayed = gameData['dominoesSpinnerPlayed'] ?? false;
      final String mode = gameData['dominoesMode'] ?? 'pioche';

      if (boardChain.isEmpty) {
        openEnds = [a, b];
        if (isDouble && mode == 'all_fives') {
          spinnerPlayed = true;
        }
      } else {
        openEnds.remove(matchEnd);
        if (isDouble) {
          if (mode == 'all_fives' && !spinnerPlayed) {
            openEnds.addAll([a, b]);
            spinnerPlayed = true;
          } else {
            if (mode == 'all_fives') {
              openEnds.addAll([a, a]);
            } else {
              openEnds.add(a);
            }
          }
        } else {
          final int otherEnd = (a == matchEnd) ? b : a;
          openEnds.add(otherEnd);
        }
      }

      boardChain.add({
        'tile': tile,
        'matchEnd': matchEnd,
        'playerId': playerId,
      });

      myHand.remove(tile);
      hands[playerId] = myHand;

      final scores = Map<String, int>.from(gameData['dominoesScores'] ?? {});
      final int targetScore = gameData['dominoesTargetScore'] ?? 50;

      if (mode == 'all_fives') {
        final int sum = openEnds.fold(0, (prev, end) => prev + end);
        if (sum > 0 && sum % 5 == 0) {
          scores[playerId] = (scores[playerId] ?? 0) + sum;
          if (sum >= 20) {
            _db.collection('users').doc(currentAuthUid).set({
              'unlockedBadges.domino_all_fives': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        }
      }

      int xpBase = myHand.isEmpty ? 30 : (mode == 'all_fives' ? 10 : 5);
      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        xpBase,
        applySpeedBonus: true,
      );

      final Map<String, dynamic> updates = {
        'dominoesPlayerHands': hands,
        'dominoesBoardChain': boardChain,
        'dominoesOpenEnds': openEnds,
        'dominoesSpinnerPlayed': spinnerPlayed,
        'dominoesScores': scores,
        'dominoesPassedPlayers': [],
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (myHand.isEmpty) {
        int bonus = 0;
        for (final pId in playerOrder) {
          if (pId != playerId) {
            for (final t in List<String>.from(hands[pId] ?? [])) {
              final p = t.split('-');
              bonus += int.parse(p[0]) + int.parse(p[1]);
            }
          }
        }
        scores[playerId] = (scores[playerId] ?? 0) + bonus;
        updates['dominoesScores'] = scores;
        updates['dominoesRoundOver'] = true;

        if ((scores[playerId] ?? 0) >= targetScore) {
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            playerId,
            40,
            applySpeedBonus: false,
          );
          updates['gameState'] = 'gameOver';
          updates['dominoesGameWinner'] = playerId;
          updates['gameEndReason'] =
              "${players[playerId]['name']} atteint $targetScore points !";
        }
      } else {
        if ((scores[playerId] ?? 0) >= targetScore) {
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            playerId,
            40,
            applySpeedBonus: false,
          );
          updates['gameState'] = 'gameOver';
          updates['dominoesGameWinner'] = playerId;
          updates['gameEndReason'] =
              "${players[playerId]['name']} atteint $targetScore points !";
        } else {
          updates['dominoesCurrentPlayerIndex'] =
              (currentIndex + 1) % playerOrder.length;
        }
      }

      transaction.update(gameRef, updates);
    });
  }

  // ────────────────────────────────────────────────────────────
  // drawDominoesTile — pioche une tuile
  // ────────────────────────────────────────────────────────────
  Future<void> drawDominoesTile(String gameCode, String playerId) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      final gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing' ||
          gameData['dominoesRoundOver'] == true) {
        return;
      }
      if (gameData['dominoesMode'] != 'pioche') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if ((players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final playerOrder = List<String>.from(gameData['dominoesPlayerOrder']);
      final int currentIndex = gameData['dominoesCurrentPlayerIndex'];
      if (playerOrder[currentIndex] != playerId) return;

      final boneyard = List<String>.from(gameData['dominoesBoneyard']);
      if (boneyard.isEmpty) return;

      final hands = Map<String, dynamic>.from(gameData['dominoesPlayerHands']);
      final myHand = List<String>.from(hands[playerId] ?? []);

      final String drawnTile = boneyard.removeAt(0);
      myHand.add(drawnTile);
      hands[playerId] = myHand;

      transaction.update(gameRef, {
        'dominoesBoneyard': boneyard,
        'dominoesPlayerHands': hands,
      });
    });
  }

  // ────────────────────────────────────────────────────────────
  // passDominoesTurn — passe le tour (bloqué ou timeout)
  // ────────────────────────────────────────────────────────────
  Future<void> passDominoesTurn(
    String gameCode,
    String playerId, {
    bool isTimeout = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isTimeout && currentAuthUid == null)
      throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      final gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing' ||
          gameData['dominoesRoundOver'] == true) {
        return;
      }

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (!isTimeout &&
          (players[playerId]?['authUid'] ?? playerId) != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final playerOrder = List<String>.from(gameData['dominoesPlayerOrder']);
      final int currentIndex = gameData['dominoesCurrentPlayerIndex'];
      if (playerOrder[currentIndex] != playerId) return;

      final boneyard = List<String>.from(gameData['dominoesBoneyard'] ?? []);
      if (!isTimeout &&
          gameData['dominoesMode'] == 'pioche' &&
          boneyard.isNotEmpty) {
        throw Exception(
          "Vous devez piocher une tuile avant de pouvoir passer votre tour.",
        );
      }

      final passedPlayers = List<String>.from(
        gameData['dominoesPassedPlayers'] ?? [],
      );
      if (!passedPlayers.contains(playerId)) passedPlayers.add(playerId);

      final Map<String, dynamic> updates = {
        'dominoesPassedPlayers': passedPlayers,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (passedPlayers.length >= playerOrder.length) {
        // ─── Partie bloquée : le joueur avec le moins de pépins gagne ───
        final hands = Map<String, dynamic>.from(
          gameData['dominoesPlayerHands'],
        );
        final scores = Map<String, int>.from(gameData['dominoesScores'] ?? {});
        final int targetScore = gameData['dominoesTargetScore'] ?? 50;

        String? winnerId;
        int lowestPips = 999;
        final Map<String, int> playerPips = {};

        for (final pId in playerOrder) {
          int pips = 0;
          for (final t in List<String>.from(hands[pId] ?? [])) {
            final p = t.split('-');
            pips += int.parse(p[0]) + int.parse(p[1]);
          }
          playerPips[pId] = pips;
          if (pips < lowestPips) {
            lowestPips = pips;
            winnerId = pId;
          }
        }

        if (winnerId != null) {
          _db
              .collection('users')
              .doc(players[winnerId]?['authUid'] ?? winnerId)
              .set({
                'unlockedBadges.domino_block_win': FieldValue.serverTimestamp(),
              }, SetOptions(merge: true));
          int bonus = 0;
          for (final pId in playerOrder) {
            if (pId != winnerId) bonus += playerPips[pId]!;
          }
          scores[winnerId] = (scores[winnerId] ?? 0) + bonus;
          updates['dominoesScores'] = scores;
          updates['dominoesRoundOver'] = true;

          if ((scores[winnerId] ?? 0) >= targetScore) {
            updates['gameState'] = 'gameOver';
            updates['dominoesGameWinner'] = winnerId;
            updates['gameEndReason'] =
                "${players[winnerId]['name']} atteint $targetScore points !";
          }
        }
      } else {
        updates['dominoesCurrentPlayerIndex'] =
            (currentIndex + 1) % playerOrder.length;
      }

      transaction.update(gameRef, updates);
    });
  }

