  /// 1. Soumission d'un indice sécurisée dans une sous-collection privée via Cloud Function
  Future<void> submitJustOneClue(
    String gameCode,
    String playerId,
    String clue,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    final cleanClue =
        FirebaseService.sanitizeUserInput(clue, maxLength: 30).trim();

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, playerId);

      if (gameData['roundState'] != 'clue_giving') {
        throw Exception("Ce n'est pas la phase de proposition d'indices.");
      }
      if (gameData['justOneGuesserId'] == playerId) {
        throw Exception("Le devineur ne peut pas donner d'indice.");
      }

      final clues = Map<String, dynamic>.from(gameData['justOneClues'] ?? {});
      clues[playerId] = cleanClue;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final nonGuessersCount = players.length - 1;

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        10,
        applySpeedBonus: true,
      );

      final updates = <String, dynamic>{
        'justOneClues': clues,
        'justOneSubmittedCount': clues.length,
      };

      if (clues.length >= nonGuessersCount) {
        // Filtrage des doublons
        final Map<String, int> clueCounts = {};
        for (final c in clues.values) {
          final normalized = (c as String).toLowerCase().trim();
          clueCounts[normalized] = (clueCounts[normalized] ?? 0) + 1;
        }

        final filteredClues = <String>[];
        for (final entry in clues.entries) {
          final normalized = (entry.value as String).toLowerCase().trim();
          if ((clueCounts[normalized] ?? 0) == 1) {
            filteredClues.add(entry.value as String);
          }
        }

        if (filteredClues.length == 1) {
          final uniqueAuthorId =
              clues.entries
                  .firstWhere((e) => filteredClues.contains(e.value))
                  .key;
          _db
              .collection('users')
              .doc(players[uniqueAuthorId]?['authUid'] ?? uniqueAuthorId)
              .set({
                'unlockedBadges.just_one_unique_clue':
                    FieldValue.serverTimestamp(),
              }, SetOptions(merge: true));
        }

        updates['justOneFilteredClues'] = filteredClues;
        updates['roundState'] = 'reveal_clues';
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

  /// 3. Soumission de la proposition du devineur
  Future<void> submitJustOneGuess(
    String gameCode,
    String playerId,
    String guess,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    final cleanGuess = sanitizeUserInput(guess, maxLength: 40).toLowerCase();

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, playerId);

      if (gameData['roundState'] != 'reveal_clues') {
        throw Exception("Ce n'est pas le moment de deviner.");
      }
      if (gameData['justOneGuesserId'] != playerId) {
        throw Exception("Seul le devineur peut faire une proposition.");
      }

      String currentWord =
          (gameData['justOneCurrentWord'] as String? ?? '').toLowerCase();
      bool isCorrect = cleanGuess == currentWord;

      Map<String, dynamic> updates = {
        'justOneGuesserAnswer': cleanGuess,
        'roundState': 'result',
        'gameEndReason': isCorrect ? 'Mot deviné !' : 'Mot non deviné.',
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (isCorrect) {
        updates['justOneTotalScore'] = FieldValue.increment(1);
        final players = Map<String, dynamic>.from(gameData['players'] ?? {});
        players.keys.forEach((pId) {
          int xp = pId == playerId ? 30 : 25;
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            pId,
            xp,
            applySpeedBonus: false,
          );
        });
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> nextJustOneRound(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    await _db.runTransaction((transaction) async {
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['roundState'] != 'result') return;

      List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      List<String> justOneDeck = List<String>.from(
        gameData['justOneDeck'] ?? [],
      );
      int currentDeckIndex = gameData['justOneDeckIndex'] ?? 0;
      int nextDeckIndex = currentDeckIndex + 1;

      if (nextDeckIndex >= justOneDeck.length) {
        // Toutes les 13 cartes jouées → fin de partie
        final int finalScore = gameData['justOneTotalScore'] ?? 0;
        if (finalScore == 13) {
          final playersMap = Map<String, dynamic>.from(
            gameData['players'] ?? {},
          );
          for (final pId in playersMap.keys) {
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              pId,
              100,
              applySpeedBonus: false,
            );
            final pAuth = playersMap[pId]?['authUid'] ?? pId;
            _db.collection('users').doc(pAuth).set({
              'unlockedBadges.just_one_13': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
          }
        }

        transaction.update(gameRef, {
          'gameState': 'gameOver',
          'gameEndReason': 'Les 13 cartes ont été jouées !',
          'turnStartTime': FieldValue.serverTimestamp(),
        });
        return;
      }

      int currentGuesserIndex = playerOrder.indexOf(
        gameData['justOneGuesserId'],
      );
      int nextGuesserIndex = (currentGuesserIndex + 1) % playerOrder.length;
      String nextGuesserId = playerOrder[nextGuesserIndex];

      transaction.update(gameRef, {
        'currentRound': FieldValue.increment(1),
        'roundState': 'clue_giving',
        'justOneDeckIndex': nextDeckIndex,
        'justOneCurrentWord': justOneDeck[nextDeckIndex],
        'justOneGuesserId': nextGuesserId,
        'justOneClues': {},
        'justOneFilteredClues': [],
        'justOneSubmittedCount': 0,
        'justOneGuesserAnswer': null,
        'justOneRevealIndex': 0,
        'currentPlayerIndex': nextGuesserIndex,
        'gameEndReason': null,
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    });
  }

  Future<void> submitHotPotatoAnswer(
    String gameCode,
    String playerId,
    String answer,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    final cleanAnswer =
        sanitizeUserInput(answer, maxLength: 40).trim().toLowerCase();
    if (cleanAnswer.isEmpty) throw Exception("Réponse invalide.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, playerId);

      if (gameData['roundState'] != 'playing') {
        throw Exception("Ce n'est pas le moment de répondre.");
      }
      if (gameData['hotPotatoCurrentPlayerId'] != playerId) {
        throw Exception("Ce n'est pas votre tour d'avoir la bombe !");
      }

      final usedAnswers = List<String>.from(
        gameData['hotPotatoUsedAnswers'] ?? [],
      );
      if (usedAnswers.contains(cleanAnswer)) {
        throw Exception("Cette réponse a déjà été donnée !");
      }
      usedAnswers.add(cleanAnswer);

      final playerOrder = List<String>.from(
        gameData['playerOrder'] ?? gameData['players'].keys.toList(),
      );
      final currentIdx = playerOrder.indexOf(playerId);
      final nextIdx = (currentIdx + 1) % playerOrder.length;
      final nextPlayerId = playerOrder[nextIdx];

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        8,
        applySpeedBonus: true,
      );

      final turnStartTime = (gameData['turnStartTime'] as Timestamp?)?.toDate();
      final timerDuration =
          (gameData['hotPotatoSecondsLeft'] as num?)?.toInt() ??
          (gameData['turnTimer'] as num?)?.toInt() ??
          30;
      int secondsLeft = timerDuration;
      if (turnStartTime != null) {
        secondsLeft =
            timerDuration - DateTime.now().difference(turnStartTime).inSeconds;
      }
      if (secondsLeft <= 2 && secondsLeft > 0) {
        _db.collection('users').doc(currentAuthUid).set({
          'unlockedBadges.patate_last_second': FieldValue.serverTimestamp(),
        }, SetOptions(merge: true));
      }
      _db.collection('users').doc(currentAuthUid).set({
        'badgeProgress.patate_survivor_3': FieldValue.increment(1),
      }, SetOptions(merge: true));

      transaction.update(gameRef, {
        'hotPotatoUsedAnswers': usedAnswers,
        'hotPotatoCurrentPlayerId': nextPlayerId,
        'turnStartTime': FieldValue.serverTimestamp(),
        'gameLog': FieldValue.arrayUnion([
          "${gameData['players'][playerId]['name']} a répondu '$cleanAnswer' et passe la bombe !",
        ]),
      });
    });
  }

  Future<void> handleHotPotatoTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final gameData = snap.data() as Map<String, dynamic>;

    if (gameData['gameState'] != 'playing' ||
        gameData['roundState'] != 'playing')
      return;
    if (!_isTurnTimedOut(
      gameData,
      customDuration:
          (gameData['hotPotatoSecondsLeft'] as num?)?.toInt() ??
          (gameData['turnTimer'] as num?)?.toInt() ??
          30,
    ))
      return;

    final loserId = gameData['hotPotatoCurrentPlayerId'];
    if (loserId == null) return;

    final loserName = gameData['players']?[loserId]?['name'] ?? 'Joueur';

    await gameRef.update({
      'roundState': 'result',
      'roundLoserId': loserId,
      'players.$loserId.score': FieldValue.increment(1),
      'gameEndReason': "La bombe a explosé dans les mains de $loserName !",
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> nextHotPotatoRound(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;

    List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? gameData['players'].keys.toList(),
    );
    String gameType = gameData['gameType'] ?? '';

    // Check game-end condition for Categories
    if (gameType == 'Le Jeu des Catégories') {
      int currentRound = gameData['currentRound'] ?? 0;
      List<String> categories = List<String>.from(
        gameData['selectedCategories'] ?? [],
      );
      int maxRounds = max(categories.length, playerOrder.length * 2);
      if (currentRound >= maxRounds) {
        // Find winner (lowest score)
        Map<String, dynamic> players = Map<String, dynamic>.from(
          gameData['players'] ?? {},
        );
        String? winnerId;
        int lowestScore = 999;
        players.forEach((id, data) {
          int score = data['score'] ?? 0;
          if (score < lowestScore) {
            lowestScore = score;
            winnerId = id;
          }
        });
        if (winnerId != null) {
          final wAuth = players[winnerId]?['authUid'] ?? winnerId;
          _db.collection('users').doc(wAuth).set({
            'xp': FieldValue.increment(35),
          }, SetOptions(merge: true));
        }
        String winnerName = players[winnerId]?['name'] ?? 'Personne';
        await gameRef.update({
          'gameState': 'gameOver',
          'gameEndReason':
              '$winnerName gagne avec $lowestScore point${lowestScore > 1 ? 's' : ''} !',
        });
        return;
      }
    }

    // Récupération d'une catégorie aléatoire parmi celles sélectionnées par l'hôte ou IA
    List<String> availableCategories;
    if (gameData['aiWords'] != null &&
        (gameData['aiWords'] as List).isNotEmpty) {
      availableCategories = List<String>.from(gameData['aiWords']);
    } else {
      availableCategories = List<String>.from(
        gameData['selectedCategories'] ?? GameData.categoriesGameList,
      );
    }
    String category = "Catégorie";
    if (availableCategories.isNotEmpty) {
      category =
          availableCategories[Random().nextInt(availableCategories.length)];
    }

    int duration =
        gameData['hotPotatoUseGlobalTimer'] == true
            ? (gameData['hotPotatoGlobalDuration'] ?? 60)
            : (gameData['turnTimerSeconds'] ?? 30);

    // Pick a different player from the previous one if possible
    String? previousPlayerId = gameData['hotPotatoCurrentPlayerId'];
    String nextPlayerId = playerOrder[Random().nextInt(playerOrder.length)];
    if (playerOrder.length > 1 && nextPlayerId == previousPlayerId) {
      nextPlayerId =
          playerOrder[(playerOrder.indexOf(previousPlayerId!) + 1) %
              playerOrder.length];
    }

    await gameRef.update({
      'currentRound': FieldValue.increment(1),
      'roundState': 'playing',
      'hotPotatoCategory': category,
      'hotPotatoCurrentPlayerId': nextPlayerId,
      'hotPotatoSecondsLeft': duration,
      'hotPotatoUsedAnswers': [],
      'hotPotatoRoundStartedAt': FieldValue.serverTimestamp(),
      'turnStartTime': FieldValue.serverTimestamp(),
      'roundWinnerId': null,
      'gameEndReason': null,
    });
  }

  Future<void> drawUnoCard(
    String gameCode,
    String playerId, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) throw Exception("Partie non trouvée.");

      var gameData = gameSnap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});

      // SÉCURITÉ : Vérifier l'authUid
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (!isAuto && currentAuthUid != voterAuthUid) {
        throw Exception("Action non autorisée.");
      }

      List<String> playerOrder = List<String>.from(
        gameData['unoPlayerOrder'] ?? [],
      );
      int currentPlayerIndex = gameData['unoCurrentPlayerIndex'] ?? 0;
      int unoDirection = gameData['unoDirection'] ?? 1;
      List<String> myHand = List<String>.from(
        gameData['unoPlayerHands']?[playerId] ?? [],
      );
      List<String> deck = List<String>.from(gameData['unoDeck'] ?? []);
      List<String> discardPile = List<String>.from(
        gameData['unoDiscardPile'] ?? [],
      );
      int pendingDraw = gameData['unoPendingDraw'] ?? 0;

      if (playerOrder[currentPlayerIndex] != playerId) {
        throw Exception("Ce n'est pas votre tour de piocher.");
      }

      Map<String, dynamic> updates = {};

      if (deck.isEmpty) {
        if (discardPile.length > 1) {
          String topCard = discardPile.removeLast();
          deck.addAll(discardPile..shuffle());
          discardPile = [topCard];
          updates['unoDeck'] = deck;
          updates['unoDiscardPile'] = discardPile;
          updates['unoLog'] = FieldValue.arrayUnion([
            "La pioche est vide. La défausse est mélangée pour former une nouvelle pioche.",
          ]);
        } else {
          throw Exception(
            "Impossible de piocher, il n'y a plus de cartes disponibles.",
          );
        }
      }

      if (pendingDraw > 0) {
        List<String> drawnCards = [];
        for (int i = 0; i < pendingDraw; i++) {
          if (deck.isNotEmpty) {
            drawnCards.add(deck.removeAt(0));
          } else {
            if (discardPile.length > 1) {
              String topCard = discardPile.removeLast();
              deck.addAll(discardPile..shuffle());
              discardPile = [topCard];
              updates['unoDiscardPile'] = discardPile;
              i--; // Recommencer cette itération avec le nouveau deck
            } else {
              break; // Plus aucune carte à piocher
            }
          }
        }

        myHand.addAll(drawnCards);
        updates['unoPlayerHands.$playerId'] = myHand;
        updates['unoDeck'] = deck;
        updates['unoPendingDraw'] = 0; // La pénalité est purgée
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[playerId]?['name'] ?? 'Joueur'} a pioché $pendingDraw carte(s).",
        ]);

        int nextPlayerIdx =
            (currentPlayerIndex + unoDirection + playerOrder.length) %
            playerOrder.length;
        updates['unoCurrentPlayerIndex'] = nextPlayerIdx;
        updates['turnStartTime'] = FieldValue.serverTimestamp();

        transaction.update(gameRef, updates);
        return; // Fin de la logique pour la pioche forcée
      }

      String drawnCard = deck.removeAt(0);
      myHand.add(drawnCard);
      updates['unoPlayerHands.$playerId'] = myHand;
      updates['unoDeck'] = deck;

      if (discardPile.isEmpty) throw Exception("La pile de défausse est vide.");
      String topCard = discardPile.last;
      String? wildColor = gameData['unoWildColorChosen'];
      bool canPlayDrawnCard = GameData.canPlayUnoCard(
        drawnCard,
        topCard,
        wildColor,
      );

      if (canPlayDrawnCard) {
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[playerId]?['name'] ?? 'Joueur'} a pioché une carte et peut la jouer.",
        ]);
        updates['unoDrawActionDone'] =
            true; // Indique à l'UI de permettre de jouer la carte
        updates['unoLastDrawnCard'] = drawnCard;
      } else {
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[playerId]?['name'] ?? 'Joueur'} a pioché une carte et passe son tour.",
        ]);
        int nextPlayerIdx =
            (currentPlayerIndex + unoDirection + playerOrder.length) %
            playerOrder.length;
        updates['unoCurrentPlayerIndex'] = nextPlayerIdx;
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> callUno(
    String gameCode,
    String callerId,
    String targetId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) throw Exception("Partie non trouvée.");

      var gameData = gameSnap.data() as Map<String, dynamic>;
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});

      // SÉCURITÉ : Vérifier l'authUid de l'appelant
      final callerAuthUid = players[callerId]?['authUid'] ?? callerId;
      if (currentAuthUid != callerAuthUid) {
        throw Exception("Action non autorisée.");
      }

      Map<String, dynamic> unoPlayerHands = Map<String, dynamic>.from(
        gameData['unoPlayerHands'] ?? {},
      );
      List<String> targetHand = List<String>.from(
        unoPlayerHands[targetId] ?? [],
      );
      List<String> deck = List<String>.from(gameData['unoDeck'] ?? []);
      Map<String, dynamic> unoCalledUno = Map<String, dynamic>.from(
        gameData['unoCalledUno'] ?? {},
      );
      String? lastActionPlayerId = gameData['unoLastActionPlayerId'];

      if (targetHand.length != 1) {
        throw Exception(
          "${players[targetId]?['name'] ?? 'Le joueur'} n'a pas 1 carte, l'appel UNO est invalide.",
        );
      }
      Map<String, dynamic> updates = {};

      if (callerId != targetId &&
          !(unoCalledUno[targetId] ?? false) &&
          lastActionPlayerId == targetId) {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          callerId,
          25,
          applySpeedBonus: true,
        );
        List<String> penaltyCards = [];
        for (int i = 0; i < 2; i++) {
          if (deck.isNotEmpty) {
            penaltyCards.add(deck.removeAt(0));
          } else {
            break;
          }
        }
        targetHand.addAll(penaltyCards);
        updates['unoPlayerHands.$targetId'] = targetHand;
        updates['unoDeck'] = deck;
        updates['unoContraDeadline'] = null;
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[callerId]?['name'] ?? 'Joueur'} a crié Contre UNO ! ${players[targetId]?['name'] ?? 'Joueur'} pioche 2 cartes.",
        ]);

        updates['unoCalledUno.$targetId'] = true;
      } else if (callerId == targetId && targetHand.length == 1) {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          callerId,
          10,
          applySpeedBonus: true,
        );
        updates['unoCalledUno.$targetId'] = true;
        updates['unoContraDeadline'] = null;
        updates['unoLog'] = FieldValue.arrayUnion([
          "${players[targetId]?['name'] ?? 'Joueur'} a dit UNO !",
        ]);
      } else {
        throw Exception("Appel UNO invalide.");
      }

      transaction.update(gameRef, updates);
    });
  }

