  Future<void> nextRound(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;
    Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;

    String gameType = gameData['gameType'];
    String difficulty = gameData['difficulty'];
    Map<String, dynamic> players = gameData['players'];
    if (players.keys.isEmpty) return;

    final random = Random();

    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? [],
    );
    final int currentPlayerIndex = gameData['currentPlayerIndex'] ?? -1;

    if (playerOrder.isEmpty) {
      print(
        "ERREUR CRITIQUE: playerOrder est vide dans nextRound. Impossible de continuer.",
      );
      return;
    }

    final int nextPlayerIndex = (currentPlayerIndex + 1) % playerOrder.length;
    String activePlayerId = playerOrder[nextPlayerIndex];

    String question = "Question non trouvÃƒÂ©e";
    String? currentTargetPlayerId;
    String? liarId;
    String? undercoverId;
    String? mrWhiteId;
    Map<String, dynamic> secretData = {};
    String? roundData;
    String roundState = 'answering';
    String? memeUrl;

    final List<dynamic>? _rawAiWords = gameData['aiWords'] as List<dynamic>?;
    final List<String>? _aiWordPool =
        (_rawAiWords != null && _rawAiWords.isNotEmpty)
            ? _rawAiWords.map((e) => e.toString()).toList()
            : null;

    if (gameType == 'Le Juge') {
      List<String> questions =
          _aiWordPool ??
          GameWords.judgeData[difficulty] ??
          GameWords.judgeData['soft']!;
      question = questions[random.nextInt(questions.length)];
      currentTargetPlayerId = activePlayerId; // Le joueur actif est la cible
      question = question.replaceAll(
        '{player}',
        players[currentTargetPlayerId]['name'],
      );
      roundState = 'answering';
    } else if (gameType == 'Qui Pourrait le Plus ?') {
      List<String> questions =
          _aiWordPool ??
          GameWords.whoIsMostLikely[difficulty] ??
          GameWords.whoIsMostLikely['soft']!;
      question =
          "Qui pourrait le plus ${questions[random.nextInt(questions.length)]}";
      roundState = 'voting';
    } else if (gameType == 'Le Menteur') {
      List<String> prompts =
          _aiWordPool ??
          GameWords.liarData[difficulty] ??
          GameWords.liarData['soft']!;
      question = prompts[random.nextInt(prompts.length)];
      roundState = 'answering';

      if (gameData['isSimplifiedLiar'] == true) {
        liarId = null;
        await gameRef.update({
          'storyTruths': {},
          'playerOrder': List<String>.from(players.keys.toList())..shuffle(),
          'revealIndex': 0,
        });
      } else {
        // MODE CLASSIQUE SÉCURISÉ : On choisit le menteur secrètement
        String secretLiarId = playerOrder[random.nextInt(playerOrder.length)];
        for (var pId in players.keys) {
          await gameRef.collection('private_data').doc(pId).set({
            'isLiar': (pId == secretLiarId),
            'role': (pId == secretLiarId) ? 'Menteur' : 'Honnête',
          });
        }
        liarId = null;
      }
    } else if (gameType == 'Infiltré & Mr. White') {
      if (playerOrder.length >= 3) {
        List<String> wordPairs =
            _aiWordPool ??
            GameWords.undercoverData[difficulty]?['wordPairs'] ??
            GameWords.undercoverData['soft']!['wordPairs']!;
        String pair = wordPairs[random.nextInt(wordPairs.length)];
        List<String> words =
            pair.contains(':') ? pair.split(':') : [pair, pair];

        List<String> shuffledRoles = List.from(playerOrder)..shuffle();
        String secUndercoverId = shuffledRoles[0];
        String secMrWhiteId = shuffledRoles[1];

        question =
            "Décrivez votre mot secret en un seul mot. Imposteurs, bluffez !";
        for (var pId in players.keys) {
          String pRole =
              (pId == secUndercoverId)
                  ? 'Infiltré'
                  : (pId == secMrWhiteId ? 'Mr. White' : 'Civil');
          String pWord =
              (pId == secUndercoverId)
                  ? words[1]
                  : (pId == secMrWhiteId ? "Vous n'avez pas de mot" : words[0]);

          await gameRef.collection('private_data').doc(pId).set({
            'role': pRole,
            'secretWord': pWord,
            'specialAbilities': <String>[],
          });
        }
        undercoverId = null;
        mrWhiteId = null;
        secretData = {};
        roundData = null;
        roundState = 'answering';
      } else {
        question = "Pas assez de joueurs pour ce mode.";
        roundState = 'result';
      }
    } else if (gameType == 'Synonyme ou Banni') {
      List<String> words =
          _aiWordPool ??
          GameWords.synonymOrBanned[difficulty]?['words'] ??
          GameWords.synonymOrBanned['soft']!['words']!;
      String word = words[random.nextInt(words.length)];
      question = "Trouvez le meilleur synonyme pour le mot : $word";
      roundData = word;
      roundState = 'answering';
    } else if (gameType == 'Le Roi des Mèmes') {
      memeUrl = await _fetchRandomMemeUrl();
      question = "Ajoute la description la plus drÃƒÂ´le ÃƒÂ  ce mÃƒÂ¨me !";
      roundState = 'answering';
    } else if (gameType == 'Skull') {
      await nextSkullRound(gameCode);
      return;
    } else if (gameType == 'Uno') {
      List<String> deck = GameData.generateUnoDeck();
      Map<String, List<String>> playerHands = {};
      int startingCards = gameData['unoStartingCards'] ?? 7;

      Map<String, dynamic> currentScores = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      Map<String, int> updatedScores = {};
      currentScores.forEach((id, data) {
        updatedScores[id] = data['score'] ?? 0;
      });

      String? overallWinnerId;
      for (var entry in updatedScores.entries) {
        if (entry.value >= 500) {
          overallWinnerId = entry.key;
          break;
        }
      }

      if (overallWinnerId != null) {
        await gameRef.update({
          'gameState': 'gameOver',
          'gameWinner': overallWinnerId,
          'gameEndReason':
              "${players[overallWinnerId]?['name']} a atteint ${updatedScores[overallWinnerId]} points et gagne la partie !",
        });
        return;
      }

      for (String pId in playerOrder) {
        playerHands[pId] = [];
        for (int i = 0; i < startingCards; i++) {
          playerHands[pId]!.add(deck.removeAt(0));
        }
      }

      String firstCard;
      do {
        firstCard = deck.removeAt(0);
      } while (GameData.getUnoCardColor(firstCard) == 'wild');

      await gameRef.update({
        'unoDeck': deck,
        'unoDiscardPile': [firstCard],
        'unoPlayerHands': playerHands,
        'unoCurrentPlayerIndex': 0,
        'unoDirection': 1,
        'unoPendingDraw': 0,
        'unoWildColorChosen': null,
        'unoCalledUno': {for (var pId in playerOrder) pId: false},
        'unoLastActionPlayerId': null,
        'gameState': 'playing',
        'roundState': 'playing_turn',
        'unoLog': FieldValue.arrayUnion([
          'Une nouvelle manche de Uno commence !',
        ]),
        'turnStartTime': FieldValue.serverTimestamp(),
      });
      await _applyFirstUnoCardEffect(gameRef, firstCard, playerOrder[0]);
      return; // On arrÃƒÂªte l'exÃƒÂ©cution ici pour Uno
    }

    final updateMap = {
      'currentPlayerIndex': nextPlayerIndex,
      'currentRound': FieldValue.increment(1),
      'roundState': roundState,
      'currentQuestion': question,
      'currentTargetPlayerId': currentTargetPlayerId,
      'activePlayerId': activePlayerId,
      'liarId': liarId,
      'undercoverId': undercoverId,
      'mrWhiteId': mrWhiteId,
      'secretData': secretData,
      'roundData': roundData,
      'answers': {},
      'votes': {},
      'accusations': {},
      'roundWinnerId': null,
      'voteResults': null,
      'gameEndReason': null,
      'memeUrl': memeUrl,
      'turnStartTime': FieldValue.serverTimestamp(),
    };

    if (currentPlayerIndex > -1) {
      String oldPlayerId = playerOrder[currentPlayerIndex];
      updateMap['inactiveTurnCounts.$oldPlayerId'] = 0;
    }

    await gameRef.update(updateMap);
  }

  int _nextSkullActiveIndex(
    List<String> playerOrder,
    int currentIndex,
    Map<String, dynamic> players, [
    Set<String> blockedPlayers = const <String>{},
  ]) {
    if (playerOrder.isEmpty) return -1;

    for (int step = 1; step <= playerOrder.length; step++) {
      final int nextIndex = (currentIndex + step) % playerOrder.length;
      final String candidateId = playerOrder[nextIndex];
      final Map<String, dynamic> candidatePlayer = Map<String, dynamic>.from(
        players[candidateId] ?? {},
      );
      final int cardsInHand = candidatePlayer['cardsInHand'] ?? 0;
      final bool isOut = candidatePlayer['isOut'] == true;

      if (!isOut && cardsInHand > 0 && !blockedPlayers.contains(candidateId)) {
        return nextIndex;
      }
    }

    return -1;
  }

  List<Map<String, dynamic>> _buildSkullRevealSequence(
    List<String> playerOrder,
    String challengerId,
    Map<String, dynamic> skullMats,
  ) {
    if (playerOrder.isEmpty) return [];

    final int challengerIndex = playerOrder.indexOf(challengerId);
    final List<String> orderedPlayers = [
      ...playerOrder.sublist(challengerIndex < 0 ? 0 : challengerIndex),
      ...playerOrder.sublist(0, challengerIndex < 0 ? 0 : challengerIndex),
    ];

    final List<Map<String, dynamic>> sequence = [];
    for (final ownerId in orderedPlayers) {
      final List<Map<String, dynamic>> matCards =
          List<Map<String, dynamic>>.from(
            (skullMats[ownerId] as List? ?? []).map(
              (card) => Map<String, dynamic>.from(card as Map),
            ),
          );
      for (int index = matCards.length - 1; index >= 0; index--) {
        if (matCards[index]['revealed'] == true) continue;
        sequence.add({
          'ownerId': ownerId,
          'index': index,
          'type': matCards[index]['type'],
        });
      }
    }

    return sequence;
  }

  Future<void> placeSkullCard(
    String gameCode,
    String playerId,
    String cardType, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameType'] != 'Skull' ||
          gameData['roundState'] != 'placing') {
        return;
      }

      final Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      if (!isAuto && players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
      if (playerOrder.isEmpty ||
          currentPlayerIndex < 0 ||
          currentPlayerIndex >= playerOrder.length ||
          playerOrder[currentPlayerIndex] != playerId) {
        return;
      }

      final Map<String, dynamic> skullHands = Map<String, dynamic>.from(
        gameData['skullHands'] ?? {},
      );
      final Map<String, dynamic> skullMats = Map<String, dynamic>.from(
        gameData['skullMats'] ?? {},
      );

      final List<String> myHand = List<String>.from(skullHands[playerId] ?? []);
      if (!myHand.contains(cardType)) {
        throw Exception("Vous n'avez pas cette carte en main.");
      }

      myHand.remove(cardType);
      skullHands[playerId] = myHand;

      final List<Map<String, dynamic>> myMat = List<Map<String, dynamic>>.from(
        (skullMats[playerId] as List? ?? []).map(
          (card) => Map<String, dynamic>.from(card as Map),
        ),
      );
      myMat.add({'type': cardType, 'revealed': false});
      skullMats[playerId] = myMat;

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        3,
        applySpeedBonus: true,
      );

      players[playerId] = {
        ...Map<String, dynamic>.from(players[playerId] ?? {}),
        'cardsInHand': myHand.length,
        'isOut': false,
      };

      final int nextIndex = _nextSkullActiveIndex(
        playerOrder,
        currentPlayerIndex,
        players,
      );

      final Map<String, dynamic> updates = {
        'skullHands': skullHands,
        'skullMats': skullMats,
        'players': players,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (nextIndex == -1) {
        updates['roundState'] = 'result';
        updates['gameEndReason'] = 'Plus aucun joueur actif.';
        updates['gameState'] = 'gameOver';
        updates['gameWinner'] = playerId;
      } else {
        updates['skullCurrentPlayerIndex'] = nextIndex;
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> startSkullBid(
    String gameCode,
    String playerId,
    int bid, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameType'] != 'Skull' ||
          gameData['roundState'] != 'placing') {
        return;
      }

      final Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      if (!isAuto && players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
      if (playerOrder.isEmpty || playerOrder[currentPlayerIndex] != playerId) {
        return;
      }

      final Map<String, dynamic> skullMats = Map<String, dynamic>.from(
        gameData['skullMats'] ?? {},
      );

      final List<String> activePlayers =
          playerOrder.where((pId) {
            final data = Map<String, dynamic>.from(players[pId] ?? {});
            return data['isOut'] != true && (data['cardsInHand'] ?? 0) > 0;
          }).toList();

      final bool allActivePlaced = activePlayers.every((pId) {
        final List mat = skullMats[pId] as List? ?? [];
        return mat.isNotEmpty;
      });

      if (!allActivePlaced) {
        throw Exception(
          "Chaque joueur actif doit poser au moins une carte avant de lancer une enchère.",
        );
      }

      final int totalCardsOnTables = skullMats.values.fold<int>(0, (
        sum,
        cards,
      ) {
        return sum + (cards is List ? cards.length : 0);
      });

      if (bid < 1 || bid > totalCardsOnTables) {
        throw Exception("Enchère invalide.");
      }

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        8, // +8 XP pour l'ouverture de l'enchère
        applySpeedBonus: true,
      );

      final Map<String, dynamic> updates = {
        'roundState': 'bidding',
        'skullCurrentBid': bid,
        'skullHighestBidderId': playerId,
        'skullPassedPlayers': <String>[],
        'skullNextStarterId': playerId,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      final int nextIndex = _nextSkullActiveIndex(
        playerOrder,
        currentPlayerIndex,
        players,
        {playerId},
      );
      if (nextIndex == -1) {
        updates['roundState'] = 'result';
        updates['skullLastChallengeWinnerId'] = playerId;
        updates['skullLastChallengeOutcome'] = 'win';
      } else {
        updates['skullCurrentPlayerIndex'] = nextIndex;
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> raiseSkullBid(String gameCode, String playerId, int bid) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameType'] != 'Skull' ||
          gameData['roundState'] != 'bidding') {
        return;
      }

      final Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
      if (playerOrder.isEmpty || playerOrder[currentPlayerIndex] != playerId) {
        return;
      }

      final int currentBid = gameData['skullCurrentBid'] ?? 0;
      if (bid <= currentBid) {
        throw Exception("La surenchère doit être supérieure.");
      }

      final int nextIndex = _nextSkullActiveIndex(
        playerOrder,
        currentPlayerIndex,
        players,
        {playerId},
      );

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        8,
        applySpeedBonus: true,
      );

      final Map<String, dynamic> updates = {
        'skullCurrentBid': bid,
        'skullHighestBidderId': playerId,
        'skullPassedPlayers': <String>[],
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (nextIndex == -1) {
        updates['roundState'] = 'result';
        updates['skullLastChallengeWinnerId'] = playerId;
        updates['skullLastChallengeOutcome'] = 'win';
      } else {
        updates['skullCurrentPlayerIndex'] = nextIndex;
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> passSkullBid(
    String gameCode,
    String playerId, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameType'] != 'Skull' ||
          gameData['roundState'] != 'bidding') {
        return;
      }

      final Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      if (!isAuto && players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
      if (playerOrder.isEmpty || playerOrder[currentPlayerIndex] != playerId) {
        return;
      }

      final List<String> passedPlayers = List<String>.from(
        gameData['skullPassedPlayers'] ?? [],
      );
      if (!passedPlayers.contains(playerId)) {
        passedPlayers.add(playerId);
      }

      final String? highestBidderId = gameData['skullHighestBidderId'];
      final int activeCount =
          playerOrder.where((pId) {
            final data = Map<String, dynamic>.from(players[pId] ?? {});
            return data['isOut'] != true && (data['cardsInHand'] ?? 0) > 0;
          }).length;
      final int requiredPasses = max(1, activeCount - 1);

      final Map<String, dynamic> updates = {
        'skullPassedPlayers': passedPlayers,
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (passedPlayers.length >= requiredPasses) {
        await _resolveSkullChallengeTransaction(transaction, gameRef, gameData);
        return;
      }

      final int nextIndex = _nextSkullActiveIndex(
        playerOrder,
        currentPlayerIndex,
        players,
        {...passedPlayers, if (highestBidderId != null) highestBidderId},
      );

      if (nextIndex == -1) {
        await _resolveSkullChallengeTransaction(transaction, gameRef, gameData);
        return;
      }

      updates['skullCurrentPlayerIndex'] = nextIndex;
      transaction.update(gameRef, updates);
    });
  }

  Future<void> _resolveSkullChallengeTransaction(
    Transaction transaction,
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? [],
    );
    final String? challengerId = gameData['skullHighestBidderId'];
    if (challengerId == null) return;

    final int bid = gameData['skullCurrentBid'] ?? 0;
    Map<String, dynamic> skullMats = Map<String, dynamic>.from(
      gameData['skullMats'] ?? {},
    );
    Map<String, dynamic> skullHands = Map<String, dynamic>.from(
      gameData['skullHands'] ?? {},
    );

    final List<Map<String, dynamic>> sequence = _buildSkullRevealSequence(
      playerOrder,
      challengerId,
      skullMats,
    );

    final List<Map<String, dynamic>> revealedCards = [];
    bool challengeLost = false;

    for (int i = 0; i < min(bid, sequence.length); i++) {
      final entry = sequence[i];
      final String ownerId = entry['ownerId'] as String;
      final int index = entry['index'] as int;
      final String type = entry['type'] as String;

      final List<Map<String, dynamic>> ownerMat =
          List<Map<String, dynamic>>.from(
            (skullMats[ownerId] as List? ?? []).map(
              (card) => Map<String, dynamic>.from(card as Map),
            ),
          );

      if (index < ownerMat.length) {
        ownerMat[index] = {...ownerMat[index], 'revealed': true};
        skullMats[ownerId] = ownerMat;
      }

      revealedCards.add({'ownerId': ownerId, 'type': type});

      if (type == 'Crane') {
        challengeLost = true;
        // Piège réussi : le propriétaire du Crâne reçoit de l'XP !
        if (ownerId != challengerId) {
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            ownerId,
            25,
            applySpeedBonus: false,
          );
        }
        break;
      }
    }

    // 1. Récupération des cartes dans les mains de chaque joueur propriétaire
    for (String pId in playerOrder) {
      List<Map<String, dynamic>> mat = List<Map<String, dynamic>>.from(
        (skullMats[pId] as List? ?? []).map(
          (c) => Map<String, dynamic>.from(c as Map),
        ),
      );
      List<String> hand = List<String>.from(skullHands[pId] ?? []);

      for (var card in mat) {
        hand.add(card['type'] as String);
      }
      skullHands[pId] = hand;
      skullMats[pId] = <Map<String, dynamic>>[]; // Tapis remis à zéro
    }

    final Map<String, dynamic> updates = {
      'skullLastChallengeBid': bid,
      'skullLastChallengeRevealed': revealedCards,
      'skullLastChallengeWinnerId': challengerId,
      'skullLastChallengeLoserId': challengeLost ? challengerId : null,
      'skullLastChallengeOutcome': challengeLost ? 'lost' : 'won',
      'skullNextStarterId': challengerId,
      'skullMats': skullMats,
      'turnStartTime': FieldValue.serverTimestamp(),
    };

    if (challengeLost) {
      // Le challenger perd 1 carte au hasard de sa main
      List<String> challengerHand = List<String>.from(
        skullHands[challengerId] ?? [],
      );
      if (challengerHand.isNotEmpty) {
        int removeIdx = Random().nextInt(challengerHand.length);
        challengerHand.removeAt(removeIdx);
        skullHands[challengerId] = challengerHand;
      }

      bool isOut = challengerHand.isEmpty;
      players[challengerId] = {
        ...Map<String, dynamic>.from(players[challengerId] ?? {}),
        'cardsInHand': challengerHand.length,
        'isOut': isOut,
      };

      if (isOut) {
        playerOrder.remove(challengerId);
        updates['playerOrder'] = playerOrder;
        // Choisir le prochain joueur actif comme nouveau démarreur
        updates['skullNextStarterId'] =
            playerOrder.isNotEmpty ? playerOrder.first : null;
      }

      updates['skullHands'] = skullHands;
      updates['players'] = players;

      if (playerOrder.length <= 1) {
        final String winnerId =
            playerOrder.isNotEmpty ? playerOrder.first : challengerId;
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          winnerId,
          40,
          applySpeedBonus: false,
        );
        updates['gameState'] = 'gameOver';
        updates['gameWinner'] = winnerId;
        updates['gameEndReason'] =
            '${players[winnerId]?['name'] ?? 'Un joueur'} est le dernier survivant et remporte Skull !';
      } else {
        updates['roundState'] = 'result';
      }
    } else {
      // Succès du défi : +1 point (+ bonus si grosse prise de risque)
      int challengeXp = bid >= 5 ? 50 : 30;
      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        challengerId,
        challengeXp,
        applySpeedBonus: true,
      );
      final int currentScore = (players[challengerId]?['score'] ?? 0) as int;
      int newScore = currentScore + 1;
      players[challengerId] = {
        ...Map<String, dynamic>.from(players[challengerId] ?? {}),
        'score': newScore,
        'cardsInHand': (skullHands[challengerId] as List).length,
      };

      updates['skullHands'] = skullHands;
      updates['players'] = players;

      if (newScore >= 2) {
        _db
            .collection('users')
            .doc(players[challengerId]?['authUid'] ?? challengerId)
            .set({
              'unlockedBadges.skull_double_win': FieldValue.serverTimestamp(),
            }, SetOptions(merge: true));
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          challengerId,
          40,
          applySpeedBonus: false,
        );
        updates['gameState'] = 'gameOver';
        updates['gameWinner'] = challengerId;
        updates['gameEndReason'] =
            '${players[challengerId]?['name'] ?? 'Un joueur'} a remporté 2 défis et gagne la partie !';
      } else {
        updates['roundState'] = 'result';
      }
    }

    transaction.update(gameRef, updates);
  }

  Future<void> resolveSkullChallenge(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameType'] != 'Skull' ||
          gameData['roundState'] != 'bidding') {
        return;
      }

      await _resolveSkullChallengeTransaction(transaction, gameRef, gameData);
    });
  }

  Future<void> nextSkullRound(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists || gameSnap.data() == null) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameType'] != 'Skull' ||
          gameData['gameState'] == 'gameOver') {
        return;
      }

      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      final Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );

      if (playerOrder.isEmpty) return;

      String? starterId = gameData['skullNextStarterId'] as String?;
      if (starterId == null || !playerOrder.contains(starterId)) {
        starterId = playerOrder.firstWhere(
          (pId) =>
              (players[pId]?['cardsInHand'] ?? 0) > 0 &&
              players[pId]?['isOut'] != true,
          orElse: () => playerOrder.first,
        );
      }

      final int starterIndex = playerOrder.indexOf(starterId);
      if (starterIndex < 0) return;

      final int activePlayers =
          playerOrder.where((pId) {
            final data = Map<String, dynamic>.from(players[pId] ?? {});
            return data['isOut'] != true && (data['cardsInHand'] ?? 0) > 0;
          }).length;

      if (activePlayers <= 1) {
        final String winnerId = playerOrder.first;
        transaction.update(gameRef, {
          'gameState': 'gameOver',
          'gameWinner': winnerId,
          'gameEndReason':
              '${players[winnerId]?['name'] ?? 'Un joueur'} remporte Skull !',
        });
        return;
      }

      transaction.update(gameRef, {
        'roundState': 'placing',
        'skullCurrentPlayerIndex': starterIndex,
        'skullCurrentBid': 0,
        'skullHighestBidderId': null,
        'skullPassedPlayers': [],
        'skullLastChallengeWinnerId': null,
        'skullLastChallengeLoserId': null,
        'skullLastChallengeOutcome': null,
        'skullLastChallengeBid': 0,
        'skullLastChallengeRevealed': [],
        'turnStartTime': FieldValue.serverTimestamp(),
        'gameEndReason': null,
      });
    });
  }

  Future<void> handleSkullTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final gameSnap = await gameRef.get();
    if (!gameSnap.exists || gameSnap.data() == null) return;

    final gameData = gameSnap.data() as Map<String, dynamic>;
    if (gameData['gameType'] != 'Skull') return;
    if (gameData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(gameData)) return;

    final String roundState = gameData['roundState'] ?? '';
    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? [],
    );
    if (playerOrder.isEmpty) return;

    final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
    if (currentPlayerIndex < 0 || currentPlayerIndex >= playerOrder.length) {
      return;
    }

    final String currentPlayerId = playerOrder[currentPlayerIndex];
    final String playerName =
        gameData['players']?[currentPlayerId]?['name'] ?? 'Un joueur';
    final Map<String, dynamic> skullHands = Map<String, dynamic>.from(
      gameData['skullHands'] ?? {},
    );
    final List<String> myHand = List<String>.from(
      skullHands[currentPlayerId] ?? [],
    );

    if (roundState == 'placing') {
      if (myHand.isNotEmpty) {
        await notifyAutoPlay(
          gameRef,
          playerName,
          actionDetails: "pose de carte",
        );
        final String randomCard = myHand[Random().nextInt(myHand.length)];
        await placeSkullCard(
          gameCode,
          currentPlayerId,
          randomCard,
          isAuto: true,
        );
      } else {
        final Map<String, dynamic> skullMats = Map<String, dynamic>.from(
          gameData['skullMats'] ?? {},
        );
        final int totalCardsOnTables = skullMats.values.fold<int>(0, (
          sum,
          cards,
        ) {
          return sum + (cards is List ? cards.length : 0);
        });
        await notifyAutoPlay(
          gameRef,
          playerName,
          actionDetails: "enchère automatique",
        );
        await startSkullBid(
          gameCode,
          currentPlayerId,
          max(1, totalCardsOnTables),
          isAuto: true,
        );
      }
      return;
    }

    if (roundState == 'bidding') {
      await notifyAutoPlay(
        gameRef,
        playerName,
        actionDetails: "passe l'enchère",
      );
      await passSkullBid(gameCode, currentPlayerId, isAuto: true);
    }
  }

  Future<void> submitAnswer(
    String gameCode,
    String playerId,
    String rawAnswer,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    final cleanAnswer = sanitizeUserInput(rawAnswer, maxLength: 120);
    if (cleanAnswer.isEmpty) throw Exception("Réponse vide.");

    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    await _db.runTransaction((transaction) async {
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      Map<String, dynamic> gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['roundState'] != 'answering') return;

      _verifyPlayerAuth(gameData, playerId);

      Map<String, dynamic> players = Map<String, dynamic>.from(
        gameData['players'] ?? {},
      );
      String gameType = gameData['gameType'] ?? '';

      if (gameType == 'Le Juge') {
        final currentJudgeId = gameData['currentTargetPlayerId'];
        if (playerId == currentJudgeId) {
          throw Exception("Le Juge ne peut pas soumettre de réponse.");
        }
      }

      Map<String, dynamic> answers = Map<String, dynamic>.from(
        gameData['answers'] ?? {},
      );
      answers[playerId] =
          (gameType == 'Synonyme ou Banni')
              ? sanitizeUserInput(cleanAnswer, maxLength: 50)
              : cleanAnswer;

      if (gameType == 'Le Menteur' || gameType == 'Le Roi des Mèmes') {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          5,
          applySpeedBonus: true,
        );
      }

      int playersCount = players.length;
      int answersCount = answers.length;

      Map<String, dynamic> updates = {'answers': answers};

      if (gameType == 'Le Menteur' && gameData['isSimplifiedLiar'] == true) {
        if (answersCount == playersCount) {
          updates['roundState'] = 'declaring_truth';
          updates['turnStartTime'] = FieldValue.serverTimestamp();
          updates['gameLog'] = FieldValue.arrayUnion([
            "Tout le monde a répondu ! Place au dévoilement.",
          ]);
        }
      } else if (gameType == 'Synonyme ou Banni') {
        if (answersCount >= playersCount) {
          updates['roundState'] = 'voting';
          updates['turnStartTime'] = FieldValue.serverTimestamp();
          updates['gameLog'] = FieldValue.arrayUnion([
            "Tous les synonymes sont soumis ! Votez pour bannir le pire.",
          ]);
        }
      } else if ([
            'Infiltré & Mr. White',
            'La Patate Chaude',
            'Le Roi des Mèmes',
          ].contains(gameType) ||
          gameType == 'Le Menteur') {
        if (answersCount >= playersCount) {
          updates['roundState'] = 'voting';
          updates['turnStartTime'] = FieldValue.serverTimestamp();
          updates['gameLog'] = FieldValue.arrayUnion([
            "Tout le monde a répondu ! Place au vote.",
          ]);
        }
      } else if (gameType == 'Le Juge') {
        final int requiredAnswers = playersCount - 1; // Tous sauf le juge
        if (answersCount >= requiredAnswers) {
          updates['roundState'] = 'voting';
          updates['turnStartTime'] = FieldValue.serverTimestamp();
          updates['gameLog'] = FieldValue.arrayUnion([
            "Toutes les réponses sont reçues ! Le Juge doit trancher.",
          ]);
        }
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> submitJudgeAnswer(
    String gameCode,
    String playerId,
    String rawAnswer,
  ) => submitAnswer(gameCode, playerId, rawAnswer);

  Future<void> submitSynonymeAnswer(
    String gameCode,
    String playerId,
    String rawAnswer,
  ) => submitAnswer(gameCode, playerId, rawAnswer);

  Future<void> submitStoryTruth(
    String gameCode,
    String playerId,
    bool isTrue,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      _verifyPlayerAuth(gameData, playerId);

      final truths = Map<String, dynamic>.from(gameData['storyTruths'] ?? {});
      truths[playerId] = isTrue;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final updates = <String, dynamic>{'storyTruths': truths};

      if (truths.length >= players.length) {
        updates['roundState'] = 'voting';
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> submitVote(
    String gameCode,
    String voterId,
    String votedForId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    final gameRef = _db.collection('games').doc(gameCode);

    await _db.runTransaction((transaction) async {
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;

      final gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'voting') {
        return;
      }

      _verifyPlayerAuth(gameData, voterId);

      final players = Map<String, dynamic>.from(
        gameData['players'] as Map? ?? {},
      );
      final gameType = gameData['gameType'];

      if (!players.containsKey(votedForId)) {
        throw Exception("Joueur ciblé introuvable.");
      }

      if (gameType == 'Qui Pourrait le Plus ?') {
        if (voterId == votedForId) {
          throw Exception("Interdiction formelle de voter pour soi-même !");
        }
      } else if (gameType == 'Synonyme ou Banni') {
        if (voterId == votedForId) {
          throw Exception("Vous ne pouvez pas bannir votre propre synonyme !");
        }
      } else if (gameType == 'Le Juge') {
        final targetJudgeId = gameData['currentTargetPlayerId'];
        if (voterId != targetJudgeId) {
          throw Exception("Seul le Juge en titre peut désigner le gagnant.");
        }
        final answers = Map<String, dynamic>.from(gameData['answers'] ?? {});
        if (!answers.containsKey(votedForId)) {
          throw Exception("Ce joueur n'a pas soumis de réponse.");
        }
      }

      final votes = Map<String, dynamic>.from(gameData['votes'] as Map? ?? {});
      votes[voterId] = votedForId;

      if (gameType == 'Qui Pourrait le Plus ?') {
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          voterId,
          5,
          applySpeedBonus: true,
        );
      }

      int requiredVotes = players.length;

      if (gameType == 'Le Juge') {
        requiredVotes = 1;
      }

      if (gameType == 'Qui Pourrait le Plus ?' &&
          gameData['quiPourraitVoteMode'] == 'grouper') {
        requiredVotes = 1;
      }

      if (votes.length >= requiredVotes) {
        final updates = <String, dynamic>{'votes': votes};

        if (gameType == 'Qui Pourrait le Plus ?') {
          final Map<String, int> voteCounts = {};
          for (final target in votes.values) {
            voteCounts[target as String] = (voteCounts[target] ?? 0) + 1;
          }

          int maxVotes = 0;
          List<String> topVoted = [];
          voteCounts.forEach((target, count) {
            if (count > maxVotes) {
              maxVotes = count;
              topVoted = [target];
            } else if (count == maxVotes) {
              topVoted.add(target);
            }
          });

          updates['roundState'] = 'result';
          updates['turnStartTime'] = FieldValue.serverTimestamp();

          if (topVoted.length == 1) {
            final winner = topVoted.first;
            updates['roundWinnerId'] = winner;
            updates['players.$winner.score'] = FieldValue.increment(1);
          } else {
            updates['roundWinnerId'] = null;
            updates['gameEndReason'] =
                "Égalité parfaite ! Aucun point attribué.";
          }
        } else if (gameType == 'Synonyme ou Banni') {
          final Map<String, int> banCounts = {};
          for (final t in votes.values) {
            banCounts[t as String] = (banCounts[t] ?? 0) + 1;
          }

          int maxVotes = 0;
          List<String> topBanned = [];
          banCounts.forEach((target, count) {
            if (count > maxVotes) {
              maxVotes = count;
              topBanned = [target];
            } else if (count == maxVotes) {
              topBanned.add(target);
            }
          });

          updates['roundState'] = 'result';
          updates['turnStartTime'] = FieldValue.serverTimestamp();

          if (topBanned.length == 1) {
            final loserId = topBanned.first;
            updates['roundLoserId'] = loserId;
            updates['roundWinnerId'] = null;

            players.keys.where((id) => id != loserId).forEach((winnerId) {
              updates['players.$winnerId.score'] = FieldValue.increment(1);
            });
          } else {
            updates['roundLoserId'] = null;
            updates['gameEndReason'] =
                "Égalité dans les votes : aucun joueur banni ce tour.";
          }
        } else if (gameType == 'Le Juge') {
          final winnerPlayerId = votedForId;
          final winnerName = players[winnerPlayerId]?['name'] ?? 'Joueur';
          updates['roundState'] = 'result';
          updates['roundWinnerId'] = winnerPlayerId;
          updates['players.$winnerPlayerId.score'] = FieldValue.increment(1);
          updates['turnStartTime'] = FieldValue.serverTimestamp();
          updates['gameLog'] = FieldValue.arrayUnion([
            "$winnerName remporte la manche !",
          ]);
        } else {
          Map<String, int> voteCounts = {};
          votes.forEach((voter, votedFor) {
            voteCounts[votedFor] = (voteCounts[votedFor] ?? 0) + 1;
          });

          String? mostVotedPlayerId;
          int maxVotes = 0;
          voteCounts.forEach((playerId, count) {
            if (count > maxVotes) {
              maxVotes = count;
              mostVotedPlayerId = playerId;
            }
          });

          updates['roundState'] = 'result';
          updates['roundWinnerId'] = mostVotedPlayerId;
          updates['turnStartTime'] = FieldValue.serverTimestamp();

          if (mostVotedPlayerId != null) {
            updates['players.$mostVotedPlayerId.score'] = FieldValue.increment(
              1,
            );
          }
        }

        transaction.update(gameRef, updates);
      } else {
        transaction.update(gameRef, {'votes': votes});
      }
    });
  }

  Future<void> submitQuiPourraitVote(
    String gameCode,
    String voterId,
