  ) => submitVote(gameCode, voterId, votedForId);

  Future<void> submitSynonymeBanVote(
    String gameCode,
    String voterId,
    String bannedTargetPlayerId,
  ) => submitVote(gameCode, voterId, bannedTargetPlayerId);

  Future<void> submitSimplifiedLiarVote(
    String gameCode,
    String voterId,
    String storyOwnerId,
    String voteValue,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    final gameRef = _db.collection('games').doc(gameCode);

    bool allVotesIn = false;
    await _db.runTransaction((transaction) async {
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'voting') return;

      _verifyPlayerAuth(gameData, voterId);

      final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});
      final storyVotes = Map<String, dynamic>.from(votes[storyOwnerId] ?? {});
      storyVotes[voterId] = voteValue;
      votes[storyOwnerId] = storyVotes;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final expectedVotesPerStory =
          players.length - 1; // Tous les joueurs sauf l'auteur

      int completedStories = 0;
      for (final pId in players.keys) {
        final sVotes = Map<String, dynamic>.from(votes[pId] ?? {});
        if (sVotes.length >= expectedVotesPerStory) {
          completedStories++;
        }
      }

      if (completedStories >= players.length) {
        allVotesIn = true;
      }

      transaction.update(gameRef, {'votes': votes});
    });

    if (allVotesIn) {
      final snap = await gameRef.get();
      if (snap.exists) {
        await _tallyVotes(gameRef, snap.data() as Map<String, dynamic>);
      }
    }
  }

  Future<void> submitUndercoverVote(
    String gameCode,
    String voterId,
    String targetPlayerId,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    final gameRef = _db.collection('games').doc(gameCode);
    bool shouldTally = false;

    await _db.runTransaction((transaction) async {
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'voting') return;

      _verifyPlayerAuth(gameData, voterId);

      final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});
      votes[voterId] = targetPlayerId;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final alivePlayers =
          players.entries
              .where((e) => e.value['isEliminated'] != true)
              .map((e) => e.key)
              .toList();

      if (votes.length >= alivePlayers.length) {
        shouldTally = true;
      }

      transaction.update(gameRef, {'votes': votes});
    });

    if (shouldTally) {
      final snap = await gameRef.get();
      if (snap.exists) {
        await _tallyVotes(gameRef, snap.data() as Map<String, dynamic>);
      }
    }
  }

  Future<void> validateMrWhiteGuess(String gameCode, String guess) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    final cleanGuess =
        sanitizeUserInput(guess, maxLength: 40).trim().toLowerCase();

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      final snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      final gameData = snap.data() as Map<String, dynamic>;

      final civilianWord =
          (gameData['civilianWord'] as String? ?? '').trim().toLowerCase();
      final isCorrect = cleanGuess == civilianWord;

      final updates = <String, dynamic>{
        'mrWhiteGuess': cleanGuess,
        'mrWhiteGuessCorrect': isCorrect,
        'roundState': 'result',
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      if (isCorrect) {
        updates['roundWinnerId'] = 'mr_white';
        updates['gameEndReason'] =
            "Mr. White a deviné le mot secret : '$civilianWord' !";
        final mrWhiteId = gameData['mrWhiteId'];
        if (mrWhiteId != null) {
          updates['players.$mrWhiteId.score'] = FieldValue.increment(3);
        }
      } else {
        updates['roundWinnerId'] = 'civilians';
        updates['gameEndReason'] =
            "Mr. White a échoué à deviner le mot (c'était '$civilianWord').";
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> _tallyVotes(
    DocumentReference gameRef,
    Map<String, dynamic> initialGameData,
  ) async {
    await _db.runTransaction((transaction) async {
      final gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      final gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'voting') return;

      final votes = Map.from(gameData['votes'] as Map<String, dynamic>);
      final gameType = gameData['gameType'];
      final updates = <String, dynamic>{};

      if (gameType == 'Le Menteur' && gameData['isSimplifiedLiar'] == true) {
        final storyTruths = Map.from(
          gameData['storyTruths'] as Map<String, dynamic>,
        );
        final players = Map.from(gameData['players'] as Map<String, dynamic>);
        Map<String, int> roundPoints = {for (var pId in players.keys) pId: 0};

        votes.forEach((storyOwnerId, storyVotesMap) {
          final storyVotes = Map.from(storyVotesMap as Map<String, dynamic>);
          final bool actualTruth = storyTruths[storyOwnerId] ?? false;

          storyVotes.forEach((voterId, voteValue) {
            final bool guessedCorrectly =
                (voteValue == 'Vrai' && actualTruth) ||
                (voteValue == 'Faux' && !actualTruth);
            if (guessedCorrectly) {
              roundPoints[voterId] = (roundPoints[voterId] ?? 0) + 1;
            } else {
              roundPoints[storyOwnerId] = (roundPoints[storyOwnerId] ?? 0) + 1;
            }
          });
        });

        roundPoints.forEach((playerId, points) {
          if (points > 0) {
            updates['players.$playerId.score'] = FieldValue.increment(points);
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              playerId,
              points * 10,
              applySpeedBonus: false,
            );
          }
        });
        updates['voteResults'] = votes;
      } else if (gameType == 'Le Roi des Mèmes') {
        Map<String, int> voteCounts = {};
        votes.forEach((voter, votedFor) {
          voteCounts[votedFor] = (voteCounts[votedFor] ?? 0) + 1;
        });

        String? mostVotedPlayerId;
        int maxVotes = -1;
        voteCounts.forEach((playerId, count) {
          if (count > maxVotes) {
            maxVotes = count;
            mostVotedPlayerId = playerId;
          }
        });

        if (mostVotedPlayerId != null) {
          updates['players.$mostVotedPlayerId.score'] = FieldValue.increment(1);
          updates['roundWinnerId'] = mostVotedPlayerId;
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            mostVotedPlayerId!,
            25,
            applySpeedBonus: false,
          );
          updates['gameEndReason'] =
              'La description la plus drôle a été choisie !';
        } else {
          updates['gameEndReason'] = 'Aucune description n\'a été votée.';
        }
        updates['voteResults'] = voteCounts;
      } else if (gameType == 'Qui Pourrait le Plus ?') {
        final Map<String, int> voteCounts = {};
        for (final target in votes.values) {
          voteCounts[target as String] = (voteCounts[target] ?? 0) + 1;
        }

        int maxVotes = 0;
        List<String> topVoted = [];
        voteCounts.forEach((target, count) {
          if (count > maxVotes) {
            maxVotes = count;
            topVoted = [target];
          } else if (count == maxVotes) {
            topVoted.add(target);
          }
        });

        if (topVoted.length == 1) {
          final winner = topVoted.first;
          updates['roundWinnerId'] = winner;
          updates['players.$winner.score'] = FieldValue.increment(1);
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            winner,
            15,
            applySpeedBonus: false,
          );
        } else {
          updates['roundWinnerId'] = null;
          updates['gameEndReason'] = "Égalité parfaite ! Aucun point attribué.";
        }
        updates['voteResults'] = voteCounts;
      } else if (gameType == 'Synonyme ou Banni') {
        final Map<String, int> banCounts = {};
        for (final t in votes.values) {
          banCounts[t as String] = (banCounts[t] ?? 0) + 1;
        }

        int maxVotes = 0;
        List<String> topBanned = [];
        banCounts.forEach((target, count) {
          if (count > maxVotes) {
            maxVotes = count;
            topBanned = [target];
          } else if (count == maxVotes) {
            topBanned.add(target);
          }
        });

        final players = Map<String, dynamic>.from(gameData['players'] ?? {});
        if (topBanned.length == 1) {
          final loserId = topBanned.first;
          updates['roundLoserId'] = loserId;
          updates['roundWinnerId'] = null;

          players.keys.where((id) => id != loserId).forEach((winnerId) {
            updates['players.$winnerId.score'] = FieldValue.increment(1);
            _db
                .collection('users')
                .doc(players[winnerId]?['authUid'] ?? winnerId)
                .set({
                  'unlockedBadges.synonyme_unbanned':
                      FieldValue.serverTimestamp(),
                }, SetOptions(merge: true));
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              winnerId,
              15,
              applySpeedBonus: false,
            );
          });
        } else {
          updates['roundLoserId'] = null;
          updates['gameEndReason'] =
              "Égalité dans les votes : aucun joueur banni ce tour.";
        }
        updates['voteResults'] = banCounts;
      } else {
        Map<String, int> voteCounts = {};
        votes.forEach((voter, votedFor) {
          voteCounts[votedFor] = (voteCounts[votedFor] ?? 0) + 1;
        });

        String? mostVotedPlayerId;
        int maxVotes = 0;
        voteCounts.forEach((playerId, count) {
          if (count > maxVotes) {
            maxVotes = count;
            mostVotedPlayerId = playerId;
          }
        });

        if (gameType == 'La Patate Chaude' && mostVotedPlayerId != null) {
          updates['players.$mostVotedPlayerId.score'] = FieldValue.increment(1);
          updates['roundWinnerId'] = mostVotedPlayerId;
        } else if (gameType == 'Le Menteur') {
          String? actualLiarId = gameData['liarId'];
          if (actualLiarId == null) {
            final privSnap = await gameRef.collection('private_data').get();
            for (var doc in privSnap.docs) {
              if (doc.data()['isLiar'] == true) {
                actualLiarId = doc.id;
                break;
              }
            }
          }
          if (actualLiarId != null) {
            updates['liarId'] = actualLiarId;
            int fooledCount = 0;
            votes.forEach((voterId, votedId) {
              if (votedId == actualLiarId) {
                updates['players.$voterId.score'] = FieldValue.increment(2);
                creditPlayerXp(
                  transaction,
                  gameRef,
                  gameData,
                  voterId,
                  15,
                  applySpeedBonus: false,
                );
              } else {
                fooledCount++;
              }
            });
            if (fooledCount > 0) {
              updates['players.$actualLiarId.score'] = FieldValue.increment(
                fooledCount,
              );
              creditPlayerXp(
                transaction,
                gameRef,
                gameData,
                actualLiarId,
                fooledCount * 12,
                applySpeedBonus: false,
              );
            }
          }
        } else if (gameType == 'Infiltré & Mr. White') {
          String? undercoverId = gameData['undercoverId'];
          String? mrWhiteId = gameData['mrWhiteId'];
          if (undercoverId == null || mrWhiteId == null) {
            final privSnap = await gameRef.collection('private_data').get();
            for (var doc in privSnap.docs) {
              if (doc.data()['role'] == 'Infiltré') undercoverId = doc.id;
              if (doc.data()['role'] == 'Mr. White') mrWhiteId = doc.id;
            }
          }
          if (undercoverId != null) updates['undercoverId'] = undercoverId;
          if (mrWhiteId != null) updates['mrWhiteId'] = mrWhiteId;

          if (mostVotedPlayerId == undercoverId) {
            updates['roundWinnerId'] = 'civilians_and_mrwhite';
            (gameData['players'] as Map).keys
                .where((pId) => pId != undercoverId)
                .forEach((pId) {
                  updates['players.$pId.score'] = FieldValue.increment(1);
                  creditPlayerXp(
                    transaction,
                    gameRef,
                    gameData,
                    pId.toString(),
                    20,
                    applySpeedBonus: false,
                  );
                });
          } else if (mostVotedPlayerId == mrWhiteId) {
            updates['roundWinnerId'] = 'civilians_and_undercover';
            (gameData['players'] as Map).keys
                .where((pId) => pId != mrWhiteId)
                .forEach((pId) {
                  updates['players.$pId.score'] = FieldValue.increment(1);
                  creditPlayerXp(
                    transaction,
                    gameRef,
                    gameData,
                    pId.toString(),
                    20,
                    applySpeedBonus: false,
                  );
                });
          } else {
            updates['roundWinnerId'] = 'impostors';
            if (undercoverId != null) {
              updates['players.$undercoverId.score'] = FieldValue.increment(2);
              creditPlayerXp(
                transaction,
                gameRef,
                gameData,
                undercoverId,
                30,
                applySpeedBonus: false,
              );
            }
            if (mrWhiteId != null) {
              updates['players.$mrWhiteId.score'] = FieldValue.increment(2);
              creditPlayerXp(
                transaction,
                gameRef,
                gameData,
                mrWhiteId,
                30,
                applySpeedBonus: false,
              );
            }
          }
        }
      }

      updates['roundState'] = 'result';
      updates['turnStartTime'] = FieldValue.serverTimestamp();
      transaction.update(gameRef, updates);
    });
  }

  Future<void> selectWinningAnswer(
    String gameCode,
    String winnerPlayerId, {
    String? judgePlayerId,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['roundState'] != 'voting') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final currentJudgeId = gameData['currentTargetPlayerId'] ?? judgePlayerId;
      if (currentJudgeId == null || !players.containsKey(currentJudgeId)) {
        throw Exception("Juge introuvable.");
      }

      final judgeAuthUid =
          players[currentJudgeId]?['authUid'] ?? currentJudgeId;
      if (currentAuthUid != judgeAuthUid) {
        throw Exception("Seul le Juge en titre peut désigner le gagnant.");
      }

      final answers = Map<String, dynamic>.from(gameData['answers'] ?? {});
      if (!answers.containsKey(winnerPlayerId)) {
        throw Exception("Ce joueur n'a pas soumis de réponse.");
      }

      final winnerName = players[winnerPlayerId]?['name'] ?? 'Joueur';

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        winnerPlayerId,
        20,
        applySpeedBonus: false,
      );

      transaction.update(gameRef, {
        'players.$winnerPlayerId.score': FieldValue.increment(1),
        'roundState': 'result',
        'roundWinnerId': winnerPlayerId,
        'turnStartTime': FieldValue.serverTimestamp(),
        'gameLog': FieldValue.arrayUnion(["$winnerName remporte la manche !"]),
      });
    });
  }

  Future<void> sendChatMessage(
    String gameCode,
    String playerId,
    String message,
    String chatType,
  ) async {
    final cleanMessage = message.trim();
    if (cleanMessage.isEmpty) return;
    final safeMessage =
        cleanMessage.length > 150
            ? cleanMessage.substring(0, 150)
            : cleanMessage;

    DocumentReference gameRef = _db.collection('games').doc(gameCode);

    DocumentSnapshot gameSnap = await gameRef.get();
    if (!gameSnap.exists) return;

    var gameData = gameSnap.data() as Map<String, dynamic>;
    var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    var players = Map<String, dynamic>.from(gameData['players'] ?? {});
    String playerName =
        playerData[playerId]?['name'] ??
        players[playerId]?['name'] ??
        'Inconnu';

    // 1. Ajout dans la sous-collection 'chat' pour le FloatingChatOverlay
    await gameRef.collection('chat').add({
      'senderId': playerId,
      'senderName': playerName,
      'text': safeMessage,
      'chatType': chatType,
      'timestamp': FieldValue.serverTimestamp(),
    });

    // 2. Synchronisation dans les tableaux du document pour les canaux Loup-Garou / Infiltré
    await _db.runTransaction((transaction) async {
      DocumentSnapshot freshSnap = await transaction.get(gameRef);
      if (!freshSnap.exists) return;

      var freshData = freshSnap.data() as Map<String, dynamic>;

      Map<String, dynamic> chatMessage = {
        'senderId': playerId,
        'senderName': playerName,
        'message': safeMessage,
        'timestamp': DateTime.now().millisecondsSinceEpoch,
      };

      if (chatType == 'lover') {
        List<String> lovers = List<String>.from(freshData['lovers'] ?? []);
        if (lovers.contains(playerId) && lovers.isNotEmpty) {
          lovers.sort();
          String chatKey = lovers.join('_');
          Map<String, dynamic> loverChat = Map<String, dynamic>.from(
            freshData['loverChatMessages']?[chatKey] ?? {},
          );
          List<dynamic> currentList = List.from(loverChat['messages'] ?? []);
          if (currentList.length >= 30) currentList.removeAt(0);
          currentList.add(chatMessage);
          transaction.update(gameRef, {
            'loverChatMessages.$chatKey.messages': currentList,
          });
        }
        return;
      }

      String fieldToUpdate =
          chatType == 'wolf'
              ? 'wolfChatMessages'
              : (chatType == 'dead' ? 'deadChatMessages' : 'chatMessages');

      List<dynamic> currentList = List.from(freshData[fieldToUpdate] ?? []);
      if (currentList.length >= 30) {
        currentList.removeAt(0);
      }
      currentList.add(chatMessage);

      transaction.update(gameRef, {fieldToUpdate: currentList});
    });

    // Déclenche la vérification du mot pour le Loup Bavard
    await handleLoupBavardChat(gameCode, playerId, safeMessage);
  }

  Future<void> _startZeroPointeRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();

    List<int> deck = [];

    deck.addAll(List.generate(4, (_) => -2));
    deck.addAll(List.generate(6, (_) => -1));
    deck.addAll(List.generate(10, (_) => 0));

    for (int i = 1; i <= 12; i++) {
      deck.addAll(List.generate(10, (_) => i));
    }
    deck.shuffle();

    Map<String, dynamic> playerGrids = {};
    Map<String, dynamic> totalScores = Map.from(gameData['totalScores'] ?? {});
    Map<String, int> revealedCardsCount = {};

    for (String pId in playerIds) {
      List<Map<String, dynamic>> grid = [];
      for (int i = 0; i < 12; i++) {
        grid.add({'value': deck.removeAt(0), 'revealed': false});
      }
      playerGrids[pId] = grid;

      if (!totalScores.containsKey(pId)) {
        totalScores[pId] = 0;
      }
      revealedCardsCount[pId] = 0;
    }

    List<int> discardPile = [deck.removeAt(0)];

    await gameRef.update({
      'gameState': 'playing',
      'roundState':
          'revealing_initial', // Phase oÃƒÂ¹ chaque joueur retourne 2 cartes
      'deck': deck,
      'playerGrids': playerGrids,
      'discardPile': discardPile,
      'playerOrder': playerIds,
      'currentPlayerId': playerIds.first,
      'drawnCard': null,
      'roundEnderId': null,
      'roundScores': {},
      'totalScores': totalScores, // Garder les scores totaux
      'revealedInitialCardsCount': revealedCardsCount,
      'gameLog': [
        "La partie de Zéro Pointé commence ! Chaque joueur doit rÃƒÂ©vÃƒÂ©ler 2 cartes.",
      ],
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> revealInitialZeroPointeCard(
    String gameCode,
    String playerId,
    int cardIndex,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      if (gameData['roundState'] != 'revealing_initial') return;

      var grids = Map<String, dynamic>.from(gameData['playerGrids'] ?? {});
      var counts = Map<String, dynamic>.from(
        gameData['revealedInitialCardsCount'] ?? {},
      );

      var playerGrid =
          (grids[playerId] as List)
              .map((e) => Map<String, dynamic>.from(e as Map))
              .toList();

      if ((counts[playerId] ?? 0) < 2 &&
          playerGrid[cardIndex]['revealed'] == false) {
        playerGrid[cardIndex]['revealed'] = true;
        grids[playerId] = playerGrid;
        counts[playerId] = (counts[playerId] ?? 0) + 1;
        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          2,
          applySpeedBonus: true,
        );
        transaction.update(gameRef, {
          'playerGrids': grids,
          'revealedInitialCardsCount': counts,
        });
      }

      bool allReady = true;
      (gameData['players'] as Map).keys.forEach((pId) {
        if ((counts[pId] ?? 0) < 2) {
          allReady = false;
        }
      });

      if (allReady) {
        transaction.update(gameRef, {
          'roundState': 'player_turn',
          'gameLog': FieldValue.arrayUnion([
            "Tout le monde a révélé ses cartes. La partie commence !",
          ]),
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });
  }

  Future<void> takeDiscardZeroPointe(
    String gameCode,
    String playerId,
    int gridIndexToReplace,
  ) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      if (gameData['currentPlayerId'] != playerId ||
          gameData['roundState'] != 'player_turn') {
        return;
      }

      var grids = Map<String, dynamic>.from(gameData['playerGrids'] ?? {});
      var playerGrid =
          (grids[playerId] as List)
              .map((e) => Map<String, dynamic>.from(e as Map))
              .toList();
      var discardPile = List<int>.from(gameData['discardPile'] ?? []);
      if (discardPile.isEmpty) return;

      int takenCard = discardPile.removeLast();
      int replacedCardValue = playerGrid[gridIndexToReplace]['value'];
      if (replacedCardValue == -100) {
        return; // Ne pas remplacer une case de colonne éliminée
      }

      playerGrid[gridIndexToReplace]['value'] = takenCard;
      playerGrid[gridIndexToReplace]['revealed'] = true;
      grids[playerId] = playerGrid;
      discardPile.add(replacedCardValue);

      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        2,
        applySpeedBonus: true,
      );

      transaction.update(gameRef, {
        'playerGrids': grids,
        'discardPile': discardPile,
      });

      gameData['playerGrids'] = grids;
      await _processZeroPointeTurnEnd(transaction, gameRef, gameData, playerId);
    });
  }

  Future<void> drawFromDeckZeroPointe(String gameCode, String playerId) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      if (players[playerId]?['authUid'] != currentAuthUid) {
        throw Exception("Action non autorisée.");
      }

      if (gameData['currentPlayerId'] != playerId ||
          gameData['roundState'] != 'player_turn') {
        return;
      }

      var deck = List<int>.from(gameData['deck'] ?? []);
      var discardPile = List<int>.from(gameData['discardPile'] ?? []);

      // Recyclage automatique si pioche vide
      if (deck.isEmpty) {
        if (discardPile.length > 1) {
          int topDiscard = discardPile.removeLast();
          deck = List<int>.from(discardPile)..shuffle();
          discardPile = [topDiscard];
        } else {
          throw Exception("Plus aucune carte disponible.");
        }
      }

      int drawnCard = deck.removeAt(0);

      transaction.update(gameRef, {
        'deck': deck,
        'discardPile': discardPile,
        'drawnCard': drawnCard,
        'roundState': 'drawn_card_phase',
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    });
  }

