  Future<void> _startPokerHand(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds =
        players.keys
            .toList(); // Ne pas mÃƒÂ©langer pour garder l'ordre des blinds

    Map<String, dynamic> playerData = Map.from(gameData['playerData'] ?? {});
    bool isFirstHand = playerData.isEmpty;
    if (isFirstHand) {
      int startChips = gameData['startChips'] ?? 1000;
      for (String pId in playerIds) {
        playerData[pId] = {
          'name': players[pId]['name'],
          'chips': startChips,
          'hand': [],
          'currentBet': 0,
          'status': 'active', // 'active', 'folded', 'all-in'
        };
      }
    } else {
      playerData.forEach((pId, data) {
        playerData[pId]['hand'] = [];
        playerData[pId]['currentBet'] = 0;
        playerData[pId]['status'] = (data['chips'] ?? 0) > 0 ? 'active' : 'out';
      });

      List<String> playersWithChips =
          playerData.entries
              .where((e) => (e.value['chips'] as num? ?? 0) > 0)
              .map((e) => e.key)
              .toList();

      if (playersWithChips.length <= 1) {
        String winner =
            playersWithChips.isNotEmpty
                ? playersWithChips.first
                : playerIds.first;
        String winnerName =
            playerData[winner]?['name'] ?? players[winner]?['name'] ?? 'Joueur';
        await gameRef.update({
          'gameState': 'gameOver',
          'gameWinner': winner,
          'gameEndReason':
              "$winnerName a remporté tous les jetons de la table !",
        });
        return;
      }
    }

    List<String> suits = [
      'H',
      'D',
      'C',
      'S',
    ]; // Coeur, Carreau, TrÃƒÂ¨fle, Pique
    List<String> ranks = [
      '2',
      '3',
      '4',
      '5',
      '6',
      '7',
      '8',
      '9',
      'T',
      'J',
      'Q',
      'K',
      'A',
    ];
    List<String> deck = [
      for (var suit in suits)
        for (var rank in ranks) '$rank$suit',
    ]..shuffle();

    playerData.forEach((pId, data) {
      if (data['status'] == 'active') {
        playerData[pId]['hand'] = [deck.removeAt(0), deck.removeAt(0)];
      }
    });

    // Helper to find next non-out player index
    int nextActivePokerIndex(int fromIndex) {
      int idx = (fromIndex + 1) % playerIds.length;
      int safety = 0;
      while (playerData[playerIds[idx]]?['status'] == 'out' &&
          safety < playerIds.length) {
        idx = (idx + 1) % playerIds.length;
        safety++;
      }
      return idx;
    }

    int dealerIndex = nextActivePokerIndex(
      (gameData['dealerIndex'] as int?) ?? -1,
    );
    int smallBlindIndex = nextActivePokerIndex(dealerIndex);
    int bigBlindIndex = nextActivePokerIndex(smallBlindIndex);
    int firstToActIndex = nextActivePokerIndex(bigBlindIndex);

    String smallBlindId = playerIds[smallBlindIndex];
    String bigBlindId = playerIds[bigBlindIndex];

    int smallBlindAmount = gameData['smallBlind'] ?? 10;
    int bigBlindAmount = gameData['bigBlind'] ?? 20;

    int smallBlindActual =
        (playerData[smallBlindId]['chips'] as int) < smallBlindAmount
            ? (playerData[smallBlindId]['chips'] as int)
            : smallBlindAmount;
    int bigBlindActual =
        (playerData[bigBlindId]['chips'] as int) < bigBlindAmount
            ? (playerData[bigBlindId]['chips'] as int)
            : bigBlindAmount;

    playerData[smallBlindId]['chips'] -= smallBlindActual;
    playerData[smallBlindId]['currentBet'] = smallBlindActual;
    playerData[bigBlindId]['chips'] -= bigBlindActual;
    playerData[bigBlindId]['currentBet'] = bigBlindActual;
    int pot = smallBlindActual + bigBlindActual;

    await gameRef.update({
      'gameState': 'playing',
      'phase': 'pre-flop',
      'playerData': playerData,
      'deck': deck,
      'communityCards': [],
      'pot': pot,
      'dealerIndex': dealerIndex,
      'currentPlayerIndex': firstToActIndex,
      'playerOrder': playerIds, // Important pour l'ordre de jeu
      'currentBet': bigBlindActual,
      'lastRaiserId': bigBlindId,
      'smallBlindIndex': smallBlindIndex,
      'bigBlindIndex': bigBlindIndex,
      'handLog': [
        "Nouvelle main ! ${players[playerIds[dealerIndex]]['name']} est le donneur.",
        "${players[smallBlindId]['name']} pose la petite blind de $smallBlindActual.",
        "${players[bigBlindId]['name']} pose la grosse blind de $bigBlindActual.",
      ],
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> pokerAction(
    String gameCode,
    String playerId,
    String action, {
    int? amount,
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    try {
      await _db.runTransaction((transaction) async {
        final gameRef = _db.collection('games').doc(gameCode);
        DocumentSnapshot gameSnap = await transaction.get(gameRef);

        if (!gameSnap.exists) {
          throw Exception("La partie n'existe pas.");
        }

        var gameData = gameSnap.data() as Map<String, dynamic>;
        final players = Map<String, dynamic>.from(gameData['players'] ?? {});

        // SÉCURITÉ : Vérifier l'authUid
        final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
        if (!isAuto && currentAuthUid != voterAuthUid) {
          throw Exception("Action non autorisée.");
        }

        List<String> playerOrder = List<String>.from(
          gameData['playerOrder'] ?? [],
        );
        final int currentPlayerIndex =
            (gameData['currentPlayerIndex'] as num? ?? 0).toInt();

        if (playerOrder.isEmpty || currentPlayerIndex >= playerOrder.length) {
          throw Exception(
            "Données de jeu invalides (playerOrder/currentPlayerIndex).",
          );
        }
        if (playerOrder[currentPlayerIndex] != playerId) {
          throw Exception("Ce n'est pas le tour de $playerId.");
        }

        var playerData = Map<String, dynamic>.from(
          json.decode(json.encode(gameData['playerData'] ?? {})),
        );
        var myData = playerData[playerId];

        if (myData == null) {
          throw Exception("Données du joueur $playerId introuvables.");
        }

        int currentBet = (gameData['currentBet'] as num? ?? 0).toInt();
        int pot = (gameData['pot'] as num? ?? 0).toInt();
        List<String> handLog = List<String>.from(gameData['handLog'] ?? []);
        String? lastRaiserId = gameData['lastRaiserId'];

        Map<String, dynamic> allUpdates = {};

        switch (action) {
          case 'fold':
            myData['status'] = 'folded';
            handLog.add("${myData['name']} se couche.");
            break;
          case 'check':
            if ((myData['currentBet'] as num).toInt() < currentBet) {
              throw Exception("Vous ne pouvez pas checker, quelqu'un a misé.");
            }
            handLog.add("${myData['name']} check.");
            break;
          case 'call':
            int callAmount = currentBet - (myData['currentBet'] as num).toInt();
            if (callAmount >= (myData['chips'] as num).toInt()) {
              callAmount = (myData['chips'] as num).toInt();
              myData['status'] = 'all-in';
              handLog.add("${myData['name']} fait tapis (all-in) !");
            } else {
              handLog.add("${myData['name']} suit pour $callAmount.");
            }
            myData['chips'] -= callAmount;
            myData['currentBet'] += callAmount;
            pot += callAmount;
            break;
          case 'raise':
            if (amount == null) {
              throw Exception("Montant de relance requis.");
            }
            int totalBetAmount = (amount as num).toInt();
            if (totalBetAmount <= currentBet) {
              throw Exception(
                "La relance doit être strictement supérieure à la mise actuelle.",
              );
            }
            int maxPossibleBet =
                (myData['chips'] as num).toInt() +
                (myData['currentBet'] as num).toInt();
            if (totalBetAmount > maxPossibleBet) {
              throw Exception(
                "Vous n'avez pas assez de jetons pour cette relance.",
              );
            }

            // Règle de relance minimale (au moins le double de la mise précédente, ou tapis)
            int minRaise = currentBet * 2;
            if (totalBetAmount < minRaise && totalBetAmount < maxPossibleBet) {
              throw Exception(
                "La relance doit être d'au moins le double de la mise précédente (ou faire tapis).",
              );
            }

            int raiseAmount =
                totalBetAmount - (myData['currentBet'] as num).toInt();
            myData['chips'] -= raiseAmount;
            myData['currentBet'] = totalBetAmount;
            pot += raiseAmount;
            currentBet = totalBetAmount;
            lastRaiserId = playerId;

            if ((myData['chips'] as num).toInt() == 0) {
              myData['status'] = 'all-in';
              handLog.add(
                "${myData['name']} fait tapis (all-in) en relançant à $totalBetAmount !",
              );
            } else {
              handLog.add("${myData['name']} relance à $totalBetAmount.");
            }
            break;
        }
        playerData[playerId] = myData;

        int xpBase =
            (action == 'raise' || action == 'call')
                ? ((myData['status'] == 'all-in') ? 15 : 3)
                : 0;
        if (xpBase > 0) {
          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            playerId,
            xpBase,
            applySpeedBonus: true,
          );
        }

        var updatedGameData = Map<String, dynamic>.from(gameData);
        updatedGameData['playerData'] = playerData;
        updatedGameData['pot'] = pot;
        updatedGameData['currentBet'] = currentBet;
        updatedGameData['lastRaiserId'] = lastRaiserId;
        updatedGameData['handLog'] = handLog;

        final turnUpdates = _advancePokerTurn(updatedGameData);

        allUpdates.addAll({
          'playerData': playerData,
          'pot': pot,
          'currentBet': currentBet,
          'lastRaiserId': lastRaiserId,
          'handLog': handLog,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
        allUpdates.addAll(turnUpdates);

        transaction.update(gameRef, allUpdates);
      });
    } catch (e) {
      rethrow;
    }
  }

  Map<String, dynamic> _advancePokerTurn(Map<String, dynamic> gameData) {
    List<String> playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    int currentIndex = (gameData['currentPlayerIndex'] as num? ?? 0).toInt();
    String? lastRaiserId = gameData['lastRaiserId'];

    if (playerOrder.isEmpty || playerData.isEmpty) return {};

    List<String> activePlayers =
        playerOrder
            .where((pId) => playerData[pId]?['status'] != 'folded')
            .toList();
    if (activePlayers.length <= 1) {
      return _determinePokerWinner(gameData);
    }

    int nextIndex = currentIndex;
    int safetyCounter = 0;
    do {
      nextIndex = (nextIndex + 1) % playerOrder.length;
      safetyCounter++;
    } while ((playerData[playerOrder[nextIndex]]?['status'] == 'folded' ||
            playerData[playerOrder[nextIndex]]?['status'] == 'all-in') &&
        safetyCounter <= playerOrder.length);

    if (safetyCounter > playerOrder.length) {
      var updatedData = Map<String, dynamic>.from(gameData);
      Map<String, dynamic> allUpdates = {};
      while (updatedData['phase'] != 'river') {
        final phaseUpdates = _startNextPokerPhase(updatedData);
        allUpdates.addAll(phaseUpdates);
        updatedData.addAll(phaseUpdates);
      }
      allUpdates.addAll(_determinePokerWinner(updatedData));
      return allUpdates;
    }

    String nextPlayerId = playerOrder[nextIndex];

    bool allBetsMatched = activePlayers
        .where((pId) => playerData[pId]?['status'] == 'active')
        .every(
          (pId) =>
              (playerData[pId]?['currentBet'] as num? ?? 0).toInt() ==
              (gameData['currentBet'] as num? ?? 0).toInt(),
        );

    bool isRoundComplete =
        (nextPlayerId == lastRaiserId) ||
        (lastRaiserId != null &&
            playerData[lastRaiserId]?['status'] == 'folded' &&
            allBetsMatched) ||
        (lastRaiserId == null && nextIndex == (gameData['bigBlindIndex'] ?? 0));

    if (isRoundComplete) {
      Map<String, dynamic> currentData = Map.from(gameData);
      final phaseUpdates = _startNextPokerPhase(currentData);
      currentData.addAll(phaseUpdates);

      if (currentData['phase'] == 'showdown') {
        phaseUpdates.addAll(_determinePokerWinner(currentData));
      }
      return phaseUpdates;
    } else {
      return {'currentPlayerIndex': nextIndex};
    }
  }

  Map<String, dynamic> _startNextPokerPhase(Map<String, dynamic> gameData) {
    String currentPhase = gameData['phase'];
    String nextPhase = '';
    List<dynamic> communityCards = List.from(gameData['communityCards'] ?? []);
    List<dynamic> deck = List.from(gameData['deck'] ?? []);
    List<String> log = List.from(gameData['handLog'] ?? []);

    Map<String, dynamic> updates = {};

    switch (currentPhase) {
      case 'pre-flop':
        nextPhase = 'flop';
        if (deck.length >= 3)
          communityCards.addAll([
            deck.removeAt(0),
            deck.removeAt(0),
            deck.removeAt(0),
          ]);
        log.add("--- FLOP ---");
        break;
      case 'flop':
        nextPhase = 'turn';
        if (deck.isNotEmpty) communityCards.add(deck.removeAt(0));
        log.add("--- TURN ---");
        break;
      case 'turn':
        nextPhase = 'river';
        if (deck.isNotEmpty) communityCards.add(deck.removeAt(0));
        log.add("--- RIVER ---");
        break;
      case 'river':
        nextPhase = 'showdown';
        log.add("--- ABATTAGE (SHOWDOWN) ---");
        break;
      default:
        return {}; // Ne rien faire si la phase est inconnue
    }

    var playerData = Map<String, dynamic>.from(
      json.decode(json.encode(gameData['playerData'])),
    );
    List<String> playerOrder = List.from(gameData['playerOrder'] ?? []);
    int dealerIndex = (gameData['dealerIndex'] as num? ?? -1).toInt();

    playerData.forEach((pId, data) {
      if (data['status'] != 'folded') {
        data['currentBet'] = 0;
      }
    });

    int firstToActIndex = (dealerIndex + 1) % playerOrder.length;
    int count = 0;
    while (playerData[playerOrder[firstToActIndex]]?['status'] != 'active') {
      firstToActIndex = (firstToActIndex + 1) % playerOrder.length;
      count++;
      if (count > playerOrder.length) break;
    }

    updates.addAll({
      'phase': nextPhase,
      'communityCards': communityCards,
      'deck': deck,
      'handLog': log,
      'playerData': playerData,
      'currentBet': 0,
      'currentPlayerIndex': firstToActIndex,
      'lastRaiserId': playerOrder[firstToActIndex],
    });

    return updates;
  }

  Map<String, dynamic> _determinePokerWinner(Map<String, dynamic> gameData) {
    var playerData = Map<String, dynamic>.from(
      json.decode(json.encode(gameData['playerData'])),
    );
    final communityCards =
        (gameData['communityCards'] as List<dynamic>? ?? [])
            .cast<String>()
            .toList();
    List<String> playersInHand =
        playerData.keys
            .where((pId) => playerData[pId]?['status'] != 'folded')
            .toList();

    String winnerAnnouncement = "";
    List<String> winners = [];
    PokerHand? bestHand;

    if (playersInHand.length == 1) {
      winners.add(playersInHand.first);
      winnerAnnouncement =
          "${playerData[winners.first]['name']} gagne le pot par forfait !";
    } else {
      Map<String, PokerHand> playerFinalHands = {};
      for (String pId in playersInHand) {
        final playerHand =
            (playerData[pId]['hand'] as List<dynamic>? ?? [])
                .cast<String>()
                .toList();
        final sevenCards = [...playerHand, ...communityCards];
        playerFinalHands[pId] = PokerHandEvaluator.evaluateHand(sevenCards);
      }

      playerFinalHands.forEach((pId, hand) {
        if (bestHand == null || hand.compareTo(bestHand!) > 0) {
          bestHand = hand;
          winners = [pId];
        } else if (hand.compareTo(bestHand!) == 0) {
          winners.add(pId);
        }
      });

      final winnerNames = winners
          .map((id) => playerData[id]?['name'] ?? 'Inconnu')
          .join(' et ');
      winnerAnnouncement =
          "$winnerNames gagne(nt) le pot avec ${bestHand?.rank.name ?? 'une main'} !";
    }

    Map<String, dynamic> scoreUpdates = {};
    if (winners.isNotEmpty) {
      int pot = (gameData['pot'] as num? ?? 0).toInt();
      int potPerWinner = (pot / winners.length).floor();

      for (String winId in winners) {
        playerData[winId]['chips'] += potPerWinner;
        int winXp = 30;
        if (bestHand?.rank == HandRank.straight ||
            bestHand?.rank == HandRank.flush ||
            bestHand?.rank == HandRank.fullHouse ||
            bestHand?.rank == HandRank.fourOfAKind ||
            bestHand?.rank == HandRank.straightFlush ||
            bestHand?.rank == HandRank.royalFlush) {
          winXp = 50;
        }
        final authUid = playerData[winId]['authUid'] ?? winId;
        _db.collection('users').doc(authUid).set({
          'xp': FieldValue.increment(winXp),
        }, SetOptions(merge: true));
        playerData[winId]['xp'] =
            ((playerData[winId]['xp'] as num?)?.toInt() ?? 0) + winXp;
        scoreUpdates['players.$winId.xp'] = FieldValue.increment(winXp);
      }
    }

    List<String> handLog = List.from(gameData['handLog'] ?? []);
    handLog.add(winnerAnnouncement);

    return {
      'phase': 'hand_over',
      'playerData': playerData,
      'handLog': handLog,
      'showdownHands': {
        for (var pId in playersInHand) pId: playerData[pId]['hand'],
      },
      'turnStartTime': FieldValue.serverTimestamp(),
      ...scoreUpdates,
    };
  }

  List<String> _generateBeloteDeck() {
    const suits = ['H', 'D', 'C', 'S'];
    const ranks = ['7', '8', '9', '10', 'J', 'Q', 'K', 'A'];
    List<String> deck = [];
    for (var s in suits) {
      for (var r in ranks) {
        deck.add('$r$s');
      }
    }
    deck.shuffle();
    return deck;
  }

  Future<void> _startBeloteRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();
    if (playerIds.length != 4) {
      throw Exception("La Belote requiert exactement 4 joueurs.");
    }

    List<String> deck = _generateBeloteDeck();
    Map<String, dynamic> playerData = {};

    // Équipes : 0 & 2 = teamA, 1 & 3 = teamB
    for (int i = 0; i < 4; i++) {
      String pId = playerIds[i];
      List<String> hand = [];
      for (int j = 0; j < 5; j++) {
        hand.add(deck.removeAt(0));
      }
      playerData[pId] = {
        'name': players[pId]['name'],
        'team': (i % 2 == 0) ? 'teamA' : 'teamB',
        'hand': hand,
      };
    }

    String turnedCard = deck.removeAt(0);

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'bidding',
      'beloteDeck': deck,
      'beloteTurnedCard': turnedCard,
      'beloteTrumpSuit': null,
      'beloteTakerId': null,
      'belotePlayerData': playerData,
      'belotePlayerOrder': playerIds,
      'beloteCurrentPlayerIndex': 0,
      'beloteCurrentTrick': {},
      'beloteTeamScores':
          gameData['beloteTeamScores'] ?? {'teamA': 0, 'teamB': 0},
      'beloteTargetScore': gameData['beloteTargetScore'] ?? 500,
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': FieldValue.arrayUnion(["La partie de Belote commence !"]),
    });
  }

  Future<void> beloteAction(
    String gameCode,
    String playerId,
    String action, {
    String? card,
    String? suit,
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['gameState'] != 'playing') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (!isAuto && currentAuthUid != voterAuthUid) {
        throw Exception("Action non autorisée.");
      }

      Map<String, dynamic> playerData = Map.from(gameData['belotePlayerData']);
      List<String> playerOrder = List.from(gameData['belotePlayerOrder']);
      int currentIndex = gameData['beloteCurrentPlayerIndex'];

      if (playerOrder[currentIndex] != playerId) {
        throw Exception("Ce n'est pas votre tour.");
      }

      if (action == 'bid' && suit != null) {
        List<String> deck = List<String>.from(gameData['beloteDeck']);
        String turnedCard = gameData['beloteTurnedCard'];

        // Le preneur prend la carte retournée + 2 cartes du paquet (total 8)
        List<String> takerHand = List<String>.from(
          playerData[playerId]['hand'],
        );
        takerHand.add(turnedCard);
        for (int i = 0; i < 2; i++) {
          if (deck.isNotEmpty) takerHand.add(deck.removeAt(0));
        }
        playerData[playerId]['hand'] = takerHand;

        // Les 3 autres reçoivent 3 cartes
        for (String pId in playerOrder) {
          if (pId == playerId) continue;
          List<String> hand = List<String>.from(playerData[pId]['hand']);
          for (int i = 0; i < 3; i++) {
            if (deck.isNotEmpty) hand.add(deck.removeAt(0));
          }
          playerData[pId]['hand'] = hand;
        }

        creditPlayerXp(
          transaction,
          gameRef,
          gameData,
          playerId,
          5,
          applySpeedBonus: true,
        );

        transaction.update(gameRef, {
          'beloteDeck': deck,
          'beloteTrumpSuit': suit,
          'beloteTakerId': playerId,
          'belotePlayerData': playerData,
          'roundState': 'playing_trick',
          'beloteCurrentTrick': {},
          'beloteCurrentPlayerIndex': 0,
          'turnStartTime': FieldValue.serverTimestamp(),
          'gameLog': FieldValue.arrayUnion([
            "${playerData[playerId]['name']} a pris à $suit !",
          ]),
        });
      } else if (action == 'pass') {
        int nextIndex = (currentIndex + 1) % playerOrder.length;
        transaction.update(gameRef, {
          'beloteCurrentPlayerIndex': nextIndex,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      } else if (action == 'play' && card != null) {
        List<String> hand = List.from(playerData[playerId]['hand']);
        if (!hand.contains(card)) throw Exception("Carte non possédée.");

        Map<String, dynamic> currentTrick = Map.from(
          gameData['beloteCurrentTrick'] ?? {},
        );
        String trumpSuit = gameData['beloteTrumpSuit'] ?? 'H';

        // Validation de jeu (Fournir la couleur si possible)
        if (currentTrick.isNotEmpty) {
          String ledCard = currentTrick.values.first as String;
          String ledSuit = ledCard.substring(ledCard.length - 1);
          String playedSuit = card.substring(card.length - 1);
          bool hasLedSuit = hand.any((c) => c.endsWith(ledSuit));

          if (hasLedSuit && playedSuit != ledSuit) {
            throw Exception(
              "Vous devez fournir la couleur demandée ($ledSuit).",
            );
          }
        }

        hand.remove(card);
        playerData[playerId]['hand'] = hand;
        currentTrick[playerId] = card;

        if (currentTrick.length == 4) {
          String winningPlayer = currentTrick.keys.first;
          String ledCard = currentTrick.values.first as String;
          String ledSuit = ledCard.substring(ledCard.length - 1);
          int highestPower = -1;

          currentTrick.forEach((pId, c) {
            String cSuit = c.substring(c.length - 1);
            String rank = c.substring(0, c.length - 1);
            bool isTrump = (cSuit == trumpSuit);
            int cardPower = _getBeloteCardValue(c, isTrump);
            int cardRank = _getBeloteCardRank(rank, isTrump);

            int totalPower = 0;
            if (isTrump) {
              totalPower = 2000 + (cardPower * 10) + cardRank; // Atout bat tout
            } else if (cSuit == ledSuit) {
              totalPower =
                  1000 + (cardPower * 10) + cardRank; // Couleur demandée
            } else {
              totalPower = 0; // Pisse / Défausse
            }

            if (totalPower > highestPower) {
              highestPower = totalPower;
              winningPlayer = pId;
            }
          });

          int trickPoints = 0;
          currentTrick.values.forEach((c) {
            trickPoints += _getBeloteCardValue(c, c.endsWith(trumpSuit));
          });

          if (trickPoints >= 162) {
            final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
            if (currentAuthUid != null) {
              _db.collection('users').doc(currentAuthUid).set({
                'unlockedBadges.belote_capot': FieldValue.serverTimestamp(),
              }, SetOptions(merge: true));
            }
          }

          String winnerTeam = playerData[winningPlayer]['team'];
          Map<String, dynamic> teamScores = Map.from(
            gameData['beloteTeamScores'] ?? {'teamA': 0, 'teamB': 0},
          );
          teamScores[winnerTeam] = (teamScores[winnerTeam] ?? 0) + trickPoints;

          bool roundOver = playerOrder.every(
            (pId) => (playerData[pId]['hand'] as List).isEmpty,
          );

          creditPlayerXp(
            transaction,
            gameRef,
            gameData,
            winningPlayer,
            5,
            applySpeedBonus: false,
          );
          if (roundOver) {
            creditPlayerXp(
              transaction,
              gameRef,
              gameData,
              winningPlayer,
              20,
              applySpeedBonus: false,
            );
          }

          if (roundOver) {
            teamScores[winnerTeam] =
                (teamScores[winnerTeam] ?? 0) + 10; // Dix de der
            int targetScore = gameData['beloteTargetScore'] ?? 500;
            bool gameOver =
                (teamScores['teamA'] >= targetScore) ||
                (teamScores['teamB'] >= targetScore);

            transaction.update(gameRef, {
              'belotePlayerData': playerData,
              'beloteTeamScores': teamScores,
              'beloteCurrentTrick': {},
              'roundState': gameOver ? 'gameOver' : 'round_over',
              'gameState': gameOver ? 'gameOver' : 'playing',
              'gameWinner':
                  gameOver
                      ? (teamScores['teamA'] > teamScores['teamB']
                          ? 'teamA'
                          : 'teamB')
                      : null,
              'turnStartTime': FieldValue.serverTimestamp(),
            });
          } else {
            int winnerIndex = playerOrder.indexOf(winningPlayer);
            transaction.update(gameRef, {
              'belotePlayerData': playerData,
              'beloteTeamScores': teamScores,
              'beloteCurrentTrick': {},
              'beloteCurrentPlayerIndex': winnerIndex,
              'turnStartTime': FieldValue.serverTimestamp(),
            });
          }
        } else {
          int nextIndex = (currentIndex + 1) % playerOrder.length;
          transaction.update(gameRef, {
            'belotePlayerData': playerData,
            'beloteCurrentTrick': currentTrick,
            'beloteCurrentPlayerIndex': nextIndex,
            'turnStartTime': FieldValue.serverTimestamp(),
          });
        }
      }
    });
  }

  int _getBeloteCardValue(String card, bool isTrump) {
    String rank = card.substring(0, card.length - 1);
    if (isTrump) {
      switch (rank) {
        case 'J':
          return 20;
        case '9':
          return 14;
        case 'A':
          return 11;
        case '10':
          return 10;
        case 'K':
          return 4;
        case 'Q':
          return 3;
        case '8':
          return 0;
        case '7':
          return 0;
        default:
          return 0;
      }
    } else {
      switch (rank) {
        case 'A':
          return 11;
        case '10':
          return 10;
        case 'K':
          return 4;
        case 'Q':
          return 3;
        case 'J':
          return 2;
        case '9':
          return 0;
        case '8':
          return 0;
        case '7':
          return 0;
        default:
          return 0;
      }
    }
  }

  int _getBeloteCardRank(String rank, bool isTrump) {
    if (isTrump) {
      const order = {
        '7': 0,
        '8': 1,
        'Q': 2,
        'K': 3,
        '10': 4,
        'A': 5,
        '9': 6,
        'J': 7,
      };
      return order[rank] ?? 0;
    } else {
      const order = {
        '7': 0,
        '8': 1,
        '9': 2,
        'J': 3,
        'Q': 4,
        'K': 5,
        '10': 6,
        'A': 7,
      };
      return order[rank] ?? 0;
    }
  }

  // Gestion du timeout (si un joueur ne joue pas à temps)
  Future<void> handleBeloteTimeout(String gameCode) async {
    final gameRef = _db.collection('games').doc(gameCode);
    final snap = await gameRef.get();
    if (!snap.exists) return;
    final gameData = snap.data() as Map<String, dynamic>;
    if (gameData['gameState'] != 'playing') return;
    if (!_isTurnTimedOut(gameData)) return;

    final playerOrder = gameData['belotePlayerOrder'] as List<dynamic>?;
    final currentIndex = gameData['beloteCurrentPlayerIndex'] as int?;
    if (playerOrder != null && currentIndex != null && playerOrder.isNotEmpty) {
      String timedOutPlayerId = playerOrder[currentIndex];
      String roundState = gameData['roundState'];
      final playerName =
          gameData['players']?[timedOutPlayerId]?['name'] ?? 'Un joueur';

      if (roundState == 'bidding') {
        await notifyAutoPlay(
          gameRef,
          playerName,
          actionDetails: "passe l'annonce",
        );
        await beloteAction(gameCode, timedOutPlayerId, 'pass', isAuto: true);
      } else if (roundState == 'playing_trick') {
        List<String> hand = List<String>.from(
          gameData['belotePlayerData']?[timedOutPlayerId]?['hand'] ?? [],
        );
        if (hand.isNotEmpty) {
          final currentTrick = Map<String, dynamic>.from(
            gameData['beloteCurrentTrick'] ?? {},
          );
          String cardToPlay = hand.first;

          if (currentTrick.isNotEmpty) {
            String ledCard = currentTrick.values.first as String;
            String ledSuit = ledCard.substring(ledCard.length - 1);
            // Chercher en priorité une carte de la couleur demandée
            final matchingCard = hand.firstWhere(
              (c) => c.endsWith(ledSuit),
              orElse: () => '',
            );
            if (matchingCard.isNotEmpty) {
              cardToPlay = matchingCard;
            }
          }

          await notifyAutoPlay(
            gameRef,
            playerName,
            actionDetails: "carte $cardToPlay",
          );
          await beloteAction(
            gameCode,
            timedOutPlayerId,
            'play',
            card: cardToPlay,
            isAuto: true,
          );
        }
      }
    }
  }

  Future<void> _startBlokusRound(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds = players.keys.toList()..shuffle();
    final colors = ['blue', 'red', 'green', 'yellow'];

    Map<String, String> playerColors = {};
    Map<String, List<int>> playerHands = {};
    Map<String, bool> firstPiecePlaced = {};

    for (int i = 0; i < playerIds.length; i++) {
      playerColors[playerIds[i]] = colors[i % 4];
      playerHands[playerIds[i]] = List.generate(21, (index) => index + 1);
      firstPiecePlaced[playerIds[i]] = false;
    }

    await gameRef.update({
      'gameState': 'playing',
      'roundState': 'playing_turn',
      'blokusBoard': {}, // Map<String, String> "row_col": "color"
      'blokusPlayerColors': playerColors,
      'blokusPlayerHands': playerHands,
      'blokusFirstPiecePlaced': firstPiecePlaced,
      'blokusPlayerOrder': playerIds,
      'blokusCurrentPlayerIndex': 0,
      'blokusPassedPlayers': [],
      'turnStartTime': FieldValue.serverTimestamp(),
      'gameLog': ["La partie de Blokus commence !"],
    });
  }

  Future<void> placeBlokusPiece(
    String gameCode,
    String playerId,
    int pieceId,
    int startRow,
    int startCol,
    int rotation, {
    bool flipped = false,
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;

      // SÉCURITÉ AUTH
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (!isAuto && currentAuthUid != voterAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final playerOrder = List<String>.from(gameData['blokusPlayerOrder']);
      if (playerOrder[gameData['blokusCurrentPlayerIndex']] != playerId) {
        throw Exception("Ce n'est pas votre tour.");
      }

      final myColor = gameData['blokusPlayerColors'][playerId];
      final hand = List<int>.from(gameData['blokusPlayerHands'][playerId]);
      if (!hand.contains(pieceId)) throw Exception("Pièce déjà utilisée.");

      final board = Map<String, String>.from(gameData['blokusBoard'] ?? {});
      final isFirstPiece =
          !(gameData['blokusFirstPiecePlaced'][playerId] ?? false);

      // Prise en compte du flipped côté serveur
      final rotatedPiece = GameData.getRotatedPiece(
        pieceId,
        rotation,
        flipped: flipped,
      );
      final absoluteCoords =
          rotatedPiece.map((p) => [p[0] + startRow, p[1] + startCol]).toList();

      // 1. Limites et Chevauchement
      for (var c in absoluteCoords) {
        if (c[0] < 0 || c[0] >= 20 || c[1] < 0 || c[1] >= 20) {
          throw Exception("Hors limites !");
        }
        if (board.containsKey("${c[0]}_${c[1]}")) {
          throw Exception("Case déjà occupée !");
        }
      }

      // 2. Règle des côtés (Orthogonal interdit)
      for (var c in absoluteCoords) {
        List<List<int>> neighbors = [
          [c[0] - 1, c[1]],
          [c[0] + 1, c[1]],
          [c[0], c[1] - 1],
          [c[0], c[1] + 1],
        ];
        for (var n in neighbors) {
          if (board["${n[0]}_${n[1]}"] == myColor) {
            throw Exception("Contact par le côté interdit !");
          }
        }
      }

      // 3. Règle des coins (Diagonal obligatoire)
      bool touchesCorner = false;
      for (var c in absoluteCoords) {
        List<List<int>> diags = [
          [c[0] - 1, c[1] - 1],
          [c[0] - 1, c[1] + 1],
          [c[0] + 1, c[1] - 1],
          [c[0] + 1, c[1] + 1],
        ];
        for (var d in diags) {
          if (board["${d[0]}_${d[1]}"] == myColor) {
            touchesCorner = true;
            break;
          }
        }
        if (touchesCorner) break;
      }

      if (isFirstPiece) {
        String cornerTarget =
            myColor == 'blue'
                ? "0_0"
                : myColor == 'red'
                ? "19_19"
                : myColor == 'green'
                ? "0_19"
                : "19_0";
        bool coversCorner = absoluteCoords.any(
          (c) => "${c[0]}_${c[1]}" == cornerTarget,
        );
        if (!coversCorner) {
          throw Exception(
            "Le premier coup doit couvrir votre coin de départ !",
          );
        }
      } else {
        if (!touchesCorner) {
          throw Exception(
            "Votre pièce doit toucher une de vos pièces par un coin !",
          );
        }
      }

      // Placement effectif
      for (var c in absoluteCoords) {
        board["${c[0]}_${c[1]}"] = myColor;
      }
      hand.remove(pieceId);

      // Mémoriser la dernière pièce posée pour le bonus 1x1
      Map<String, dynamic> lastPiecesPlaced = Map<String, dynamic>.from(
        gameData['blokusLastPiecesPlaced'] ?? {},
      );
      lastPiecesPlaced[playerId] = pieceId;

      int xpBase = (pieceId == 1) ? 15 : (hand.isEmpty ? 40 : 5);
      creditPlayerXp(
        transaction,
        gameRef,
        gameData,
        playerId,
        xpBase,
        applySpeedBonus: true,
      );

      Map<String, dynamic> updates = {
        'blokusBoard': board,
        'blokusPlayerHands.$playerId': hand,
        'blokusFirstPiecePlaced.$playerId': true,
        'blokusLastPiecesPlaced': lastPiecesPlaced,
      };

      List<String> passedPlayers = List<String>.from(
        gameData['blokusPassedPlayers'] ?? [],
      );
      if (hand.isEmpty && !passedPlayers.contains(playerId)) {
        passedPlayers.add(playerId);
        updates['blokusPassedPlayers'] = passedPlayers;
      }

      if (passedPlayers.length >= playerOrder.length) {
        Map<String, int> scores = {};
        playerOrder.forEach((pId) {
          List<int> pHand = List<int>.from(
            gameData['blokusPlayerHands'][pId] ?? [],
          );
          if (pId == playerId) pHand = hand;
          int remainingSquares = pHand.fold(
            0,
            (sum, id) => sum + GameData.blokusPieces[id]!.length,
          );
          int score = -remainingSquares;
          if (remainingSquares == 0) {
            score += 15;
            // Correction de la règle : bonus si la DERNIÈRE pièce était bien le carré 1x1 (id: 1)
            if (lastPiecesPlaced[pId] == 1) score += 5;
          }
          scores[pId] = score;
        });
        String winnerId =
            scores.entries.reduce((a, b) => a.value > b.value ? a : b).key;
        updates.addAll({
          'gameState': 'gameOver',
          'gameWinner': winnerId,
          'players.$winnerId.score': FieldValue.increment(1),
          'blokusScores': scores,
          'gameEndReason': "Fin de la partie !",
        });
      } else {
        int nextIndex =
            (gameData['blokusCurrentPlayerIndex'] + 1) % playerOrder.length;
        int loopCount = 0;
        while (passedPlayers.contains(playerOrder[nextIndex]) &&
            loopCount < playerOrder.length) {
          nextIndex = (nextIndex + 1) % playerOrder.length;
          loopCount++;
        }
        updates['blokusCurrentPlayerIndex'] = nextIndex;
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }

      transaction.update(gameRef, updates);
    });
  }

  Future<void> passBlokusTurn(
    String gameCode,
    String playerId, {
    bool isAuto = false,
  }) async {
    final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
    if (!isAuto && currentAuthUid == null) throw Exception("Non authentifié.");

    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      if (gameData['gameState'] != 'playing') return;

      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final voterAuthUid = players[playerId]?['authUid'] ?? playerId;
      if (!isAuto && currentAuthUid != voterAuthUid) {
        throw Exception("Action non autorisée.");
      }

      final playerOrder = List<String>.from(gameData['blokusPlayerOrder']);
      if (playerOrder[gameData['blokusCurrentPlayerIndex']] != playerId) return;

      List<String> passedPlayers = List<String>.from(
        gameData['blokusPassedPlayers'] ?? [],
      );
      if (!passedPlayers.contains(playerId)) passedPlayers.add(playerId);

      Map<String, dynamic> updates = {'blokusPassedPlayers': passedPlayers};

      if (passedPlayers.length >= playerOrder.length) {
        Map<String, dynamic> lastPiecesPlaced = Map<String, dynamic>.from(
          gameData['blokusLastPiecesPlaced'] ?? {},
        );
        Map<String, int> scores = {};
        playerOrder.forEach((pId) {
          List<int> pHand = List<int>.from(
            gameData['blokusPlayerHands'][pId] ?? [],
          );
          int remainingSquares = pHand.fold(
            0,
            (sum, id) => sum + GameData.blokusPieces[id]!.length,
          );
          int score = -remainingSquares;
          if (remainingSquares == 0) {
            score += 15;
            if (lastPiecesPlaced[pId] == 1) score += 5;
          }
          scores[pId] = score;
        });
        String winnerId =
            scores.entries.reduce((a, b) => a.value > b.value ? a : b).key;
        updates.addAll({
          'gameState': 'gameOver',
          'gameWinner': winnerId,
          'players.$winnerId.score': FieldValue.increment(1),
          'blokusScores': scores,
          'gameEndReason': "Fin de la partie !",
        });
      } else {
        int nextIndex =
            (gameData['blokusCurrentPlayerIndex'] + 1) % playerOrder.length;
        int loopCount = 0;
        while (passedPlayers.contains(playerOrder[nextIndex]) &&
            loopCount < playerOrder.length) {
          nextIndex = (nextIndex + 1) % playerOrder.length;
          loopCount++;
        }
        updates['blokusCurrentPlayerIndex'] = nextIndex;
        updates['turnStartTime'] = FieldValue.serverTimestamp();
      }
      transaction.update(gameRef, updates);
    });
  }
}

