  void _showLaunchOptions(bool canLocal, bool canMonde) {
    // Vérifie si la communication est activée pour griser le mode Local
    final bool isCommunicationEnabled = _videoEnabled || _audioEnabled;
    // Vérifie si la recherche publique est activée pour griser Local et Privé
    final bool isPublicSearchEnabled = _enablePublicSearch;
    final bool isDevineTete = _selectedGame.contains('Devine T');
    final bool blockOnlineForDevineTete = isDevineTete && !_videoEnabled;

    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.grey[900],
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (ctx) {
        return Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                "Comment voulez-vous jouer ?",
                style: Theme.of(context).textTheme.headlineSmall,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 24),
              if (canLocal) ...[
                ElevatedButton.icon(
                  icon: Icon(Icons.phone_android),
                  style: ElevatedButton.styleFrom(
                    backgroundColor:
                        isPublicSearchEnabled || isCommunicationEnabled
                            ? Colors.grey
                            : Colors.green,
                    minimumSize: Size(double.infinity, 50),
                  ),
                  onPressed:
                      isPublicSearchEnabled
                          ? () {
                            ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(
                                content: Text(
                                  "Désactivez la 'Recherche Publique' pour pouvoir jouer en Local.",
                                ),
                              ),
                            );
                          }
                          : isCommunicationEnabled
                          ? () {
                            ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(
                                content: Text(
                                  "Désactivez la Vidéo ou l'Audio pour pouvoir jouer en Local.",
                                ),
                              ),
                            );
                          }
                          : () {
                            Navigator.pop(ctx);
                            Navigator.push(
                              context,
                              MaterialPageRoute(
                                builder:
                                    (_) => LocalPlayerSetupScreen(
                                      targetGame: _selectedGame,
                                    ),
                              ),
                            );
                          },
                  label: Text(
                    isPublicSearchEnabled
                        ? "Local indisponible (Recherche active)"
                        : isCommunicationEnabled
                        ? "Local indisponible (Vidéo/Audio actif)"
                        : "Jouer en Local (Sur cet appareil)",
                  ),
                ),
                SizedBox(height: 12),
              ],

              ElevatedButton.icon(
                icon: Icon(Icons.lock),
                style: ElevatedButton.styleFrom(
                  backgroundColor:
                      (isPublicSearchEnabled || blockOnlineForDevineTete)
                          ? Colors.grey
                          : Colors.deepPurple,
                  minimumSize: Size(double.infinity, 50),
                ),
                onPressed:
                    (isPublicSearchEnabled || blockOnlineForDevineTete)
                        ? () {
                          ScaffoldMessenger.of(context).showSnackBar(
                            SnackBar(
                              content: Text(
                                blockOnlineForDevineTete
                                    ? "La vidéo est obligatoire pour jouer à Devine Tête en ligne."
                                    : "Désactivez la 'Recherche Publique' pour créer une partie privée.",
                              ),
                            ),
                          );
                        }
                        : () {
                          Navigator.pop(ctx);
                          _createGameForFriends();
                        },
                label: Text(
                  isPublicSearchEnabled
                      ? "Privé indisponible (Recherche active)"
                      : blockOnlineForDevineTete
                      ? "Privé indisponible (Vidéo requise)"
                      : "Créer une partie privée (Avec code)",
                ),
              ),
              SizedBox(height: 12),

              // N'affiche le Matchmaking public que si le jeu le permet (canMonde)
              if (canMonde) ...[
                ElevatedButton.icon(
                  icon: Icon(Icons.public),
                  style: ElevatedButton.styleFrom(
                    backgroundColor:
                        _enablePublicSearch ? Colors.blue : Colors.grey[800],
                    minimumSize: Size(double.infinity, 50),
                  ),
                  onPressed:
                      _enablePublicSearch
                          ? () {
                            Navigator.pop(ctx);
                            _startMatchmaking(isRanked: false);
                          }
                          : () {
                            ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(
                                content: Text(
                                  blockOnlineForDevineTete
                                      ? "La vidéo est obligatoire pour jouer à Devine Tête en ligne."
                                      : "Activez le bouton 'Recherche Publique' dans les paramètres pour jouer avec le monde.",
                                ),
                              ),
                            );
                          },
                  label: Text(
                    _enablePublicSearch
                        ? "Recherche rapide (Monde)"
                        : blockOnlineForDevineTete
                        ? "Recherche rapide (Vidéo requise)"
                        : "Recherche Monde (Désactivée)",
                  ),
                ),
                SizedBox(height: 12),
                ElevatedButton.icon(
                  icon: Icon(Icons.star, color: Colors.white),
                  style: ElevatedButton.styleFrom(
                    backgroundColor:
                        _enablePublicSearch
                            ? Colors.orange[800]
                            : Colors.grey[800],
                    minimumSize: Size(double.infinity, 50),
                  ),
                  onPressed:
                      _enablePublicSearch
                          ? () {
                            Navigator.pop(ctx);
                            _startMatchmaking(isRanked: true);
                          }
                          : () {
                            ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(
                                content: Text(
                                  blockOnlineForDevineTete
                                      ? "La vidéo est obligatoire pour jouer à Devine Tête en Classé."
                                      : "Activez le bouton 'Recherche Publique' dans les paramètres pour jouer en Classé.",
                                ),
                              ),
                            );
                          },
                  label: Text(
                    _enablePublicSearch
                        ? "Partie Classée (Ranked)"
                        : blockOnlineForDevineTete
                        ? "Partie Classée (Vidéo requise)"
                        : "Partie Classée (Désactivée)",
                  ),
                ),
              ],

              if (!canMonde && widget.isWorldMode) ...[
                Text(
                  "Ce jeu requiert de connaître les autres joueurs et n'est pas disponible en matchmaking public.",
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    color: Colors.redAccent,
                    fontStyle: FontStyle.italic,
                  ),
                ),
              ],
            ],
          ),
        );
      },
    );
  }

  /// Ouvre l'historique Firebase dans une bottom sheet
  void _openAiHistorySheet(BuildContext context, String uid) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: const Color(0xFF141422),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (ctx) {
        return SizedBox(
          height: MediaQuery.of(context).size.height * 0.85,
          child: Column(
            children: [
              Container(
                padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(
                  color: Colors.black.withOpacity(0.3),
                  borderRadius: const BorderRadius.vertical(
                    top: Radius.circular(24),
                  ),
                  border: const Border(
                    bottom: BorderSide(color: Colors.white12),
                  ),
                ),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      "Historique des thèmes : $_selectedGame",
                      style: const TextStyle(
                        color: Colors.white,
                        fontWeight: FontWeight.bold,
                        fontSize: 16,
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.close, color: Colors.white70),
                      onPressed: () => Navigator.pop(ctx),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: StreamBuilder<List<AiThemeHistoryItem>>(
                  stream: _firebaseService.getAiHistoryStream(
                    uid,
                    _selectedGame,
                  ),
                  builder: (context, snapshot) {
                    if (!snapshot.hasData) {
                      return const Center(child: CircularProgressIndicator());
                    }
                    final items = snapshot.data ?? [];
                    if (items.isEmpty) {
                      return const Center(
                        child: Text(
                          "Aucun thème sauvegardé pour ce jeu sur Firebase.",
                          style: TextStyle(color: Colors.white54),
                        ),
                      );
                    }

                    return ListView.builder(
                      padding: const EdgeInsets.all(16),
                      itemCount: items.length,
                      itemBuilder: (context, index) {
                        final item = items[index];
                        final isSelected = _activeAiDocId == item.id;

                        return Container(
                          margin: const EdgeInsets.only(bottom: 12),
                          padding: const EdgeInsets.all(14),
                          decoration: BoxDecoration(
                            color:
                                isSelected
                                    ? Colors.deepPurple.withOpacity(0.3)
                                    : const Color(0xFF1E1E2E),
                            borderRadius: BorderRadius.circular(16),
                            border: Border.all(
                              color:
                                  isSelected
                                      ? Colors.amberAccent
                                      : Colors.white10,
                              width: isSelected ? 2 : 1,
                            ),
                          ),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(
                                mainAxisAlignment:
                                    MainAxisAlignment.spaceBetween,
                                children: [
                                  Expanded(
                                    child: Text(
                                      item.title,
                                      style: const TextStyle(
                                        color: Colors.white,
                                        fontWeight: FontWeight.bold,
                                        fontSize: 16,
                                      ),
                                      overflow: TextOverflow.ellipsis,
                                    ),
                                  ),
                                  IconButton(
                                    icon: const Icon(
                                      Icons.delete_outline,
                                      size: 18,
                                      color: Colors.redAccent,
                                    ),
                                    onPressed:
                                        () => _firebaseService
                                            .deleteAiThemeFromFirebase(
                                              uid,
                                              item.id,
                                            ),
                                    visualDensity: VisualDensity.compact,
                                  ),
                                ],
                              ),
                              if (item.prompt.isNotEmpty)
                                Text(
                                  "Prompt : \"${item.prompt}\"",
                                  style: const TextStyle(
                                    color: Colors.white54,
                                    fontSize: 12,
                                    fontStyle: FontStyle.italic,
                                  ),
                                ),
                              const SizedBox(height: 8),
                              Wrap(
                                spacing: 6,
                                runSpacing: 4,
                                children:
                                    item.words.take(8).map((w) {
                                      return Container(
                                        padding: const EdgeInsets.symmetric(
                                          horizontal: 8,
                                          vertical: 3,
                                        ),
                                        decoration: BoxDecoration(
                                          color: Colors.white.withOpacity(0.06),
                                          borderRadius: BorderRadius.circular(
                                            8,
                                          ),
                                        ),
                                        child: Text(
                                          w,
                                          style: const TextStyle(
                                            color: Colors.white70,
                                            fontSize: 11,
                                          ),
                                        ),
                                      );
                                    }).toList(),
                              ),
                              const SizedBox(height: 12),
                              Row(
                                children: [
                                  Expanded(
                                    child: ElevatedButton.icon(
                                      icon: const Icon(Icons.check, size: 16),
                                      label: const Text("UTILISER"),
                                      style: ElevatedButton.styleFrom(
                                        backgroundColor: Colors.green[700],
                                        foregroundColor: Colors.white,
                                      ),
                                      onPressed: () {
                                        setState(() {
                                          _selectedAiWords = List.from(
                                            item.words,
                                          );
                                          _activeAiThemeTitle = item.title;
                                          _activeAiDocId = item.id;
                                          _aiInstructionsController.text =
                                              item.prompt;
                                        });
                                        Navigator.pop(ctx);
                                      },
                                    ),
                                  ),
                                  const SizedBox(width: 8),
                                  Expanded(
                                    child: OutlinedButton.icon(
                                      icon: const Icon(
                                        Icons.edit_note,
                                        size: 16,
                                      ),
                                      label: const Text("Modifier / Compléter"),
                                      style: OutlinedButton.styleFrom(
                                        foregroundColor: Colors.cyanAccent,
                                        side: const BorderSide(
                                          color: Colors.cyanAccent,
                                        ),
                                      ),
                                      onPressed:
                                          () => _openEditDialog(
                                            context,
                                            uid,
                                            item,
                                          ),
                                    ),
                                  ),
                                ],
                              ),
                            ],
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  /// Boîte de dialogue pour modifier la liste et demander à l'IA de rajouter X mots
  void _openEditDialog(
    BuildContext context,
    String uid,
    AiThemeHistoryItem item,
  ) {
    final titleCtrl = TextEditingController(text: item.title);
    final addWordCtrl = TextEditingController();
    List<String> wordsList = List.from(item.words);
    bool isGeneratingMore = false;

    showDialog(
      context: context,
      builder: (dCtx) {
        return StatefulBuilder(
          builder: (context, setDState) {
            return AlertDialog(
              backgroundColor: const Color(0xFF1B1B2A),
              title: const Text(
                "Modifier le Thème",
                style: TextStyle(color: Colors.white, fontSize: 18),
              ),
              content: SizedBox(
                width: double.maxFinite,
                height: 420,
                child: Column(
                  children: [
                    TextField(
                      controller: titleCtrl,
                      decoration: const InputDecoration(
                        labelText: "Titre du thème (IA / Personnalisé)",
                      ),
                      style: const TextStyle(
                        color: Colors.white,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    const SizedBox(height: 10),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: addWordCtrl,
                            decoration: const InputDecoration(
                              hintText: "Ajouter un mot...",
                            ),
                            onSubmitted: (v) {
                              if (v.trim().isNotEmpty) {
                                setDState(() {
                                  wordsList.add(v.trim());
                                  addWordCtrl.clear();
                                });
                              }
                            },
                          ),
                        ),
                        IconButton(
                          icon: const Icon(
                            Icons.add_circle,
                            color: Colors.greenAccent,
                          ),
                          onPressed: () {
                            if (addWordCtrl.text.trim().isNotEmpty) {
                              setDState(() {
                                wordsList.add(addWordCtrl.text.trim());
                                addWordCtrl.clear();
                              });
                            }
                          },
                        ),
                      ],
                    ),
                    const SizedBox(height: 8),
                    // Bouton IA pour compléter la liste
                    SizedBox(
                      width: double.infinity,
                      child: OutlinedButton.icon(
                        icon:
                            isGeneratingMore
                                ? const SizedBox(
                                  width: 14,
                                  height: 14,
                                  child: CircularProgressIndicator(
                                    strokeWidth: 2,
                                    color: Colors.amberAccent,
                                  ),
                                )
                                : const Icon(
                                  Icons.auto_awesome,
                                  size: 16,
                                  color: Colors.amberAccent,
                                ),
                        label: Text(
                          isGeneratingMore
                              ? "Génération en cours..."
                              : "Compléter avec l'IA (+15 mots)",
                          style: const TextStyle(
                            color: Colors.amberAccent,
                            fontSize: 12,
                          ),
                        ),
                        onPressed:
                            isGeneratingMore
                                ? null
                                : () async {
                                  setDState(() => isGeneratingMore = true);
                                  try {
                                    final addedWords =
                                        await FirebaseService.generateAiWords(
                                          instructions:
                                              "Complète cette liste sur le thème ${titleCtrl.text}. Mots existants : ${wordsList.take(10).join(', ')}",
                                          count: 15,
                                          gameType: _selectedGame,
                                        );
                                    if (addedWords.isNotEmpty) {
                                      setDState(() {
                                        for (var w in addedWords) {
                                          if (!wordsList.contains(w))
                                            wordsList.add(w);
                                        }
                                      });
                                    }
                                  } finally {
                                    setDState(() => isGeneratingMore = false);
                                  }
                                },
                      ),
                    ),
                    const SizedBox(height: 8),
                    Expanded(
                      child: Container(
                        padding: const EdgeInsets.all(8),
                        decoration: BoxDecoration(
                          color: Colors.black26,
                          borderRadius: BorderRadius.circular(10),
                        ),
                        child: SingleChildScrollView(
                          child: Wrap(
                            spacing: 6,
                            runSpacing: 6,
                            children:
                                wordsList.map((w) {
                                  return Chip(
                                    label: Text(
                                      w,
                                      style: const TextStyle(fontSize: 12),
                                    ),
                                    onDeleted:
                                        () => setDState(
                                          () => wordsList.remove(w),
                                        ),
                                  );
                                }).toList(),
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(dCtx),
                  child: const Text("Annuler"),
                ),
                ElevatedButton(
                  onPressed: () async {
                    await _firebaseService.saveAiThemeToFirebase(
                      uid: uid,
                      prompt: item.prompt,
                      gameType: _selectedGame,
                      words: wordsList,
                      title: titleCtrl.text.trim(),
                      existingDocId: item.id,
                    );
                    if (_activeAiDocId == item.id) {
                      setState(() {
                        _selectedAiWords = wordsList;
                        _activeAiThemeTitle = titleCtrl.text.trim();
                      });
                    }
                    Navigator.pop(dCtx);
                  },
                  child: const Text("Enregistrer sur Firebase"),
                ),
              ],
            );
          },
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    int totalRolesCount = _selectedLoupGarouRoles.values.fold(
      0,
      (sum, count) => sum + count,
    );
    bool canProceed = true;
    String validationMessage = "";

    if (_selectedGame == 'Loup-Garou') {
      if (totalRolesCount < 5) {
        canProceed = false;
        validationMessage = "SÃ©lectionnez au moins 5 rÃ´les pour commencer.";
      }
    }

    final gameDataInfo = allAppGames.firstWhere(
      (g) => g['name'] == _selectedGame,
      orElse:
          () => {
            'modes': ['multi'],
          },
    );
    final modes = gameDataInfo['modes'] as List<String>;
    final bool canLocal = modes.contains('local');
    bool isDevineTete = _selectedGame.contains('Devine T');
    bool forceVideo = false;
    final bool isAiActive =
        (_selectedAiWords != null && _selectedAiWords!.isNotEmpty) ||
        _aiInstructionsController.text.trim().isNotEmpty;

    return Scaffold(
      appBar: AppBar(
        title: Text("CrÃ©er une Partie"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
