                                        style: ElevatedButton.styleFrom(
                                          backgroundColor: Colors.amberAccent,
                                          padding: const EdgeInsets.symmetric(
                                            vertical: 12,
                                          ),
                                          shape: RoundedRectangleBorder(
                                            borderRadius: BorderRadius.circular(
                                              12,
                                            ),
                                          ),
                                        ),
                                        onPressed:
                                            _isAiLoading ||
                                                    _aiInstructionsController
                                                        .text
                                                        .trim()
                                                        .isEmpty
                                                ? null
                                                : () async {
                                                  final prompt =
                                                      _aiInstructionsController
                                                          .text
                                                          .trim();
                                                  setState(
                                                    () => _isAiLoading = true,
                                                  );
                                                  try {
                                                    final formattedPrompt =
                                                        FirebaseService.formatAiPromptForGame(
                                                          _selectedGame,
                                                          prompt,
                                                        );
                                                    final wordCount =
                                                        FirebaseService.getAiWordCountForGame(
                                                          _selectedGame,
                                                        );
                                                    final generated =
                                                        await FirebaseService.generateAiWords(
                                                          instructions:
                                                              formattedPrompt,
                                                          count: wordCount,
                                                          gameType:
                                                              _selectedGame,
                                                        );
                                                    if (generated.isNotEmpty) {
                                                      String autoTitle = prompt;
                                                      if (autoTitle.length > 25)
                                                        autoTitle =
                                                            "${autoTitle.substring(0, 25)}...";

                                                      final docId =
                                                          await _firebaseService
                                                              .saveAiThemeToFirebase(
                                                                uid:
                                                                    ps.userId ??
                                                                    widget
                                                                        .playerId,
                                                                prompt: prompt,
                                                                gameType:
                                                                    _selectedGame,
                                                                words:
                                                                    generated,
                                                                title:
                                                                    autoTitle,
                                                              );

                                                      setState(() {
                                                        _selectedAiWords =
                                                            generated;
                                                        _activeAiThemeTitle =
                                                            autoTitle;
                                                        _activeAiDocId = docId;
                                                      });

