  bool _xpAwarded = false; // AJOUT : EmpÃƒÂªcher de donner l'XP plusieurs fois

  StreamSubscription? _timerSubscription;
  String?
  _lastTimerKey; // tracks start-time+roundState to avoid restart on each rebuild

  final TextEditingController _chatController = TextEditingController();
  String _selectedChatType = 'global';

  AudioPlayer? _hotPotatoPlayer;
  bool _isHotPotatoMusicPlaying = false;

  String? _selectedWildColor;
  bool _isUnoCalling = false;
  bool _unoDrawActionDone = false;
  PageController? _gribouillisPageController;
  final SupabaseService _supabaseService = SupabaseService();
  bool _isUploading = false;

  Timer? _heartbeatTimer;
  Timer? _pauseRemovalTimer;
  Timer? _stalePlayerCheckTimer;

  bool _livekitInitialized = false;
  late LivekitService _livekitService;

  Future<void> _connectToLivekit(bool videoEnabled, bool audioEnabled) async {
    if (_livekitInitialized) return;
    _livekitInitialized = true;

    try {
      await _livekitService.initialize();
      await _livekitService.joinChannel(
        widget.gameCode,
        identity: widget.playerId,
        videoEnabled: videoEnabled,
        audioEnabled: audioEnabled,
      );
    } catch (e) {
      print("Erreur init Livekit: $e");
    }
  }

  @override
  void initState() {
    super.initState();
    _livekitService = Provider.of<LivekitService>(context, listen: false);

    _gribouillisPageController = PageController();

    // Ãƒâ€°couter les changements de LivekitService pour mettre ÃƒÂ  jour Firestore
    _livekitService.addListener(() {
      if (_livekitService.localUserJoined &&
          _livekitService.localIdentity.isNotEmpty) {
        final currentAuthUid = FirebaseAuth.instance.currentUser?.uid;
        FirebaseFirestore.instance
            .collection('games')
            .doc(widget.gameCode)
            .update({
              'players.${widget.playerId}.livekitIdentity':
                  _livekitService.localIdentity,
              if (currentAuthUid != null && currentAuthUid.isNotEmpty)
                'players.${widget.playerId}.authUid': currentAuthUid,
            });
      }
    });

    _answerController.addListener(() {
      setState(() {});
    });

    // Listener pour le bouton + de Times Up (rebuild quand le texte change)
    _timesUpWordController.addListener(() {
      if (mounted) setState(() {});
    });

    WidgetsBinding.instance.addObserver(this);
    _startHeartbeat();
    _startStalePlayerCheck();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused) {
      // L'app est en arriÃƒÂ¨re-plan Ã¢â‚¬â€ si pas de retour dans 60s, retirer le joueur
      _pauseRemovalTimer?.cancel();
      _pauseRemovalTimer = Timer(const Duration(seconds: 60), () {
        _firebaseService.removePlayerFromGame(widget.gameCode, widget.playerId);
      });
    } else if (state == AppLifecycleState.resumed) {
      _pauseRemovalTimer?.cancel();
      _pauseRemovalTimer = null;
      // Mettre ÃƒÂ  jour le heartbeat immÃƒÂ©diatement au retour
      _sendHeartbeat();
    } else if (state == AppLifecycleState.detached) {
      if (widget.loungeId != null) {
        FirebaseFirestore.instance
            .collection('lounges')
            .doc(widget.loungeId)
            .update({
              'pendingGame.joinedPlayers': FieldValue.arrayRemove([
                widget.playerId,
              ]),
            });
      }
      _firebaseService.removePlayerFromGame(widget.gameCode, widget.playerId);
    }
  }

  void _startHeartbeat() {
    _sendHeartbeat();
    _heartbeatTimer = Timer.periodic(const Duration(seconds: 30), (_) {
      _sendHeartbeat();
    });
  }

  void _sendHeartbeat() {
    _firebaseService.updatePlayerHeartbeat(widget.gameCode, widget.playerId);
  }

  void _startStalePlayerCheck() {
    _stalePlayerCheckTimer = Timer.periodic(const Duration(seconds: 30), (
      _,
    ) async {
      // Seul l'hÃƒÂ´te vÃƒÂ©rifie les joueurs inactifs
      final gameSnap =
          await FirebaseFirestore.instance
              .collection('games')
              .doc(widget.gameCode)
              .get();
      if (!gameSnap.exists) return;
      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['hostId'] != widget.playerId) return;
      if (gameData['gameState'] != 'playing') return;

      final presencesSnap =
          await FirebaseFirestore.instance
              .collection('games')
              .doc(widget.gameCode)
              .collection('presences')
              .get();
      final now = DateTime.now();
      for (final doc in presencesSnap.docs) {
        if (doc.id == widget.playerId) continue;
        final lastHeartbeat =
            (doc.data()['lastHeartbeat'] as Timestamp?)?.toDate();
        if (lastHeartbeat != null &&
            now.difference(lastHeartbeat).inSeconds > 90) {
          final players = Map<String, dynamic>.from(gameData['players'] ?? {});
          final pData = players[doc.id] as Map<String, dynamic>?;
          if (pData != null &&
              pData['isBot'] != true &&
              pData['replacedByBot'] != true) {
            final pending =
                gameData['pendingBotReplacement'] as Map<String, dynamic>?;
            if (pending?['playerId'] != doc.id) {
              await _firebaseService.requestBotReplacement(
                widget.gameCode,
                doc.id,
                pData['name'] ?? 'Joueur',
                'déconnecté',
              );
            }
          }
        }
      }
    });
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _heartbeatTimer?.cancel();
    _pauseRemovalTimer?.cancel();
    _stalePlayerCheckTimer?.cancel();
    _pictionaryDebounceTimer?.cancel();
    _timerSubscription?.cancel();
    _playerTurnTimer?.cancel();
    _postGameTimer?.cancel();
    _dobblePenaltyTimer?.cancel();
    _answerController.removeListener(() {
      setState(() {});
    });
    _answerController.dispose();
    _timesUpWordController.dispose();
    _pictionaryGuessController.dispose();
    _pictionaryDrawingController.dispose();
    _justOneClueController.dispose();
    _justOneGuessController.dispose();
    _answerControllers.values.forEach((controller) => controller.dispose());
    _chatController.dispose();
    _hotPotatoPlayer?.dispose();
    _gribouillisPageController?.dispose();
    try {
      if (_livekitInitialized) {
        _livekitService.leaveChannel();
      }
    } catch (e) {
      print("Erreur dispose LivekitService: $e");
    }
    super.dispose();
  }

  // Copie cette mÃƒÂ©thode dans ta classe _MultiplayerGameScreenState
  Widget _buildEasel(String text, {bool isCancelled = false}) {
    return Container(
      margin: EdgeInsets.all(4),
