  Widget _buildUndercoverPlayerLine(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = Map<String, dynamic>.from(gameData['playerData']);
    final playerOrder = List<String>.from(gameData['playerOrder']);
    final clues = Map<String, dynamic>.from(gameData['playerClues'] ?? {});
    final currentPhase = gameData['currentPhase'];
    final isVotingPhase =
        currentPhase == 'voting' || currentPhase == 'resolving_votes';
    final myData = playerData[playerId];
    final canIVote = myData['canVote'] ?? false;
    final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});

    Map<String, List<String>> votesReceived = {};
    votes.forEach((voterId, targetId) {
      if (!votesReceived.containsKey(targetId)) {
        votesReceived[targetId] = [];
      }
      votesReceived[targetId]!.add(playerData[voterId]?['name'] ?? 'Anonyme');
    });

    final Map<String, IconData> roleIcons = {
      'Boomerang': Icons.autorenew,
      'Vengeuse': Icons.whatshot,
      'DÃƒÂ©esse de la Justice': Icons.gavel,
      'FantÃƒÂ´me': Icons.visibility,
      'Amoureux': Icons.favorite,
      'Mr. Meme': Icons.gesture,
      'Vendeur de Falafels': Icons.fastfood,
      'Duellistes': Icons.compare_arrows,
    };

    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      padding: const EdgeInsets.symmetric(horizontal: 16.0),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children:
            playerOrder.map((pId) {
              final pData = playerData[pId];
              final isDead = pData['status'] == 'eliminated';
              final clue = clues[pId];
              final bool canBeVotedFor =
                  isVotingPhase && canIVote && pId != playerId && !isDead;
              final List<String> voters = votesReceived[pId] ?? [];

              return Padding(
                padding: const EdgeInsets.symmetric(horizontal: 12.0),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    GestureDetector(
                      onTap:
                          canBeVotedFor && !_isActionPending
                              ? () {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .submitUndercoverVote(
                                      widget.gameCode,
                                      playerId,
                                      pId,
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              }
                              : null,
                      child: Opacity(
                        opacity: clue != null ? 1.0 : 0.0,
                        child: Container(
                          constraints: BoxConstraints(
                            minHeight: 40,
                            maxWidth: 100,
                          ),
                          padding: EdgeInsets.all(8),
                          decoration: BoxDecoration(
                            color:
                                canBeVotedFor
                                    ? Colors.deepPurple
                                    : Colors.grey[800],
                            borderRadius: BorderRadius.circular(10),
                          ),
                          child: Text(
                            clue ?? "",
                            textAlign: TextAlign.center,
                            style: TextStyle(color: Colors.white),
                          ),
                        ),
                      ),
                    ),
                    SizedBox(height: 8),

                    Stack(
                      alignment: Alignment.center,
                      clipBehavior: Clip.none,
                      children: [
                        CircleAvatar(
                          radius: 30,
                          child: Text(
                            (pData['name'] as String?)?.substring(0, 1) ?? "?",
                            style: TextStyle(fontSize: 24),
                          ),
                        ),
                        if (isDead)
                          Positioned.fill(
                            child: Icon(
                              Icons.close,
                              color: Colors.red.withOpacity(0.8),
                              size: 70,
                            ),
                          ),
                      ],
                    ),
                    SizedBox(height: 4),

                    Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Text(
                          pData['name'],
                          style: TextStyle(
                            color: isDead ? Colors.grey : Colors.white,
                          ),
                        ),
                        ...(pData['revealedAbilities'] as List<dynamic>? ?? [])
                            .map((ability) {
                              if (roleIcons.containsKey(ability)) {
                                return Padding(
                                  padding: const EdgeInsets.only(left: 4.0),
                                  child: Icon(
                                    roleIcons[ability],
                                    size: 16,
                                    color: Colors.cyanAccent,
                                  ),
                                );
                              }
                              return SizedBox.shrink();
                            })
                            .toList(),
                      ],
                    ),

                    if (isVotingPhase && voters.isNotEmpty)
                      Padding(
                        padding: const EdgeInsets.only(top: 4.0),
                        child: Column(
                          children: [
                            Chip(
                              label: Text(
                                "${voters.length} vote(s)",
                                style: TextStyle(fontSize: 10),
                              ),
                              padding: EdgeInsets.zero,
                              visualDensity: VisualDensity.compact,
                            ),
                            Text(
                              voters.join(', '),
                              style: TextStyle(
                                fontSize: 9,
                                color: Colors.grey[400],
                              ),
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                            ),
                          ],
                        ),
                      ),
                  ],
                ),
              );
            }).toList(),
      ),
    );
  }

  Future<void> _pickAndUploadPhotos(
    String playerId,
    Map<String, dynamic> gameData,
  ) async {
    if (!mounted) return;
    setState(() => _isUploading = true);

    try {
      final PermissionState ps = await PhotoManager.requestPermissionExtend();
      if (ps != PermissionState.authorized && ps != PermissionState.limited) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text(
                "Permission refusée. Impossible d'accéder à la galerie.",
              ),
            ),
          );
          setState(() => _isUploading = false);
        }
        return;
      }

      final int photosToPick =
          gameData['photoRouletteSettings']?['photosPerPlayer'] ?? 20;
      final String mediaType =
          gameData['photoRouletteSettings']?['mediaType'] ?? 'Photos';

      RequestType requestType = RequestType.image;
      if (mediaType == 'Vidéos') requestType = RequestType.video;
      if (mediaType == 'Mixte') requestType = RequestType.common;

      List<AssetPathEntity> albums = await PhotoManager.getAssetPathList(
        type: requestType,
        onlyAll: true,
      );

      if (albums.isEmpty) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text("Aucun album média trouvé.")),
          );
          setState(() => _isUploading = false);
        }
        return;
      }

      List<AssetEntity> allPhotos = await albums[0].getAssetListRange(
        start: 0,
        end: 300,
      );

      if (allPhotos.isEmpty) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text("Votre galerie est vide.")),
          );
          setState(() => _isUploading = false);
        }
        return;
      }

      allPhotos.shuffle();
      List<AssetEntity> selectedAssets = allPhotos.take(photosToPick).toList();
      List<String> uploadedUrls = [];

      for (final asset in selectedAssets) {
        // Optimisation : thumbnail haute qualité (1080x1080) au lieu de l'image brute 4K
        final Uint8List? bytes = await asset.thumbnailDataWithSize(
          const ThumbnailSize(1080, 1080),
          quality: 85,
        );

        if (bytes != null) {
          final url = await _supabaseService.uploadImageBytes(
            bytes,
            widget.gameCode,
          );
          if (url != null) uploadedUrls.add(url);
        }
      }

      if (uploadedUrls.isNotEmpty) {
        await _firebaseService.playerReadyForPhotoRoulette(
          widget.gameCode,
          playerId,
          uploadedUrls,
        );
      } else {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text("Échec de l'upload des photos vers Supabase."),
            ),
          );
        }
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text("Erreur lors de la sélection des photos : $e"),
          ),
        );
      }
    } finally {
      if (mounted) setState(() => _isUploading = false);
    }
  }

  void _startPhotoRouletteTimer(
    DateTime startTime,
    int durationSeconds,
    String gameCode,
    String currentRoundState,
  ) {
    _timerSubscription?.cancel();
    _timerSubscription = Stream.periodic(
      Duration(seconds: 1),
      (count) => count,
    ).listen((_) {
      if (!mounted) {
        _timerSubscription?.cancel();
        return;
      }
      final now = DateTime.now();
      final elapsed = now.difference(startTime).inSeconds;
      final remaining = durationSeconds - elapsed;

      if (remaining <= 0) {
        _timerSubscription?.cancel();

        // --- CORRECTION ---
        // ANCIEN : final String playerId = Provider.of<String>(context, listen: false);
        // NOUVEAU :
        final String playerId = widget.playerId;
        // ------------------

        final gameData =
            Provider.of<DocumentSnapshot>(context, listen: false).data()
                as Map<String, dynamic>;
        if (gameData['hostId'] == playerId &&
            currentRoundState == 'showing_photo') {
          _firebaseService.handlePhotoRouletteTimeout(gameCode);
        }
      }
    });
  }

