  PreferredSizeWidget? _buildTurnTimerIndicator(Map<String, dynamic> gameData) {
    bool useTimer = gameData['useTimer'] ?? true;
    if (!useTimer || gameData['gameState'] != 'playing') return null;

    final turnStartTimeStamp = gameData['turnStartTime'] as Timestamp?;
    if (turnStartTimeStamp == null) return null;

    final roundState = gameData['roundState'];
    final currentPhase = gameData['currentPhase'];
    final loupGarouPhase = gameData['phase'];

    final statesWithTimer = [
      'placement',
      'playing',
      'playing_turn',
      'rolling',
      'player_turn',
      'voting',
      'result',
      'round_end',
      'pre-flop',
      'flop',
      'turn',
      'river',
      'hand_over',
      'clue_giving',
      'turn_result',
      'answering',
      'declaring_truth',
      'guesser_chooses_word',
      'reveal_clues',
      'initial_writing',
      'drawing',
      'guessing',
      'nuit',
      'jour_discussion',
      'jour_vote',
      'showing_photo',
      'placing',
      'bidding',
      'challenging',
      'judging_selection',
      'judge_voting',
    ];

    bool shouldShow =
        statesWithTimer.contains(roundState) ||
        statesWithTimer.contains(currentPhase) ||
        (loupGarouPhase != null && statesWithTimer.contains(loupGarouPhase));

    if (!shouldShow) {
      return null;
    }

    final turnStartTime = turnStartTimeStamp.toDate();

    double turnDurationSeconds =
        (gameData['turnTimerSeconds'] as num?)?.toDouble() ?? 30.0;

    if (roundState == 'result' ||
        roundState == 'round_end' ||
        roundState == 'hand_over' ||
        currentPhase == 'turn_result') {
      turnDurationSeconds =
          (gameData['resultTimerSeconds'] as num?)?.toDouble() ?? 15.0;
    }

    final String currentTurnKey =
        "${turnStartTimeStamp.millisecondsSinceEpoch}_${gameData['currentPlayerIndex'] ?? gameData['unoCurrentPlayerIndex'] ?? gameData['milleBornesCurrentPlayerIndex'] ?? gameData['petitsChevauxCurrentIndex'] ?? 0}_${gameData['roundState']}_${gameData['phase']}";

    return PreferredSize(
      preferredSize: const Size.fromHeight(20.0),
      child: StreamBuilder(
        stream: Stream.periodic(const Duration(milliseconds: 100)),
        builder: (context, snapshot) {
          final elapsedSeconds =
              DateTime.now().difference(turnStartTime).inMilliseconds / 1000.0;
          final progress =
              (turnDurationSeconds - elapsedSeconds) / turnDurationSeconds;
          final remainingSeconds = max(
            0,
            (turnDurationSeconds - elapsedSeconds).ceil(),
          );

          // ⚡ DÉCLENCHEMENT INSTANTANÉ DÈS QUE LE TEMPS EST ÉCOULÉ (0s)
          if (elapsedSeconds >= turnDurationSeconds &&
              _lastExecutedTimeoutKey != currentTurnKey) {
            _lastExecutedTimeoutKey = currentTurnKey;

            // Exécute le coup et passe au joueur suivant sans attendre
            WidgetsBinding.instance.addPostFrameCallback((_) {
              if (mounted) {
                _executeAutoPlayForGame(gameData);
              }
            });
          }

          return Stack(
            alignment: Alignment.center,
            children: [
              LinearProgressIndicator(
                value: progress.clamp(0.0, 1.0),
                backgroundColor: Colors.grey[700],
                valueColor: AlwaysStoppedAnimation<Color>(
                  progress > 0.5
                      ? Colors.greenAccent
                      : (progress > 0.2
                          ? Colors.orangeAccent
                          : Colors.redAccent),
                ),
                minHeight: 20,
              ),
              Text(
                "$remainingSeconds s",
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                  fontSize: 12,
                  shadows: [
                    Shadow(blurRadius: 2, color: Colors.black.withOpacity(0.8)),
                  ],
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _buildScoreHeader(
    BuildContext context,
    Map<String, dynamic> players,
    Map<String, dynamic> gameData,
  ) {
    String gameType = gameData['gameType'] ?? '';

    // Liste des jeux où voir la main adverse est pertinent
    bool canViewHands = [
      'Président',
      'Uno',
      'Zéro Pointé',
      'Poker',
      'Big Two',
    ].contains(gameType);

    // Trie les joueurs par score
    List<MapEntry<String, dynamic>> sortedPlayers =
        players.entries.toList()..sort(
          (a, b) => (b.value['score'] ?? 0).compareTo(a.value['score'] ?? 0),
        );

    // Pour Zéro Pointé, on trie par score total croissant (le plus bas gagne)
    if (gameType == 'Zéro Pointé') {
      sortedPlayers.sort((a, b) {
        int scoreA = (gameData['totalScores']?[a.key] ?? 0);
        int scoreB = (gameData['totalScores']?[b.key] ?? 0);
        return scoreA.compareTo(scoreB);
      });
    }

    return Card(
      elevation: 4,
      color: Colors.black.withOpacity(0.4),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 8.0, vertical: 6.0),
        child: Container(
          width: double.infinity,
          child: Wrap(
            spacing: 8,
            runSpacing: 6,
            alignment: WrapAlignment.center,
            children:
                sortedPlayers.map((entry) {
                  String pId = entry.key;
                  String pName = entry.value['name'] ?? 'Inconnu';
                  int pScore =
                      (gameType == 'Zéro Pointé')
                          ? (gameData['totalScores']?[pId] ?? 0)
                          : (entry.value['score'] ?? 0);
                  int pXp = (entry.value['xp'] as num?)?.toInt() ?? 0;
                  bool isMe = pId == widget.playerId;
                  bool isSelected = _viewedOpponentId == pId;
                  final String targetAuthUid = entry.value['authUid'] ?? pId;
                  final String myAuthUid =
                      players[widget.playerId]?['authUid'] ?? widget.playerId;

                  void openProfile() {
                    showUserProfileDialog(
                      context,
                      targetUid: targetAuthUid,
                      currentUserId: myAuthUid,
                    );
                  }

                  return ActionChip(
                    avatar: CircleAvatar(
                      backgroundColor:
                          isMe ? Colors.deepPurpleAccent : Colors.grey[800],
                      child: Text(
                        pName.isNotEmpty ? pName[0].toUpperCase() : "?",
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 11,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ),
                    label: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          "$pName: $pScore pts",
                          style: TextStyle(
                            fontWeight:
                                isMe ? FontWeight.bold : FontWeight.normal,
                            color: isMe ? Colors.amberAccent : Colors.white,
                            fontSize: 12,
                          ),
                        ),
                        const SizedBox(width: 5),
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 5,
                            vertical: 1.5,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.deepPurple.withOpacity(0.4),
                            borderRadius: BorderRadius.circular(8),
                            border: Border.all(
                              color: Colors.deepPurpleAccent.withOpacity(0.6),
                              width: 0.8,
                            ),
                          ),
                          child: Text(
                            "$pXp XP",
                            style: const TextStyle(
                              color: Color(0xFF67E8F9),
                              fontWeight: FontWeight.bold,
                              fontSize: 10.5,
                            ),
                          ),
                        ),
                        if (canViewHands && !isMe) ...[
                          const SizedBox(width: 4),
                          GestureDetector(
                            onTap: () {
                              setState(() {
                                _viewedOpponentId =
                                    (_viewedOpponentId == pId) ? null : pId;
                              });
                            },
                            child: Icon(
                              _viewedOpponentId == pId
                                  ? Icons.visibility_off
                                  : Icons.visibility,
                              size: 14,
                              color:
                                  _viewedOpponentId == pId
                                      ? Colors.amberAccent
                                      : Colors.white54,
                            ),
                          ),
                        ],
                      ],
                    ),
                    backgroundColor:
                        isSelected
                            ? Colors.deepPurple.withOpacity(0.6)
                            : const Color(0xFF1E1E28),
                    side:
                        isSelected
                            ? const BorderSide(
                              color: Colors.deepPurpleAccent,
                              width: 2,
                            )
                            : null,
                    onPressed: () {
                      openProfile();
                    },
                  );
                }).toList(),
          ),
        ),
      ),
    );
  }

  Widget _buildOpponentHandView(
    Map<String, dynamic> gameData,
    String opponentId,
  ) {
    final String gameType = gameData['gameType'] ?? '';

    Widget buildFaceDownCard() => Container(
      width: 32,
      height: 48,
      decoration: BoxDecoration(
        color: const Color(0xFF1E293B),
        borderRadius: BorderRadius.circular(4),
        border: Border.all(color: Colors.white24),
        boxShadow: const [
          BoxShadow(color: Colors.black45, offset: Offset(1, 1), blurRadius: 2),
        ],
      ),
      child: const Center(
        child: Icon(Icons.style_rounded, color: Colors.white24, size: 16),
      ),
    );

    Widget buildFannedCards(int count, {List<String>? visibleCards}) {
      if (count == 0) {
        return const Text(
          "N'a plus de cartes",
          style: TextStyle(color: Colors.white70, fontSize: 12),
        );
      }
      return SizedBox(
        height: 52,
        child: SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          physics: const BouncingScrollPhysics(),
          child: Row(
            children: [
              ...List.generate(count, (index) {
                Widget cardWidget;
                if (visibleCards != null && index < visibleCards.length) {
                  cardWidget = _buildCard(
                    card: visibleCards[index],
                    isSelected: false,
                    scale: 0.5,
                  );
                } else {
                  cardWidget = buildFaceDownCard();
                }

                return Align(
                  widthFactor: 0.38,
                  alignment: Alignment.centerLeft,
                  child: cardWidget,
                );
              }),
              const SizedBox(width: 24),
            ],
          ),
        ),
      );
    }

    switch (gameType) {
      case 'Président':
        final hand = List<String>.from(
          gameData['playerHands']?[opponentId] ?? [],
        );
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              "${hand.length} cartes restantes",
              style: const TextStyle(color: Colors.white70, fontSize: 11),
            ),
            const SizedBox(height: 4),
            buildFannedCards(hand.length),
          ],
        );

      case 'Big Two':
        int count =
            (gameData['bigTwoPlayerHands']?[opponentId] as List?)?.length ?? 0;
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              "$count cartes restantes",
              style: const TextStyle(color: Colors.white70, fontSize: 11),
            ),
            const SizedBox(height: 4),
            buildFannedCards(count),
          ],
        );

      case 'Uno':
        final handUno = List<String>.from(
          gameData['unoPlayerHands']?[opponentId] ?? [],
        );
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              "${handUno.length} cartes restantes",
              style: const TextStyle(color: Colors.white70, fontSize: 11),
            ),
            const SizedBox(height: 4),
            buildFannedCards(handUno.length),
          ],
        );

      case 'Poker':
        final pData = gameData['playerData']?[opponentId] ?? {};
        final chips = pData['chips'] ?? 0;
        final bet = pData['currentBet'] ?? 0;
        final status = pData['status'] ?? 'out';
        final hand = List<String>.from(pData['hand'] ?? []);
        return Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              "Jetons: $chips \$ | Mise: $bet \$",
              style: const TextStyle(color: Colors.amberAccent, fontSize: 11),
            ),
            const SizedBox(height: 4),
            (gameData['phase'] == 'showdown' || status == 'all-in')
                ? buildFannedCards(hand.length, visibleCards: hand)
                : buildFannedCards(hand.length),
          ],
        );

      case 'Zéro Pointé':
        return Container(
          constraints: const BoxConstraints(maxHeight: 120),
          child: SingleChildScrollView(
            child: _buildZeroPointeGrid(
              List<Map<String, dynamic>>.from(
                gameData['playerGrids']?[opponentId] ?? [],
              ),
              null,
            ),
          ),
        );

      default:
        return const SizedBox.shrink();
    }
  }

  Widget buildFaceDownCard() => Container(
    width: 40,
    height: 60,
    margin: EdgeInsets.symmetric(horizontal: 2),
    decoration: BoxDecoration(
      color: Colors.indigo,
      borderRadius: BorderRadius.circular(4),
      border: Border.all(color: Colors.white24),
