  Widget _buildBigTwoUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerOrder = List<String>.from(gameData['bigTwoPlayerOrder']);
    final hands = Map<String, dynamic>.from(gameData['bigTwoPlayerHands']);
    final myHand = List<String>.from(hands[playerId] ?? []);
    final currentIndex = gameData['bigTwoCurrentPlayerIndex'];
    final currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentIndex] : '';
    final isMyTurn = currentPlayerId == playerId;
    final lastPlay =
        gameData['bigTwoLastPlay'] != null
            ? Map<String, dynamic>.from(gameData['bigTwoLastPlay'])
            : null;
    final finishedPlayers = List<String>.from(
      gameData['bigTwoFinishedPlayers'] ?? [],
    );

    if (gameData['gameState'] == 'gameOver') {
      final winnerName = players[gameData['gameWinner']]?['name'] ?? 'Inconnu';
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie TerminÃ©e !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                SizedBox(height: 10),
                Text(
                  "$winnerName a gagnÃ© !",
                  style: TextStyle(color: Colors.amber, fontSize: 20),
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      () => Navigator.of(
                        context,
                      ).popUntil((route) => route.isFirst),
                  child: Text("Retour"),
                ),
              ],
            ),
          ),
        ),
      );
    }

    return Column(
      children: [
        // Liste des adversaires retirée pour simplifier l'interface
        Expanded(
          flex: 2,
          child: Container(
            padding: EdgeInsets.all(16),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Text(
                  isMyTurn
                      ? "C'est votre tour !"
                      : "Au tour de ${players[currentPlayerId]?['name']}",
                  style: TextStyle(
                    color: isMyTurn ? Colors.greenAccent : Colors.white70,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                SizedBox(height: 20),
                if (lastPlay != null) ...[
                  Text(
                    "Carte(s) en jeu :",
                    style: TextStyle(color: Colors.white54),
                  ),
                  SizedBox(height: 10),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children:
                        (lastPlay['cards'] as List)
                            .map((c) => _buildBigTwoCard(c.toString()))
                            .toList(),
                  ),
                  SizedBox(height: 10),
                  Text(
                    "JouÃ© par ${players[lastPlay['playedBy']]?['name']}",
                    style: TextStyle(fontSize: 12, color: Colors.white38),
                  ),
                ] else
                  Text(
                    "Aucune carte en jeu. Jouez ce que vous voulez !",
                    style: TextStyle(color: Colors.amber),
                  ),
              ],
            ),
          ),
        ),
        Expanded(
          flex: 3,
          child: Container(
            padding: EdgeInsets.all(8),
            decoration: BoxDecoration(color: Colors.black.withOpacity(0.3)),
            child: Column(
              children: [
                Expanded(
                  child: SingleChildScrollView(
                    scrollDirection: Axis.horizontal,
                    child: Row(
                      children:
                          myHand.map((card) {
                            bool isSelected = _selectedBigTwoCards.contains(
                              card,
                            );
                            return GestureDetector(
                              onTap:
                                  isMyTurn
                                      ? () {
                                        setState(() {
                                          if (isSelected)
                                            _selectedBigTwoCards.remove(card);
                                          else
                                            _selectedBigTwoCards.add(card);
                                        });
                                      }
                                      : null,
                              child: Transform.translate(
                                offset: Offset(0, isSelected ? -20 : 0),
                                child: _buildBigTwoCard(
                                  card,
                                  isSelected: isSelected,
                                ),
                              ),
                            );
                          }).toList(),
                    ),
                  ),
                ),
                if (isMyTurn)
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                    children: [
                      ElevatedButton(
                        onPressed: lastPlay != null ? () => bigTwoPass() : null,
                        child: Text("Passer"),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.red,
                        ),
                      ),
                      ElevatedButton(
                        onPressed:
                            _selectedBigTwoCards.isNotEmpty
                                ? () => bigTwoPlay()
                                : null,
                        child: Text("Jouer (${_selectedBigTwoCards.length})"),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.green,
                        ),
                      ),
                    ],
                  ),
              ],
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildBigTwoCard(String card, {bool isSelected = false}) {
    String rank = card.substring(0, card.length - 1);
    String suit = card.substring(card.length - 1);
    Color textColor = (suit == 'H' || suit == 'D') ? Colors.red : Colors.black;
    String suitSymbol =
        {'H': 'â™¥', 'D': 'â™¦', 'C': 'â™£', 'S': 'â™ '}[suit] ?? '?';

    return Container(
      width: 60,
      height: 90,
      margin: EdgeInsets.symmetric(horizontal: 4),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: isSelected ? Colors.greenAccent : Colors.grey,
          width: isSelected ? 3 : 1,
        ),
        boxShadow: [
          BoxShadow(color: Colors.black26, blurRadius: 4, offset: Offset(2, 3)),
        ],
      ),
      child: Stack(
        children: [
          Center(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Text(
                  rank,
                  style: TextStyle(
                    fontSize: 24,
                    fontWeight: FontWeight.bold,
                    color: textColor,
                  ),
                ),
                Text(
                  suitSymbol,
                  style: TextStyle(fontSize: 24, color: textColor),
                ),
              ],
            ),
          ),
          Positioned(
            top: 4,
            left: 4,
            child: Text(
              rank,
              style: TextStyle(
                fontSize: 12,
                color: textColor,
                fontWeight: FontWeight.bold,
              ),
            ),
          ),
          Positioned(
            top: 18,
            left: 4,
            child: Text(
              suitSymbol,
              style: TextStyle(fontSize: 12, color: textColor),
            ),
          ),
        ],
      ),
    );
  }

  void bigTwoPlay() async {
    setState(() => _isActionPending = true);
    try {
      await _firebaseService.bigTwoAction(
        widget.gameCode,
        widget.playerId,
        'play',
        cards: _selectedBigTwoCards,
      );
      setState(() => _selectedBigTwoCards.clear());
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(e.toString().replaceAll('Exception: ', ''))),
      );
    } finally {
      if (mounted) setState(() => _isActionPending = false);
    }
  }

  void bigTwoPass() async {
    setState(() => _isActionPending = true);
    try {
      await _firebaseService.bigTwoAction(
        widget.gameCode,
        widget.playerId,
        'pass',
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(e.toString().replaceAll('Exception: ', ''))),
      );
    } finally {
      if (mounted) setState(() => _isActionPending = false);
    }
  }

  // =============================================================================
  // ACTION OU VÉRITÉ - INTERFACE DE JEU EN LIGNE
  // =============================================================================

  Widget _buildActionOuVeriteUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    if (gameData['gameState'] == 'gameOver') {
      final winnerId = gameData['gameWinner'];
      final players = Map<String, dynamic>.from(gameData['players'] ?? {});
      final customScores = <String, int>{};
      players.forEach((pId, pData) {
        if (pData is Map) {
          customScores[pId] = (pData['xp'] as num?)?.toInt() ?? 0;
        }
      });

      return UniversalGameEndScreen(
        gameTitle: "Action ou Vérité",
        winnerId: winnerId,
        winnerName: players[winnerId]?['name'],
        reason: gameData['gameEndReason'] ?? "La partie est terminée !",
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: widget.playerId == gameData['hostId'],
        onExit: () => Navigator.pop(context),
        customScores: customScores,
      );
    }

    return ActionOuVeriteGameView(
      gameData: gameData,
      playerId: playerId,
      gameCode: widget.gameCode,
      firebaseService: _firebaseService,
    );
  }

  Widget _buildCheckersUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final Map<String, String> board = Map<String, String>.from(
      gameData['checkersBoard'] ?? {},
    );
    final String currentColor = gameData['checkersCurrentColor'] ?? 'red';
    final List<String> playerOrder = List<String>.from(
      gameData['checkersPlayerOrder'] ?? [],
    );
    final int currentIndex = gameData['checkersCurrentPlayerIndex'] ?? 0;
    final String currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentIndex] : '';
    final bool isMyTurn = currentPlayerId == playerId;
    final players = gameData['players'] as Map<String, dynamic>;

    // NOUVEAU : RÃ©cupÃ©rer le pion obligatoire s'il y a une prise multiple en cours
    final String? mandatoryPiece = gameData['checkersMandatoryPiece'];

    if (gameData['gameState'] == 'gameOver') {
      return UniversalGameEndScreen(
        gameTitle: "Jeu de Dames",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ??
            "Plus aucun coup possible pour l'adversaire !",
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    return Column(
      children: [
        Container(
          padding: EdgeInsets.all(12),
          color: isMyTurn ? Colors.green.withOpacity(0.2) : Colors.transparent,
          child: Column(
            children: [
              Text(
                isMyTurn
                    ? "C'est votre tour ! (${currentColor == 'red' ? 'Rouges' : 'Noirs'})"
                    : "Au tour de ${players[currentPlayerId]?['name'] ?? '...'}",
                style: TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  color: isMyTurn ? Colors.greenAccent : Colors.white,
                ),
              ),
              if (isMyTurn && mandatoryPiece != null)
                Padding(
                  padding: const EdgeInsets.only(top: 8.0),
                  child: Text(
                    "âš ï¸ Prise en chaÃ®ne ! Vous devez rejouer le pion clignotant.",
                    style: TextStyle(
                      color: Colors.orangeAccent,
                      fontSize: 14,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
            ],
          ),
        ),
        Expanded(
          child: AspectRatio(
            aspectRatio: 1.0,
            child: Container(
              margin: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                border: Border.all(color: Colors.brown[900]!, width: 6),
                boxShadow: const [
                  BoxShadow(
                    color: Colors.black45,
                    blurRadius: 10,
                    offset: Offset(0, 5),
                  ),
                ],
              ),
              child: StreamBuilder<DatabaseEvent>(
                stream: _firebaseService.getCheckersLiveStream(widget.gameCode),
                builder: (context, liveSnap) {
                  String? liveSelectedPiece = _selectedCheckersPiece;
                  if (!isMyTurn &&
                      liveSnap.hasData &&
                      liveSnap.data!.snapshot.value != null) {
                    try {
                      final raw = Map<String, dynamic>.from(
                        liveSnap.data!.snapshot.value as Map,
                      );
                      liveSelectedPiece = raw['fromKey'] as String?;
                    } catch (_) {}
                  }

                  return GridView.builder(
                    physics: const NeverScrollableScrollPhysics(),
                    gridDelegate:
                        const SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: 8,
                        ),
                    itemCount: 64,
                    itemBuilder: (context, index) {
                      int r = index ~/ 8;
                      int c = index % 8;
                      bool isDark = (r + c) % 2 != 0;
                      String key = "$r,$c";
                      String? piece = board[key];

                      bool isSelected = key == liveSelectedPiece;
                      bool isMandatory = key == mandatoryPiece;
                      Color bgColor =
                          isDark ? Colors.brown[700]! : const Color(0xFFF5F5DC);

                      return GestureDetector(
                        onTap:
                            isMyTurn && isDark
                                ? () {
                                  if (_selectedCheckersPiece == null) {
                                    if (piece != null &&
                                        piece.startsWith(currentColor)) {
                                      if (mandatoryPiece != null &&
                                          key != mandatoryPiece) {
                                        ScaffoldMessenger.of(
                                          context,
                                        ).showSnackBar(
                                          const SnackBar(
                                            content: Text(
                                              "Vous devez sélectionner le pion en surbrillance orange.",
                                            ),
                                            duration: Duration(seconds: 2),
                                          ),
                                        );
                                        return;
                                      }
                                      setState(
                                        () => _selectedCheckersPiece = key,
                                      );
                                      _firebaseService
                                          .updateCheckersSelectionLive(
                                            widget.gameCode,
                                            playerId,
                                            key,
                                          );
                                    }
                                  } else {
                                    if (key == _selectedCheckersPiece) {
                                      setState(
                                        () => _selectedCheckersPiece = null,
                                      );
                                      _firebaseService
                                          .updateCheckersSelectionLive(
                                            widget.gameCode,
                                            playerId,
                                            null,
                                          );
                                    } else {
                                      List<int> from =
                                          _selectedCheckersPiece!
                                              .split(',')
                                              .map(int.parse)
                                              .toList();
                                      _firebaseService
                                          .updateCheckersSelectionLive(
                                            widget.gameCode,
                                            playerId,
                                            null,
                                          );
                                      _firebaseService
                                          .checkersMove(
                                            widget.gameCode,
                                            playerId,
                                            from[0],
                                            from[1],
                                            r,
                                            c,
                                          )
                                          .then((_) {
                                            setState(
                                              () =>
                                                  _selectedCheckersPiece = null,
                                            );
                                          })
                                          .catchError((e) {
                                            setState(
                                              () =>
                                                  _selectedCheckersPiece = null,
                                            );
                                          });
                                    }
                                  }
                                }
                                : null,
                        child: Container(
                          color: bgColor,
                          child:
                              piece != null
                                  ? Center(
                                    child: AnimatedContainer(
                                      duration: const Duration(
                                        milliseconds: 200,
                                      ),
                                      width: 35,
                                      height: 35,
                                      decoration: BoxDecoration(
                                        shape: BoxShape.circle,
                                        color:
                                            piece.startsWith('red')
                                                ? Colors.red[800]!
                                                : Colors.black87,
                                        border: Border.all(
                                          color:
                                              isSelected
                                                  ? Colors.greenAccent
                                                  : (isMandatory
                                                      ? Colors.orangeAccent
                                                      : Colors.white),
                                          width:
                                              (isSelected || isMandatory)
                                                  ? 3
                                                  : 2,
                                        ),
                                        boxShadow:
                                            (isSelected || isMandatory)
                                                ? [
                                                  BoxShadow(
                                                    color:
                                                        isMandatory
                                                            ? Colors.orange
                                                            : Colors
                                                                .greenAccent,
                                                    blurRadius: 8,
                                                    spreadRadius: 2,
                                                  ),
                                                ]
                                                : null,
                                      ),
                                      child:
                                          piece.endsWith('_king')
                                              ? const Icon(
                                                Icons.star,
                                                color: Colors.amber,
                                                size: 20,
                                              )
                                              : null,
                                    ),
                                  )
                                  : null,
                        ),
                      );
                    },
                  );
                },
              ),
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildGameContent(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String rawGameType = gameData['gameType'] ?? '';

    // Normalisation UTF-8 pour Ã©viter les erreurs d'accentuation ("non implÃ©mentÃ©")
    final String gameType = rawGameType
        .replaceAll('ÃƒÆ’Ã‚Â©', 'Ã©')
        .replaceAll('ÃƒÂ©', 'Ã©')
        .replaceAll('ÃƒÆ’Ã‚Â¨', 'Ã¨')
        .replaceAll('ÃƒÂ¨', 'Ã¨')
        .replaceAll('ÃƒÆ’Ã‚Âª', 'Ãª')
        .replaceAll('ÃƒÂª', 'Ãª')
        .replaceAll('ÃƒÆ’Ã‚Â´', 'Ã´')
        .replaceAll('ÃƒÂ´', 'Ã´')
        .replaceAll('ÃƒÆ’Ã‚Â»', 'Ã»')
        .replaceAll('ÃƒÂ»', 'Ã»');

    switch (gameType) {
      case 'Action ou Vérité':
        return _buildActionOuVeriteUI(context, gameData, playerId);
      case 'Jeu de Dames':
        return _buildCheckersUI(context, gameData, playerId);
      case 'Big Two':
        return _buildBigTwoUI(context, gameData, playerId);
      case 'Zombie!':
        return _buildZombieUI(context, gameData, playerId);
      case 'Blokus':
        return _buildBlokusUI(context, gameData, playerId);
      case 'Petits Chevaux':
        return _buildPetitsChevauxUI(context, gameData, playerId);
      case 'Cadavre Exquis':
        return _buildCadavreExquisUI(context, gameData, playerId);
      case 'Bataille Navale':
        return _buildBatailleNavaleUI(context, gameData, playerId);
      case 'Mille Bornes':
        return _buildMilleBornesUI(context, gameData, playerId);
      case 'Rami':
        return _buildRamiUI(context, gameData, playerId);
      case 'Belote':
        return _buildBeloteUI(context, gameData, playerId);
      case 'Yams':
        return _buildYamsUI(context, gameData, playerId);
      case 'Devine Tête':
        return _buildDevineTeteMultiUI(context, gameData, playerId);
      case 'Infiltré & Mr. White':
        return _buildUndercoverGameUI(context, gameData, playerId);
      case 'Photo Roulette':
        return _buildPhotoRouletteUI(context, gameData, playerId);
      case 'Zéro Pointé':
        return _buildZeroPointeUI(context, gameData, playerId);
      case 'Gribouillis':
        return _buildGribouillisUI(context, gameData, playerId);
      case 'Taboo':
        return _buildTabooUI(context, gameData, playerId);
      case 'Poker':
        return _buildPokerUI(context, gameData, playerId);
      case 'Uno':
        return _buildUnoUI(context, gameData, playerId);
      case 'Dobble':
        return _buildDobbleUI(context, gameData, playerId);
      case 'Codenames':
        return _buildCodenamesUI(context, gameData, playerId);
      case "Time's Up":
        return _buildTimesUpUI(context, gameData, playerId);
      case 'Petit Bac':
        return _buildPetitBacUI(context, gameData, playerId);
      case 'Président':
        return _buildPresidentUI(context, gameData, playerId);
      case 'Skull':
        return _buildSkullUI(context, gameData, playerId);
      case 'Pictionary':
        return _buildPictionaryUI(context, gameData, playerId);
      case 'Just One':
        return _buildJustOneUI(context, gameData, playerId);
      case 'La Patate Chaude':
      case 'Le Jeu des Catégories':
        return _buildHotPotatoUI(context, gameData, playerId);
      case 'Loup-Garou':
        return _buildLoupGarouUI(context, gameData, playerId);
      case 'Dominoes':
        return _buildDominoesUI(context, gameData, playerId);
      case 'Blanc Manger Coco':
        return _buildBlancMangerCocoUI(context, gameData, playerId);
      case 'Qui Pourrait le Plus ?':
      case 'Synonyme ou Banni':
      case 'Le Juge':
      case 'Le Menteur':
      case 'Le Roi des Mêmes':
        return _getWidgetForRoundState(context, gameData, playerId);
      default:
        return Center(child: Text("Jeu non implÃ©mentÃ© : $rawGameType"));
    }
  }

  Widget _buildDevineTeteMultiUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'playing_turn';
    final String currentGuesserId = gameData['currentGuesserId'] ?? '';
    final String currentWord = gameData['currentWord'] ?? '...';
    final int guessedCount = gameData['guessedCount'] ?? 0;
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final bool isMyTurn = playerId == currentGuesserId;
    final String guesserName =
        players[currentGuesserId]?['name'] ?? 'Un joueur';

    final bool useTeams = gameData['devineTeteUseTeams'] == true;
    final String activeTeam = gameData['activeTeam'] ?? 'teamA';
    final Map<String, dynamic> teamScores =
        gameData['teamScores'] ?? {'teamA': 0, 'teamB': 0};

    bool isMyTeamTurn = false;
    if (useTeams) {
      List<String> teamList = List<String>.from(
        gameData['teams']?[activeTeam] ?? [],
      );
      isMyTeamTurn = teamList.contains(playerId);
    }

    if (gameData['gameState'] == 'gameOver') {
      return UniversalGameEndScreen(
        gameTitle: "Devine Tête",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason: gameData['gameEndReason'] ?? "Fin de la partie !",
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    // Fin du chrono de 60s pour ce joueur : annonce et passage au suivant
    if (roundState == 'turn_result') {
      return Center(
        child: Container(
          margin: const EdgeInsets.all(24),
          padding: const EdgeInsets.all(24),
          decoration: BoxDecoration(
            color: const Color(0xFF1E1B4B),
            borderRadius: BorderRadius.circular(24),
            border: Border.all(
              color: Colors.amberAccent.withOpacity(0.6),
              width: 2,
            ),
            boxShadow: [
              BoxShadow(color: Colors.black.withOpacity(0.5), blurRadius: 16),
            ],
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(
                Icons.timer_off_rounded,
                size: 54,
                color: Colors.amberAccent,
              ),
              const SizedBox(height: 14),
              Text(
                "Temps écoulé !",
                style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                  fontWeight: FontWeight.bold,
                  color: Colors.white,
                ),
              ),
              const SizedBox(height: 8),
              Text(
                "$guesserName a trouvé $guessedCount mot(s) !",
                style: const TextStyle(
                  fontSize: 20,
                  color: Colors.greenAccent,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 24),
              if (gameData['hostId'] == playerId)
                ElevatedButton.icon(
                  icon: const Icon(Icons.arrow_forward_rounded),
                  label: const Text("Tour Suivant"),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.green[700],
                    padding: const EdgeInsets.symmetric(
                      horizontal: 24,
                      vertical: 12,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14),
                    ),
                  ),
                  onPressed:
                      _isActionPending
                          ? null
                          : () {
                            setState(() => _isActionPending = true);
                            _firebaseService
                                .nextDevineTeteTurn(widget.gameCode)
                                .then((_) {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                )
              else
                const Text(
                  "En attente de l'hôte pour lancer le tour suivant...",
                  style: TextStyle(
                    color: Colors.white54,
                    fontStyle: FontStyle.italic,
                  ),
                ),
            ],
          ),
        ),
      );
    }

    // Phase de jeu active
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        if (useTeams)
          Padding(
            padding: const EdgeInsets.only(bottom: 12.0),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color:
                        activeTeam == 'teamA'
                            ? Colors.redAccent.withOpacity(0.3)
                            : Colors.black26,
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                      color:
                          activeTeam == 'teamA'
                              ? Colors.redAccent
                              : Colors.white12,
                    ),
                  ),
                  child: Text(
                    "Équipe A : ${teamScores['teamA']} pts",
                    style: TextStyle(
                      color:
                          activeTeam == 'teamA'
                              ? Colors.redAccent
                              : Colors.white70,
                      fontWeight: FontWeight.bold,
                      fontSize: 15,
                    ),
                  ),
                ),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color:
                        activeTeam == 'teamB'
                            ? Colors.blueAccent.withOpacity(0.3)
                            : Colors.black26,
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                      color:
                          activeTeam == 'teamB'
                              ? Colors.blueAccent
                              : Colors.white12,
                    ),
                  ),
                  child: Text(
                    "Équipe B : ${teamScores['teamB']} pts",
                    style: TextStyle(
                      color:
                          activeTeam == 'teamB'
                              ? Colors.blueAccent
                              : Colors.white70,
                      fontWeight: FontWeight.bold,
                      fontSize: 15,
                    ),
                  ),
                ),
              ],
            ),
          ),

        if (isMyTurn) ...[
          const Text(
            "C'est à TOI de deviner !",
            style: TextStyle(
              color: Colors.greenAccent,
              fontSize: 22,
              fontWeight: FontWeight.w900,
            ),
          ),
          const SizedBox(height: 4),
          Text(
            useTeams
                ? "Écoutez les indices de votre équipe !"
                : "Regardez vos amis à l'écran, ils vous aident !",
            style: const TextStyle(color: Colors.white70, fontSize: 13),
            textAlign: TextAlign.center,
          ),
          const Spacer(),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceEvenly,
            children: [
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFFEA580C),
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 24,
                    vertical: 14,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                ),
                onPressed: () {
                  HapticFeedback.lightImpact();
                  _firebaseService.actionDevineTete(
                    widget.gameCode,
                    playerId,
                    false, // Passer -> mot suivant immédiat
                  );
                },
                icon: const Icon(Icons.skip_next_rounded, size: 24),
                label: const Text(
                  "PASSER",
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                ),
              ),
              ElevatedButton.icon(
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF16A34A),
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 28,
                    vertical: 14,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(16),
                  ),
                  elevation: 6,
                ),
                onPressed: () {
                  HapticFeedback.mediumImpact();
                  _firebaseService.actionDevineTete(
                    widget.gameCode,
                    playerId,
                    true, // Trouvé -> mot suivant immédiat
                  );
                },
                icon: const Icon(Icons.check_circle_rounded, size: 24),
                label: const Text(
                  "TROUVÉ !",
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
        ] else ...[
          Text(
            useTeams && !isMyTeamTurn
                ? "L'équipe adverse joue (surveillez les fautes) :"
                : "Faites deviner ce mot à $guesserName :",
            style: TextStyle(
              color:
                  (useTeams && !isMyTeamTurn)
                      ? Colors.orangeAccent
                      : Colors.amberAccent,
              fontSize: 15,
              fontWeight: FontWeight.bold,
            ),
            textAlign: TextAlign.center,
          ),
          const SizedBox(height: 10),
          Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(vertical: 24, horizontal: 16),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(24),
              boxShadow: [
                BoxShadow(
                  color: Colors.amberAccent.withOpacity(0.3),
                  blurRadius: 20,
                  spreadRadius: 2,
                ),
              ],
            ),
            child: Text(
              currentWord.toUpperCase(),
              style: TextStyle(
                color: Colors.deepPurple[900],
                fontSize: 32,
                fontWeight: FontWeight.w900,
                letterSpacing: 1.2,
              ),
              textAlign: TextAlign.center,
            ),
          ),
          const Spacer(),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 6),
            decoration: BoxDecoration(
              color: Colors.green.withOpacity(0.2),
              borderRadius: BorderRadius.circular(16),
            ),
            child: Text(
              "Mots trouvés : $guessedCount",
              style: const TextStyle(
                color: Colors.greenAccent,
                fontSize: 16,
                fontWeight: FontWeight.bold,
              ),
            ),
          ),
          const SizedBox(height: 12),
        ],
      ],
    );
  }

  // ===========================================================================
  // 📜 CADAVRE EXQUIS (FEUILLE PLIÉE EN ACCORDÉON & ENCRE MANUSCRITE)
  // ===========================================================================
  Widget _buildCadavreExquisUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final roundState = gameData['roundState'];
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    final variant = gameData['cadavreVariant'] ?? 'classic';
    final passingMode = gameData['cadavrePassingMode'] ?? 'single';
    final currentRound = gameData['currentRound'] ?? 0;
    final currentPlayerIndex = gameData['currentPlayerIndex'] ?? 0;
    final totalSteps = gameData['totalStepsPerPaper'] ?? 5;
    final papers = Map<String, dynamic>.from(gameData['papers'] ?? {});

    final isMyTurn =
        playerOrder.isNotEmpty && playerOrder[currentPlayerIndex] == playerId;
    final currentPlayerName =
        playerOrder.isNotEmpty
            ? (players[playerOrder[currentPlayerIndex]]?['name'] ?? 'Un joueur')
            : '...';

    // --- 1. ÉCRAN DES RÉSULTATS / DÉPLIAGE DU PARCHEMIN ---
    if (roundState == 'results' || gameData['gameState'] == 'gameOver') {
      return _buildCadavreExquisResults(context, papers, players, passingMode);
    }

    // Récupération de la feuille courante
    int paperIndex =
        passingMode == 'single'
            ? 0
            : ((currentPlayerIndex - currentRound + playerOrder.length) %
                playerOrder.length);
    Map<String, dynamic> currentPaper = Map<String, dynamic>.from(
      papers[paperIndex.toString()] ?? {'steps': []},
    );
    List<dynamic> steps = currentPaper['steps'] ?? [];

    String grammaticalPrompt = "";
    String peekingSnippet = "";
    String previousAuthorName = "";

    if (variant == 'classic') {
      int stepIndex = passingMode == 'single' ? steps.length : currentRound;
      final promptItem =
          stepIndex < GameData.cadavreExquisPrompts.length
              ? GameData.cadavreExquisPrompts[stepIndex]
              : 'la suite de l\'histoire...';
      grammaticalPrompt = "Écrivez $promptItem";
    } else {
      grammaticalPrompt = "Complétez la phrase (1 à 8 mots)";
      if (steps.isNotEmpty) {
        final lastStep = steps.last;
        String lastText = (lastStep['text'] ?? '').toString().trim();
        previousAuthorName =
            players[lastStep['authorId']]?['name'] ?? 'Auteur précédent';
        List<String> words = lastText.split(' ');
        peekingSnippet =
            words.length <= 3
                ? lastText
                : words.sublist(words.length - 3).join(' ');
      }
    }

    return Container(
      decoration: const BoxDecoration(
        gradient: RadialGradient(
          center: Alignment.topCenter,
          radius: 1.2,
          colors: [Color(0xFF2C2219), Color(0xFF140F0A), Color(0xFF070503)],
        ),
      ),
      child: Column(
        children: [
          // BANDEAU SUPÉRIEUR : ÉTAT DU TOUR & PROGRESSION
          Container(
            margin: const EdgeInsets.fromLTRB(12, 4, 12, 8),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
            decoration: BoxDecoration(
              color: const Color(0xFF241A12).withOpacity(0.9),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(
                color: isMyTurn ? const Color(0xFFE0A96D) : Colors.white12,
                width: isMyTurn ? 1.5 : 1,
              ),
              boxShadow: [
                if (isMyTurn)
                  BoxShadow(
                    color: const Color(0xFFE0A96D).withOpacity(0.2),
                    blurRadius: 10,
                  ),
              ],
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Row(
                  children: [
                    Container(
                      padding: const EdgeInsets.all(6),
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color:
                            isMyTurn
                                ? const Color(0xFFE0A96D).withOpacity(0.2)
                                : Colors.white10,
                      ),
                      child: Icon(
                        Icons.history_edu_rounded,
                        size: 16,
                        color:
                            isMyTurn ? const Color(0xFFF3C68F) : Colors.white60,
                      ),
                    ),
                    const SizedBox(width: 8),
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          isMyTurn
                              ? "À VOUS D'ÉCRIRE !"
                              : "AU TOUR DE $currentPlayerName",
                          style: TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w900,
                            letterSpacing: 1,
                            color:
                                isMyTurn
                                    ? const Color(0xFFF3C68F)
                                    : Colors.white70,
                          ),
                        ),
                        Text(
                          variant == 'classic'
                              ? "Surréalisme classique"
                              : "Suite de 3 mots",
                          style: const TextStyle(
                            fontSize: 10,
                            color: Colors.white38,
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.black45,
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: Colors.white10),
                  ),
                  child: Text(
                    "Étape ${currentRound + 1} / $totalSteps",
                    style: const TextStyle(
                      color: Color(0xFFE0A96D),
                      fontSize: 11,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
              ],
            ),
          ),

          // FEUILLE DE PAPIER ACCORDÉON
          Expanded(
            child: Center(
              child: SingleChildScrollView(
                physics: const BouncingScrollPhysics(),
                padding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 4,
                ),
                child:
                    isMyTurn
                        ? _buildAccordionPaperActive(
                          context,
                          grammaticalPrompt: grammaticalPrompt,
                          peekingSnippet: peekingSnippet,
                          previousAuthorName: previousAuthorName,
                          variant: variant,
                          playerId: playerId,
                        )
                        : _buildAccordionPaperSpectator(
                          context,
                          currentPlayerName: currentPlayerName,
                          totalSteps: totalSteps,
                          currentRound: currentRound,
                        ),
              ),
            ),
          ),
        ],
      ),
    );
  }

