  Widget _buildResultUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    // DÃƒÂ©tection du mode Mondial : Soit c'est un lobby Premium, soit c'est un jeu configurÃƒÂ© avec Timer + Scope Monde
    final bool isWorldMode =
        gameData['isPremiumLobby'] == true ||
        (gameData['useTimer'] == true && gameData['scope'] == 'monde');

    final String gameState = gameData['gameState'];
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final bool isHost = gameData['hostId'] == playerId;

    // ---------------------------------------------------------------------
    // 1. Ãƒâ€°TAT REFILLING : Un joueur a quittÃƒÂ©, on cherche un remplaÃƒÂ§ant
    // ---------------------------------------------------------------------
    if (gameState == 'refilling') {
      // Initialisation du timer de 10s si ce n'est pas dÃƒÂ©jÃƒÂ  fait
      if (_postGameTimer == null || !_postGameTimer!.isActive) {
        _refillCountdown = 10;
        _postGameTimer = Timer.periodic(Duration(seconds: 1), (timer) {
          if (!mounted) return;
          setState(() {
            if (_refillCountdown > 0) _refillCountdown--;
          });
          if (_refillCountdown <= 0) {
            timer.cancel();
            // Le temps est ÃƒÂ©coulÃƒÂ©, on force le dÃƒÂ©marrage avec les joueurs prÃƒÂ©sents
            _firebaseService.forceStartAfterRefill(widget.gameCode);
          }
        });
      }

      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                CircularProgressIndicator(),
                SizedBox(height: 20),
                Text(
                  "Un joueur a quittÃƒÂ©...",
                  style: Theme.of(context).textTheme.headlineSmall,
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 10),
                Text(
                  "Recherche de remplaÃƒÂ§ants en cours...",
                  style: Theme.of(context).textTheme.bodyLarge,
                ),
                SizedBox(height: 20),
                Text(
                  "DÃƒÂ©marrage automatique dans",
                  style: TextStyle(color: Colors.white70),
                ),
                Text(
                  "$_refillCountdown s",
                  style: TextStyle(
                    fontSize: 32,
                    fontWeight: FontWeight.bold,
                    color: Colors.amberAccent,
                  ),
                ),
                SizedBox(height: 20),
                Text(
                  "Joueurs connectÃƒÂ©s : ${players.length}",
                  style: TextStyle(fontStyle: FontStyle.italic),
                ),
              ],
            ),
          ),
        ),
      );
    }

    // ---------------------------------------------------------------------
    // 2. Ãƒâ€°TAT GAME OVER (MODE MONDIAL) : Vote pour Rejouer ou Quitter
    // ---------------------------------------------------------------------
    if (isWorldMode && gameState == 'gameOver') {
      final restartVotes = Map<String, dynamic>.from(
        gameData['restartVotes'] ?? {},
      );
      final bool hasVoted = restartVotes.containsKey(playerId);

      // Initialisation du timer de vote de 15s
      if (_postGameTimer == null || !_postGameTimer!.isActive) {
        _postGameCountdown = 15;
        _postGameTimer = Timer.periodic(Duration(seconds: 1), (timer) {
          if (!mounted) return;
          setState(() {
            if (_postGameCountdown > 0) _postGameCountdown--;
          });
          if (_postGameCountdown <= 0) {
            timer.cancel();
            // Si je suis l'hÃƒÂ´te ou le premier joueur (fail-safe), je dÃƒÂ©clenche le nettoyage
            // FirebaseService gÃƒÂ¨re la concurrence via Transaction
            if (isHost || players.keys.first == playerId) {
              _firebaseService.handleRestartDecisionTimeout(widget.gameCode);
            }
          }
        });
      }

      // RÃƒÂ©cupÃƒÂ©ration du gagnant pour l'affichage
      List<MapEntry<String, dynamic>> sortedPlayers =
          players.entries.toList()..sort(
            (a, b) => (b.value['score'] ?? 0).compareTo(a.value['score'] ?? 0),
          );
      String winnerName =
          sortedPlayers.isNotEmpty
              ? sortedPlayers.first.value['name']
              : "Personne";

      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie TerminÃƒÂ©e !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                SizedBox(height: 10),
                Text(
                  "Vainqueur : $winnerName",
                  style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                    color: Colors.amberAccent,
                  ),
                ),
                SizedBox(height: 5),
                Text(
                  gameData['gameEndReason'] ?? "",
                  textAlign: TextAlign.center,
                  style: TextStyle(color: Colors.white70),
                ),

                Divider(height: 30),

                Text(
                  "Voulez-vous rejouer ?",
                  style: Theme.of(context).textTheme.titleLarge,
                ),
                SizedBox(height: 5),
                Text(
                  "$_postGameCountdown s",
                  style: TextStyle(
                    fontSize: 30,
                    fontWeight: FontWeight.bold,
                    color:
                        _postGameCountdown <= 5
                            ? Colors.redAccent
                            : Colors.white,
                  ),
                ),

                SizedBox(height: 20),
                Wrap(
                  spacing: 20,
                  alignment: WrapAlignment.center,
                  children: [
                    ElevatedButton.icon(
                      icon: Icon(Icons.replay),
                      label: Text(
                        hasVoted
                            ? "En attente (${restartVotes.length}/${players.length})"
                            : "REJOUER",
                      ),
                      style: ElevatedButton.styleFrom(
                        backgroundColor: hasVoted ? Colors.grey : Colors.green,
                        padding: EdgeInsets.symmetric(
                          horizontal: 24,
                          vertical: 12,
                        ),
                      ),
                      onPressed:
                          hasVoted
                              ? null
                              : () {
                                _firebaseService.submitRestartVote(
                                  widget.gameCode,
                                  playerId,
                                );
                              },
                    ),
                    OutlinedButton.icon(
                      icon: Icon(Icons.exit_to_app),
                      label: Text("Quitter"),
                      style: OutlinedButton.styleFrom(
                        foregroundColor: Colors.redAccent,
                        side: BorderSide(color: Colors.redAccent),
                        padding: EdgeInsets.symmetric(
                          horizontal: 24,
                          vertical: 12,
                        ),
                      ),
                      onPressed: () async {
                        if (_livekitInitialized) {
                          await _livekitService.leaveChannel();
                          await Future.delayed(
                            const Duration(milliseconds: 300),
                          );
                        }
                        _firebaseService.removePlayerFromGame(
                          widget.gameCode,
                          playerId,
                        );
                        Navigator.of(
                          context,
                        ).popUntil((route) => route.isFirst);
                      },
                    ),
                  ],
                ),
                SizedBox(height: 15),
                Text(
                  "Si un joueur ne rÃƒÂ©pond pas ou quitte, la partie cherchera un remplaÃƒÂ§ant.",
                  style: TextStyle(
                    fontSize: 11,
                    color: Colors.white38,
                    fontStyle: FontStyle.italic,
                  ),
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),
        ),
      );
    }

    // ---------------------------------------------------------------------
    // 3. AFFICHAGE STANDARD DES RÃƒâ€°SULTATS (Mode Amis ou Fin de Tour)
    // ---------------------------------------------------------------------
    final gameType = gameData['gameType'];
    String resultText = "";
    Widget? extraInfo;
    final isSimplifiedLiar = gameData['isSimplifiedLiar'] ?? false;
    final String? gameEndReason = gameData['gameEndReason'];
    final String? memeUrl = gameData['memeUrl'];
    final bool isSkullGameOver =
        gameType == 'Skull' && gameData['gameState'] == 'gameOver';

    // --- LOGIQUE SPÃƒâ€°CIFIQUE PAR JEU (CopiÃƒÂ©e de l'ancienne version) ---
    switch (gameType) {
      case 'Le Juge':
        final winnerId = gameData['roundWinnerId'];
        final winnerName = players[winnerId]?['name'] ?? 'Quelqu\'un';
        final winningAnswer =
            (gameData['answers'] as Map<String, dynamic>?)?[winnerId] ??
            'aucune rÃƒÂ©ponse';
        resultText =
            "$winnerName a ÃƒÂ©tÃƒÂ© choisi pour sa rÃƒÂ©ponse et gagne 1 point !";
        extraInfo = Text(
          '"${winningAnswer}"',
          style: TextStyle(fontStyle: FontStyle.italic, color: Colors.white70),
          textAlign: TextAlign.center,
        );
        break;

      case 'Le Menteur':
        if (isSimplifiedLiar) {
          resultText = "RÃƒÂ©sultats des votes";
          final answers = gameData['answers'] as Map<String, dynamic>;
          final storyTruths = gameData['storyTruths'] as Map<String, dynamic>;
          final votes = gameData['voteResults'] as Map<String, dynamic>;
          extraInfo = Expanded(
            child: ListView(
              children:
                  answers.keys.map((storyOwnerId) {
                    final storyOwnerName =
                        players[storyOwnerId]?['name'] ?? '...';
                    final story = answers[storyOwnerId];
                    final actualTruth =
                        storyTruths[storyOwnerId] == true ? "VRAIE" : "FAUSSE";
                    final storyVotes = Map.from(
                      votes[storyOwnerId] as Map<String, dynamic>? ?? {},
                    );

                    return Card(
                      margin: EdgeInsets.symmetric(vertical: 8),
                      child: Padding(
                        padding: const EdgeInsets.all(12.0),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              'Histoire de $storyOwnerName (ÃƒÂ©tait $actualTruth)',
                              style: Theme.of(
                                context,
                              ).textTheme.titleLarge?.copyWith(
                                color:
                                    actualTruth == "VRAIE"
                                        ? Colors.greenAccent
                                        : Colors.redAccent,
                              ),
                            ),
                            SizedBox(height: 4),
                            Text(
                              '"$story"',
                              style: TextStyle(
                                fontStyle: FontStyle.italic,
                                color: Colors.white70,
                              ),
                            ),
                            Divider(height: 20),
                            Text(
                              "Votes :",
                              style: Theme.of(context).textTheme.bodyMedium,
                            ),
                            ...storyVotes.entries.map((voteEntry) {
                              final voterName =
                                  players[voteEntry.key]?['name'] ?? '...';
                              final voteValue = voteEntry.value;
                              final bool wasCorrect =
                                  (voteValue == "Vrai" &&
                                      actualTruth == "VRAIE") ||
                                  (voteValue == "Faux" &&
                                      actualTruth == "FAUSSE");
                              return Row(
                                children: [
                                  Icon(
                                    wasCorrect
                                        ? Icons.check_circle
                                        : Icons.cancel,
                                    color:
                                        wasCorrect ? Colors.green : Colors.red,
                                    size: 16,
                                  ),
                                  SizedBox(width: 8),
                                  Text('$voterName a votÃƒÂ© : $voteValue'),
                                ],
                              );
                            }),
                          ],
                        ),
                      ),
                    );
                  }).toList(),
            ),
          );
          break;
        } else {
          final liarId = gameData['liarId'];
          final liarName = players[liarId]?['name'] ?? 'Le menteur';
          resultText = "Le menteur ÃƒÂ©tait... $liarName !";
          extraInfo = Text(
            "Les points ont ÃƒÂ©tÃƒÂ© distribuÃƒÂ©s en fonction de vos votes.",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          );
        }
        break;

      case 'Infiltré & Mr. White':
        final undercoverId = gameData['undercoverId'];
        final mrWhiteId = gameData['mrWhiteId'];
        final undercoverName = players[undercoverId]?['name'] ?? 'Inconnu';
        final mrWhiteName = players[mrWhiteId]?['name'] ?? 'Inconnu';
        final wordPair = (gameData['roundData'] as String? ?? ":").split(":");
        final winner = gameData['roundWinnerId'];

        if (winner == 'impostors') {
          resultText =
              "Les imposteurs ont gagnÃƒÂ© ! Un civil a ÃƒÂ©tÃƒÂ© ÃƒÂ©liminÃƒÂ©.";
        } else if (winner == 'civilians_and_mrwhite') {
          resultText =
              "L'InfiltrÃƒÂ© ($undercoverName) a ÃƒÂ©tÃƒÂ© dÃƒÂ©masquÃƒÂ© !";
        } else if (winner == 'civilians_and_undercover') {
          resultText = "Mr. White ($mrWhiteName) a ÃƒÂ©tÃƒÂ© dÃƒÂ©masquÃƒÂ© !";
        } else {
          resultText = "Le tour est terminÃƒÂ© !";
        }

        extraInfo = Column(
          children: [
            Text(
              "Le mot des Civils ÃƒÂ©tait : '${wordPair[0]}'",
              style: TextStyle(
                fontStyle: FontStyle.italic,
                color: Colors.white70,
              ),
            ),
            if (undercoverId != null)
              Text(
                "Le mot de l'InfiltrÃƒÂ© (${undercoverName}) ÃƒÂ©tait : '${wordPair[1]}'",
                style: TextStyle(
                  fontStyle: FontStyle.italic,
                  color: Colors.white70,
                ),
              ),
            if (mrWhiteId != null)
              Text(
                "Mr. White (${mrWhiteName}) n'avait pas de mot.",
                style: TextStyle(
                  fontStyle: FontStyle.italic,
                  color: Colors.white70,
                ),
              ),
          ],
        );
        break;

      case 'Synonyme ou Banni':
        final loserId = gameData['roundLoserId'];
        if (loserId != null) {
          final loserName = players[loserId]?['name'] ?? 'Quelqu\'un';
          final word = gameData['roundData'];
          final loserAnswer = gameData['answers'][loserId];
          resultText =
              "$loserName a ÃƒÂ©tÃƒÂ© banni pour sa proposition '$loserAnswer' !";
          extraInfo = Text(
            "Le mot ÃƒÂ  trouver ÃƒÂ©tait un synonyme de '$word'. Les autres joueurs marquent 1 point.",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          );
        } else {
          resultText = "Ãƒâ€°galitÃƒÂ© dans les votes ! Personne n'est banni.";
        }
        break;

      case 'Le Jeu des Catégories':
      case 'La Patate Chaude':
        final loserId = gameData['roundWinnerId'];
        if (loserId != null) {
          final loserName = players[loserId]?['name'] ?? 'Inconnu';
          resultText =
              "${loserName} n'a pas rÃƒÂ©pondu ÃƒÂ  temps et gagne 1 point !";
          extraInfo = Text(
            gameData['gameEndReason'] ?? "Temps ÃƒÂ©coulÃƒÂ© !",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          );
        } else {
          resultText =
              "Ãƒâ€°galitÃƒÂ© ! Personne ne prend de point ce tour-ci.";
        }
        break;

      case 'Pictionary':
        final winnerId = gameData['roundWinnerId'];
        final currentWord = gameData['currentPictionaryWord'] ?? 'Mot';
        final drawingPlayerName =
            players[gameData['currentDrawingPlayerId']]?['name'] ??
            'Le dessinateur';
        if (winnerId != null) {
          final winnerName = players[winnerId]?['name'] ?? 'Quelqu\'un';
          resultText = "$winnerName a trouvÃƒÂ© le mot : '$currentWord' !";
          extraInfo = Text(
            "FÃƒÂ©licitations au dessinateur $drawingPlayerName et ÃƒÂ  $winnerName !",
            textAlign: TextAlign.center,
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          );
        } else {
          resultText = "Personne n'a trouvÃƒÂ© le mot : '$currentWord'.";
          extraInfo = Text(
            gameEndReason ??
                "Le temps est ÃƒÂ©coulÃƒÂ© ou le dessin ÃƒÂ©tait trop complexe !",
            textAlign: TextAlign.center,
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          );
        }
        break;

      case 'Just One':
        final currentWord = gameData['justOneCurrentWord'] ?? 'Mot';
        final guesserName =
            players[gameData['justOneGuesserId']]?['name'] ?? 'Le devin';
        final guesserAnswer =
            gameData['justOneGuesserAnswer'] ?? '(pas de rÃƒÂ©ponse)';
        if (gameEndReason == 'Mot devinÃƒÂ© !') {
          resultText = "$guesserName a trouvÃƒÂ© le mot : '$currentWord' !";
          extraInfo = Text(
            "Sa rÃƒÂ©ponse ÃƒÂ©tait : '$guesserAnswer'.",
            textAlign: TextAlign.center,
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.greenAccent,
            ),
          );
        } else {
          resultText = "$guesserName n'a pas trouvÃƒÂ© le mot.";
          extraInfo = Column(
            children: [
              Text(
                "Le mot ÃƒÂ©tait : '$currentWord'.",
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontStyle: FontStyle.italic,
                  color: Colors.white70,
                ),
              ),
              Text(
                "Sa rÃƒÂ©ponse ÃƒÂ©tait : '$guesserAnswer'.",
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontStyle: FontStyle.italic,
                  color: Colors.redAccent,
                ),
              ),
            ],
          );
        }
        break;

      case 'Skull':
        final String? outcome = gameData['skullLastChallengeOutcome'];
        final int challengeBid = gameData['skullLastChallengeBid'] ?? 0;
        final List<dynamic> revealed = List<dynamic>.from(
          gameData['skullLastChallengeRevealed'] ?? [],
        );
        final String? winnerId = gameData['gameWinner'];

        if (gameData['gameState'] == 'gameOver' && winnerId != null) {
          resultText =
              "${players[winnerId]?['name'] ?? 'Un joueur'} remporte Skull !";
          extraInfo = Text(
            gameData['gameEndReason'] ?? 'Deux dÃƒÂ©fis rÃƒÂ©ussis.',
            textAlign: TextAlign.center,
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.greenAccent,
            ),
          );
        } else if (outcome == 'won') {
          resultText =
              "DÃƒÂ©fi gagnÃƒÂ© : $challengeBid carte(s) rÃƒÂ©vÃƒÂ©lÃƒÂ©e(s) !";
        } else if (outcome == 'lost') {
          final loserName =
              players[gameData['skullLastChallengeLoserId']]?['name'] ??
              'Le challenger';
          resultText = "$loserName a perdu le dÃƒÂ©fi.";
        } else {
          resultText = "Le tour est terminÃƒÂ©.";
        }

        if (revealed.isNotEmpty) {
          extraInfo = Column(
            children: [
              Text(
                "Cartes rÃƒÂ©vÃƒÂ©lÃƒÂ©es :",
                style: TextStyle(color: Colors.white70),
              ),
              SizedBox(height: 8),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children:
                    revealed.map((entry) {
                      final Map<String, dynamic> card =
                          Map<String, dynamic>.from(entry as Map);
                      final String ownerName =
                          players[card['ownerId']]?['name'] ?? 'Joueur';
                      return Chip(
                        label: Text(
                          '$ownerName : ${card['type'] == 'Crane' ? 'CrÃƒÂ¢ne' : 'Rose'}',
                        ),
                        backgroundColor:
                            card['type'] == 'Crane'
                                ? Colors.redAccent.withOpacity(0.3)
                                : Colors.greenAccent.withOpacity(0.2),
                      );
                    }).toList(),
              ),
            ],
          );
        }
        break;

      case 'Le Roi des Mèmes':
        final winnerId = gameData['roundWinnerId'];
        if (winnerId != null) {
          final winnerName = players[winnerId]?['name'] ?? 'Quelqu\'un';
          final winningDescription =
              (gameData['answers'] as Map<String, dynamic>?)?[winnerId] ??
              'une description hilarante';
          resultText = "$winnerName a gagnÃƒÂ© avec sa description :";
          extraInfo = Column(
            children: [
              Text(
                '"${winningDescription}"',
                style: Theme.of(
                  context,
                ).textTheme.titleLarge?.copyWith(color: Colors.greenAccent),
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 15),
              if (memeUrl != null)
                Container(
                  constraints: BoxConstraints(maxHeight: 250),
                  child: Image.network(
                    memeUrl,
                    fit: BoxFit.contain,
                    errorBuilder:
                        (context, error, stackTrace) => Center(
                          child: Text("Erreur de chargement du mÃƒÂ¨me."),
                        ),
                  ),
                ),
            ],
          );
        } else {
          resultText =
              "Personne n'a gagnÃƒÂ© ce tour. Ãƒâ€°galitÃƒÂ© des votes ou pas de description.";
          extraInfo = Text(
            gameEndReason ?? "",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
            textAlign: TextAlign.center,
          );
        }
        break;

      case 'Dobble':
        final winnerId = gameData['roundWinnerId'];
        if (winnerId != null) {
          final winnerName = players[winnerId]?['name'] ?? 'Quelqu\'un';
          final commonSym = gameData['commonSymbol'];
          resultText =
              "$winnerName a trouvÃƒÂ© le symbole $commonSym ! Il gagne la carte.";
          extraInfo = Text(
            "Score actuel de ${players[winnerId]?['name'] ?? 'Lui'}: ${players[winnerId]?['score'] ?? 0} cartes.",
            style: TextStyle(fontStyle: FontStyle.italic),
          );
        } else {
          resultText =
              "Le tour est terminÃƒÂ©. Personne n'a trouvÃƒÂ© le symbole commun.";
          extraInfo = Text(
            gameEndReason ?? "Un problÃƒÂ¨me est survenu.",
            style: TextStyle(fontStyle: FontStyle.italic),
          );
        }
        break;

      case 'Qui Pourrait le Plus ?':
      default:
        final roundWinnerId = gameData['roundWinnerId'];
        if (roundWinnerId != null) {
          final winnerName = players[roundWinnerId]?['name'] ?? 'Inconnu';
          resultText =
              "$winnerName a ÃƒÂ©tÃƒÂ© dÃƒÂ©signÃƒÂ©(e) et gagne 1 point !";
        } else {
          resultText =
              "Ãƒâ€°galitÃƒÂ© ! Personne ne marque de point ce tour-ci.";
        }
        break;
    }

    // Affichage final de la carte de rÃƒÂ©sultat
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text("Fin du tour", style: Theme.of(context).textTheme.headlineMedium),
        SizedBox(height: 20),
        Card(
          child: Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              resultText,
              textAlign: TextAlign.center,
              style: Theme.of(context).textTheme.titleLarge,
            ),
          ),
        ),
        SizedBox(height: 10),
        if (extraInfo != null) extraInfo,
        SizedBox(height: 40),

        // Affichage des contrÃƒÂ´les (HÃƒÂ´te vs Client)
        if (isHost && !isSkullGameOver)
          ElevatedButton(
            onPressed:
                _isActionPending
                    ? null
                    : () {
                      setState(() => _isActionPending = true);

                      if (gameType == 'Dobble') {
                        _firebaseService
                            .nextDobbleRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      } else if (gameType == 'La Patate Chaude' ||
                          gameType == 'Le Jeu des Catégories') {
                        _firebaseService
                            .nextHotPotatoRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      } else if (gameType == 'Pictionary') {
                        _firebaseService
                            .nextPictionaryRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      } else if (gameType == 'Just One') {
                        _firebaseService
                            .nextJustOneRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      } else if (gameType == 'Skull') {
                        _firebaseService
                            .nextSkullRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      } else {
                        _firebaseService
                            .nextRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      }
                    },
            child:
                _isActionPending
                    ? SizedBox(
                      height: 20,
                      width: 20,
                      child: CircularProgressIndicator(
                        color: Colors.white,
                        strokeWidth: 2,
                      ),
                    )
                    : Text("Tour suivant"),
          )
        else if (isSkullGameOver)
          TextButton(
            onPressed: () => _exitGame(),
            child: Text("Retour ÃƒÂ  l'accueil"),
          )
        else
          Text(
            "En attente de l'hÃƒÂ´te pour le tour suivant...",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          ),
      ],
    );
  }

  Widget _buildWaitingWidget(
    String message,
    Map<String, dynamic> players,
    int currentCount,
    int totalExpected,
  ) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        CircularProgressIndicator(
          value: totalExpected > 0 ? currentCount / totalExpected : null,
          backgroundColor: Colors.white12,
          valueColor: AlwaysStoppedAnimation<Color>(Colors.deepPurpleAccent),
        ),
        SizedBox(height: 20),
        Text(
          message,
          style: TextStyle(color: Colors.white70, fontStyle: FontStyle.italic),
          textAlign: TextAlign.center,
        ),
        if (totalExpected > 0)
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Text(
              "$currentCount / $totalExpected",
              style: TextStyle(color: Colors.white, fontSize: 18),
            ),
          ),

        if (_isActionPending)
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Text(
              "Votre action est en cours d'enregistrement...",
              style: TextStyle(color: Colors.amberAccent, fontSize: 14),
            ),
          ),
      ],
    );
  }

  Widget _buildCodenamesUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'],
    );
    final List<String> redTeam = List<String>.from(gameData['redTeam'] ?? []);
    final List<String> blueTeam = List<String>.from(gameData['blueTeam'] ?? []);
    final String? masterSpyRed = gameData['masterSpyRed'];
    final String? masterSpyBlue = gameData['masterSpyBlue'];
    final String activeTeam = gameData['activeTeam'] ?? 'red';
    final String roundState = gameData['roundState'] ?? 'clue_giving';
    final List<String> codenamesWords = List<String>.from(
      gameData['codenamesWords'] ?? [],
    );
    final Map<String, String> keyCard = Map<String, String>.from(
      gameData['codenamesKeyCard'] ?? {},
    );
    final Map<String, bool> revealedWords = Map<String, bool>.from(
      gameData['codenamesRevealed'] ?? {},
    );
    final String? currentClue = gameData['currentClue'];
    final int clueCount = gameData['clueCount'] ?? 0;
    final int guessesLeft = gameData['guessesLeft'] ?? 0;
    final String gameWinner = gameData['gameWinner'] ?? '';
    final String gameEndReason = gameData['gameEndReason'] ?? '';

    bool isMasterSpy = (playerId == masterSpyRed || playerId == masterSpyBlue);
    bool isMyTeamTurn =
        (activeTeam == 'red' && redTeam.contains(playerId)) ||
        (activeTeam == 'blue' && blueTeam.contains(playerId));
    bool canGiveClue =
        isMasterSpy && isMyTeamTurn && roundState == 'clue_giving';
    bool canGuess = !isMasterSpy && isMyTeamTurn && roundState == 'guessing';
    bool isGameOver = gameData['gameState'] == 'gameOver';

    if (isGameOver) {
      final String winnerTeamName =
          gameWinner == 'red'
              ? 'Équipe Rouge'
              : (gameWinner == 'blue'
                  ? 'Équipe Bleue'
                  : (players[gameWinner]?['name'] ?? 'Inconnu'));
      return UniversalGameEndScreen(
        gameTitle: "Codenames",
        winnerId: gameWinner,
        winnerName: winnerTeamName,
        reason: gameEndReason.isNotEmpty ? gameEndReason : "Fin de mission !",
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    return Column(
      children: [
        Container(
          padding: EdgeInsets.symmetric(vertical: 8.0),
          decoration: BoxDecoration(
            color:
                activeTeam == 'red'
                    ? Colors.red.withOpacity(0.2)
                    : Colors.blue.withOpacity(0.2),
            borderRadius: BorderRadius.circular(8),
          ),
          child: Column(
            children: [
              Text(
                "C'est au tour de l'ÃƒÂ©quipe : ${activeTeam == 'red' ? 'Rouge' : 'Bleue'}",
                style: Theme.of(context).textTheme.titleLarge,
              ),
              SizedBox(height: 5),
              Text(
                "Vous ÃƒÂªtes : ${redTeam.contains(playerId) ? 'Ãƒâ€°quipe Rouge' : (blueTeam.contains(playerId) ? 'Ãƒâ€°quipe Bleue' : 'Spectateur')}"
                "${(playerId == masterSpyRed || playerId == masterSpyBlue) ? ' (MaÃƒÂ®tre-espion)' : ' (Agent)'}",
                style: Theme.of(context).textTheme.bodyMedium,
              ),
            ],
          ),
        ),
        SizedBox(height: 15),
        Expanded(
          child: GridView.builder(
            gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 5,
              childAspectRatio: 2.0,
              crossAxisSpacing: 8.0,
              mainAxisSpacing: 8.0,
            ),
            itemCount: codenamesWords.length,
            itemBuilder: (context, index) {
              String word = codenamesWords[index];
              Map<String, dynamic> revealedColors = Map<String, dynamic>.from(
                gameData['codenamesRevealedColors'] ?? {},
              );
              String actualColor = revealedColors[word] ?? 'neutral';
              bool isRevealed = revealedWords[word] ?? false;

              Color cardColor = Colors.grey[800]!;
              Color textColor = Colors.white;

              if (isRevealed) {
                if (actualColor == 'red')
                  cardColor = Colors.red[900]!;
                else if (actualColor == 'blue')
                  cardColor = Colors.blue[900]!;
                else if (actualColor == 'assassin')
                  cardColor = Colors.black;
                else
                  cardColor = Colors.brown[700]!;
              }

              return GestureDetector(
                onTap:
                    canGuess && !isRevealed && !_isActionPending
                        ? () {
                          setState(() => _isActionPending = true);
                          _firebaseService
                              .revealCodenamesWord(widget.gameCode, word)
                              .whenComplete(() {
                                if (mounted)
                                  setState(() => _isActionPending = false);
                              });
                        }
                        : null,

                child: Card(
                  color: cardColor,
                  child: Center(
                    child: Text(
                      word,
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        color: textColor,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
        ),
        SizedBox(height: 15),
        if (isMasterSpy)
          _buildCodenamesMasterSpyUI(context, gameData, playerId, canGiveClue)
        else
          _buildCodenamesAgentUI(context, gameData, playerId, canGuess),
      ],
    );
  }

  Widget _buildCodenamesMasterSpyUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
    bool canGiveClue,
  ) {
    final Map<String, bool> revealedWords = Map<String, bool>.from(
      gameData['codenamesRevealed'] ?? {},
    );
    final List<String> codenamesWords = List<String>.from(
      gameData['codenamesWords'] ?? {},
    );
    final TextEditingController clueController = TextEditingController();
    int chosenCount = 1;

    return StreamBuilder<DocumentSnapshot>(
      stream:
          FirebaseFirestore.instance
              .collection('games')
              .doc(widget.gameCode)
              .collection('private_data')
              .doc(playerId)
              .snapshots(),
      builder: (context, snapshot) {
        Map<String, String> keyCard = {};
        if (snapshot.hasData && snapshot.data!.exists) {
          final pData = snapshot.data!.data() as Map<String, dynamic>?;
          if (pData != null && pData['keyCard'] != null) {
            keyCard = Map<String, String>.from(pData['keyCard']);
          }
        }

        return Column(
          children: [
            Text(
              "Vue Maître-Espion (Carte Clé)",
              style: Theme.of(context).textTheme.titleLarge,
            ),
            SizedBox(
              height: 200,
              child: GridView.builder(
                gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount: 5,
                  childAspectRatio: 1.0,
                  crossAxisSpacing: 4.0,
                  mainAxisSpacing: 4.0,
                ),
                itemCount: codenamesWords.length,
                itemBuilder: (context, index) {
                  String word = codenamesWords[index];
                  String actualColor = keyCard[word] ?? 'neutral';
                  bool isRevealed = revealedWords[word] ?? false;

                  Color dotColor = Colors.grey;
                  if (actualColor == 'red')
                    dotColor = Colors.red;
                  else if (actualColor == 'blue')
                    dotColor = Colors.blue;
                  else if (actualColor == 'assassin')
                    dotColor = Colors.black;

                  return Container(
                    decoration: BoxDecoration(
                      color:
                          isRevealed
                              ? dotColor.withOpacity(0.5)
                              : Colors.grey[900],
                      border: Border.all(color: dotColor, width: 2),
                      borderRadius: BorderRadius.circular(4),
                    ),
                    child: Center(
                      child: Text(
                        word,
                        textAlign: TextAlign.center,
                        style: TextStyle(color: Colors.white, fontSize: 10),
                      ),
                    ),
                  );
                },
              ),
            ),
            SizedBox(height: 10),
            if (canGiveClue)
              Column(
                children: [
                  TextField(
                    controller: clueController,
                    decoration: InputDecoration(
                      labelText: "Votre indice (un mot)",
                    ),
                  ),
                  SizedBox(height: 10),
                  DropdownButtonFormField<int>(
                    value: chosenCount,
                    items:
                        List.generate(10, (index) => index + 1)
                            .map(
                              (count) => DropdownMenuItem(
                                value: count,
                                child: Text("$count"),
                              ),
                            )
                            .toList(),
                    onChanged: (val) => chosenCount = val!,
                    decoration: InputDecoration(labelText: "Nombre de mots"),
                  ),
                  SizedBox(height: 10),

                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () {
                              if (clueController.text.trim().isNotEmpty &&
                                  chosenCount > 0) {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .submitCodenamesClue(
                                      widget.gameCode,
                                      clueController.text.trim(),
                                      chosenCount,
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                                clueController.clear();
                              }
                            },
                    child:
                        _isActionPending
                            ? SizedBox(
                              height: 20,
                              width: 20,
                              child: CircularProgressIndicator(
                                color: Colors.white,
                                strokeWidth: 2,
                              ),
                            )
                            : Text("Donner l'indice"),
                  ),
                ],
              )
            else if (gameData['currentClue'] != null)
              Text(
                "Vous avez donné l'indice: '${gameData['currentClue']} ${gameData['clueCount']}'",
                textAlign: TextAlign.center,
                style: TextStyle(fontStyle: FontStyle.italic),
              ),
          ],
        );
      },
    );
  }

