  Widget _buildSkullUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );

    if (gameData['gameState'] == 'gameOver') {
      return UniversalGameEndScreen(
        gameTitle: "Skull",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason: gameData['gameEndReason'] ?? "Deux défis réussis !",
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? players.keys.toList(),
    );
    final Map<String, dynamic> skullHands = Map<String, dynamic>.from(
      gameData['skullHands'] ?? {},
    );
    final Map<String, dynamic> skullMats = Map<String, dynamic>.from(
      gameData['skullMats'] ?? {},
    );
    final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
    final String? currentPlayerId =
        playerOrder.isNotEmpty && currentPlayerIndex < playerOrder.length
            ? playerOrder[currentPlayerIndex]
            : null;
    final String roundState = gameData['roundState'] ?? 'placing';
    final int currentBid = gameData['skullCurrentBid'] ?? 0;
    final String? highestBidderId = gameData['skullHighestBidderId'];
    final List<String> passedPlayers = List<String>.from(
      gameData['skullPassedPlayers'] ?? [],
    );
    final bool isMyTurn = currentPlayerId == playerId;
    final List<String> myHand = List<String>.from(skullHands[playerId] ?? []);
    final int totalCardsOnTables = skullMats.values.fold<int>(0, (sum, cards) {
      return sum + (cards is List ? cards.length : 0);
    });

    if (roundState == 'result') {
      return _buildResultUI(context, gameData, playerId);
    }

    return Container(
      decoration: const BoxDecoration(
        gradient: RadialGradient(
          center: Alignment.topCenter,
          radius: 1.2,
          colors: [Color(0xFF1A1A28), Color(0xFF09090F)],
        ),
      ),
      child: Column(
        children: [
          // 1. BANDEAU DE STATUT MINIMALISTE
          Container(
            margin: const EdgeInsets.fromLTRB(12, 6, 12, 4),
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
            decoration: BoxDecoration(
              color: const Color(0xFF14141E).withOpacity(0.85),
              borderRadius: BorderRadius.circular(18),
              border: Border.all(color: Colors.white12),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withOpacity(0.35),
                  blurRadius: 10,
                  offset: const Offset(0, 4),
                ),
              ],
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Row(
                  children: [
                    Container(
                      padding: const EdgeInsets.all(6),
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color:
                            isMyTurn
                                ? Colors.amber.withOpacity(0.2)
                                : Colors.white10,
                      ),
                      child: Icon(
                        roundState == 'bidding'
                            ? Icons.whatshot_rounded
                            : Icons.layers_rounded,
                        size: 16,
                        color: isMyTurn ? Colors.amberAccent : Colors.white70,
                      ),
                    ),
                    const SizedBox(width: 10),
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
