                                  : const Color(0xFF13131C),
                          borderRadius: BorderRadius.circular(18),
                          border: Border.all(
                            color:
                                isCurrent
                                    ? Colors.amberAccent.withOpacity(0.8)
                                    : (hasPassed
                                        ? Colors.white10
                                        : Colors.white12),
                            width: isCurrent ? 1.5 : 1,
                          ),
                          boxShadow:
                              isCurrent
                                  ? [
                                    BoxShadow(
                                      color: Colors.amberAccent.withOpacity(
                                        0.15,
                                      ),
                                      blurRadius: 10,
                                    ),
                                  ]
                                  : null,
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              children: [
                                CircleAvatar(
                                  radius: 12,
                                  backgroundColor:
                                      isMe
                                          ? Colors.deepPurpleAccent
                                          : Colors.white24,
                                  child: Text(
                                    name.isNotEmpty
                                        ? name[0].toUpperCase()
                                        : '?',
                                    style: const TextStyle(
                                      fontSize: 10,
                                      color: Colors.white,
                                      fontWeight: FontWeight.bold,
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 8),
                                Expanded(
                                  child: Text(
                                    isMe ? "Moi ($name)" : name,
                                    style: TextStyle(
                                      fontSize: 12,
                                      fontWeight: FontWeight.bold,
                                      color:
                                          isOut ? Colors.white30 : Colors.white,
                                    ),
                                    overflow: TextOverflow.ellipsis,
                                  ),
                                ),
                                // Points / Défis réussis
                                Row(
                                  children: [
                                    Icon(
                                      Icons.star_rounded,
                                      size: 14,
                                      color:
                                          score >= 1
                                              ? Colors.amberAccent
                                              : Colors.white24,
                                    ),
                                    Icon(
                                      Icons.star_rounded,
                                      size: 14,
                                      color:
                                          score >= 2
                                              ? Colors.amberAccent
                                              : Colors.white24,
                                    ),
                                  ],
                                ),
                              ],
                            ),
                            const SizedBox(height: 10),
                            // Tapis de sous-bocks empilés
                            Container(
                              height: 48,
                              alignment: Alignment.center,
                              child:
                                  isOut
                                      ? const Text(
                                        "Éliminé",
                                        style: TextStyle(
                                          color: Colors.redAccent,
                                          fontSize: 11,
                                        ),
                                      )
                                      : hiddenCount == 0
                                      ? const Text(
                                        "Tapis vide",
                                        style: TextStyle(
                                          color: Colors.white24,
                                          fontSize: 11,
                                        ),
                                      )
                                      : Stack(
                                        alignment: Alignment.center,
                                        children: List.generate(hiddenCount, (
                                          i,
                                        ) {
                                          return Positioned(
                                            top: i * 5.0,
                                            child: Container(
                                              width: 70,
                                              height: 28,
                                              decoration: BoxDecoration(
                                                color:
                                                    isMe
                                                        ? const Color(
                                                          0xFF2E1C44,
                                                        )
                                                        : const Color(
                                                          0xFF1E1E28,
                                                        ),
                                                borderRadius:
                                                    BorderRadius.circular(14),
                                                border: Border.all(
                                                  color:
                                                      isMe
                                                          ? Colors.purpleAccent
                                                              .withOpacity(0.5)
                                                          : Colors.white24,
                                                ),
                                                boxShadow: const [
                                                  BoxShadow(
                                                    color: Colors.black45,
                                                    blurRadius: 4,
                                                    offset: Offset(0, 2),
                                                  ),
                                                ],
                                              ),
                                              child: Center(
                                                child: Text(
                                                  isMe
                                                      ? (matCards[i]['type'] ==
                                                              'Crane'
                                                          ? '💀'
                                                          : '🌸')
                                                      : "•",
                                                  style: TextStyle(
                                                    fontSize: isMe ? 12 : 16,
                                                    color: Colors.white70,
                                                  ),
                                                ),
                                              ),
                                            ),
                                          );
                                        }),
                                      ),
                            ),
                            if (hasPassed && !isOut)
                              const Center(
                                child: Padding(
                                  padding: EdgeInsets.only(top: 4.0),
                                  child: Text(
                                    "A PASSÉ",
                                    style: TextStyle(
                                      fontSize: 9,
                                      color: Colors.redAccent,
                                      fontWeight: FontWeight.bold,
                                      letterSpacing: 1,
                                    ),
                                  ),
                                ),
                              ),
                          ],
                        ),
                      );
                    }).toList(),
              ),
            ),
          ),

          // 3. MA MAIN DE DISQUES & ACTIONS (EN BAS)
          Container(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 16),
            decoration: BoxDecoration(
              color: const Color(0xFF101018),
              borderRadius: const BorderRadius.vertical(
                top: Radius.circular(24),
              ),
              border: Border.all(color: Colors.white10),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withOpacity(0.5),
                  blurRadius: 16,
                  offset: const Offset(0, -4),
                ),
              ],
            ),
            child: SafeArea(
              top: false,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Text(
                        "VOTRE MAIN (${myHand.length} cartes)",
                        style: const TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.bold,
                          letterSpacing: 1.5,
                          color: Colors.white54,
                        ),
                      ),
                      if (isMyTurn)
                        Text(
                          roundState == 'placing'
                              ? "Touchez pour poser"
                              : "Enchérissez ou passez",
                          style: const TextStyle(
                            fontSize: 11,
                            color: Colors.amberAccent,
                          ),
                        ),
                    ],
                  ),
                  const SizedBox(height: 12),

                  // Affichage des disques en main (Rose vs Crâne)
                  if (roundState == 'placing') ...[
                    Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        _buildSkullDiscCard(
                          type: 'Rose',
                          label: "ROSE",
                          icon: Icons.filter_vintage_rounded,
                          color: const Color(0xFFF472B6), // Rose doux
                          count: myHand.where((c) => c == 'Rose').length,
                          isMyTurn: isMyTurn,
                          onTap: () {
                            HapticFeedback.lightImpact();
                            setState(() => _isActionPending = true);
                            _firebaseService
                                .placeSkullCard(
                                  widget.gameCode,
                                  playerId,
                                  'Rose',
                                )
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                        ),
                        const SizedBox(width: 16),
                        _buildSkullDiscCard(
                          type: 'Crane',
                          label: "CRÂNE",
                          icon: Icons.coronavirus_rounded,
                          color: const Color(0xFFEF4444), // Rouge crâne
                          count: myHand.where((c) => c == 'Crane').length,
                          isMyTurn: isMyTurn,
                          onTap: () {
                            HapticFeedback.mediumImpact();
                            setState(() => _isActionPending = true);
                            _firebaseService
                                .placeSkullCard(
                                  widget.gameCode,
                                  playerId,
                                  'Crane',
                                )
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                        ),
                      ],
                    ),
                    if (isMyTurn && totalCardsOnTables > 0) ...[
                      const SizedBox(height: 12),
                      SizedBox(
                        width: double.infinity,
                        height: 48,
                        child: OutlinedButton.icon(
                          icon: const Icon(Icons.flash_on_rounded, size: 18),
                          label: const Text("LANCER LE DÉFI (ENCHÈRE)"),
                          style: OutlinedButton.styleFrom(
                            foregroundColor: Colors.amberAccent,
                            side: const BorderSide(
                              color: Colors.amberAccent,
                              width: 1.5,
                            ),
                            shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(14),
                            ),
                          ),
                          onPressed: () async {
                            final int? bid = await _askSkullBid(
                              context,
                              minimumBid: 1,
                              maximumBid: max(1, totalCardsOnTables),
                              playerId: playerId,
                            );
                            if (bid == null) return;
                            setState(() => _isActionPending = true);
                            _firebaseService
                                .startSkullBid(widget.gameCode, playerId, bid)
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                        ),
                      ),
                    ],
                  ] else if (roundState == 'bidding') ...[
                    // Contrôles pendant la surenchère
                    if (isMyTurn) ...[
                      Row(
                        children: [
                          Expanded(
                            child: SizedBox(
                              height: 50,
                              child: OutlinedButton.icon(
                                icon: const Icon(Icons.close_rounded),
                                label: const Text("PASSER"),
                                style: OutlinedButton.styleFrom(
                                  foregroundColor: Colors.redAccent,
                                  side: const BorderSide(
                                    color: Colors.redAccent,
                                    width: 1.5,
                                  ),
                                  shape: RoundedRectangleBorder(
                                    borderRadius: BorderRadius.circular(14),
                                  ),
                                ),
                                onPressed: () {
                                  HapticFeedback.lightImpact();
                                  setState(() => _isActionPending = true);
                                  _firebaseService
                                      .passSkullBid(widget.gameCode, playerId)
                                      .whenComplete(() {
                                        if (mounted)
                                          setState(
                                            () => _isActionPending = false,
                                          );
                                      });
                                },
                              ),
                            ),
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: SizedBox(
                              height: 50,
                              child: ElevatedButton.icon(
                                icon: const Icon(Icons.trending_up_rounded),
                                label: const Text("SURENCHÉRIR"),
                                style: ElevatedButton.styleFrom(
                                  backgroundColor: Colors.amber[700],
                                  foregroundColor: Colors.black,
                                  elevation: 4,
                                  shape: RoundedRectangleBorder(
                                    borderRadius: BorderRadius.circular(14),
                                  ),
                                ),
                                onPressed:
                                    currentBid >= totalCardsOnTables
                                        ? null
                                        : () async {
                                          final int? bid = await _askSkullBid(
                                            context,
                                            minimumBid: currentBid + 1,
                                            maximumBid: totalCardsOnTables,
                                            playerId: playerId,
                                          );
                                          if (bid == null) return;
                                          setState(
                                            () => _isActionPending = true,
                                          );
                                          _firebaseService
                                              .raiseSkullBid(
                                                widget.gameCode,
                                                playerId,
                                                bid,
                                              )
                                              .whenComplete(() {
                                                if (mounted) {
                                                  setState(
                                                    () =>
                                                        _isActionPending =
                                                            false,
                                                  );
                                                }
                                              });
                                        },
                              ),
                            ),
                          ),
                        ],
                      ),
                    ] else ...[
                      Container(
                        padding: const EdgeInsets.all(12),
                        alignment: Alignment.center,
                        child: const Text(
                          "En attente de la décision du joueur en cours...",
                          style: TextStyle(
                            color: Colors.white54,
                            fontStyle: FontStyle.italic,
                          ),
                        ),
                      ),
                    ],
                  ],
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  // --- WIDGET HELPER : DISQUE SKULL TACTILE & MODERNE ---
  Widget _buildSkullDiscCard({
    required String type,
    required String label,
    required IconData icon,
    required Color color,
    required int count,
    required bool isMyTurn,
    required VoidCallback onTap,
  }) {
    final bool hasCard = count > 0;
    final bool canInteract = isMyTurn && hasCard && !_isActionPending;

    return Expanded(
      child: GestureDetector(
        onTap: canInteract ? onTap : null,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 200),
          padding: const EdgeInsets.symmetric(vertical: 14, horizontal: 12),
          decoration: BoxDecoration(
            gradient: LinearGradient(
              colors: [
                canInteract
                    ? color.withOpacity(0.25)
                    : Colors.white.withOpacity(0.04),
                canInteract
                    ? color.withOpacity(0.08)
                    : Colors.white.withOpacity(0.02),
              ],
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
            ),
            borderRadius: BorderRadius.circular(20),
            border: Border.all(
              color: canInteract ? color.withOpacity(0.8) : Colors.white12,
              width: canInteract ? 1.5 : 1,
            ),
            boxShadow:
                canInteract
                    ? [
                      BoxShadow(
                        color: color.withOpacity(0.2),
                        blurRadius: 10,
                        offset: const Offset(0, 4),
                      ),
                    ]
                    : [],
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  Text(
                    label,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w900,
                      letterSpacing: 1,
                      color: hasCard ? color : Colors.white30,
                    ),
                  ),
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 7,
                      vertical: 2,
                    ),
                    decoration: BoxDecoration(
                      color: hasCard ? color.withOpacity(0.2) : Colors.white10,
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: Text(
                      "x$count",
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.bold,
                        color: hasCard ? color : Colors.white30,
                      ),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              Icon(icon, size: 38, color: hasCard ? color : Colors.white24),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildPictionaryUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'setup';
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final String? currentDrawingPlayerId = gameData['currentDrawingPlayerId'];
    final String? currentPictionaryWord = gameData['currentPictionaryWord'];
    final String? pictionaryDrawingData = gameData['pictionaryDrawing'];

    final Timestamp? startTime = gameData['pictionaryStartTime'];
    final int roundDuration =
        (roundState == 'drawing')
            ? (gameData['turnTimerSeconds'] ?? 90)
            : (gameData['resultTimerSeconds'] ?? 30);

    int secondsRemaining = 0;
    if (startTime != null) {
      secondsRemaining = max(
        0,
        roundDuration - DateTime.now().difference(startTime.toDate()).inSeconds,
      );
    }

    final bool pictionaryOnly30Strokes =
        gameData['pictionaryOnly30Strokes'] == true;
    final bool isCollective = gameData['pictionaryTeams'] == true;
    final int collectiveCardIndex =
        (gameData['pictionaryCollectiveCardIndex'] ?? 0) as int;
    final int collectiveGuessed =
        (gameData['pictionaryCollectiveGuessed'] ?? 0) as int;
    final int collectiveTotal =
        (gameData['pictionaryCollectiveWords'] as List?)?.length ?? 13;
    final bool amIDrawingPlayer = playerId == currentDrawingPlayerId;
    final bool drawingBlocked =
        pictionaryOnly30Strokes && _pictionaryStrokeCount >= 30;
    final String drawerName =
        players[currentDrawingPlayerId]?['name'] ?? 'Quelqu\'un';

    if (roundState == 'result') {
      return _buildResultUI(context, gameData, playerId);
    }

    return Column(
      children: [
        // EN-TÊTE AVEC INFO (Simplifié)
        if (amIDrawingPlayer)
          Container(
            padding: EdgeInsets.symmetric(vertical: 4),
            child: Text(
              'Mot à dessiner : ${currentPictionaryWord ?? "..."}',
              style: TextStyle(
                fontSize: 22,
                fontWeight: FontWeight.bold,
                color: Colors.amberAccent,
              ),
              textAlign: TextAlign.center,
            ),
          ),
        SizedBox(height: 6),

        // ZONE DE DESSIN (TABLEAU BLANC)
        Expanded(
          flex: 5,
          child: Container(
            margin: EdgeInsets.symmetric(horizontal: 8),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(12),
              border: Border.all(
                color: Colors.grey[400]!,
                width: 8,
              ), // Cadre ÃƒÂ©pais style tableau
              boxShadow: [
                BoxShadow(
                  color: Colors.black45,
                  blurRadius: 10,
                  offset: Offset(0, 5),
                ),
              ],
            ),
            child: Stack(
              children: [
                // Canvas ou Image
                ClipRRect(
                  borderRadius: BorderRadius.circular(4),
                  child:
                      amIDrawingPlayer
                          ? (pictionaryOnly30Strokes
                              // Mode 30 traits : segments droits uniquement
                              ? RepaintBoundary(
                                key: _straightLineKey,
                                child: GestureDetector(
                                  onPanStart:
                                      drawingBlocked
                                          ? null
                                          : (d) {
                                            setState(
                                              () =>
                                                  _straightLineStart =
                                                      d.localPosition,
                                            );
                                          },
                                  onPanUpdate:
                                      drawingBlocked
                                          ? null
                                          : (d) {
                                            if (_straightLineStart != null) {
                                              setState(
                                                () =>
                                                    _straightLineCurrentEnd =
                                                        d.localPosition,
                                              );
                                            }
                                          },
                                  onPanEnd:
                                      drawingBlocked
                                          ? null
                                          : (d) async {
                                            if (_straightLineStart == null ||
                                                _straightLineCurrentEnd == null)
                                              return;
                                            setState(() {
                                              _straightLinePoints.add(
                                                _straightLineStart!,
                                              );
                                              _straightLinePoints.add(
                                                _straightLineCurrentEnd!,
                                              );
                                              _straightLineStart = null;
                                              _straightLineCurrentEnd = null;
                                              _pictionaryStrokeCount++;
                                            });
                                            // Capture and upload
                                            await Future.delayed(
                                              Duration(milliseconds: 50),
                                            );
                                            if (!mounted) return;
                                            try {
                                              final boundary =
                                                  _straightLineKey
                                                          .currentContext
                                                          ?.findRenderObject()
                                                      as RenderRepaintBoundary?;
                                              if (boundary != null) {
                                                final image = await boundary
                                                    .toImage(pixelRatio: 1.0);
                                                final bytes = await image
                                                    .toByteData(
                                                      format:
                                                          ui
                                                              .ImageByteFormat
                                                              .png,
                                                    );
                                                if (bytes != null && mounted) {
                                                  final base64Image =
                                                      base64Encode(
                                                        bytes.buffer
                                                            .asUint8List(),
                                                      );
                                                  await _firebaseService
                                                      .updatePictionaryDrawing(
                                                        widget.gameCode,
                                                        base64Image,
                                                        _pictionaryStrokeCount,
                                                      );
                                                }
                                              }
                                            } catch (_) {}
                                          },
                                  child: CustomPaint(
                                    foregroundPainter: _StraightLinePainter(
                                      points: _straightLinePoints,
                                      currentStart: _straightLineStart,
                                      currentEnd: _straightLineCurrentEnd,
                                    ),
                                    child: Container(color: Colors.white),
                                  ),
                                ),
                              )
                              // Mode libre : Signature widget
                              : AbsorbPointer(
                                absorbing: drawingBlocked,
                                child: Listener(
                                  onPointerUp: (_) async {
                                    setState(() => _pictionaryStrokeCount++);
                                    if (_pictionaryDrawingController
                                        .isNotEmpty) {
                                      final pngBytes =
                                          await _pictionaryDrawingController
                                              .toPngBytes();
                                      if (pngBytes != null) {
                                        final String base64Image = base64Encode(
                                          pngBytes,
                                        );
                                        await _firebaseService
                                            .updatePictionaryDrawing(
                                              widget.gameCode,
                                              base64Image,
                                              _pictionaryStrokeCount,
                                            );
                                      }
                                    }
                                  },
                                  child: Signature(
                                    controller: _pictionaryDrawingController,
                                    backgroundColor: Colors.white,
                                  ),
                                ),
                              ))
                          // Utilisation de Realtime Database pour ÃƒÂ©viter le spam de StreamBuilder Firestore
                          : StreamBuilder<DatabaseEvent>(
                            stream:
                                FirebaseDatabase.instance
                                    .ref(
                                      'games/${widget.gameCode}/pictionary/drawing',
                                    )
                                    .onValue,
                            builder: (context, snapshot) {
                              final data =
                                  snapshot.data?.snapshot.value as String?;
                              if (data != null &&
                                  data.isNotEmpty &&
                                  data != 'rtdb_used') {
                                return Image.memory(
                                  base64Decode(data),
                                  gaplessPlayback: true,
                                  fit: BoxFit.contain,
                                  width: double.infinity,
                                  height: double.infinity,
                                  filterQuality: FilterQuality.low,
                                );
                              }
                              return Center(
                                child: Column(
                                  mainAxisAlignment: MainAxisAlignment.center,
                                  children: [
                                    Icon(
                                      Icons.brush,
                                      size: 40,
                                      color: Colors.grey[300],
                                    ),
                                    Text(
                                      "En attente du dessin...",
                                      style: TextStyle(color: Colors.grey[400]),
                                    ),
                                  ],
                                ),
                              );
                            },
                          ),
                ),

                // Petit badge avec le nom de l'artiste et compteur de traits
                Positioned(
                  top: 10,
                  left: 10,
                  child: Container(
                    padding: EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    decoration: BoxDecoration(
                      color: Colors.black12,
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: Row(
                      children: [
                        Icon(Icons.edit, size: 12, color: Colors.black54),
                        SizedBox(width: 4),
                        Text(
                          drawerName,
                          style: TextStyle(color: Colors.black54, fontSize: 12),
                        ),
                        if (pictionaryOnly30Strokes && amIDrawingPlayer) ...[
                          SizedBox(width: 8),
                          Text(
                            "$_pictionaryStrokeCount/30 traits",
                            style: TextStyle(
                              color:
                                  drawingBlocked ? Colors.red : Colors.black54,
                              fontSize: 12,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ],
                      ],
                    ),
                  ),
                ),

                // Bouton Clear pour le dessinateur
                if (amIDrawingPlayer)
                  Positioned(
                    top: 10,
                    right: 10,
                    child: IconButton(
                      icon: Icon(Icons.delete, color: Colors.red),
                      onPressed: () {
                        setState(() {
                          _pictionaryStrokeCount = 0;
                          _straightLinePoints = [];
                          _straightLineStart = null;
                          _straightLineCurrentEnd = null;
                        });
                        _pictionaryDrawingController.clear();
                        _firebaseService.updatePictionaryDrawing(
                          widget.gameCode,
                          "",
                          0,
                        );
                      },
                    ),
                  ),
              ],
            ),
          ),
        ),

        // ZONE DE CHAT / DEVINETTES
        Expanded(
          flex: 4,
          child: Column(
            children: [
              Expanded(
                child: Builder(
                  builder: (context) {
                    // Utilisation du Provider pour avoir les mises ÃƒÂ  jour en temps rÃƒÂ©el
                    final gameDataFromProvider =
                        Provider.of<DocumentSnapshot>(
                              context,
                              listen: true,
                            ).data()
                            as Map<String, dynamic>;
                    final List<dynamic> pictionaryGuesses = List.from(
                      gameDataFromProvider['pictionaryGuesses'] ?? [],
                    );

                    pictionaryGuesses.sort(
                      (a, b) => (a['timestamp'] as int).compareTo(
                        b['timestamp'] as int,
                      ),
                    );

                    return ListView.builder(
                      reverse:
                          true, // Pour afficher les nouveaux messages en bas
                      itemCount: pictionaryGuesses.length,
                      itemBuilder: (context, index) {
                        final guessData =
                            pictionaryGuesses.reversed.toList()[index]
                                as Map<String, dynamic>;

                        return Card(
                          color: Colors.grey[900],
                          margin: EdgeInsets.symmetric(
                            vertical: 2,
                            horizontal: 8,
                          ),
                          child: ListTile(
                            dense: true,
                            title: Text(
                              guessData['guess'] ?? '',
                              style: TextStyle(fontWeight: FontWeight.bold),
                            ),
                            subtitle: Text(
                              guessData['guesserName'] ?? '...',
                              style: TextStyle(fontSize: 10),
                            ),
                            // Bouton pour valider la bonne rÃƒÂ©ponse (seulement pour le dessinateur)
                            trailing:
                                amIDrawingPlayer
                                    ? ElevatedButton(
                                      onPressed:
                                          () => _firebaseService
                                              .validatePictionaryGuess(
                                                widget.gameCode,
                                                guessData['guesserId'],
                                              ),
                                      child: Icon(Icons.check, size: 16),
                                      style: ElevatedButton.styleFrom(
                                        backgroundColor: Colors.green,
                                        padding: EdgeInsets.all(8),
                                        shape: CircleBorder(),
                                        minimumSize: Size(30, 30),
                                      ),
                                    )
                                    : null,
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _buildJustOneUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'clue_giving';
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final String? justOneGuesserId = gameData['justOneGuesserId'];
    final String? justOneCurrentWord = gameData['justOneCurrentWord'];
    final Map<String, dynamic> justOneClues = Map<String, dynamic>.from(
      gameData['justOneClues'] ?? {},
    );
    final List<dynamic> justOneFilteredClues = List<dynamic>.from(
      gameData['justOneFilteredClues'] ?? [],
    );
    final int deckIndex = (gameData['justOneDeckIndex'] ?? 0) + 1;
    final int deckTotal = (gameData['justOneDeck'] as List?)?.length ?? 13;
    final int totalScore = gameData['justOneTotalScore'] ?? 0;

    bool amIGuesser = playerId == justOneGuesserId;
    String guesserName = players[justOneGuesserId]?['name'] ?? 'Quelqu\'un';

    // Reset flag si nouveau tour (indice pas encore soumis)
    if (roundState == 'clue_giving' && !justOneClues.containsKey(playerId)) {
      _justOneHasSubmittedClue = false;
    }

    // Fin de partie collective
    if (gameData['gameState'] == 'gameOver') {
      String rating =
          totalScore >= 12
              ? 'Ã°Å¸Ââ€  LÃƒÂ©gendaire !'
              : totalScore >= 10
              ? 'Ã¢Â­Â Excellent !'
              : totalScore >= 7
              ? 'Ã°Å¸â€˜Â Bien jouÃƒÂ© !'
              : totalScore >= 4
              ? 'Ã°Å¸Ëœâ€¦ Pas mal !'
              : 'Ã°Å¸â€™Âª On peut mieux faire !';
      bool isHost = gameData['hostId'] == playerId;
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie terminÃƒÂ©e !",
                  style: Theme.of(context).textTheme.headlineMedium,
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 16),
                Text(
                  "Score collectif",
                  style: Theme.of(context).textTheme.titleLarge,
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 8),
                Text(
                  "$totalScore / $deckTotal",
                  style: TextStyle(
                    fontSize: 64,
                    fontWeight: FontWeight.bold,
                    color: Colors.amberAccent,
                  ),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 8),
                Text(
                  rating,
                  style: TextStyle(fontSize: 22),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 24),
                if (isHost)
                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () {
                              setState(() => _isActionPending = true);
                              _firebaseService
                                  .returnToLobby(widget.gameCode)
                                  .whenComplete(() {
                                    if (mounted)
                                      setState(() => _isActionPending = false);
                                  });
                            },
                    child: Text("Retour au salon"),
                  ),
              ],
            ),
          ),
        ),
      );
    }

    // RÃƒÂ©sultat du tour
    if (roundState == 'result') {
      final String answer = gameData['justOneGuesserAnswer'] ?? '';
      final bool wasCorrect =
          answer.trim().toLowerCase() ==
          (justOneCurrentWord ?? '').toLowerCase();
      bool isHost = gameData['hostId'] == playerId;
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Carte $deckIndex / $deckTotal",
                  style: TextStyle(color: Colors.white54, fontSize: 14),
                ),
                SizedBox(height: 12),
                Text(
                  wasCorrect ? "Ã¢Å“â€¦ Bravo !" : "Ã¢ÂÅ’ RatÃƒÂ© !",
                  style: TextStyle(
                    fontSize: 28,
                    fontWeight: FontWeight.bold,
                    color: wasCorrect ? Colors.greenAccent : Colors.redAccent,
                  ),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 8),
                Text(
                  "Le mot ÃƒÂ©tait : ${justOneCurrentWord ?? ''}",
                  style: Theme.of(context).textTheme.titleLarge,
                  textAlign: TextAlign.center,
                ),
                if (answer.isNotEmpty)
                  Text(
                    "RÃƒÂ©ponse de $guesserName : \"$answer\"",
                    style: TextStyle(color: Colors.white70),
                    textAlign: TextAlign.center,
                  ),
                SizedBox(height: 16),
                Container(
                  padding: EdgeInsets.symmetric(horizontal: 24, vertical: 12),
                  decoration: BoxDecoration(
                    color: Colors.amberAccent.withOpacity(0.15),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Text(
                    "Score : $totalScore / $deckIndex",
                    style: TextStyle(
                      fontSize: 20,
                      fontWeight: FontWeight.bold,
                      color: Colors.amberAccent,
                    ),
                  ),
                ),
                SizedBox(height: 20),
                if (isHost)
                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () {
                              setState(() => _isActionPending = true);
                              _firebaseService
                                  .nextJustOneRound(widget.gameCode)
                                  .whenComplete(() {
                                    if (mounted)
                                      setState(() => _isActionPending = false);
                                  });
                            },
                    child:
                        _isActionPending
                            ? CircularProgressIndicator(color: Colors.white)
                            : Text(
                              deckIndex >= deckTotal
                                  ? "Voir le score final"
                                  : "Carte suivante Ã¢â€ â€™",
                            ),
                  ),
                if (!isHost)
                  Text(
                    "En attente de l'hÃƒÂ´te pour la suite...",
                    style: TextStyle(color: Colors.white54),
                  ),
              ],
            ),
          ),
        ),
      );
    }

    switch (roundState) {
      // --- PHASE 2 : LES AUTRES Ãƒâ€°CRIVENT LES INDICES ---
      case 'clue_giving':
        if (amIGuesser) {
          return Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(
                "Chut ! Ferme les yeux Ã°Å¸â„¢Ë†",
                style: Theme.of(context).textTheme.headlineSmall,
              ),
              SizedBox(height: 8),
              Text(
                "Carte $deckIndex / $deckTotal",
                style: TextStyle(color: Colors.white54, fontSize: 14),
              ),
              SizedBox(height: 20),
              Text(
                "Les autres ÃƒÂ©crivent des indices pour toi...",
                style: TextStyle(fontSize: 16, color: Colors.white70),
              ),
              SizedBox(height: 30),
              _buildWaitingWidget(
