  Widget _buildHotPotatoUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'playing';
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final String? currentPotatoPlayerId = gameData['hotPotatoCurrentPlayerId'];

    // Handle gameOver for Categories
    if (gameData['gameState'] == 'gameOver') {
      final String gameEndReason =
          gameData['gameEndReason'] ?? 'Partie terminÃƒÂ©e !';
      List<MapEntry<String, int>> sortedScores = [];
      players.forEach((id, data) {
        sortedScores.add(
          MapEntry(data['name'] ?? 'Inconnu', data['score'] ?? 0),
        );
      });
      sortedScores.sort((a, b) => a.value.compareTo(b.value));
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie TerminÃƒÂ©e !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                SizedBox(height: 10),
                Text(
                  gameEndReason,
                  style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                    color: Colors.amberAccent,
                  ),
                ),
                SizedBox(height: 20),
                Text(
                  "Classement final",
                  style: Theme.of(context).textTheme.titleLarge,
                ),
                SizedBox(height: 8),
                ...sortedScores.asMap().entries.map(
                  (e) => Padding(
                    padding: const EdgeInsets.symmetric(vertical: 2),
                    child: Text(
                      "${e.key + 1}. ${e.value.key}: ${e.value.value} pt${e.value.value > 1 ? 's' : ''}",
                      style: TextStyle(
                        fontSize: 16,
                        fontWeight:
                            e.key == 0 ? FontWeight.bold : FontWeight.normal,
                      ),
                    ),
                  ),
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      () => Navigator.of(
                        context,
                      ).popUntil((route) => route.isFirst),
                  child: Text("Retour ÃƒÂ  l'accueil"),
                ),
              ],
            ),
          ),
        ),
      );
    }

    int secondsLeft = gameData['hotPotatoSecondsLeft'] ?? 0;
    if (gameData['hotPotatoRoundStartedAt'] != null) {
      final Timestamp startTimeStamp = gameData['hotPotatoRoundStartedAt'];
      final DateTime startTime = startTimeStamp.toDate();
      final int duration = secondsLeft;
      final int elapsed = DateTime.now().difference(startTime).inSeconds;
      secondsLeft = max(0, duration - elapsed);
    }

    final String category = gameData['hotPotatoCategory'] ?? "CatÃƒÂ©gorie";
    final List<String> usedAnswers = List<String>.from(
      gameData['hotPotatoUsedAnswers'] ?? [],
    );

    final bool isMyTurn = playerId == currentPotatoPlayerId;
    final String currentPotatoPlayerName =
        players[currentPotatoPlayerId]?['name'] ?? 'Quelqu\'un';

    if (roundState == 'exploded') {
      return _buildHotPotatoExplodedUI(context, gameData, playerId);
    }

    // Couleur de fond dynamique (Vert -> Rouge)
    Color timerColor =
        secondsLeft > 10
            ? Colors.green
            : (secondsLeft > 5 ? Colors.orange : Colors.red);
    // Animation simple de pulsation quand il reste peu de temps
    double pulseScale =
        isMyTurn
            ? (1.0 +
                (secondsLeft <= 5
                    ? (DateTime.now().millisecond % 500) / 1000.0
                    : 0.0))
            : 1.0;

    final String gameType = gameData['gameType'] ?? '';
    final bool isCategories = gameType == 'Le Jeu des Catégories';
    final int currentRound = gameData['currentRound'] ?? 1;

    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        // Round & score info for Categories
        if (isCategories) ...[
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                "Manche $currentRound",
                style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14),
              ),
              Row(
                mainAxisSize: MainAxisSize.min,
                children:
                    players.entries
                        .map(
                          (e) => Padding(
                            padding: const EdgeInsets.symmetric(horizontal: 4),
                            child: Chip(
                              label: Text(
                                "${e.value['name']?.toString().substring(0, min(4, (e.value['name']?.toString().length ?? 0)))}: ${e.value['score'] ?? 0}",
                                style: TextStyle(fontSize: 11),
                              ),
                              padding: EdgeInsets.zero,
                              visualDensity: VisualDensity.compact,
                            ),
                          ),
                        )
                        .toList(),
              ),
            ],
          ),
          SizedBox(height: 8),
        ],
        // Indicateur de tour
        Container(
          padding: EdgeInsets.all(16),
          decoration: BoxDecoration(
            color:
                isMyTurn
                    ? Colors.redAccent.withOpacity(0.2)
                    : Colors.transparent,
            borderRadius: BorderRadius.circular(20),
            border:
                isMyTurn ? Border.all(color: Colors.redAccent, width: 2) : null,
          ),
          child: Column(
            children: [
              Text(
                isMyTurn
                    ? "C'EST Ãƒâ‚¬ TOI !"
                    : "Au tour de $currentPotatoPlayerName",
                style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                  fontWeight: FontWeight.bold,
                  color: isMyTurn ? Colors.redAccent : Colors.white,
                ),
              ),
              SizedBox(height: 10),
              // Bombe visuelle
              Transform.scale(
                scale: pulseScale,
                child: Container(
                  width: 100,
                  height: 100,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: Colors.black,
                    boxShadow: [
                      BoxShadow(
                        color: timerColor,
                        blurRadius: 20,
                        spreadRadius: 5,
                      ),
                    ],
                  ),
                  child: Center(
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Icon(
                          Icons.local_fire_department,
                          color: timerColor,
                          size: 40,
                        ),
                        Text(
                          "$secondsLeft",
                          style: TextStyle(
                            fontSize: 24,
                            fontWeight: FontWeight.bold,
                            color: Colors.white,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),

        SizedBox(height: 30),

        // Carte de la catÃƒÂ©gorie
        Card(
          elevation: 8,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(15),
          ),
          child: Container(
            width: double.infinity,
            padding: const EdgeInsets.all(24.0),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(15),
              gradient: LinearGradient(
                colors: [Colors.deepPurple[700]!, Colors.deepPurple[900]!],
              ),
            ),
            child: Column(
              children: [
                Text(
                  "CatÃƒÂ©gorie",
                  style: TextStyle(color: Colors.white70, letterSpacing: 2),
                ),
                SizedBox(height: 10),
                Text(
                  category,
                  style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                    color: Colors.white,
                    fontWeight: FontWeight.bold,
                  ),
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),
        ),

        SizedBox(height: 20),

        // Zone de saisie (active seulement si c'est mon tour)
        if (isMyTurn)
          Column(
            children: [
              TextField(
                controller: _answerController,
                autofocus: true,
                decoration: InputDecoration(
                  labelText: "Vite ! Un mot !",
                  filled: true,
                  fillColor: Colors.white,
                  labelStyle: TextStyle(color: Colors.black54),
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(30),
                  ),
                ),
                style: TextStyle(color: Colors.black, fontSize: 18),
                onSubmitted: (_) => _submitHotPotatoAnswer(),
              ),
              SizedBox(height: 15),
              ElevatedButton.icon(
                icon: Icon(Icons.send),
                label: Text("VALIDER & PASSER"),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.redAccent,
                  padding: EdgeInsets.symmetric(horizontal: 40, vertical: 15),
                  textStyle: TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                onPressed:
                    _isActionPending ? null : () => _submitHotPotatoAnswer(),
              ),
            ],
          )
        else
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              "PrÃƒÂ©pare ta rÃƒÂ©ponse pendant que les autres paniquent...",
              style: TextStyle(
                fontStyle: FontStyle.italic,
                color: Colors.white38,
              ),
            ),
          ),

        Spacer(),

        // Historique des mots
        Container(
          height: 100,
          child: SingleChildScrollView(
            reverse: true,
            child: Wrap(
              spacing: 8.0,
              runSpacing: 4.0,
              alignment: WrapAlignment.center,
              children:
                  usedAnswers
                      .map(
                        (answer) => Chip(
                          label: Text(answer),
                          backgroundColor: Colors.grey[800],
                        ),
                      )
                      .toList(),
            ),
          ),
        ),
      ],
    );
  }

  void _submitHotPotatoAnswer() async {
    if (_isActionPending) return;

    // --- CORRECTION ICI ---
    // Au lieu de : final String playerId = Provider.of<String>(context, listen: false);
    // Utilisez ceci :
    final String playerId = widget.playerId;
    // ----------------------

    final answer = _answerController.text.trim();

    setState(() => _isActionPending = true);
    try {
      await _firebaseService.submitHotPotatoAnswer(
        widget.gameCode,
        playerId,
        answer,
      );
      _answerController.clear();
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(e.toString().replaceAll('Exception: ', ''))),
      );
    } finally {
      if (mounted) setState(() => _isActionPending = false);
    }
  }

  Widget _buildHotPotatoExplodedUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final String? loserId = gameData['roundWinnerId'];
    final String loserName = players[loserId]?['name'] ?? 'Inconnu';
    final String gameEndReason =
        gameData['gameEndReason'] ?? "La patate a explosÃƒÂ© !";
    final isHost = gameData['hostId'] == playerId;
    final String gameType = gameData['gameType'] ?? '';
    final bool isCategories = gameType == 'Le Jeu des Catégories';

    if (_isHotPotatoMusicPlaying) {
      _hotPotatoPlayer?.stop();
      _hotPotatoPlayer?.dispose();
      _hotPotatoPlayer = null;
      _isHotPotatoMusicPlaying = false;
    }

    // Build score list for Categories
    List<MapEntry<String, int>> sortedScores = [];
    if (isCategories) {
      players.forEach((id, data) {
        sortedScores.add(
          MapEntry(data['name'] ?? 'Inconnu', data['score'] ?? 0),
        );
      });
      sortedScores.sort((a, b) => a.value.compareTo(b.value));
    }

    return Column(
      key: ValueKey('exploded_multi'),
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Icon(Icons.local_fire_department, size: 100, color: Colors.redAccent),
        SizedBox(height: 20),
        Text(
          "BOOM !",
          style: Theme.of(context).textTheme.headlineMedium?.copyWith(
            fontSize: 48,
            color: Colors.redAccent,
          ),
        ),
        SizedBox(height: 20),
        Text(
          "$loserName a perdu !",
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        SizedBox(height: 10),
        Text(gameEndReason, style: Theme.of(context).textTheme.bodyMedium),
        if (isCategories) ...[
          SizedBox(height: 20),
          Text(
            "Scores (moins = mieux)",
            style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
          ),
          SizedBox(height: 8),
          ...sortedScores.map(
            (e) => Text(
              "${e.key}: ${e.value} pt${e.value > 1 ? 's' : ''}",
              style: TextStyle(fontSize: 14),
            ),
          ),
        ],
        SizedBox(height: 40),
        if (isHost)
          ElevatedButton(
            onPressed:
                _isActionPending
                    ? null
                    : () async {
                      setState(() => _isActionPending = true);
                      await _firebaseService
                          .nextHotPotatoRound(widget.gameCode)
                          .whenComplete(() {
                            if (mounted)
                              setState(() => _isActionPending = false);
                          });
                    },
            child:
                _isActionPending
                    ? SizedBox(
                      height: 20,
                      width: 20,
                      child: CircularProgressIndicator(
                        color: Colors.white,
                        strokeWidth: 2,
                      ),
                    )
                    : Text("Nouvelle Manche"),
          )
        else
          Text(
            "En attente de l'hÃƒÂ´te pour la prochaine manche...",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          ),
      ],
    );
  }

  String _getLgTransitionLogs(
    String phase,
    String subPhase,
    List<dynamic> logs,
  ) {
    if (logs.isEmpty) return "";
    if (phase == 'nuit' && subPhase == 'initial') {
      return "La nuit tombe sur le village...\n\nFermez les yeux.";
    } else if (phase == 'jour_discussion' && subPhase.isEmpty) {
      List<String> morningLogs = [];
      for (int i = logs.length - 1; i >= 0; i--) {
        String log = logs[i].toString();
        morningLogs.insert(0, log);
        if (log.contains("Le soleil se lÃ¨ve")) break;
      }
      return morningLogs.join("\n\n");
    } else if (phase == 'jour_vote') {
      return "Le moment est venu...\n\nLe village doit voter.";
    }
    return "";
  }

  // ===========================================================================
  // INTERFACE MODERNE & MINIMALISTE - LOUP-GAROU
  // ===========================================================================

  Widget _buildLoupGarouUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String phase = gameData['phase'] ?? 'lobby';
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final List<dynamic> gameLog = List<dynamic>.from(gameData['gameLog'] ?? []);

    if (phase == 'gameOver' || gameData['gameState'] == 'gameOver') {
      String winnerText = gameData['gameWinner'] ?? 'Fin de la partie';
      if (winnerText == 'village')
        winnerText = 'Victoire des Villageois !';
      else if (winnerText == 'loups')
        winnerText = 'Victoire des Loups-Garous !';
      else if (winnerText == 'amoureux')
        winnerText = 'Victoire des Amoureux !';
      return UniversalGameEndScreen(
        gameTitle: "Loup-Garou",
        winnerId: gameData['gameWinner'],
        winnerName: winnerText,
        reason:
            gameLog.isNotEmpty
                ? gameLog.last.toString()
                : (gameData['gameEndReason'] ?? "Fin du jeu"),
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    final String subPhase = gameData['subPhase'] ?? '';
    final Map<String, dynamic> playerData = Map<String, dynamic>.from(
      gameData['playerData'] ?? {},
    );
    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? [],
    );
    final Map<String, dynamic> nightActions = Map<String, dynamic>.from(
      gameData['nightActions'] ?? {},
    );
    final Map<String, dynamic> dayVotes = Map<String, dynamic>.from(
      gameData['dayVotes'] ?? {},
    );
    final String? captainId = gameData['captainId'];
    final List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
    final int nightNumber = gameData['nightNumber'] ?? 0;

    final myData = playerData[playerId] ?? {};
    final myRole = myData['role'] ?? 'Inconnu';
    final myStatus = myData['status'] ?? 'vivant';
    final myPrivateInfo = myData['privateInfo'];
    final bool amILoup =
        GameData.roleCamps[myRole] == 'loups' ||
        myData['infectionStatus'] == 'infecte';
    final bool isHost = gameData['hostId'] == playerId;
    final bool isNight = phase == 'nuit';

    // Transition narrative
    if (_lgLastSubPhase != subPhase || _lgLastPhase != phase) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          setState(() {
            _lgLastSubPhase = subPhase;
            _lgLastPhase = phase;
            _lgLocalSelection.clear();
            _lgActionMode = 'normal';
            _lgTransitionText = _getLgTransitionLogs(phase, subPhase, gameLog);
            if (_lgTransitionText.isNotEmpty) {
              _showLgTransition = true;
              Timer(const Duration(seconds: 3), () {
                if (mounted) setState(() => _showLgTransition = false);
              });
            }
          });
        }
      });
    }

    String promptText =
        isNight ? "Le village s'endort..." : "Le village délibère...";
    Widget? centerActionWidget;

    // Décompte des votes
    Map<String, List<String>> votesReceived = {};
    if (phase == 'jour_vote') {
      dayVotes.forEach((voterId, targetId) {
        final voterName = playerData[voterId]?['name'] ?? 'Inconnu';
        votesReceived.putIfAbsent(targetId, () => []).add(voterName);
      });

      if (myRole == 'Mentaliste' && myStatus == 'vivant') {
        String? topTarget;
        int topVotes = 0;
        votesReceived.forEach((target, voters) {
          if (voters.length > topVotes) {
            topVotes = voters.length;
            topTarget = target;
          }
        });
        if (topTarget != null && topVotes > 0) {
          final targetRole = playerData[topTarget]?['role'];
          final isWolf =
              GameData.roleCamps[targetRole] == 'loups' ||
              playerData[topTarget]?['infectionStatus'] == 'infecte';
          if (isWolf) {
            Provider.of<PlayerState>(
              context,
              listen: false,
            ).recordBadgeEvent('lg_mentaliste_detect');
          }
        }
      }
    } else if (phase == 'nuit' && subPhase == 'loups_turn') {
      if (nightActions['votes'] != null) {
        (nightActions['votes'] as Map<String, dynamic>).forEach((
          voterId,
          targetId,
        ) {
          final voterName = playerData[voterId]?['name'] ?? 'Loup';
          votesReceived.putIfAbsent(targetId, () => []).add(voterName);
        });
      }
    }

    List<String> contaminatedPlayers = List<String>.from(
      gameData['ratMaladeContaminated'] ?? [],
    );

    // Vérification d'éligibilité pour ciblage
    bool canSelectTarget(String targetId) {
      if (targetId == playerId &&
          !(subPhase == 'garde_turn' || subPhase == 'cupidon_turn'))
        return false;
      if (playerData[targetId]?['status'] != 'vivant') return false;

      if (phase == 'nuit') {
        switch (subPhase) {
          case 'cupidon_turn':
            return myRole == 'Cupidon' &&
                myStatus == 'vivant' &&
                lovers.isEmpty &&
                !lovers.contains(targetId);
          case 'heritier_turn':
            return myRole == 'Héritier' &&
                myStatus == 'vivant' &&
                myData['testateurId'] == null;
          case 'garde_turn':
            return myRole == 'Garde' &&
                myStatus == 'vivant' &&
                nightActions['gardeActed'] != true &&
                myData['lastProtectedId'] != targetId;
          case 'voyante_turn':
            return myRole == 'Voyante' &&
                myStatus == 'vivant' &&
                nightActions['voyanteActed'] != true;
          case 'rat_malade_turn':
            return myRole == 'Rat Malade' &&
                myStatus == 'vivant' &&
                !contaminatedPlayers.contains(targetId);
          case 'loups_turn':
            bool targetIsLoup =
                GameData.roleCamps[playerData[targetId]?['role']] == 'loups' ||
                playerData[targetId]?['infectionStatus'] == 'infecte';
            if (amILoup && myStatus == 'vivant') return !targetIsLoup;
            if (myRole == 'Petite Fille' && myStatus == 'vivant' && !amILoup)
              return true;
            return false;
          case 'loup_blanc_turn':
            return myRole == 'Loup Blanc' &&
                myStatus == 'vivant' &&
                nightNumber % 2 != 0 &&
                nightActions['loupBlancActed'] != true;
          case 'sorciere_turn':
            return myRole == 'Sorcière' &&
                myStatus == 'vivant' &&
                _lgActionMode == 'poison' &&
                myData['potions']?['poison'] == true;
          case 'pyromancien_turn':
            return myRole == 'Pyromancien' &&
                myStatus == 'vivant' &&
                _lgActionMode == 'placer_tonneau';
        }
      } else if (phase == 'jour_discussion') {
        if (subPhase == 'captain_designate' ||
            subPhase == 'chasseur_revenge' ||
            subPhase == 'fossoyeur_reveal' ||
            subPhase == 'dictateur_coup') {
          return gameData['activePlayerId'] == playerId;
        }
      } else if (phase == 'jour_vote') {
        return myStatus == 'vivant' && !dayVotes.containsKey(playerId);
      }
      return false;
    }

    void handleTargetSelection(String targetId) async {
      if (_isActionPending) return;

      if (phase == 'nuit') {
        switch (subPhase) {
          case 'cupidon_turn':
          case 'rat_malade_turn':
            setState(() {
              if (_lgLocalSelection.contains(targetId)) {
                _lgLocalSelection.remove(targetId);
              } else {
                if (_lgLocalSelection.length < 2)
                  _lgLocalSelection.add(targetId);
              }
            });
            break;
          case 'heritier_turn':
            setState(() => _isActionPending = true);
            await _firebaseService.heritierChooseTestateur(
              widget.gameCode,
              playerId,
              targetId,
            );
            setState(() => _isActionPending = false);
            break;
          case 'garde_turn':
            setState(() => _isActionPending = true);
            await _firebaseService.gardeProtect(
              widget.gameCode,
              playerId,
              targetId,
            );
            setState(() => _isActionPending = false);
            break;
          case 'voyante_turn':
            setState(() => _isActionPending = true);
            await _firebaseService.voyanteSee(
              widget.gameCode,
              playerId,
              targetId,
            );
            setState(() => _isActionPending = false);
            break;
          case 'loups_turn':
            setState(() => _isActionPending = true);
            if (amILoup)
              await _firebaseService.loupGarouVote(
                widget.gameCode,
                playerId,
                targetId,
              );
            if (myRole == 'Petite Fille')
              await _firebaseService.petiteFilleSpy(
                widget.gameCode,
                playerId,
                targetId,
              );
            setState(() => _isActionPending = false);
            break;
          case 'loup_blanc_turn':
            setState(() => _isActionPending = true);
            await _firebaseService.loupBlancDevour(
              widget.gameCode,
              playerId,
              targetId,
            );
            setState(() => _isActionPending = false);
            break;
          case 'sorciere_turn':
            if (_lgActionMode == 'poison') {
              setState(() => _isActionPending = true);
              await _firebaseService.sorciereUsePotion(
                widget.gameCode,
                playerId,
                'poison',
                targetId,
              );
              setState(() {
                _isActionPending = false;
                _lgActionMode = 'normal';
              });
            }
            break;
          case 'pyromancien_turn':
            if (_lgActionMode == 'placer_tonneau') {
              setState(() => _isActionPending = true);
              await _firebaseService.pyromancienAct(
                widget.gameCode,
                playerId,
                'place',
                targetId,
              );
              setState(() {
                _isActionPending = false;
                _lgActionMode = 'normal';
              });
            }
            break;
        }
      } else if (phase == 'jour_discussion') {
        setState(() => _isActionPending = true);
        if (subPhase == 'captain_designate')
          await _firebaseService.captainDesignate(
            widget.gameCode,
            playerId,
            targetId,
          );
        if (subPhase == 'chasseur_revenge') {
          final targetRole = playerData[targetId]?['role'];
          if (GameData.roleCamps[targetRole] == 'loups') {
            Provider.of<PlayerState>(
              context,
              listen: false,
            ).recordBadgeEvent('lg_chasseur_revenge');
          }
          await _firebaseService.chasseurShoot(
            widget.gameCode,
            playerId,
            targetId,
          );
        }
        if (subPhase == 'fossoyeur_reveal')
          await _firebaseService.fossoyeurReveal(
            widget.gameCode,
            playerId,
            targetId,
          );
        if (subPhase == 'dictateur_coup') {
          final targetRole = playerData[targetId]?['role'];
          if (GameData.roleCamps[targetRole] == 'loups') {
            Provider.of<PlayerState>(
              context,
              listen: false,
            ).recordBadgeEvent('lg_dictateur_coup');
          }
          await _firebaseService.dictateurCoup(
            widget.gameCode,
            playerId,
            targetId,
          );
        }
        setState(() => _isActionPending = false);
      } else if (phase == 'jour_vote') {
        setState(() => _isActionPending = true);
        await _firebaseService.submitDayVote(
          widget.gameCode,
          playerId,
          targetId,
        );
        setState(() => _isActionPending = false);
      }
    }

    // Définition des instructions contextuelles et boutons d'action au centre
    if (phase == 'nuit') {
      switch (subPhase) {
        case 'cupidon_turn':
          promptText =
              lovers.isEmpty ? "Désignez 2 amoureux" : "Amoureux unis !";
          if (myRole == 'Cupidon' && myStatus == 'vivant' && lovers.isEmpty) {
            centerActionWidget = _buildActionButton(
              label: "Valider le couple (${_lgLocalSelection.length}/2)",
              icon: Icons.favorite,
              color: Colors.pinkAccent,
              onPressed:
                  _lgLocalSelection.length == 2
                      ? () async {
                        setState(() => _isActionPending = true);
                        for (String tgt in _lgLocalSelection) {
                          await _firebaseService.selectCupidonLover(
                            widget.gameCode,
                            playerId,
                            tgt,
                          );
                        }
                        setState(() {
                          _isActionPending = false;
                          _lgLocalSelection.clear();
                        });
                      }
                      : null,
            );
          }
          break;
        case 'heritier_turn':
          promptText = "L'Héritier choisit son testament";
          if (myRole == 'Héritier' &&
              myStatus == 'vivant' &&
              myData['testateurId'] == null) {
            promptText = "Sélectionnez votre testateur";
          }
          break;
        case 'garde_turn':
          promptText = "Le Garde protège un villageois";
          if (myRole == 'Garde' &&
              myStatus == 'vivant' &&
              nightActions['gardeActed'] != true) {
            promptText = "Sélectionnez qui protéger";
          }
          break;
        case 'voyante_turn':
          promptText = "La Voyante consulte les astres";
          if (myRole == 'Voyante' &&
              myStatus == 'vivant' &&
              nightActions['voyanteActed'] != true) {
            promptText = "Touchez un joueur pour sonder son rôle";
          }
          break;
        case 'rat_malade_turn':
          promptText = "Le Rat Malade rôde...";
          if (myRole == 'Rat Malade' && myStatus == 'vivant') {
            promptText = "Contaminez jusqu'à 2 joueurs";
            centerActionWidget = _buildActionButton(
              label: "Contaminer (${_lgLocalSelection.length})",
              icon: Icons.sick,
              color: Colors.lightGreenAccent,
              onPressed:
                  _lgLocalSelection.isNotEmpty
                      ? () async {
                        setState(() => _isActionPending = true);
                        await _firebaseService.ratMaladeContaminate(
                          widget.gameCode,
                          playerId,
                          _lgLocalSelection,
                        );
                        setState(() {
                          _isActionPending = false;
                          _lgLocalSelection.clear();
                        });
                      }
                      : null,
            );
          }
          break;
        case 'loups_turn':
          promptText = "Les Loups chassent en meute";
          if (amILoup && myStatus == 'vivant')
            promptText = "Votez pour dévorer une proie";
          if (myRole == 'Petite Fille' && myStatus == 'vivant' && !amILoup)
            promptText = "Espionnez un joueur...";
          break;
        case 'loup_noir_action':
          promptText = "Le Loup Noir décide du destin de la proie";
          String? loupNoirId =
              playerData.entries
                  .firstWhere(
                    (e) =>
                        e.value['role'] == 'Loup Noir' &&
                        e.value['status'] == 'vivant',
                    orElse: () => const MapEntry('', {}),
                  )
                  .key;
          if (loupNoirId == playerId &&
              myStatus == 'vivant' &&
              !(myData['infectionUsed'] ?? true) &&
              nightActions['loupTarget'] != null) {
            String targetName =
                playerData[nightActions['loupTarget']]?['name'] ?? 'la victime';
            promptText = "Infecter $targetName ?";
            centerActionWidget = Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                _buildActionButton(
                  label: "Infecter",
                  icon: Icons.auto_fix_high,
                  color: Colors.purpleAccent,
                  onPressed: () {
                    Provider.of<PlayerState>(
                      context,
                      listen: false,
                    ).recordBadgeEvent('lg_loup_noir_infect');
                    _firebaseService.loupNoirInfect(
                      widget.gameCode,
                      playerId,
                      true,
                    );
                  },
                ),
                const SizedBox(width: 8),
                _buildActionButton(
                  label: "Dévorer",
                  icon: Icons.close,
                  color: Colors.redAccent,
                  onPressed:
                      () => _firebaseService.loupNoirInfect(
                        widget.gameCode,
                        playerId,
                        false,
                      ),
                ),
              ],
            );
          }
          break;
        case 'loup_blanc_turn':
          promptText = "Le Loup Blanc frappe en solitaire";
          if (myRole == 'Loup Blanc' &&
              myStatus == 'vivant' &&
              nightNumber % 2 != 0 &&
              nightActions['loupBlancActed'] != true) {
            promptText = "Choisissez une victime à dévorer";
          }
          break;
        case 'sorciere_turn':
          promptText = "La Sorcière prépare ses potions";
          if (myRole == 'Sorcière' &&
              myStatus == 'vivant' &&
              nightActions['sorciereActed'] != true) {
            final victimeId = nightActions['loupTarget'];
            final victimeName = playerData[victimeId]?['name'] ?? 'Personne';
            promptText = "Cible des loups : $victimeName";
            if (_lgActionMode == 'poison')
              promptText = "Touchez le joueur à éliminer";

            centerActionWidget = Wrap(
              spacing: 6,
              runSpacing: 6,
              alignment: WrapAlignment.center,
              children: [
                if (myData['potions']?['guerison'] == true && victimeId != null)
                  _buildActionButton(
                    label: "Sauver",
                    icon: Icons.health_and_safety,
                    color: Colors.greenAccent,
                    onPressed:
                        () => _firebaseService.sorciereUsePotion(
                          widget.gameCode,
                          playerId,
                          'guerison',
                          victimeId,
                        ),
                  ),
                if (myData['potions']?['poison'] == true)
                  _buildActionButton(
                    label:
                        _lgActionMode == 'poison' ? "Annuler" : "Empoisonner",
                    icon: Icons.science,
                    color:
                        _lgActionMode == 'poison'
                            ? Colors.amberAccent
                            : Colors.purpleAccent,
                    onPressed:
                        () => setState(
                          () =>
                              _lgActionMode =
                                  _lgActionMode == 'poison'
                                      ? 'normal'
                                      : 'poison',
                        ),
                  ),
                _buildActionButton(
                  label: "Ne rien faire",
                  icon: Icons.nightlight_round,
                  color: Colors.white60,
                  onPressed:
                      () => _firebaseService.sorciereUsePotion(
                        widget.gameCode,
                        playerId,
                        'rien',
                        null,
                      ),
                ),
              ],
            );
          }
          break;
        case 'pyromancien_turn':
          promptText = "Le Pyromancien prépare ses explosifs";
          if (myRole == 'Pyromancien' && myStatus == 'vivant') {
            centerActionWidget = Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                _buildActionButton(
                  label:
                      _lgActionMode == 'placer_tonneau'
                          ? "Annuler"
                          : "Poser tonneau",
                  icon: Icons.local_gas_station,
                  color: Colors.orangeAccent,
                  onPressed:
                      () => setState(
                        () =>
                            _lgActionMode =
                                _lgActionMode == 'placer_tonneau'
                                    ? 'normal'
                                    : 'placer_tonneau',
                      ),
                ),
                const SizedBox(width: 8),
                _buildActionButton(
                  label: "Faire exploser",
                  icon: Icons.local_fire_department,
                  color: Colors.redAccent,
                  onPressed:
                      () => _firebaseService.pyromancienAct(
                        widget.gameCode,
                        playerId,
                        'detonate',
                        null,
                      ),
                ),
              ],
            );
          }
          break;
      }
    } else if (phase == 'jour_discussion') {
      promptText = "Débats du village";
      if (subPhase == 'captain_designate') {
        promptText = "Le Capitaine désigne son successeur";
      } else if (subPhase == 'chasseur_revenge') {
        promptText = "Dernier tir du Chasseur...";
      } else if (subPhase == 'fossoyeur_reveal') {
        promptText = "Le Fossoyeur révèle une sépulture";
      } else if (subPhase == 'dictateur_coup') {
        promptText = "Coup d'État du Dictateur !";
      } else {
        if (myRole == 'Dictateur' &&
            myStatus == 'vivant' &&
            !(myData['powerUsed'] ?? false) &&
            !(gameData['dictatorUsed'] ?? false)) {
          centerActionWidget = _buildActionButton(
            label: "Coup d'État",
            icon: Icons.gavel,
            color: Colors.deepPurpleAccent,
            onPressed:
                () => _firebaseService.triggerDictateurCoup(
                  widget.gameCode,
                  playerId,
                ),
          );
        }
        if (isHost) {
          centerActionWidget = _buildActionButton(
            label: "Ouvrir les votes",
            icon: Icons.how_to_vote,
            color: Colors.amberAccent,
            onPressed:
                () => _firebaseService.startDayVotePhase(widget.gameCode),
          );
        }
      }
    } else if (phase == 'jour_vote') {
      promptText = "Vote du tribunal populaire";
      if (myStatus == 'vivant' && !dayVotes.containsKey(playerId)) {
        promptText = "Touchez un suspect pour voter";
      } else if (isHost) {
        centerActionWidget = _buildActionButton(
          label: "Clôturer le vote",
          icon: Icons.done_all,
          color: Colors.amberAccent,
          onPressed: () => _firebaseService.processDayVote(widget.gameCode),
        );
      }
    } else if (phase == 'gameOver') {
      promptText = "Partie terminée !";
      centerActionWidget = Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            gameLog.isNotEmpty ? gameLog.last.toString() : "Fin du jeu",
            style: const TextStyle(
              color: Colors.white,
              fontSize: 13,
              fontWeight: FontWeight.w600,
            ),
            textAlign: TextAlign.center,
          ),
          const SizedBox(height: 8),
          Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              _buildActionButton(
                label: "Quitter",
                icon: Icons.exit_to_app,
                color: Colors.redAccent,
                onPressed: () => _exitGame(),
              ),
              if (isHost) ...[
                const SizedBox(width: 8),
                _buildActionButton(
                  label: "Rejouer",
                  icon: Icons.replay,
                  color: Colors.greenAccent,
                  onPressed:
                      () =>
                          _firebaseService.resetLoupGarouGame(widget.gameCode),
                ),
              ],
            ],
          ),
        ],
      );
    }

    final bool canSeeLovers = lovers.contains(playerId) || myRole == 'Cupidon';

    return Container(
      decoration: BoxDecoration(
        gradient: RadialGradient(
          center: Alignment.center,
          radius: 1.1,
          colors:
              isNight
                  ? [const Color(0xFF0F172A), const Color(0xFF020617)]
                  : [const Color(0xFF1E293B), const Color(0xFF0F172A)],
        ),
      ),
      child: Stack(
        children: [
          // 1. CERCLE DES JOUEURS (ARENA)
          Positioned.fill(
            child: LayoutBuilder(
              builder: (context, constraints) {
                final double width = constraints.maxWidth;
                final double height = constraints.maxHeight;
                final double centerX = width / 2;
                final double centerY = height * 0.44;
                final double radius = min(width, height) * 0.36;

                return Stack(
                  alignment: Alignment.center,
                  children: [
                    // Décoration centrale subtile
                    Positioned(
                      left: centerX - (radius * 0.9),
                      top: centerY - (radius * 0.9),
                      width: radius * 1.8,
                      height: radius * 1.8,
                      child: Container(
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          border: Border.all(
                            color:
                                isNight
                                    ? Colors.cyanAccent.withOpacity(0.06)
                                    : Colors.amberAccent.withOpacity(0.06),
                            width: 1.5,
                          ),
                        ),
                      ),
                    ),

                    // Actions centrales (ne chevauchent plus)
                    if (centerActionWidget != null)
                      Positioned(
                        left: 40,
                        right: 40,
                        top: centerY - 32,
                        child: Center(child: centerActionWidget),
                      ),

                    // Avatars des joueurs disposés en cercle
                    ...playerOrder.asMap().entries.map((entry) {
                      final int index = entry.key;
                      final String pId = entry.value;
                      final double angle =
                          (2 * pi * index) / max(1, playerOrder.length) -
                          (pi / 2);
                      final pData = playerData[pId] ?? {};
                      final x = radius * cos(angle);
                      final y = radius * sin(angle);

                      const double avatarSize = 54.0;
                      return Positioned(
                        left: centerX + x - (avatarSize / 2),
                        top: centerY + y - (avatarSize / 2),
                        child: _buildPlayerAvatar(
                          pData,
                          pId,
                          pId == playerId,
                          votesReceived[pId],
                          captainId,
                          lovers,
                          amILoup,
                          nightNumber,
                          currentRoundState: phase,
                          contaminatedPlayers: contaminatedPlayers,
                          canSeeLovers: canSeeLovers,
                          isSelectable: canSelectTarget(pId),
                          isSelected: _lgLocalSelection.contains(pId),
                          onTap: () => handleTargetSelection(pId),
                        ),
                      );
                    }).toList(),
                  ],
                );
              },
            ),
          ),

          // 2. HUD MINIMALISTE SUPÉRIEUR
          Positioned(
            top: 8,
            left: 12,
            right: 12,
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
              decoration: BoxDecoration(
                color: const Color(0xFF0F172A).withOpacity(0.8),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(color: Colors.white.withOpacity(0.08)),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withOpacity(0.3),
                    blurRadius: 10,
                    offset: const Offset(0, 4),
                  ),
                ],
              ),
              child: Row(
                children: [
                  // Icône Phase
                  Container(
                    padding: const EdgeInsets.all(6),
                    decoration: BoxDecoration(
                      color:
                          isNight
                              ? Colors.indigo.withOpacity(0.3)
                              : Colors.amber.withOpacity(0.2),
                      shape: BoxShape.circle,
                    ),
                    child: Icon(
                      isNight
                          ? Icons.nights_stay_rounded
                          : Icons.wb_sunny_rounded,
                      size: 16,
                      color: isNight ? Colors.cyanAccent : Colors.amberAccent,
                    ),
                  ),
                  const SizedBox(width: 10),

                  // Texte de consigne & rôle
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          promptText,
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 13,
                            fontWeight: FontWeight.bold,
                          ),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                        ),
                        if (myPrivateInfo != null &&
                            myPrivateInfo.toString().trim().isNotEmpty)
                          Text(
                            myPrivateInfo.toString(),
                            style: const TextStyle(
                              color: Colors.lightBlueAccent,
                              fontSize: 10,
                            ),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                      ],
                    ),
                  ),

                  // Badge Rôle discret
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 10,
                      vertical: 4,
                    ),
                    decoration: BoxDecoration(
                      color:
                          amILoup
                              ? Colors.redAccent.withOpacity(0.2)
                              : Colors.deepPurpleAccent.withOpacity(0.2),
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(
                        color:
                            amILoup
                                ? Colors.redAccent.withOpacity(0.5)
                                : Colors.deepPurpleAccent.withOpacity(0.5),
                      ),
                    ),
                    child: Text(
                      myRole,
                      style: TextStyle(
                        color:
                            amILoup
                                ? const Color(0xFFFCA5A5)
                                : const Color(0xFFDDD6FE),
                        fontWeight: FontWeight.bold,
                        fontSize: 11,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),

          // 3. TCHAT LIVE ÉLÉGANT & INTÉGRÉ AU BAS
          Positioned(
            bottom: 6,
            left: 10,
            right: 10,
            height: MediaQuery.of(context).size.height * 0.28,
            child: _buildChatInterface(gameData, playerId, isLiveStyle: true),
          ),

          // 4. TRANSITION NARRATIVE ÉPURÉE
          if (_showLgTransition)
            Positioned.fill(
              child: AnimatedOpacity(
                opacity: _showLgTransition ? 1.0 : 0.0,
                duration: const Duration(milliseconds: 400),
                child: Container(
                  color: Colors.black.withOpacity(0.85),
                  child: Center(
                    child: Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 32.0),
                      child: Text(
                        _lgTransitionText,
                        textAlign: TextAlign.center,
                        style: TextStyle(
                          fontSize: 20,
                          color:
                              isNight
                                  ? Colors.cyanAccent.shade100
                                  : Colors.amberAccent.shade100,
                          fontWeight: FontWeight.bold,
                          height: 1.4,
                          letterSpacing: 0.5,
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  // --- BOUTON D'ACTION GLASSMORPHIC ---
  Widget _buildActionButton({
    required String label,
    required IconData icon,
    required Color color,
    required VoidCallback? onPressed,
  }) {
    return ElevatedButton.icon(
      icon: Icon(icon, size: 14, color: Colors.white),
      label: Text(
        label,
        style: const TextStyle(fontSize: 11, fontWeight: FontWeight.bold),
      ),
      style: ElevatedButton.styleFrom(
        backgroundColor: color.withOpacity(0.85),
        foregroundColor: Colors.white,
        elevation: 4,
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      ),
      onPressed: onPressed,
    );
  }

  // --- AVATAR ÉPURÉ & MODERNE ---
  Widget _buildPlayerAvatar(
    Map<String, dynamic> pData,
    String pId,
    bool isMe,
    List<String>? voters,
    String? captainId,
    List<String> lovers,
    bool amICurrentPlayerLoup,
    int nightNumber, {
    required String currentRoundState,
    required List<String> contaminatedPlayers,
    bool canSeeLovers = true,
    bool isSelectable = false,
    bool isSelected = false,
    VoidCallback? onTap,
  }) {
    final bool isDead = pData['status'] == 'mort';
    final String name = pData['name'] ?? '?';
    final bool isCaptain = (pId == captainId);
    final bool isLover = lovers.contains(pId) && canSeeLovers;
    final bool isInfected = pData['infectionStatus'] == 'infecte';
    final bool isContaminated =
        contaminatedPlayers.contains(pId) &&
        contaminatedPlayers.contains(widget.playerId);
    final bool isLoupRole = GameData.roleCamps[pData['role']] == 'loups';
    final bool showWolfGlow =
        currentRoundState == 'nuit' &&
        (amICurrentPlayerLoup || isInfected) &&
        (isLoupRole || isInfected);

    Color borderColor = Colors.white.withOpacity(0.15);
    Color bgColor = const Color(0xFF1E293B);

    if (isDead) {
      bgColor = Colors.black.withOpacity(0.6);
      borderColor = Colors.white10;
    } else if (isSelected) {
      borderColor = Colors.greenAccent;
    } else if (isSelectable) {
      borderColor = Colors.cyanAccent;
    } else if (showWolfGlow) {
      borderColor = Colors.redAccent.withOpacity(0.8);
      bgColor = const Color(0xFF450A0A);
    } else if (isMe) {
      borderColor = Colors.deepPurpleAccent.withOpacity(0.8);
    }

    return GestureDetector(
      onTap: isSelectable ? onTap : null,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Stack(
            clipBehavior: Clip.none,
            alignment: Alignment.center,
            children: [
              // Avatar Circle
              AnimatedContainer(
                duration: const Duration(milliseconds: 200),
                width: 44,
                height: 44,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: bgColor,
                  border: Border.all(
                    color: borderColor,
                    width: (isSelectable || isSelected) ? 2.5 : 1.2,
                  ),
                  boxShadow:
                      (isSelectable || isSelected)
                          ? [
                            BoxShadow(
                              color: (isSelected
                                      ? Colors.greenAccent
                                      : Colors.cyanAccent)
                                  .withOpacity(0.4),
                              blurRadius: 8,
                              spreadRadius: 1,
                            ),
                          ]
                          : null,
                ),
                child: Center(
                  child:
                      isDead
                          ? const Icon(
                            Icons.close_rounded,
                            size: 20,
                            color: Colors.white38,
                          )
                          : Text(
                            name.isNotEmpty ? name[0].toUpperCase() : '?',
                            style: TextStyle(
                              fontSize: 16,
                              fontWeight: FontWeight.bold,
                              color: isDead ? Colors.white30 : Colors.white,
                            ),
                          ),
                ),
              ),

              // Badge Capitaine
              if (isCaptain)
                Positioned(
                  top: -4,
                  right: -4,
                  child: Container(
                    padding: const EdgeInsets.all(2),
                    decoration: const BoxDecoration(
                      color: Colors.amber,
                      shape: BoxShape.circle,
                    ),
                    child: const Icon(
                      Icons.star_rounded,
                      size: 10,
                      color: Colors.black,
                    ),
                  ),
                ),

              // Badge Amoureux
              if (isLover)
                Positioned(
                  bottom: -4,
                  right: -4,
                  child: Container(
                    padding: const EdgeInsets.all(2),
                    decoration: const BoxDecoration(
                      color: Colors.pinkAccent,
                      shape: BoxShape.circle,
                    ),
                    child: const Icon(
                      Icons.favorite_rounded,
                      size: 10,
                      color: Colors.white,
                    ),
                  ),
                ),

              // Badge Infecté
              if (isInfected && showWolfGlow)
                Positioned(
                  top: -4,
                  left: -4,
                  child: Container(
                    padding: const EdgeInsets.all(2),
                    decoration: const BoxDecoration(
                      color: Colors.purpleAccent,
                      shape: BoxShape.circle,
                    ),
                    child: const Icon(
                      Icons.coronavirus_rounded,
                      size: 10,
                      color: Colors.white,
                    ),
                  ),
                ),

              // Badge Contaminé
              if (isContaminated)
                Positioned(
                  bottom: -4,
                  left: -4,
                  child: Container(
                    padding: const EdgeInsets.all(2),
                    decoration: const BoxDecoration(
                      color: Colors.lightGreenAccent,
                      shape: BoxShape.circle,
                    ),
                    child: const Icon(
                      Icons.bubble_chart_rounded,
                      size: 10,
                      color: Colors.black,
                    ),
                  ),
                ),
            ],
          ),
          const SizedBox(height: 3),

          // Nom du joueur
          SizedBox(
            width: 60,
            child: Text(
              isMe ? "Moi" : name,
              style: TextStyle(
                fontSize: 10,
                fontWeight: isMe ? FontWeight.bold : FontWeight.w500,
                color: isDead ? Colors.white30 : Colors.white70,
              ),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              textAlign: TextAlign.center,
            ),
          ),

          // Votes reçus
          if (voters != null && voters.isNotEmpty)
            Container(
              margin: const EdgeInsets.only(top: 2),
              padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 1),
              decoration: BoxDecoration(
                color: Colors.redAccent.withOpacity(0.85),
                borderRadius: BorderRadius.circular(8),
              ),
              child: Text(
                "${voters.length}",
                style: const TextStyle(
                  fontSize: 9,
                  fontWeight: FontWeight.w900,
                  color: Colors.white,
                ),
              ),
            ),
        ],
      ),
    );
  }

  // --- TCHAT COMPACT & MODERNE ---
  Widget _buildChatInterface(
    Map<String, dynamic> gameData,
    String playerId, {
    bool isLiveStyle = false,
  }) {
    final Map<String, dynamic> playerData = Map<String, dynamic>.from(
      gameData['playerData'] ?? {},
    );
    final myData = playerData[playerId] ?? {};
    final myStatus = myData['status'] ?? 'vivant';
    final myRole = myData['role'] ?? 'Inconnu';
    final bool amILoup =
        GameData.roleCamps[myRole] == 'loups' ||
        myData['infectionStatus'] == 'infecte';
    final bool amIDead = myStatus == 'mort';
    final bool amILover = (gameData['lovers'] ?? []).contains(playerId);
    final bool amINecromancer = myRole == 'Nécromancien';
    final List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
    List<dynamic> currentChatMessages = [];
    bool canSendMessage = false;

    switch (_selectedChatType) {
      case 'wolf':
        currentChatMessages = List<dynamic>.from(
          gameData['wolfChatMessages'] ?? [],
        );
        canSendMessage = amILoup && !amIDead;
        break;
      case 'dead':
        currentChatMessages = List<dynamic>.from(
          gameData['deadChatMessages'] ?? [],
        );
        canSendMessage = amIDead || amINecromancer;
        break;
      case 'lover':
        if (lovers.isNotEmpty && lovers.contains(playerId)) {
          lovers.sort();
          String chatKey = lovers.join('_');
          Map<String, dynamic> loverChat = Map<String, dynamic>.from(
            gameData['loverChatMessages']?[chatKey] ?? {},
          );
          currentChatMessages = List<dynamic>.from(loverChat['messages'] ?? []);
          canSendMessage = amILover && !amIDead;
        }
        break;
      default:
        currentChatMessages = List<dynamic>.from(
          gameData['chatMessages'] ?? [],
        );
        canSendMessage = !amIDead;
        break;
    }

    return Container(
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
        color: const Color(0xFF0B1120).withOpacity(0.75),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.white.withOpacity(0.08)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Onglets de canaux
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              children: [
                _buildChatTab("Village", 'global', Colors.blueAccent),
                if (amILoup || (amIDead && amILoup)) ...[
                  const SizedBox(width: 4),
                  _buildChatTab("Loups", 'wolf', Colors.redAccent),
                ],
                if (amIDead || amINecromancer) ...[
                  const SizedBox(width: 4),
                  _buildChatTab("Outre-tombe", 'dead', Colors.purpleAccent),
                ],
                if (amILover && lovers.length == 2) ...[
                  const SizedBox(width: 4),
                  _buildChatTab("Amoureux", 'lover', Colors.pinkAccent),
                ],
              ],
            ),
          ),
          const SizedBox(height: 4),

          // Messages
          Expanded(
            child: ListView.builder(
              reverse: true,
              physics: const BouncingScrollPhysics(),
              itemCount: currentChatMessages.length,
              itemBuilder: (context, index) {
                final messageData =
                    currentChatMessages[currentChatMessages.length - 1 - index];
                final senderId = messageData['senderId'];
                final senderName = messageData['senderName'] ?? 'Inconnu';
                final message = messageData['message'] ?? '';
                final isMine = senderId == playerId;

                return Padding(
                  padding: const EdgeInsets.symmetric(vertical: 1.5),
                  child: RichText(
                    text: TextSpan(
                      style: const TextStyle(fontSize: 11, color: Colors.white),
                      children: [
                        TextSpan(
                          text: isMine ? "Moi: " : "$senderName: ",
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            color:
                                isMine
                                    ? Colors.cyanAccent
                                    : (_selectedChatType == 'wolf'
                                        ? Colors.redAccent.shade100
                                        : Colors.white60),
                          ),
                        ),
                        TextSpan(text: message),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),

          // Barre d'envoi compacte
          if (canSendMessage)
            Row(
              children: [
                Expanded(
                  child: SizedBox(
                    height: 32,
                    child: TextField(
                      controller: _chatController,
                      style: const TextStyle(fontSize: 12, color: Colors.white),
                      decoration: InputDecoration(
                        hintText:
                            "Écrire au ${_selectedChatType == 'wolf' ? 'meute' : 'village'}...",
                        hintStyle: const TextStyle(
                          color: Colors.white30,
                          fontSize: 11,
                        ),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(16),
                          borderSide: BorderSide.none,
                        ),
                        filled: true,
                        fillColor: Colors.white.withOpacity(0.08),
                        contentPadding: const EdgeInsets.symmetric(
                          horizontal: 10,
                          vertical: 0,
                        ),
                      ),
                      onSubmitted: (text) {
                        if (text.trim().isNotEmpty) {
                          _firebaseService.sendChatMessage(
                            widget.gameCode,
                            playerId,
                            text.trim(),
                            _selectedChatType,
                          );
                          _chatController.clear();
                        }
                      },
                    ),
                  ),
                ),
                const SizedBox(width: 4),
                IconButton(
                  icon: const Icon(
                    Icons.send_rounded,
                    size: 18,
                    color: Colors.cyanAccent,
                  ),
                  padding: EdgeInsets.zero,
                  constraints: const BoxConstraints(),
                  onPressed: () {
                    if (_chatController.text.trim().isNotEmpty) {
                      _firebaseService.sendChatMessage(
                        widget.gameCode,
                        playerId,
                        _chatController.text.trim(),
                        _selectedChatType,
                      );
                      _chatController.clear();
                    }
                  },
                ),
              ],
            ),
        ],
      ),
    );
  }

  Widget _buildChatTab(String label, String type, Color activeColor) {
    final bool isSelected = _selectedChatType == type;
    return GestureDetector(
      onTap: () => setState(() => _selectedChatType = type),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
        decoration: BoxDecoration(
          color:
              isSelected
                  ? activeColor.withOpacity(0.25)
                  : Colors.white.withOpacity(0.04),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(
            color:
                isSelected ? activeColor.withOpacity(0.6) : Colors.transparent,
          ),
        ),
        child: Text(
          label,
          style: TextStyle(
            fontSize: 10,
            fontWeight: isSelected ? FontWeight.bold : FontWeight.normal,
            color: isSelected ? activeColor : Colors.white60,
          ),
        ),
      ),
    );
  }

  // --- MISE Ã€ JOUR DE L'AVATAR POUR LE RENDRE INTERACTIF ---

  Widget _buildSyncTimer(Timestamp? startTime, int durationInSeconds) {
    if (startTime == null) return const SizedBox.shrink();

    // TweenAnimationBuilder permet un chrono visuel super fluide sans Timer bloquant et setState manuel, ce qui allÃƒÂ¨ge grandement le thread (Point 4)
    final endTime = startTime.toDate().add(
      Duration(seconds: durationInSeconds),
    );
    final remaining = endTime.difference(DateTime.now());

    if (remaining.isNegative)
      return Text(
        "0 s",
        style: Theme.of(
          context,
        ).textTheme.headlineSmall?.copyWith(color: Colors.redAccent),
      );

    return TweenAnimationBuilder<Duration>(
      duration: remaining,
      tween: Tween(begin: remaining, end: Duration.zero),
      builder: (BuildContext context, Duration value, Widget? child) {
        final seconds = value.inSeconds;
        return Text(
          "Temps restant : $seconds s",
          style: Theme.of(context).textTheme.headlineSmall?.copyWith(
            color: seconds < 20 ? Colors.redAccent : Colors.amberAccent,
          ),
        );
      },
    );
  }

  Widget _buildPetitsChevauxUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerOrder = List<String>.from(
      gameData['petitsChevauxPlayerOrder'] ?? [],
    );
    final positions = Map<String, dynamic>.from(
      gameData['petitsChevauxPositions'] ?? {},
    );
    final int currentIndex = gameData['petitsChevauxCurrentIndex'] ?? 0;
    final String currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentIndex] : '';
    final bool isMyTurn = currentPlayerId == playerId;
    final int dice = (gameData['petitsChevauxDice'] as num?)?.toInt() ?? 0;
    final bool hasRolled = gameData['petitsChevauxHasRolled'] ?? false;
    final bool isTeamMode = gameData['petitsChevauxTeamMode'] ?? false;
    final Map<String, dynamic> consecutiveSixes = Map<String, dynamic>.from(
      gameData['petitsChevauxConsecutiveSixes'] ?? {},
    );
    final int mySixStreak = consecutiveSixes[playerId] ?? 0;

    // Palette moderne fluo / arcade sur fond sombre
    final List<Color> playerColors = [
      const Color(0xFFEF4444), // Rouge néon
      const Color(0xFF38BDF8), // Bleu ciel néon
      const Color(0xFF10B981), // Vert émeraude
      const Color(0xFFF59E0B), // Ambre doré
    ];

    // --- ÉCRAN DE VICTOIRE ---
    if (gameData['gameState'] == 'gameOver') {
      return UniversalGameEndScreen(
        gameTitle: "Petits Chevaux",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason: gameData['gameEndReason'] ?? "Arrivée au centre du plateau !",
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    return Column(
      children: [
        // 1. BANDEAU D'ÉTAT SUPÉRIEUR ÉLÉGANT
        Container(
          margin: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
          decoration: BoxDecoration(
            color: isMyTurn ? const Color(0xFF261E3E) : const Color(0xFF14141E),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(
              color:
                  isMyTurn
                      ? Colors.greenAccent.withOpacity(0.6)
                      : Colors.white10,
              width: 1.5,
            ),
            boxShadow: [
              if (isMyTurn)
                BoxShadow(
                  color: Colors.greenAccent.withOpacity(0.15),
                  blurRadius: 10,
                ),
            ],
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Row(
                children: [
                  Container(
                    padding: const EdgeInsets.all(6),
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color:
                          isMyTurn
                              ? Colors.greenAccent.withOpacity(0.2)
                              : Colors.white10,
                    ),
                    child: Icon(
                      Icons.casino_rounded,
                      size: 16,
                      color: isMyTurn ? Colors.greenAccent : Colors.white60,
                    ),
                  ),
                  const SizedBox(width: 8),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        isMyTurn
                            ? (hasRolled
                                ? "DÉPLACEZ UN CHEVAL !"
                                : "À VOUS DE LANCER !")
                            : "TOUR DE ${players[currentPlayerId]?['name'] ?? ''}",
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.bold,
                          letterSpacing: 1,
                          color: isMyTurn ? Colors.greenAccent : Colors.white60,
                        ),
                      ),
                      Text(
                        isTeamMode ? "Mode 2v2 Alliés" : "Course individuelle",
                        style: const TextStyle(
                          fontSize: 10,
                          color: Colors.white38,
                        ),
                      ),
                    ],
                  ),
                ],
              ),
              if (mySixStreak > 0)
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.amberAccent.withOpacity(0.2),
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                      color: Colors.amberAccent.withOpacity(0.5),
                    ),
                  ),
                  child: Row(
                    children: [
                      const Icon(
                        Icons.bolt_rounded,
                        size: 13,
                        color: Colors.amberAccent,
                      ),
                      const SizedBox(width: 2),
                      Text(
                        "6 consécutifs : $mySixStreak/3",
                        style: const TextStyle(
                          fontSize: 10,
                          fontWeight: FontWeight.bold,
                          color: Colors.amberAccent,
                        ),
                      ),
                    ],
                  ),
                ),
            ],
          ),
        ),

        Expanded(
          flex: 4,
          child: LayoutBuilder(
            builder: (context, constraints) {
              final double boardSize =
                  min(constraints.maxWidth, constraints.maxHeight) * 0.96;
              final cellSize = boardSize / 15;

              return StreamBuilder<DatabaseEvent>(
                stream: _firebaseService.getLudoHoverStream(widget.gameCode),
                builder: (context, hoverSnap) {
                  String? hoveredOwner;
                  int? hoveredPawnIdx;
                  if (hoverSnap.hasData &&
                      hoverSnap.data!.snapshot.value != null) {
                    try {
                      final raw = Map<String, dynamic>.from(
                        hoverSnap.data!.snapshot.value as Map,
                      );
                      hoveredOwner = raw['ownerId'] as String?;
                      hoveredPawnIdx = raw['pawnIndex'] as int?;
                    } catch (_) {}
                  }

                  Offset? ghostDestination;
                  if (hoveredOwner != null &&
                      hoveredPawnIdx != null &&
                      dice > 0) {
                    final pList = List<int>.from(
                      positions[hoveredOwner] ?? [-1, -1, -1, -1],
                    );
                    final curP = pList[hoveredPawnIdx];
                    final pIdx = playerOrder.indexOf(hoveredOwner);
                    if (curP == -1 && (dice == 1 || dice == 6)) {
                      ghostDestination = _getLudoPathPosition(
                        0,
                        pIdx % 4,
                        cellSize,
                      );
                    } else if (curP >= 0 && curP + dice <= 56) {
                      final targetP = curP + dice;
                      if (targetP <= 50) {
                        ghostDestination = _getLudoPathPosition(
                          targetP,
                          pIdx % 4,
                          cellSize,
                        );
                      } else {
                        ghostDestination = _getLudoHomePosition(
                          targetP - 51,
                          pIdx % 4,
                          cellSize,
                        );
                      }
                    }
                  }

                  return Center(
                    child: Container(
                      width: boardSize,
                      height: boardSize,
                      decoration: BoxDecoration(
                        borderRadius: BorderRadius.circular(24),
                        boxShadow: [
                          BoxShadow(
                            color: Colors.black.withOpacity(0.7),
                            blurRadius: 20,
                            offset: const Offset(0, 8),
                          ),
                        ],
                      ),
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(24),
                        child: Stack(
                          alignment: Alignment.center,
                          children: [
                            CustomPaint(
                              size: Size(boardSize, boardSize),
                              painter: _LudoBoardPainter(playerColors),
                            ),
                            if (ghostDestination != null)
                              Positioned(
                                left: ghostDestination.dx - (cellSize * 0.45),
                                top: ghostDestination.dy - (cellSize * 0.45),
                                child: Container(
                                  width: cellSize * 0.9,
                                  height: cellSize * 0.9,
                                  decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    color: Colors.amberAccent.withOpacity(0.4),
                                    border: Border.all(
                                      color: Colors.amberAccent,
                                      width: 2,
                                    ),
                                    boxShadow: [
                                      BoxShadow(
                                        color: Colors.amberAccent.withOpacity(
                                          0.6,
                                        ),
                                        blurRadius: 10,
                                        spreadRadius: 2,
                                      ),
                                    ],
                                  ),
                                  child: const Icon(
                                    Icons.gps_fixed,
                                    color: Colors.amberAccent,
                                    size: 16,
                                  ),
                                ),
                              ),
                            ..._buildLudoPawns(
                              boardSize,
                              positions,
                              playerOrder,
                              playerColors,
                              playerId,
                              isMyTurn,
                              dice,
                              hasRolled,
                              widget.gameCode,
                              _firebaseService,
                              isTeamMode,
                              selectedOwnerId: _selectedLudoPawnOwner,
                              selectedPawnIdx: _selectedLudoPawnIdx,
                              onPawnTap: (ownerId, pawnIdx) {
                                if (!isMyTurn || !hasRolled || dice <= 0)
                                  return;
                                if (_selectedLudoPawnOwner == ownerId &&
                                    _selectedLudoPawnIdx == pawnIdx) {
                                  // 2e clic : Confirmation et déplacement !
                                  HapticFeedback.mediumImpact();
                                  _firebaseService.updateLudoPawnHover(
                                    widget.gameCode,
                                    playerId,
                                    null,
                                    null,
                                  );
                                  setState(() {
                                    _selectedLudoPawnIdx = null;
                                    _selectedLudoPawnOwner = null;
                                  });
                                  _firebaseService
                                      .movePawnPetitsChevaux(
                                        widget.gameCode,
                                        playerId,
                                        ownerId,
                                        pawnIdx,
                                      )
                                      .catchError((e) {
                                        debugPrint(e.toString());
                                      });
                                } else {
                                  // 1er clic : Sélection et diffusion live RTDB
                                  HapticFeedback.selectionClick();
                                  setState(() {
                                    _selectedLudoPawnIdx = pawnIdx;
                                    _selectedLudoPawnOwner = ownerId;
                                  });
                                  _firebaseService.updateLudoPawnHover(
                                    widget.gameCode,
                                    playerId,
                                    ownerId,
                                    pawnIdx,
                                  );
                                }
                              },
                            ),
                          ],
                        ),
                      ),
                    ),
                  );
                },
              );
            },
          ),
        ),

        // 3. ZONE DÉ & COMMANDES TACTILES
        Container(
          padding: const EdgeInsets.fromLTRB(16, 8, 16, 12),
          decoration: BoxDecoration(
            color: const Color(0xFF101018),
            borderRadius: const BorderRadius.vertical(top: Radius.circular(20)),
            border: Border.all(color: Colors.white10),
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceEvenly,
            children: [
              // Dé 3D avec vrais points
              _Ludo3DDice(
                value: dice,
                isRolling: false,
                isMyTurn: isMyTurn && !hasRolled,
                onTap:
                    isMyTurn && !hasRolled
                        ? () {
                          setState(() {
                            _selectedLudoPawnIdx = null;
                            _selectedLudoPawnOwner = null;
                          });
                          _firebaseService.updateLudoPawnHover(
                            widget.gameCode,
                            playerId,
                            null,
                            null,
                          );
                          _firebaseService.rollDicePetitsChevaux(
                            widget.gameCode,
                            playerId,
                          );
                        }
                        : null,
              ),

              // Actions
              Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  if (isMyTurn && !hasRolled)
                    ElevatedButton.icon(
                      icon: const Icon(Icons.casino_rounded, size: 20),
                      label: const Text("LANCER LE DÉ"),
                      style: ElevatedButton.styleFrom(
                        backgroundColor: Colors.deepPurpleAccent,
                        foregroundColor: Colors.white,
                        padding: const EdgeInsets.symmetric(
                          horizontal: 20,
                          vertical: 12,
                        ),
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(14),
                        ),
                      ),
                      onPressed: () {
                        setState(() {
                          _selectedLudoPawnIdx = null;
                          _selectedLudoPawnOwner = null;
                        });
                        _firebaseService.updateLudoPawnHover(
                          widget.gameCode,
                          playerId,
                          null,
                          null,
                        );
                        _firebaseService.rollDicePetitsChevaux(
                          widget.gameCode,
                          playerId,
                        );
                      },
                    )
                  else if (isMyTurn && hasRolled)
                    Row(
                      children: [
                        Text(
                          _selectedLudoPawnIdx != null
                              ? "Cheval ${_selectedLudoPawnIdx! + 1} sélectionné !\nTouchez pour avancer"
                              : "Touchez un pion",
                          style: TextStyle(
                            color:
                                _selectedLudoPawnIdx != null
                                    ? Colors.amberAccent
                                    : Colors.greenAccent,
                            fontWeight: FontWeight.bold,
                            fontSize: _selectedLudoPawnIdx != null ? 11 : 13,
                          ),
                        ),
                        const SizedBox(width: 12),
                        OutlinedButton.icon(
                          icon: const Icon(Icons.skip_next_rounded, size: 16),
                          label: const Text("Passer"),
                          style: OutlinedButton.styleFrom(
                            foregroundColor: Colors.white60,
                            side: const BorderSide(color: Colors.white24),
                            padding: const EdgeInsets.symmetric(
                              horizontal: 14,
                              vertical: 8,
                            ),
                            shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(12),
                            ),
                          ),
                          onPressed: () {
                            setState(() {
                              _selectedLudoPawnIdx = null;
                              _selectedLudoPawnOwner = null;
                            });
                            _firebaseService.updateLudoPawnHover(
                              widget.gameCode,
                              playerId,
                              null,
                              null,
                            );
                            _firebaseService.passTurnPetitsChevaux(
                              widget.gameCode,
                              playerId,
                            );
                          },
                        ),
                      ],
                    )
                  else
                    Row(
                      children: [
                        const SizedBox(
                          width: 14,
                          height: 14,
                          child: CircularProgressIndicator(
                            strokeWidth: 2,
                            color: Colors.white38,
                          ),
                        ),
                        const SizedBox(width: 8),
                        Text(
                          "${players[currentPlayerId]?['name'] ?? 'Un joueur'} réfléchit...",
                          style: const TextStyle(
                            color: Colors.white54,
                            fontSize: 12,
                            fontStyle: FontStyle.italic,
                          ),
                        ),
                      ],
                    ),
                ],
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _buildDominoesUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    // ── Extraction des données ───────────────────────────────────────────────
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});

    if (gameData['gameState'] == 'gameOver') {
      final scores = Map<String, int>.from(gameData['dominoesScores'] ?? {});
      return UniversalGameEndScreen(
        gameTitle: "Dominos",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason: gameData['gameEndReason'] ?? "Score limite atteint !",
        players: players,
        customScores: scores,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }
    final playerOrder = List<String>.from(
      gameData['dominoesPlayerOrder'] ?? [],
    );
    final int currentIndex = gameData['dominoesCurrentPlayerIndex'] ?? 0;
    final currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentIndex] : '';
    final bool isMyTurn = currentPlayerId == playerId;
    final bool isHost = gameData['hostId'] == playerId;

    final hands = Map<String, dynamic>.from(
      gameData['dominoesPlayerHands'] ?? {},
    );
    final myHand = List<String>.from(hands[playerId] ?? []);
    final openEnds = List<int>.from(gameData['dominoesOpenEnds'] ?? []);
    final boardChain = List<dynamic>.from(gameData['dominoesBoardChain'] ?? []);
    final boneyard = List<String>.from(gameData['dominoesBoneyard'] ?? []);
    final scores = Map<String, int>.from(gameData['dominoesScores'] ?? {});
    final bool roundOver = gameData['dominoesRoundOver'] ?? false;
    final String mode = gameData['dominoesMode'] ?? 'pioche';

    // â”€â”€ Helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    bool canPlayTile(String tile) {
      if (openEnds.isEmpty) return true;
      final p = tile.split('-');
      final a = int.parse(p[0]);
      final b = int.parse(p[1]);
      return openEnds.contains(a) || openEnds.contains(b);
    }

    bool hasPlayableTile() => myHand.any(canPlayTile);

    // Calcule l'extrÃ©mitÃ© de correspondance, retourne null si ambigu
    int? getMatchEnd(String tile) {
      if (boardChain.isEmpty) return -1; // premier domino
      final p = tile.split('-');
      final a = int.parse(p[0]);
      final b = int.parse(p[1]);
      final matchA = openEnds.contains(a);
      final matchB = openEnds.contains(b);
      if (matchA && matchB && a != b) return null; // ambigu
      if (matchA) return a;
      if (matchB) return b;
      return -99; // invalide
    }

    void _playTile(String tile, int matchEnd) {
      _firebaseService
          .playDominoesTile(widget.gameCode, playerId, tile, matchEnd)
          .then((_) {
            _firebaseService.updateDominoHoverEnd(
              widget.gameCode,
              playerId,
              null,
            );
            if (mounted) {
              setState(() => _selectedDominoTile = null);
            }
          })
          .catchError((e) {
            _firebaseService.updateDominoHoverEnd(
              widget.gameCode,
              playerId,
              null,
            );
            if (mounted) {
              setState(() => _selectedDominoTile = null);
              ScaffoldMessenger.of(
                context,
              ).showSnackBar(SnackBar(content: Text(e.toString())));
            }
          });
    }

    void onTileTap(String tile) {
      if (!isMyTurn || roundOver) return;
      if (!canPlayTile(tile)) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text("Impossible de jouer ce domino ici.")),
        );
        return;
      }

      final matchEnd = getMatchEnd(tile);

      if (_selectedDominoTile == tile) {
        // 2e clic : Confirmation et pose du domino
        if (matchEnd == null) {
          // Ambigu : afficher un dialogue pour choisir l'extrémité
          final p = tile.split('-');
          final a = int.parse(p[0]);
          final b = int.parse(p[1]);
          final options =
              openEnds.where((e) => e == a || e == b).toSet().toList();
          showDialog(
            context: context,
            builder: (_) {
              return AlertDialog(
                backgroundColor: const Color(0xFF1e3828),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(16),
                ),
                title: const Text(
                  "Choisir l'extrémité",
                  style: TextStyle(color: Colors.white),
                ),
                content: Text(
                  "Sur quelle extrémité poser le $tile ?",
                  style: const TextStyle(color: Colors.white70),
                ),
                actions:
                    options.map((end) {
                      return TextButton(
                        onPressed: () {
                          Navigator.pop(context);
                          _playTile(tile, end);
                        },
                        child: Text(
                          "Sur le $end",
                          style: const TextStyle(color: Color(0xFF34d399)),
                        ),
                      );
                    }).toList(),
              );
            },
          ).then((_) {
            _firebaseService.updateDominoHoverEnd(
              widget.gameCode,
              playerId,
              null,
            );
            if (mounted) {
              setState(() => _selectedDominoTile = null);
            }
          });
          return;
        }

        if (matchEnd == -99) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text("Aucune extrémité compatible.")),
          );
          return;
        }

        _playTile(tile, matchEnd!);
      } else {
        // 1er clic : Sélection et diffusion live RTDB
        HapticFeedback.selectionClick();
        setState(() => _selectedDominoTile = tile);

        if (matchEnd != null && matchEnd != -99) {
          _firebaseService.updateDominoHoverEnd(
            widget.gameCode,
            playerId,
            matchEnd,
          );
        } else if (matchEnd == null && openEnds.isNotEmpty) {
          final p = tile.split('-');
          final a = int.parse(p[0]);
          final b = int.parse(p[1]);
          final firstMatching =
              openEnds.where((e) => e == a || e == b).firstOrNull;
          if (firstMatching != null) {
            _firebaseService.updateDominoHoverEnd(
              widget.gameCode,
              playerId,
              firstMatching,
            );
          }
        }
      }
    }

    // ── Build ─────────────────────────────────────────────────────────────────
    return Column(
      children: [
        if (roundOver && gameData['gameState'] != 'gameOver')
          Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
            color: Colors.black87,
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                const Text(
                  "Manche terminée ! ",
                  style: TextStyle(
                    color: Colors.amberAccent,
                    fontWeight: FontWeight.bold,
                    fontSize: 14,
                  ),
                ),
                const SizedBox(width: 12),
                if (isHost)
                  ElevatedButton(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.green,
                      foregroundColor: Colors.white,
                    ),
                    onPressed:
                        () => _firebaseService.startNextDominoesRound(
                          widget.gameCode,
                        ),
                    child: const Text("Manche Suivante"),
                  )
                else
                  const Text(
                    "En attente de l'hôte...",
                    style: TextStyle(color: Colors.white70, fontSize: 13),
                  ),
              ],
            ),
          ),

        // ── Barre de scores ──────────────────────────────────────────────────
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
          color: Colors.black.withOpacity(0.35),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              const Text(
                "Dominos",
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.w500,
                  fontSize: 15,
                ),
              ),
              Row(
                children:
                    playerOrder.map((pId) {
                      final isActive = pId == currentPlayerId;
                      return Container(
                        margin: const EdgeInsets.only(left: 8),
                        padding: const EdgeInsets.symmetric(
                          horizontal: 12,
                          vertical: 4,
                        ),
                        decoration: BoxDecoration(
                          color:
                              isActive
                                  ? Colors.green.withOpacity(0.2)
                                  : Colors.white.withOpacity(0.08),
                          borderRadius: BorderRadius.circular(20),
                          border: Border.all(
                            color:
                                isActive
                                    ? Colors.greenAccent.withOpacity(0.5)
                                    : Colors.white.withOpacity(0.12),
                          ),
                        ),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Container(
                              width: 6,
                              height: 6,
                              margin: const EdgeInsets.only(right: 5),
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                color:
                                    isActive
                                        ? Colors.greenAccent
                                        : Colors.white38,
                              ),
                            ),
                            Text(
                              players[pId]?['name']
                                      ?.toString()
                                      .split(' ')
                                      .first ??
                                  pId,
                              style: TextStyle(
                                color:
                                    isActive
                                        ? const Color(0xFF6ee7b7)
                                        : Colors.white70,
                                fontSize: 12,
                              ),
                            ),
                            const SizedBox(width: 4),
                            Text(
                              '${scores[pId] ?? 0}',
                              style: const TextStyle(
                                color: Colors.white,
                                fontWeight: FontWeight.w600,
                                fontSize: 12,
                              ),
                            ),
                          ],
                        ),
                      );
                    }).toList(),
              ),
            ],
          ),
        ),

        // ── Mains des adversaires ──────────────────────────────────────────
        Container(
          height: 64,
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
          child: Row(
            children:
                playerOrder.where((pId) => pId != playerId).map((pId) {
                  final isActive = pId == currentPlayerId;
                  final oppHand = List<String>.from(hands[pId] ?? []);
                  return Expanded(
                    child: Container(
                      margin: const EdgeInsets.only(right: 8),
                      padding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 6,
                      ),
                      decoration: BoxDecoration(
                        color: Colors.black.withOpacity(0.3),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(
                          color:
                              isActive
                                  ? Colors.amber.withOpacity(0.5)
                                  : Colors.white.withOpacity(0.1),
                        ),
                      ),
                      child: Row(
                        children: [
                          CircleAvatar(
                            radius: 12,
                            backgroundColor: Colors.green.withOpacity(0.25),
                            child: Text(
                              (players[pId]?['name'] ?? pId)[0].toUpperCase(),
                              style: const TextStyle(
                                color: Color(0xFFa3e635),
                                fontSize: 10,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                Text(
                                  (players[pId]?['name'] ?? pId).toString() +
                                      (isActive ? ' 🎯' : ''),
                                  style: const TextStyle(
                                    color: Colors.white,
                                    fontSize: 11,
                                    fontWeight: FontWeight.w500,
                                  ),
                                  overflow: TextOverflow.ellipsis,
                                ),
                                Text(
                                  '${oppHand.length} domino${oppHand.length > 1 ? 's' : ''}',
                                  style: const TextStyle(
                                    color: Colors.white38,
                                    fontSize: 10,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          // Mini-représentation des dominos cachés
                          Wrap(
                            spacing: 2,
                            children:
                                oppHand
                                    .take(7)
                                    .map(
                                      (_) => Container(
                                        width: 8,
                                        height: 14,
                                        decoration: BoxDecoration(
                                          color: Colors.white.withOpacity(0.15),
                                          borderRadius: BorderRadius.circular(
                                            1,
                                          ),
                                          border: Border.all(
                                            color: Colors.white.withOpacity(
                                              0.08,
                                            ),
                                          ),
                                        ),
                                      ),
                                    )
                                    .toList(),
                          ),
                        ],
                      ),
                    ),
                  );
                }).toList(),
          ),
        ),

        // â”€â”€ Barre extrÃ©mitÃ©s ouvertes â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 5),
          color: Colors.black.withOpacity(0.2),
          child: Row(
            children: [
              const Text(
                "ExtrÃ©mitÃ©s : ",
                style: TextStyle(color: Colors.white38, fontSize: 11),
              ),
              if (openEnds.isEmpty)
                const Text(
                  "â€”",
                  style: TextStyle(color: Colors.white24, fontSize: 11),
                )
              else
                ...openEnds.map(
                  (e) => Container(
                    margin: const EdgeInsets.only(right: 6),
                    padding: const EdgeInsets.symmetric(
                      horizontal: 10,
                      vertical: 2,
                    ),
                    decoration: BoxDecoration(
                      color: const Color(0xFF34d399).withOpacity(0.15),
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(
                        color: const Color(0xFF34d399).withOpacity(0.35),
                      ),
                    ),
                    child: Text(
                      '$e',
                      style: const TextStyle(
                        color: Color(0xFF6ee7b7),
                        fontSize: 11,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                ),
              const Spacer(),
              if (mode == 'pioche')
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.black.withOpacity(0.2),
                    borderRadius: BorderRadius.circular(20),
                  ),
                  child: Text(
                    'pioche : ${boneyard.length}',
                    style: const TextStyle(color: Colors.white38, fontSize: 11),
                  ),
                ),
            ],
          ),
        ),

        Expanded(
          flex: 4,
          child: Container(
            margin: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: const Color(0xFF3a7bd5),
              borderRadius: BorderRadius.circular(16),
            ),
            child: StreamBuilder<DatabaseEvent>(
              stream: _firebaseService.getDominoHoverStream(widget.gameCode),
              builder: (context, hoverSnap) {
                int? liveHoverEnd;
                if (hoverSnap.hasData &&
                    hoverSnap.data!.snapshot.value != null) {
                  try {
                    final raw = Map<String, dynamic>.from(
                      hoverSnap.data!.snapshot.value as Map,
                    );
                    liveHoverEnd = raw['endValue'] as int?;
                  } catch (_) {}
                }

                return ClipRRect(
                  borderRadius: BorderRadius.circular(16),
                  child: Stack(
                    children: [
                      DominoesBoardWidget(
                        chain:
                            boardChain
                                .map((e) => Map<String, dynamic>.from(e))
                                .toList(),
                      ),
                      if (liveHoverEnd != null)
                        Positioned(
                          top: 10,
                          left: 10,
                          child: Container(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 10,
                              vertical: 4,
                            ),
                            decoration: BoxDecoration(
                              color: Colors.amber.withOpacity(0.85),
                              borderRadius: BorderRadius.circular(12),
                            ),
                            child: Text(
                              "Placement visé sur le : $liveHoverEnd",
                              style: const TextStyle(
                                fontWeight: FontWeight.bold,
                                color: Colors.black,
                                fontSize: 11,
                              ),
                            ),
                          ),
                        ),
                    ],
                  ),
                );
              },
            ),
          ),
        ),
        // â”€â”€ Rack du joueur â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        Expanded(
          flex: 3,
          child: Container(
            decoration: BoxDecoration(
              color: Colors.black.withOpacity(0.6),
              borderRadius: const BorderRadius.vertical(
                top: Radius.circular(24),
              ),
              border: Border(
                top: BorderSide(color: Colors.white.withOpacity(0.1)),
              ),
            ),
            child: Column(
              children: [
                // Indicateur de tour + actions
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 10, 12, 4),
                  child: Row(
                    children: [
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 14,
                          vertical: 5,
                        ),
                        decoration: BoxDecoration(
                          color:
                              isMyTurn
                                  ? Colors.green.withOpacity(0.15)
                                  : Colors.transparent,
                          borderRadius: BorderRadius.circular(20),
                          border:
                              isMyTurn
                                  ? Border.all(
                                    color: Colors.greenAccent.withOpacity(0.5),
                                    width: 1.2,
                                  )
                                  : null,
                        ),
                        child: Text(
                          isMyTurn
                              ? "C'est votre tour !"
                              : "Tour de ${players[currentPlayerId]?['name'] ?? '...'}",
                          style: TextStyle(
                            color:
                                isMyTurn
                                    ? const Color(0xFF34d399)
                                    : Colors.white38,
                            fontSize: 13,
                            fontWeight: FontWeight.w500,
                          ),
                        ),
                      ),
                      const Spacer(),
                      // Bouton pioche
                      if (isMyTurn &&
                          !roundOver &&
                          mode == 'pioche' &&
                          boneyard.isNotEmpty &&
                          !hasPlayableTile())
                        TextButton(
                          onPressed:
                              () => _firebaseService
                                  .drawDominoesTile(widget.gameCode, playerId)
                                  .catchError(
                                    (e) => ScaffoldMessenger.of(
                                      context,
                                    ).showSnackBar(
                                      SnackBar(content: Text(e.toString())),
                                    ),
                                  ),
                          child: const Text(
                            "Piocher",
                            style: TextStyle(
                              color: Colors.white70,
                              fontSize: 12,
                            ),
                          ),
                        ),
                      // Bouton passer
                      if (isMyTurn &&
                          !roundOver &&
                          (boneyard.isEmpty || mode != 'pioche') &&
                          !hasPlayableTile())
                        TextButton(
                          onPressed:
                              () => _firebaseService
                                  .passDominoesTurn(widget.gameCode, playerId)
                                  .catchError(
                                    (e) => ScaffoldMessenger.of(
                                      context,
                                    ).showSnackBar(
                                      SnackBar(content: Text(e.toString())),
                                    ),
                                  ),
                          child: const Text(
                            "Passer",
                            style: TextStyle(
                              color: Colors.redAccent,
                              fontSize: 12,
                            ),
                          ),
                        ),
                    ],
                  ),
                ),

                // Tuiles en main
                Expanded(
                  child: SingleChildScrollView(
                    scrollDirection: Axis.horizontal,
                    padding: const EdgeInsets.fromLTRB(12, 4, 12, 12),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.center,
                      children:
                          myHand.map((tile) {
                            final playable = isMyTurn && canPlayTile(tile);
                            return HandTileWidgetSimple(
                              tile: tile,
                              isPlayable: playable,
                              onTap: playable ? () => onTileTap(tile) : null,
                            );
                          }).toList(),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildYamsUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final players = Map<String, dynamic>.from(gameData['players']);
    final currentPlayerId = gameData['yamsCurrentPlayerId'];
    final isMyTurn = currentPlayerId == playerId;
    final List<int> dice = List<int>.from(gameData['yamsDice'] ?? []);
    final List<bool> heldDice = List<bool>.from(
      gameData['yamsHeldDice'] ?? [false, false, false, false, false],
    );
    final int rollsLeft = gameData['yamsRollsLeft'] ?? 3;
    final rawScores = Map<String, dynamic>.from(gameData['yamsScores'] ?? {});
    final myScores = Map<String, dynamic>.from(rawScores[playerId] ?? {});

    const List<String> categories = [
      'As',
      'Deux',
      'Trois',
      'Quatre',
      'Cinq',
      'Six',
      'Brelan',
      'Carré',
      'Full',
      'Petite Suite',
      'Grande Suite',
      'Yams',
      'Chance',
    ];

    if (gameData['gameState'] == 'gameOver') {
      final finalScores = Map<String, int>.from(
        (gameData['yamsFinalScores'] as Map? ?? {}).map(
          (k, v) => MapEntry(k.toString(), (v as num).toInt()),
        ),
      );
      return UniversalGameEndScreen(
        gameTitle: "Yams",
        winnerId: gameData['gameWinner'],
        winnerName: players[gameData['gameWinner']]?['name'],
        reason:
            gameData['gameEndReason'] ?? "Toutes les grilles sont complétées !",
        players: players,
        customScores: finalScores,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: gameData['hostId'] == playerId,
        onExit: _exitGame,
      );
    }

    return Column(
      children: [
        Container(
          padding: const EdgeInsets.all(12),
          color: isMyTurn ? Colors.green.withOpacity(0.2) : Colors.transparent,
          child: Text(
            isMyTurn
                ? "C'est votre tour !"
                : "Au tour de ${players[currentPlayerId]?['name'] ?? '...'}",
            style: TextStyle(
              fontSize: 18,
              fontWeight: FontWeight.bold,
              color: isMyTurn ? Colors.greenAccent : Colors.white,
            ),
          ),
        ),
        Container(
          padding: const EdgeInsets.all(16),
          child: Column(
            children: [
              Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: List.generate(5, (index) {
                  final value = dice.isNotEmpty ? dice[index] : 0;
                  final isHeld = heldDice[index];
                  return GestureDetector(
                    onTap:
                        isMyTurn && rollsLeft < 3 && dice.isNotEmpty
                            ? () => _firebaseService.yamsToggleHold(
                              widget.gameCode,
                              playerId,
                              index,
                            )
                            : null,
                    child: Container(
                      margin: const EdgeInsets.symmetric(horizontal: 4),
                      width: 50,
                      height: 50,
                      decoration: BoxDecoration(
                        color: isHeld ? Colors.amber : Colors.white,
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(color: Colors.black, width: 2),
                      ),
                      child: Center(
                        child: Text(
                          value > 0 ? value.toString() : "?",
                          style: const TextStyle(
                            fontSize: 24,
                            fontWeight: FontWeight.bold,
                            color: Colors.black,
                          ),
                        ),
                      ),
                    ),
                  );
                }),
              ),
              const SizedBox(height: 16),
              Text(
                "Lancers restants : $rollsLeft",
                style: const TextStyle(fontSize: 16),
              ),
              const SizedBox(height: 10),
              if (isMyTurn && rollsLeft > 0)
                ElevatedButton.icon(
                  icon: const Icon(Icons.casino),
                  label: Text(rollsLeft == 3 ? "Lancer les dés" : "Relancer"),
                  onPressed:
                      () => _firebaseService.yamsRollDice(
                        widget.gameCode,
                        playerId,
                      ),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.deepPurple,
                  ),
                ),
            ],
          ),
        ),
        Expanded(
          child: ListView.builder(
            itemCount: categories.length,
            itemBuilder: (context, index) {
              final cat = categories[index];
              final myScore = myScores[cat];
              final canScore =
                  isMyTurn &&
                  rollsLeft < 3 &&
                  dice.isNotEmpty &&
                  myScore == null;
              final potentialScore =
                  canScore
                      ? _firebaseService.calculateYamsScore(dice, cat)
                      : null;

              return Card(
                color:
                    canScore
                        ? Colors.deepPurple.withOpacity(0.4)
                        : (myScore != null
                            ? Colors.grey.withOpacity(0.2)
                            : null),
                margin: const EdgeInsets.symmetric(vertical: 4, horizontal: 8),
                child: ListTile(
                  title: Text(
                    cat,
                    style: const TextStyle(fontWeight: FontWeight.bold),
                  ),
                  trailing:
                      myScore != null
                          ? Text(
                            "$myScore pts",
                            style: const TextStyle(
                              fontSize: 18,
                              fontWeight: FontWeight.bold,
                              color: Colors.greenAccent,
                            ),
                          )
                          : (canScore
                              ? ElevatedButton(
                                style: ElevatedButton.styleFrom(
                                  backgroundColor:
                                      (potentialScore ?? 0) > 0
                                          ? Colors.green.shade700
                                          : Colors.grey.shade800,
                                ),
                                child: Text("Valider (+$potentialScore pts)"),
                                onPressed: () {
                                  if (cat == 'Yams' &&
                                      dice.isNotEmpty &&
                                      dice.every((d) => d == dice.first)) {
                                    Provider.of<PlayerState>(
                                      context,
                                      listen: false,
                                    ).recordBadgeEvent('yams_yams');
                                  }
                                  _firebaseService.yamsScoreCategory(
                                    widget.gameCode,
                                    playerId,
                                    cat,
                                  );
                                },
                              )
                              : const Text(
                                "-",
                                style: TextStyle(color: Colors.white38),
                              )),
                ),
              );
            },
          ),
        ),
      ],
    );
  }

  // ===========================================================================
  // 🃏 BELOTE (TAPIS EN LOSANGE CASINO & BOUTONS D'ATOUTS MODERNES)
  // ===========================================================================
  Widget _buildBeloteUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final roundState = gameData['roundState'];
    final playerData = Map<String, dynamic>.from(
      gameData['belotePlayerData'] ?? {},
    );
    final myData = playerData[playerId] ?? {};
    final List<String> myHand = List<String>.from(myData['hand'] ?? []);
    final String? trumpSuit = gameData['beloteTrumpSuit'];
    final String? turnedCard = gameData['beloteTurnedCard'];
    final Map<String, dynamic> currentTrick = Map<String, dynamic>.from(
      gameData['beloteCurrentTrick'] ?? {},
    );
    final Map<String, dynamic> teamScores = Map<String, dynamic>.from(
      gameData['beloteTeamScores'] ?? {},
    );
    final List<String> playerOrder = List<String>.from(
      gameData['belotePlayerOrder'] ?? [],
    );
    final int currentIndex = gameData['beloteCurrentPlayerIndex'] ?? 0;
    final bool isMyTurn =
        playerOrder.isNotEmpty && playerOrder[currentIndex] == playerId;
    final bool isHost = gameData['hostId'] == playerId;
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});

    // --- FIN DE PARTIE ---
    if (gameData['gameState'] == 'gameOver') {
      final String winnerTeam = gameData['gameWinner'] ?? 'teamA';
      return UniversalGameEndScreen(
        gameTitle: "Belote",
        winnerId: winnerTeam,
        winnerName: winnerTeam == 'teamA' ? 'Équipe A' : 'Équipe B',
        reason:
            "Score final : ${teamScores['teamA'] ?? 0} - ${teamScores['teamB'] ?? 0}",
        players: players,
        gameData: gameData,
        gameCode: widget.gameCode,
        currentPlayerId: playerId,
        isHost: isHost,
        onExit: _exitGame,
      );
    }

    return Container(
      decoration: const BoxDecoration(
        gradient: RadialGradient(
          center: Alignment.center,
          radius: 1.2,
          colors: [Color(0xFF1B4D3E), Color(0xFF0F2E24), Color(0xFF061511)],
        ),
      ),
      child: Column(
        children: [
          // 1. SCOREBOARD & CONTRAT D'ATOUT
          Container(
            margin: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
            decoration: BoxDecoration(
              color: Colors.black.withOpacity(0.45),
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: Colors.white12),
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      "Équipe A : ${teamScores['teamA'] ?? 0} pts",
                      style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.bold,
                        color:
                            myData['team'] == 'teamA'
                                ? Colors.cyanAccent
                                : Colors.white70,
                      ),
                    ),
                    Text(
                      "Équipe B : ${teamScores['teamB'] ?? 0} pts",
                      style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.bold,
                        color:
                            myData['team'] == 'teamB'
                                ? Colors.cyanAccent
                                : Colors.white70,
                      ),
                    ),
                  ],
                ),

                // Badge Atout
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 5,
                  ),
                  decoration: BoxDecoration(
                    color:
                        trumpSuit != null
                            ? const Color(0xFF2E6F58)
                            : Colors.amber.withOpacity(0.2),
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(
                      color:
                          trumpSuit != null ? Colors.amberAccent : Colors.amber,
                    ),
                  ),
                  child: Row(
                    children: [
                      Text(
                        trumpSuit != null
                            ? "ATOUT : ${_getSuitSymbol(trumpSuit)}"
                            : "ENCHÈRES EN COURS",
                        style: TextStyle(
                          fontWeight: FontWeight.w900,
                          fontSize: 12,
                          color:
                              trumpSuit != null
                                  ? (_isRedSuit(trumpSuit)
                                      ? Colors.redAccent.shade100
                                      : Colors.white)
                                  : Colors.amberAccent,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),

          // 2. TAPIS DE JEU EN LOSANGE (PLI CENTRAL & POSITIONS DES 4 JOUEURS)
          Expanded(
            child: Stack(
              alignment: Alignment.center,
              children: [
                // Fond du losange de pli
                Container(
                  width: 220,
                  height: 220,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: Colors.black.withOpacity(0.2),
                    border: Border.all(
                      color: Colors.white.withOpacity(0.08),
                      width: 1.5,
                    ),
                  ),
                ),

                // Indicateur de tour au centre
                if (currentTrick.isEmpty && roundState == 'playing_trick')
                  Text(
                    isMyTurn
                        ? "À VOUS D'OUVRIR LE PLI !"
                        : "Tour de ${playerData[playerOrder[currentIndex]]?['name'] ?? ''}",
                    style: TextStyle(
                      color: isMyTurn ? Colors.greenAccent : Colors.white38,
                      fontWeight: FontWeight.bold,
                      fontSize: 12,
                    ),
                    textAlign: TextAlign.center,
                  ),

                // Affichage de la carte retournée pendant les enchères
                if (roundState == 'bidding' && turnedCard != null)
                  Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const Text(
                        "CARTE À PRENDRE",
                        style: TextStyle(
                          color: Colors.amberAccent,
                          fontSize: 10,
                          fontWeight: FontWeight.bold,
                          letterSpacing: 1,
                        ),
                      ),
                      const SizedBox(height: 6),
                      _buildCard(
                        card: turnedCard,
                        isSelected: false,
                        scale: 0.95,
                      ),
                    ],
                  ),

                // Cartes jouées dans le pli en cours (disposées en croix)
                ...currentTrick.entries.map((entry) {
                  final String pId = entry.key;
                  final String playedCard = entry.value.toString();
                  final int pIndex = playerOrder.indexOf(pId);
                  final int myIndex = playerOrder.indexOf(playerId);
                  final int relPos =
                      (pIndex - myIndex + 4) %
                      4; // 0=Moi (Bas), 1=Gauche, 2=Face (Haut), 3=Droite

                  double dx = 0, dy = 0;
                  if (relPos == 0) dy = 45; // Bas
                  if (relPos == 2) dy = -45; // Haut
                  if (relPos == 1) dx = -55; // Gauche
                  if (relPos == 3) dx = 55; // Droite

                  return Transform.translate(
                    offset: Offset(dx, dy),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        _buildCard(
                          card: playedCard,
                          isSelected: false,
                          scale: 0.85,
                        ),
                        const SizedBox(height: 2),
                        Text(
                          players[pId]?['name'] ?? '',
                          style: const TextStyle(
                            color: Colors.white70,
                            fontSize: 9,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ],
                    ),
                  );
                }).toList(),
              ],
            ),
          ),

          // 3. PANNEAU D'ENCHÈRES STYLISÉ
          if (roundState == 'bidding' && isMyTurn)
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
              margin: const EdgeInsets.fromLTRB(10, 0, 10, 6),
              decoration: BoxDecoration(
                color: const Color(0xFF14141E),
                borderRadius: BorderRadius.circular(18),
                border: Border.all(color: Colors.amberAccent.withOpacity(0.5)),
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Text(
                    "PRENDRE L'ATOUT OU PASSER :",
                    style: TextStyle(
                      color: Colors.white70,
                      fontSize: 11,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                    children: [
                      ...['H', 'D', 'C', 'S'].map((suit) {
                        final bool isRed = (suit == 'H' || suit == 'D');
                        return ElevatedButton(
                          style: ElevatedButton.styleFrom(
                            backgroundColor:
                                isRed
                                    ? const Color(0xFF991B1B)
                                    : const Color(0xFF1E293B),
                            foregroundColor: Colors.white,
                            padding: const EdgeInsets.symmetric(
                              horizontal: 12,
                              vertical: 8,
                            ),
                            shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(12),
                            ),
                          ),
                          onPressed: () {
                            HapticFeedback.mediumImpact();
                            _firebaseService.beloteAction(
                              widget.gameCode,
                              playerId,
                              'bid',
                              suit: suit,
                            );
                          },
                          child: Text(
                            _getSuitSymbol(suit),
                            style: const TextStyle(
                              fontSize: 18,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        );
                      }).toList(),
                      OutlinedButton(
                        style: OutlinedButton.styleFrom(
                          foregroundColor: Colors.white70,
                          side: const BorderSide(color: Colors.white24),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        onPressed: () {
                          HapticFeedback.lightImpact();
                          _firebaseService.beloteAction(
                            widget.gameCode,
                            playerId,
                            'pass',
                          );
                        },
                        child: const Text("Passer"),
                      ),
                    ],
                  ),
                ],
              ),
            ),

          // 4. MAIN DU JOUEUR (CARTES JOUABLES FLUIDES)
          Container(
            padding: const EdgeInsets.fromLTRB(10, 6, 10, 8),
            decoration: BoxDecoration(
              color: const Color(0xFF0B1713),
              borderRadius: const BorderRadius.vertical(
                top: Radius.circular(20),
              ),
              border: Border.all(color: Colors.white10),
            ),
            child: Column(
              children: [
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      "Votre main (${myHand.length})",
                      style: const TextStyle(
                        color: Colors.white60,
                        fontSize: 11,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    if (isMyTurn && roundState == 'playing_trick')
                      const Text(
                        "Touchez une carte pour la poser",
                        style: TextStyle(
                          color: Colors.greenAccent,
                          fontSize: 10,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                  ],
                ),
                const SizedBox(height: 6),
                SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  physics: const BouncingScrollPhysics(),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children:
                        myHand.map((card) {
                          final bool canPlay =
                              isMyTurn && roundState == 'playing_trick';
                          return GestureDetector(
                            onTap:
                                canPlay
                                    ? () {
                                      HapticFeedback.selectionClick();
                                      _firebaseService
                                          .beloteAction(
                                            widget.gameCode,
                                            playerId,
                                            'play',
                                            card: card,
                                          )
                                          .catchError((e) {
                                            ScaffoldMessenger.of(
                                              context,
                                            ).showSnackBar(
                                              SnackBar(
                                                content: Text(
                                                  e.toString().replaceAll(
                                                    'Exception: ',
                                                    '',
                                                  ),
                                                ),
                                                backgroundColor:
                                                    Colors.red[900],
                                              ),
                                            );
                                          });
                                    }
                                    : null,
                            child: Opacity(
                              opacity: canPlay ? 1.0 : 0.65,
                              child: _buildCard(
                                card: card,
                                isSelected: false,
                                scale: 0.95,
                              ),
                            ),
                          );
                        }).toList(),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // --- HELPERS SYMBOLES DE COULEUR POUR LA BELOTE ---
  String _getSuitSymbol(String suit) {
    switch (suit) {
      case 'H':
        return '♥ Cœur';
      case 'D':
        return '♦ Carreau';
      case 'C':
        return '♣ Trèfle';
      case 'S':
        return '♠ Pique';
      default:
        return suit;
    }
  }

  bool _isRedSuit(String suit) => (suit == 'H' || suit == 'D');

  // ===========================================================================
  // 🃏 RAMI (TAPIS FEUTRINE CASINO & PLATEAUX DE COMBINAISONS BOISÉS)
  // ===========================================================================
  Widget _buildRamiUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    final myHand = List<String>.from(
      gameData['ramiPlayerHands']?[playerId] ?? [],
    );
    final stock = List<String>.from(gameData['ramiStock'] ?? []);
    final discard = List<String>.from(gameData['ramiDiscard'] ?? []);
    final melds = Map<String, dynamic>.from(gameData['ramiMelds'] ?? {});
    final currentPlayerId = gameData['ramiCurrentPlayerId'];
    final isMyTurn = currentPlayerId == playerId;
    final hasDrawn = gameData['ramiHasDrawn'] ?? false;
    final roundOver = gameData['ramiRoundOver'] ?? false;

    if (roundOver || gameData['gameState'] == 'gameOver') {
      return _buildRamiGameOverUI(context, gameData, playerId);
    }

    return Container(
      decoration: const BoxDecoration(
        gradient: RadialGradient(
          center: Alignment.center,
          radius: 1.2,
          colors: [Color(0xFF1B4D3E), Color(0xFF0D2B22), Color(0xFF061511)],
        ),
      ),
      child: Column(
        children: [
          // 1. BANDEAU ADVERSAIRES (COMPTEURS DE CARTES)
          Container(
            height: 58,
            margin: const EdgeInsets.only(top: 4, bottom: 4),
            child: ListView(
              scrollDirection: Axis.horizontal,
              physics: const BouncingScrollPhysics(),
              padding: const EdgeInsets.symmetric(horizontal: 8),
              children:
                  playerOrder.where((p) => p != playerId).map((pId) {
                    final bool isOppTurn = (pId == currentPlayerId);
                    final int handCount =
                        (gameData['ramiPlayerHands']?[pId] as List?)?.length ??
                        0;
                    final String oppName = players[pId]?['name'] ?? 'Joueur';

                    return Container(
                      margin: const EdgeInsets.symmetric(horizontal: 4),
                      padding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 6,
                      ),
                      decoration: BoxDecoration(
                        color:
                            isOppTurn
                                ? const Color(0xFF2E6F58).withOpacity(0.9)
                                : Colors.black.withOpacity(0.4),
                        borderRadius: BorderRadius.circular(14),
                        border: Border.all(
                          color:
                              isOppTurn ? Colors.amberAccent : Colors.white12,
                          width: isOppTurn ? 1.5 : 1,
