          if (players.length < minPlayers) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  "Il faut au moins $minPlayers joueurs pour ce mode !",
                ),
              ),
            );
            return;
          }
          if (maxPlayers != null && players.length > maxPlayers) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  "Ce mode supporte au maximum $maxPlayers joueurs !",
                ),
              ),
            );
            return;
          }

          if (isTeamGame) {
            showDialog(
              context: context,
              builder: (BuildContext dialogContext) {
                return TeamSelectionDialog(
                  allPlayers: players,
                  gameName: title,
                  minPlayersPerTeam: 2,
                  onTeamsConfirmed: (teamA, teamB) {
                    if (title == "Codenames") {
                      return CodenamesLocalGameScreen(
                        players: players,
                        redTeam: teamA,
                        blueTeam: teamB,
                      );
                    } else {
                      // Time's Up
                      return TimesUpLocalGameScreen(
                        players: players,
                        teamA: teamA,
                        teamB: teamB,
                      );
                    }
                  },
                );
              },
            );
          } else {
            Navigator.push(context, MaterialPageRoute(builder: (_) => screen));
          }
        },
        contentPadding: EdgeInsets.symmetric(vertical: 10, horizontal: 16),
      ),
    );
  }
}

