class SpinTheWheelWidget extends StatefulWidget {
  final List<String> players;
  final Function(int) onSpinEnd;

  const SpinTheWheelWidget({
    Key? key,
    required this.players,
    required this.onSpinEnd,
  }) : super(key: key);

  @override
  _SpinTheWheelWidgetState createState() => _SpinTheWheelWidgetState();
}

class _SpinTheWheelWidgetState extends State<SpinTheWheelWidget>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<double> _rotationAnimation;
  double _finalRotationAngle = 0.0;
  final Random _random = Random();

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: Duration(seconds: 4),
    );
    _spinWheel();
  }

  void _spinWheel() {
    double randomRotations = 8 + _random.nextDouble() * 4;
    _finalRotationAngle = randomRotations * 2 * pi;

    _rotationAnimation = Tween<double>(
      begin: 0.0,
      end: _finalRotationAngle,
    ).animate(CurvedAnimation(parent: _controller, curve: Curves.easeOutCubic));

    _controller.forward(from: 0).then((_) {
      _determineWinner();
    });
  }

  void _determineWinner() {
    if (widget.players.isEmpty) return;
    double segmentAngle = (2 * pi) / widget.players.length;
    double normalizedAngle = _finalRotationAngle % (2 * pi);
    int winnerIndex =
        ((2 * pi - normalizedAngle) / segmentAngle).floor() %
        widget.players.length;
    widget.onSpinEnd(winnerIndex);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          "La roue tourne...",
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        SizedBox(height: 20),
        SizedBox(
          width: 300,
          height: 300,
          child: Stack(
            alignment: Alignment.center,
            children: [
              AnimatedBuilder(
                animation: _rotationAnimation,
                builder: (context, child) {
                  return Transform.rotate(
                    angle: _rotationAnimation.value,
                    child: SizedBox(
                      width: 280,
                      height: 280,
                      child: CustomPaint(
                        painter: _WheelPainter(widget.players),
                      ),
                    ),
                  );
                },
              ),
              Container(
                width: 30,
                height: 30,
                decoration: BoxDecoration(
                  color: Colors.white,
                  shape: BoxShape.circle,
                  border: Border.all(color: Colors.deepPurple, width: 2),
                ),
              ),
              Positioned(
                top: 5,
                child: Icon(
                  Icons.keyboard_arrow_down,
                  color: Colors.redAccent,
                  size: 40,
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }
}

class _WheelPainter extends CustomPainter {
  final List<String> players;
  static const List<Color> colors = [
    Color(0xFF1976D2),
    Color(0xFF388E3C),
    Color(0xFFF57C00),
    Color(0xFFD32F2F),
    Color(0xFF7B1FA2),
    Color(0xFF689F38),
    Color(0xFF0288D1),
    Color(0xFFE64A19),
    Color(0xFF5D4037),
    Color(0xFF455A64),
  ];

  _WheelPainter(this.players);

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);
    final radius = size.width / 2;
    if (players.isEmpty) return;
    final segmentAngle = 2 * pi / players.length;

    for (int i = 0; i < players.length; i++) {
      final paint =
          Paint()
            ..color = colors[i % colors.length]
            ..style = PaintingStyle.fill;
      final startAngle = -pi / 2 + i * segmentAngle;
      final path = Path();
      path.moveTo(center.dx, center.dy);
      path.arcTo(
        Rect.fromCircle(center: center, radius: radius),
        startAngle,
        segmentAngle,
        false,
      );
      path.close();
      canvas.drawPath(path, paint);

      final borderPaint =
          Paint()
            ..color = Colors.white
            ..style = PaintingStyle.stroke
            ..strokeWidth = 2;
      canvas.drawPath(path, borderPaint);

      final textAngle = startAngle + segmentAngle / 2;
      final textRadius = radius * 0.65;
      final textCenter = Offset(
        center.dx + textRadius * cos(textAngle),
        center.dy + textRadius * sin(textAngle),
      );
      final textPainter = TextPainter(
        text: TextSpan(
          text: players[i],
          style: TextStyle(
            color: Colors.white,
            fontSize: 14,
            fontWeight: FontWeight.bold,
          ),
        ),
        textAlign: TextAlign.center,
        textDirection: TextDirection.ltr,
      );
      textPainter.layout();
      canvas.save();
      canvas.translate(textCenter.dx, textCenter.dy);
      double rotation = textAngle + pi / 2;
      if (rotation > pi / 2 && rotation < 3 * pi / 2) {
        rotation += pi;
      }
      canvas.rotate(rotation);
      textPainter.paint(
        canvas,
        Offset(-textPainter.width / 2, -textPainter.height / 2),
      );
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

enum UndercoverGameState { setup, revealing, discussing, voting, result }

class UndercoverLocalGameScreen extends StatefulWidget {
  final List<String> players;
  const UndercoverLocalGameScreen({Key? key, required this.players})
    : super(key: key);

  @override
  _UndercoverLocalGameScreenState createState() =>
      _UndercoverLocalGameScreenState();
}

class _UndercoverLocalGameScreenState extends State<UndercoverLocalGameScreen> {
  String _difficulty = 'soft';
  UndercoverGameState _gameState = UndercoverGameState.setup;
  int _currentPlayerRevealIndex = 0;
  Map<String, String> _playerRoles = {};
  String _wordCivil = "";
  String _wordUndercover = "";
  String _resultMessage = "";
  List<String> _activePlayers = [];
  String? _mrWhitePlayer;

  bool _includeMrWhite = true;
  bool _mrWhiteStarts = false;
  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiWordPairs = [];

  @override
  void dispose() {
    _aiController.dispose();
    super.dispose();
  }

  void _startNewRound() {
    final random = Random();
    _activePlayers = List.from(widget.players);

    final minPlayers = _includeMrWhite ? 4 : 3;
    if (_activePlayers.length < minPlayers) {
      setState(() {
        _resultMessage =
            "Pas assez de joueurs ! Il faut au moins $minPlayers joueurs pour cette configuration.";
        _gameState = UndercoverGameState.result;
      });
      return;
    }

    List<String> shuffledPlayers = List.from(_activePlayers)..shuffle();

    String undercover = shuffledPlayers[0];
    _mrWhitePlayer = null;
    if (_includeMrWhite) {
      _mrWhitePlayer = shuffledPlayers[1];
    }

    final wordPairs =
        _aiWordPairs.isNotEmpty
            ? _aiWordPairs
            : (GameWords.undercoverData[_difficulty]?['wordPairs'] ??
                GameWords.undercoverData['soft']!['wordPairs']!);
    final rawPair = wordPairs[random.nextInt(wordPairs.length)];
    if (rawPair.contains(':')) {
      final parts = rawPair.split(':');
      _wordCivil = parts[0].trim();
      _wordUndercover = parts[1].trim();
    } else {
      int idx = wordPairs.indexOf(rawPair);
      _wordCivil = rawPair.trim();
      _wordUndercover =
          (idx + 1 < wordPairs.length)
              ? wordPairs[idx + 1].trim()
              : "${rawPair.trim()} (Variante)";
    }

    _playerRoles.clear();
    for (var player in _activePlayers) {
      if (player == undercover) {
        _playerRoles[player] = "InfiltrÃƒÂ©";
      } else if (player == _mrWhitePlayer) {
        _playerRoles[player] = "Mr. White";
      } else {
        _playerRoles[player] = "Civil";
      }
    }

    setState(() {
      _gameState = UndercoverGameState.revealing;
      _currentPlayerRevealIndex = 0;
      _resultMessage = "";
    });
  }

  void _nextPlayerReveal() {
    if (_currentPlayerRevealIndex < _activePlayers.length - 1) {
      setState(() => _currentPlayerRevealIndex++);
    } else {
      setState(() => _gameState = UndercoverGameState.discussing);
    }
  }

  void _eliminatePlayer(String player) {
    String role = _playerRoles[player]!;
    bool impostorsWin = role == "Civil";

    setState(() {
      _gameState = UndercoverGameState.result;
      if (impostorsWin) {
        _resultMessage = "$player ÃƒÂ©tait un Civil ! Les Imposteurs gagnent !";
      } else {
        _resultMessage = "$player ÃƒÂ©tait l'${role} ! Les Civils gagnent !";
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Infiltré & Mr. White"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Infiltré & Mr. White'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: AnimatedSwitcher(
          duration: Duration(milliseconds: 300),
          child: _buildContentForState(),
        ),
      ),
    );
  }

  Widget _buildContentForState() {
    switch (_gameState) {
      case UndercoverGameState.setup:
        return _buildSetupPhase();
      case UndercoverGameState.revealing:
        return _buildRevealPhase();
      case UndercoverGameState.discussing:
        return _buildDiscussionPhase();
      case UndercoverGameState.voting:
        return _buildVotingPhase();
      case UndercoverGameState.result:
        return _buildResultPhase();
    }
  }

  Widget _buildSetupPhase() {
    return Center(
      key: ValueKey('setup'),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                "Configuration",
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 20),
              SegmentedButton<String>(
                segments: const [
                  ButtonSegment(value: 'soft', label: Text('Soft')),
                  ButtonSegment(value: 'hard', label: Text('Hard')),
                  ButtonSegment(value: 'hardcore', label: Text('Hardcore')),
                ],
                selected: {_difficulty},
                onSelectionChanged:
                    (newSelection) =>
                        setState(() => _difficulty = newSelection.first),
              ),
              SizedBox(height: 20),
              SwitchListTile.adaptive(
                title: Text("Inclure Mr. White ?"),
                subtitle: Text(
                  _includeMrWhite
                      ? "Requiert 4+ joueurs"
                      : "Requiert 3+ joueurs",
                ),
                value: _includeMrWhite,
                onChanged: (val) => setState(() => _includeMrWhite = val),
                secondary: Icon(Icons.person_off),
              ),
              if (_includeMrWhite)
                SwitchListTile.adaptive(
                  title: Text("Mr. White commence ?"),
                  subtitle: Text("Il devra donner le premier indice"),
                  value: _mrWhiteStarts,
                  onChanged: (val) => setState(() => _mrWhiteStarts = val),
                  secondary: Icon(Icons.play_arrow),
                ),
              Consumer<PlayerState>(
                builder: (ctx, ps, _) {
                  if (!ps.isPremium) return SizedBox.shrink();
                  return Container(
                    margin: EdgeInsets.only(bottom: 12),
                    decoration: BoxDecoration(
                      border: Border.all(color: Colors.amberAccent),
                      borderRadius: BorderRadius.circular(12),
                    ),
                    padding: EdgeInsets.all(12),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          children: [
                            Icon(
                              Icons.auto_awesome,
                              color: Colors.amberAccent,
                              size: 18,
                            ),
                            SizedBox(width: 8),
                            Text(
                              "IA Premium",
                              style: TextStyle(
                                color: Colors.amberAccent,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                          ],
                        ),
                        SizedBox(height: 8),
                        TextField(
                          controller: _aiController,
                          decoration: InputDecoration(
                            labelText: "ThÃƒÂ¨me pour les paires de mots",
                            hintText:
                                "ex: animaux:objets, cuisine... (format civil:infiltrÃƒÂ©)",
                            border: OutlineInputBorder(),
                          ),
                          maxLines: 1,
                        ),
                      ],
                    ),
                  );
                },
              ),
              SizedBox(height: 30),
              ElevatedButton(
                onPressed:
                    _isAiLoading
                        ? null
                        : () async {
                          if (_aiController.text.trim().isNotEmpty) {
                            setState(() => _isAiLoading = true);
                            try {
                              final words =
                                  await FirebaseService.generateAiWords(
                                    instructions: _aiController.text.trim(),
                                    count: 30,
                                    gameType: 'Infiltré & Mr. White',
                                  );
                              _aiWordPairs = words;
                            } catch (e) {
                              print('AI error: $e');
                            } finally {
                              if (mounted) setState(() => _isAiLoading = false);
                            }
                          } else {
                            _aiWordPairs = [];
                          }
                          _startNewRound();
                        },
                child:
                    _isAiLoading
                        ? Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            SizedBox(
                              width: 16,
                              height: 16,
                              child: CircularProgressIndicator(
                                color: Colors.white,
                                strokeWidth: 2,
                              ),
                            ),
                            SizedBox(width: 8),
                            Text("GÃƒÂ©nÃƒÂ©ration IA..."),
                          ],
                        )
                        : Text("Commencer la manche"),
              ),
            ],
