enum HotPotatoState { setup, playing, exploded }

class HotPotatoLocalScreen extends StatefulWidget {
  final List<String> players;
  const HotPotatoLocalScreen({Key? key, required this.players})
    : super(key: key);

  @override
  _HotPotatoLocalScreenState createState() => _HotPotatoLocalScreenState();
}

class _HotPotatoLocalScreenState extends State<HotPotatoLocalScreen>
    with TickerProviderStateMixin {
  HotPotatoState _gameState = HotPotatoState.setup;
  Timer? _turnTimer;
  int _secondsLeft = 0;
  final Random _random = Random();
  final _answerController = TextEditingController();
  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiCategories = [];

  int _currentPlayerIndex = 0;
  List<String> _usedAnswers = [];

  String _selectedCategory = GameWords.hotPotatoCategories['soft']!.keys.first;
  int _turnDuration = 10;
  bool _useGlobalTimer = false;
  int _globalDuration = 30;

  @override
  void dispose() {
    _turnTimer?.cancel();
    _answerController.dispose();
    _aiController.dispose();
    super.dispose();
  }

  void _startGame() {
    _turnTimer
        ?.cancel(); // Annule tout timer prÃƒÂ©cÃƒÂ©dent par sÃƒÂ©curitÃƒÂ©
    _usedAnswers.clear();
    _currentPlayerIndex = _random.nextInt(widget.players.length);

    if (_useGlobalTimer) {
      _secondsLeft = _globalDuration;
    } else {
      int duration = _turnDuration;
      if (_turnDuration == 0) {
        // Mode alÃƒÂ©atoire
        duration = 5 + _random.nextInt(11); // 5 ÃƒÂ  15 secondes
      }
      _secondsLeft = duration;
    }

    _turnTimer = Timer.periodic(Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      if (_secondsLeft > 1) {
        setState(() => _secondsLeft--);
      } else {
        _explode();
      }
    });

    setState(() {
      _gameState = HotPotatoState.playing;
    });
  }

  void _explode() {
    _turnTimer?.cancel();
    HapticFeedback.vibrate();
    setState(() {
      _gameState = HotPotatoState.exploded;
    });
  }

  void _passPotato() {
    final answer = _answerController.text.trim().toLowerCase();
    if (answer.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text("Tu dois ÃƒÂ©crire une rÃƒÂ©ponse !")),
      );
      return;
    }
    if (_usedAnswers.contains(answer)) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text("Cette rÃƒÂ©ponse a dÃƒÂ©jÃƒÂ  ÃƒÂ©tÃƒÂ© donnÃƒÂ©e !"),
        ),
      );
      return;
    }

    _answerController.clear();
    FocusScope.of(context).unfocus();

    if (!_useGlobalTimer) {
      int duration = _turnDuration;
      if (_turnDuration == 0) {
        duration = 5 + _random.nextInt(11);
      }
      _secondsLeft = duration;
    }

    setState(() {
      _usedAnswers.add(answer);
      _currentPlayerIndex = (_currentPlayerIndex + 1) % widget.players.length;
    });
  }

  void _resetGame() {
    _turnTimer?.cancel();
    setState(() {
      _gameState = HotPotatoState.setup;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("La Patate Chaude"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'La Patate Chaude'),
          ),
        ],
      ),
      body: Center(
        child: Padding(
          padding: const EdgeInsets.all(16.0),
          child: AnimatedSwitcher(
            duration: Duration(milliseconds: 300),
            child: _buildContentForState(),
          ),
        ),
      ),
    );
  }

  Widget _buildContentForState() {
    switch (_gameState) {
      case HotPotatoState.setup:
        return _buildSetupScreen();
      case HotPotatoState.playing:
        return _buildPlayingScreen();
      case HotPotatoState.exploded:
        return _buildExplodedScreen();
    }
  }

