    );
  }

  Widget _buildResultPhase() {
    return Column(
      key: ValueKey('result'),
      mainAxisAlignment: MainAxisAlignment.center,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Icon(Icons.block, color: Colors.redAccent, size: 80),
        SizedBox(height: 20),
        Text(
          "La proposition de $_bannedPlayer a ÃƒÂ©tÃƒÂ© bannie !",
          style: Theme.of(context).textTheme.headlineMedium,
          textAlign: TextAlign.center,
        ),
        SizedBox(height: 20),
        Text(
          "$_bannedPlayer a perdu cette manche !",
          style: Theme.of(
            context,
          ).textTheme.titleLarge?.copyWith(color: Colors.amber),
          textAlign: TextAlign.center,
        ),
        SizedBox(height: 40),
        ElevatedButton(
          onPressed: () => setState(() => _phase = GamePhase.setup),
          child: Text("Nouvelle manche"),
        ),
      ],
    );
  }
}

enum LocalWhoIsPhase { question, voting, results }

class WhoIsMostLikelyLocalScreen extends StatefulWidget {
  final List<String> players;
  const WhoIsMostLikelyLocalScreen({Key? key, required this.players})
    : super(key: key);

  @override
  _WhoIsMostLikelyLocalScreenState createState() =>
      _WhoIsMostLikelyLocalScreenState();
}

class _WhoIsMostLikelyLocalScreenState
    extends State<WhoIsMostLikelyLocalScreen> {
  String _difficulty = 'soft';
  String _votingMode =
      'grouper'; // "grouper" (Ensemble) ou "chacun" (Tour par tour)
  String _currentQuestion = "";
  LocalWhoIsPhase _phase = LocalWhoIsPhase.question;

  int _currentVoterIndex = 0;
  Map<String, String> _votes = {}; // Voter -> VotedFor

  // --- SYSTÈME DE SCORES ---
  Map<String, int> _globalScores = {};

  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiQuestions = [];

  @override
  void initState() {
    super.initState();
    // Initialiser les scores à 0
    for (var p in widget.players) {
      _globalScores[p] = 0;
    }
    _getNewQuestion();
  }

  @override
  void dispose() {
    _aiController.dispose();
    super.dispose();
  }

  void _getNewQuestion() {
    if (_aiQuestions.isNotEmpty) {
      _currentQuestion = _aiQuestions[Random().nextInt(_aiQuestions.length)];
    } else {
      final questions =
          GameWords.whoIsMostLikely[_difficulty] ??
          GameWords.whoIsMostLikely['soft']!;
      _currentQuestion = questions[Random().nextInt(questions.length)];
    }
    setState(() {
      _phase = LocalWhoIsPhase.question;
      _votes.clear();
      _currentVoterIndex = 0;
    });
  }

  void _startVoting() {
    setState(() {
      _phase = LocalWhoIsPhase.voting;
      _currentVoterIndex = 0;
      _votes.clear();
    });
  }

  void _recordVote(String votedFor) {
    final voter = widget.players[_currentVoterIndex];
    setState(() {
      _votes[voter] = votedFor;
      if (_currentVoterIndex < widget.players.length - 1) {
        _currentVoterIndex++;
      } else {
        _phase = LocalWhoIsPhase.results;
        _awardPoints(); // Attribuer les points aux gagnants
      }
    });
  }

  Map<String, int> _calculateTally() {
    Map<String, int> tally = {for (var p in widget.players) p: 0};
    for (var votedFor in _votes.values) {
      tally[votedFor] = (tally[votedFor] ?? 0) + 1;
    }
    return tally;
  }

  List<String> _getWinners(Map<String, int> tally) {
    int maxVotes = 0;
    tally.forEach((_, votes) {
      if (votes > maxVotes) maxVotes = votes;
    });
    if (maxVotes == 0) return [];
    return tally.entries
        .where((e) => e.value == maxVotes)
        .map((e) => e.key)
        .toList();
  }

  void _awardPoints() {
    final tally = _calculateTally();
    final winners = _getWinners(tally);
    for (var w in winners) {
      _globalScores[w] = (_globalScores[w] ?? 0) + 1;
    }
  }

  void _showScoreDialog(String selectedPlayer) {
    showDialog(
      context: context,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (context, setStateDialog) {
            return AlertDialog(
              title: const Text(
                "Tableau des Scores",
                textAlign: TextAlign.center,
              ),
              content: Column(
                mainAxisSize: MainAxisSize.min,
                children:
                    widget.players.map((p) {
                      bool isSelected = p == selectedPlayer;
                      return ListTile(
                        title: Text(
                          p,
                          style: TextStyle(
                            fontWeight:
                                isSelected
                                    ? FontWeight.bold
                                    : FontWeight.normal,
                            color: isSelected ? Colors.amber : Colors.white,
                          ),
                        ),
                        trailing: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            IconButton(
                              icon: const Icon(
                                Icons.remove_circle_outline,
                                color: Colors.redAccent,
                              ),
                              onPressed: () {
                                setState(() {
                                  _globalScores[p] =
                                      (_globalScores[p] ?? 0) - 1;
                                });
                                setStateDialog(() {});
                              },
                            ),
                            Text(
                              "${_globalScores[p]}",
                              style: const TextStyle(
                                fontSize: 18,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                            IconButton(
                              icon: const Icon(
                                Icons.add_circle_outline,
                                color: Colors.greenAccent,
                              ),
                              onPressed: () {
                                setState(() {
                                  _globalScores[p] =
                                      (_globalScores[p] ?? 0) + 1;
                                });
                                setStateDialog(() {});
                              },
                            ),
                          ],
                        ),
                      );
                    }).toList(),
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(ctx),
                  child: const Text("Fermer"),
                ),
              ],
            );
          },
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text("Qui Pourrait le Plus ?"),
        actions: [
          IconButton(
            icon: const Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Qui Pourrait le Plus ?'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            if (_phase != LocalWhoIsPhase.results) ...[
              // FILTRE DIFFICULTE
              SegmentedButton<String>(
                segments: const [
                  ButtonSegment(value: 'soft', label: Text('Soft')),
                  ButtonSegment(value: 'hard', label: Text('Hard')),
                  ButtonSegment(value: 'hardcore', label: Text('Hardcore')),
                ],
                selected: {_difficulty},
                onSelectionChanged:
                    (s) => setState(() {
                      _difficulty = s.first;
                      _getNewQuestion();
                    }),
              ),
              const SizedBox(height: 12),
              // NOUVEAU: CHOIX DU MODE DE VOTE PENDANT LE JEU
              SegmentedButton<String>(
                segments: const [
                  ButtonSegment(
                    value: 'grouper',
                    label: Text('Groupe (Ensemble)'),
                    icon: Icon(Icons.groups),
                  ),
                  ButtonSegment(
                    value: 'chacun',
                    label: Text('Tour par tour'),
                    icon: Icon(Icons.person),
                  ),
                ],
                selected: {_votingMode},
                onSelectionChanged:
                    (s) => setState(() {
                      _votingMode = s.first;
                      if (_phase == LocalWhoIsPhase.voting) {
                        // Réinitialisation en douceur pour appliquer le changement immédiatement
                        _currentVoterIndex = 0;
                        _votes.clear();
                      }
                    }),
              ),
              const SizedBox(height: 16),
            ],
            Expanded(
              child: AnimatedSwitcher(
                duration: const Duration(milliseconds: 300),
                child: _buildContent(),
              ),
            ),
            const SizedBox(height: 10),
            _buildPlayerChips(), // Affichage permanent des scores en bas
          ],
        ),
      ),
    );
  }

  Widget _buildPlayerChips() {
    return Wrap(
      spacing: 8,
      runSpacing: 4,
      alignment: WrapAlignment.center,
      children: List.generate(widget.players.length, (index) {
        final pName = widget.players[index];
        final isCurrentVoter =
            _phase == LocalWhoIsPhase.voting &&
            _votingMode == 'chacun' &&
            index == _currentVoterIndex;
        return ActionChip(
          avatar: CircleAvatar(
            backgroundColor: Colors.white24,
            child: Text(
              pName[0],
              style: const TextStyle(fontSize: 10, color: Colors.white),
            ),
          ),
          label: Text("$pName : ${_globalScores[pName]} pts"),
          backgroundColor:
              isCurrentVoter ? Colors.deepPurple : const Color(0xFF333333),
          labelStyle: TextStyle(
            color: Colors.white,
            fontWeight: isCurrentVoter ? FontWeight.bold : FontWeight.normal,
          ),
          onPressed: () => _showScoreDialog(pName),
        );
      }),
    );
  }

  Widget _buildContent() {
    switch (_phase) {
      case LocalWhoIsPhase.question:
        return _buildQuestionStep();
      case LocalWhoIsPhase.voting:
        return _buildVotingStep();
      case LocalWhoIsPhase.results:
        return _buildResultsStep();
    }
  }

  Widget _buildQuestionStep() {
    return Column(
      key: const ValueKey('question_step'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Consumer<PlayerState>(
