}

enum PassTheObjectGameState { setup, playing, questionPhase }

class PassTheObjectGameScreen extends StatefulWidget {
  final List<String> players;
  const PassTheObjectGameScreen({Key? key, required this.players})
    : super(key: key);

  @override
  _PassTheObjectGameScreenState createState() =>
      _PassTheObjectGameScreenState();
}

class _PassTheObjectGameScreenState extends State<PassTheObjectGameScreen>
    with TickerProviderStateMixin {
  PassTheObjectGameState _gameState = PassTheObjectGameState.setup;
  String _difficulty = 'soft';
  Timer? _gameTimer;
  Timer? _flashTimer;
  int _secondsRemaining = 0;
  final Random _random = Random();
  String _currentQuestion = "";
  int _loserIndex = 0;
  bool _isFlashing = false;

  bool _useButton = true;
  bool _showTimer = true;

  int _minDuration = 10;
  int _maxDuration = 30;

  String? _nextPlayerToPass;
  final List<int> _passedSequence =
      []; // Historique pour éviter la répétition immédiate du même joueur

  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiQuestions = [];

  @override
  void dispose() {
    _gameTimer?.cancel();
    _flashTimer?.cancel();
    _aiController.dispose();
    super.dispose();
  }

  void _startGame() {
    _gameTimer?.cancel();
    _flashTimer?.cancel();
    _passedSequence.clear();

    if (_maxDuration > _minDuration) {
      _secondsRemaining =
          _minDuration + _random.nextInt(_maxDuration - _minDuration + 1);
    } else {
      _secondsRemaining = _minDuration;
    }

    _loserIndex = _random.nextInt(widget.players.length);
    _passedSequence.add(_loserIndex);
    _nextPlayerToPass = null; // Réinitialiser au début

    _gameTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      setState(() {
        _secondsRemaining--;
        if (_secondsRemaining <= 5 && _secondsRemaining > 0) {
          _startFlashing();
        }
        if (_secondsRemaining <= 0) {
          timer.cancel();
          _flashTimer?.cancel();
          _triggerQuestion();
        }
      });
    });

    setState(() {
      _gameState = PassTheObjectGameState.playing;
    });
  }

  void _passToRandomPlayer() {
    if (widget.players.length < 2) return;

    // Règle équitable : sélectionne un joueur différent qui n'a pas eu l'objet récemment
    List<int> eligibleIndices = [];
    for (int i = 0; i < widget.players.length; i++) {
      if (i != _loserIndex) {
        eligibleIndices.add(i);
      }
    }

    int nextIdx = eligibleIndices[_random.nextInt(eligibleIndices.length)];
    String nextPlayer = widget.players[nextIdx];

    // --- ATTRIBUTION XP LOCAL : +5 XP pour un passage réussi ---
    Provider.of<PlayerState>(context, listen: false).addXp(5);

    setState(() {
      _nextPlayerToPass = nextPlayer;
      _loserIndex = nextIdx;
      _passedSequence.add(nextIdx);
    });
  }

  void _startFlashing() {
    _flashTimer?.cancel();
    _flashTimer = Timer.periodic(const Duration(milliseconds: 300), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      setState(() {
        _isFlashing = !_isFlashing;
      });
    });
  }

  void _triggerQuestion() {
    String cleanQ = "";
    if (_aiQuestions.isNotEmpty) {
      cleanQ = _aiQuestions[_random.nextInt(_aiQuestions.length)];
    } else {
      final questions =
          GameWords.passTheObjectQuestions[_difficulty] ??
          GameWords.passTheObjectQuestions['soft']!;
      String rawQ = questions[_random.nextInt(questions.length)];
      cleanQ = FirebaseService.sanitizeUserInput(rawQ, maxLength: 150);
    }

    // --- ATTRIBUTION XP LOCAL : +20 XP pour répondre à la question sous pression ---
    Provider.of<PlayerState>(context, listen: false).addXp(20);

    setState(() {
      _currentQuestion = cleanQ;
      _gameState = PassTheObjectGameState.questionPhase;
      _isFlashing = false;
    });
  }

  void _resetGame() {
    _gameTimer?.cancel();
    _flashTimer?.cancel();
    _passedSequence.clear();
    setState(() {
      _gameState = PassTheObjectGameState.setup;
      _currentQuestion = "";
      _secondsRemaining = 0;
      _isFlashing = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text("Passe l'Objet"),
        actions: [
          IconButton(
            icon: const Icon(Icons.info_outline),
            onPressed:
                () => showGameRules(context, 'On se passe un objet rapidement'),
          ),
        ],
      ),
      body: AnimatedContainer(
        duration: const Duration(milliseconds: 150),
        color:
            _isFlashing
                ? Colors.red.withOpacity(0.5)
                : Theme.of(context).scaffoldBackgroundColor,
        child: Padding(
          padding: const EdgeInsets.all(16.0),
          child: AnimatedSwitcher(
            duration: const Duration(milliseconds: 300),
            child: _buildContentForState(),
          ),
        ),
      ),
    );
  }

  Widget _buildContentForState() {
    switch (_gameState) {
      case PassTheObjectGameState.setup:
        return _buildSetupScreen();
      case PassTheObjectGameState.playing:
        return _buildPlayingScreen();
      case PassTheObjectGameState.questionPhase:
        return _buildQuestionPhase();
    }
  }

  Widget _buildSetupScreen() {
    return SingleChildScrollView(
      key: const ValueKey('setup'),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const Icon(
                Icons.directions_run,
                size: 80,
                color: Colors.deepPurpleAccent,
              ),
              const SizedBox(height: 10),
              Text(
                "Passe l'Objet Rapidement",
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              const SizedBox(height: 20),
              DropdownButtonFormField<String>(
                value: _difficulty,
                items:
                    GameWords.passTheObjectQuestions.keys
                        .map(
                          (diff) =>
                              DropdownMenuItem(value: diff, child: Text(diff)),
                        )
                        .toList(),
                onChanged: (val) => setState(() => _difficulty = val!),
                decoration: const InputDecoration(
                  labelText: "Difficulté des questions",
                ),
              ),
