class LoungeListScreen extends StatelessWidget {
  final String playerId;
  LoungeListScreen({required this.playerId});

  void _showJoinPrivateDialog(BuildContext context) {
    final codeCtrl = TextEditingController();
    showDialog(
      context: context,
      builder:
          (ctx) => AlertDialog(
            title: const Text("Rejoindre un salon privé"),
            content: TextField(
              controller: codeCtrl,
              decoration: const InputDecoration(
                labelText: "Code du salon (6 chiffres) ou ID",
                hintText: "Ex: 123456",
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx),
                child: const Text("Annuler"),
              ),
              ElevatedButton(
                onPressed: () async {
                  final input = codeCtrl.text.trim();
                  if (input.isEmpty) return;

                  String? targetLoungeId;

                  // 1. Recherche par code à 6 chiffres (joinCode)
                  final querySnap =
                      await FirebaseFirestore.instance
                          .collection('lounges')
                          .where('joinCode', isEqualTo: input)
                          .limit(1)
                          .get();

                  if (querySnap.docs.isNotEmpty) {
                    targetLoungeId = querySnap.docs.first.id;
                  } else {
                    // 2. Recherche par Document ID direct
                    final doc =
                        await FirebaseFirestore.instance
                            .collection('lounges')
                            .doc(input)
                            .get();
                    if (doc.exists) {
                      targetLoungeId = doc.id;
                    }
                  }

                  if (targetLoungeId != null) {
                    Navigator.pop(ctx);
                    final ps = Provider.of<PlayerState>(context, listen: false);
                    await FirebaseService().joinLounge(
                      targetLoungeId,
                      playerId,
                      ps.userName ?? 'Joueur',
                    );
                    Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder:
                            (_) => LoungeRoomScreen(
                              loungeId: targetLoungeId!,
                              playerId: playerId,
                            ),
                      ),
                    );
                  } else {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(
                        content: Text("Code de salon introuvable."),
                      ),
                    );
                  }
                },
                child: const Text("Rejoindre"),
              ),
            ],
          ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Row(
              children: [
                const Expanded(
                  child: Text(
                    "Rejoins un salon public ou entre un code privé :",
                    style: TextStyle(color: Colors.white70),
                  ),
                ),
                OutlinedButton.icon(
                  icon: const Icon(Icons.lock_open, size: 16),
                  label: const Text("Code Privé"),
                  onPressed: () => _showJoinPrivateDialog(context),
                ),
              ],
            ),
          ),
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream:
                  FirebaseFirestore.instance
                      .collection('lounges')
                      .where('isPrivate', isEqualTo: false)
                      .orderBy('createdAt', descending: true)
                      .snapshots(),
              builder: (context, snapshot) {
                if (!snapshot.hasData)
                  return const Center(child: CircularProgressIndicator());
                final lounges = snapshot.data!.docs;

                if (lounges.isEmpty) {
                  return const Center(
                    child: Text("Aucun salon public disponible."),
                  );
                }

                return ListView.builder(
                  itemCount: lounges.length,
                  itemBuilder: (context, index) {
                    final data = lounges[index].data() as Map<String, dynamic>;
                    final players =
                        data['players'] as Map<String, dynamic>? ?? {};
                    final bool isFull =
                        players.length >= (data['maxPlayers'] ?? 10);

                    return Card(
                      margin: const EdgeInsets.symmetric(
                        horizontal: 16,
                        vertical: 8,
                      ),
                      color: Colors.blueGrey[900],
                      child: ListTile(
                        leading: const Icon(
                          Icons.living,
                          size: 40,
                          color: Colors.amber,
                        ),
                        title: Text(
                          data['name'] ?? 'Salon',
                          style: const TextStyle(fontWeight: FontWeight.bold),
                        ),
                        subtitle: Text("Thème : ${data['theme'] ?? 'Général'}"),
                        trailing: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            const Icon(Icons.people, size: 16),
                            Text(
                              "${players.length} / ${data['maxPlayers'] ?? 10}",
                              style: TextStyle(
                                color: isFull ? Colors.red : Colors.greenAccent,
                              ),
                            ),
                          ],
                        ),
                        onTap:
                            isFull
                                ? null
                                : () async {
                                  final ps = Provider.of<PlayerState>(
                                    context,
                                    listen: false,
                                  );
                                  await FirebaseService().joinLounge(
                                    lounges[index].id,
                                    playerId,
                                    ps.userName ?? 'Joueur',
                                  );
                                  Navigator.push(
                                    context,
                                    MaterialPageRoute(
                                      builder:
                                          (_) => LoungeRoomScreen(
                                            loungeId: lounges[index].id,
                                            playerId: playerId,
                                          ),
                                    ),
                                  );
                                },
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
      floatingActionButton: FloatingActionButton.extended(
        icon: const Icon(Icons.add),
        label: const Text("Créer un Salon"),
        onPressed: () {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (_) => CreateLoungeScreen(playerId: playerId),
            ),
          );
        },
      ),
    );
  }
}

class CreateLoungeScreen extends StatefulWidget {
  final String playerId;
  CreateLoungeScreen({required this.playerId});
  @override
  _CreateLoungeScreenState createState() => _CreateLoungeScreenState();
}

class _CreateLoungeScreenState extends State<CreateLoungeScreen> {
  final _nameCtrl = TextEditingController();
  final _themeCtrl = TextEditingController();
  final _descCtrl = TextEditingController();
  double _maxPlayers = 10;
  bool _isPrivate = false;
  bool _isLoading = false;

  @override
  void dispose() {
    _nameCtrl.dispose();
    _themeCtrl.dispose();
    _descCtrl.dispose();
    super.dispose();
  }

  void _createLounge() async {
    if (_nameCtrl.text.trim().isEmpty) return;

    final ps = Provider.of<PlayerState>(context, listen: false);
    if (!ps.isPremium) {
      bool success = await ps.spendCoins(5); // Le salon coÃ»te 5 piÃ¨ces
      if (!success) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              "Vous avez besoin de 5 piÃ¨ces pour crÃ©er un salon.",
            ),
          ),
        );
        return;
      }
    }

    setState(() => _isLoading = true);

    Map<String, dynamic> loungeData = {
      'name': _nameCtrl.text.trim(),
      'theme':
          _themeCtrl.text.trim().isNotEmpty
              ? _themeCtrl.text.trim()
              : 'GÃ©nÃ©ral',
      'description': _descCtrl.text.trim(),
      'maxPlayers': _maxPlayers.toInt(),
      'isPrivate': _isPrivate,
      'hostId': widget.playerId,
      'players': {
        widget.playerId: {
          'name': ps.userName ?? 'HÃ´te',
          'joinedAt': FieldValue.serverTimestamp(),
        },
      },
    };

    String loungeId = await FirebaseService().createLounge(loungeData);

    // Débloquer le badge hôte de salon
    ps.recordBadgeEvent('social_lounge_host');

    setState(() => _isLoading = false);
    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder:
            (_) =>
                LoungeRoomScreen(loungeId: loungeId, playerId: widget.playerId),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text("CrÃ©er un Salon")),
      body:
          _isLoading
              ? Center(child: CircularProgressIndicator())
              : SingleChildScrollView(
                padding: EdgeInsets.all(16),
                child: Column(
                  children: [
                    TextField(
                      controller: _nameCtrl,
                      decoration: InputDecoration(labelText: "Nom du salon"),
                    ),
                    SizedBox(height: 10),
                    TextField(
                      controller: _themeCtrl,
                      decoration: InputDecoration(
                        labelText: "ThÃ¨me (ex: Fun, Tryhard, Chill)",
                      ),
                    ),
                    SizedBox(height: 10),
                    TextField(
                      controller: _descCtrl,
                      decoration: InputDecoration(labelText: "Description"),
                      maxLines: 3,
                    ),
                    SizedBox(height: 20),
                    Text(
                      "Nombre max de joueurs : ${_maxPlayers.toInt()}",
                      style: Theme.of(context).textTheme.titleLarge,
                    ),
                    Slider(
                      value: _maxPlayers,
                      min: 2,
                      max: 20,
                      divisions: 18,
                      onChanged: (v) => setState(() => _maxPlayers = v),
                    ),
                    SwitchListTile.adaptive(
                      title: Text("Salon PrivÃ©"),
                      subtitle: Text(
                        "N'apparaÃ®tra pas dans la liste publique.",
                      ),
                      value: _isPrivate,
                      onChanged: (v) => setState(() => _isPrivate = v),
                    ),
                    SizedBox(height: 30),
                    ElevatedButton(
                      onPressed: _createLounge,
                      child: Text("CrÃ©er le Salon (CoÃ»t: 5 piÃ¨ces)"),
                      style: ElevatedButton.styleFrom(
                        minimumSize: Size(double.infinity, 50),
                      ),
                    ),
                  ],
                ),
              ),
    );
  }
}

class LoungeRoomScreen extends StatefulWidget {
  final String loungeId;
  final String playerId;
  LoungeRoomScreen({required this.loungeId, required this.playerId});
  @override
  _LoungeRoomScreenState createState() => _LoungeRoomScreenState();
}

class _LoungeRoomScreenState extends State<LoungeRoomScreen> {
  final _chatCtrl = TextEditingController();
  final FirebaseService _firebaseService = FirebaseService();
  bool _isNavigating = false;
  Timer? _heartbeatTimer;

  @override
  void initState() {
    super.initState();
    _sendHeartbeat();
    _heartbeatTimer = Timer.periodic(
      Duration(seconds: 15),
      (_) => _sendHeartbeat(),
    );
  }

  void _sendHeartbeat() {
    _firebaseService.updateLoungeHeartbeat(widget.loungeId, widget.playerId);
  }

  @override
  void dispose() {
    _heartbeatTimer?.cancel();
    _chatCtrl.dispose();
    super.dispose();
  }

  void _sendMessage() {
    final ps = Provider.of<PlayerState>(context, listen: false);
    if (_chatCtrl.text.trim().isNotEmpty) {
      _firebaseService.sendLoungeMessage(
        widget.loungeId,
        widget.playerId,
        ps.userName ?? 'Joueur',
        _chatCtrl.text.trim(),
      );
      _chatCtrl.clear();
    }
  }

  void _openGameLauncher(Map<String, dynamic> currentPlayers) {
    showModalBottomSheet(
      context: context,
      builder:
          (ctx) => Container(
            height: 400,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.all(16.0),
                  child: Text(
                    "Lancer un jeu pour le salon",
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                ),
                Expanded(
                  child: ListView.builder(
                    itemCount:
                        allAppGames
                            .where((g) => g['modes'].contains('multi'))
                            .length,
                    itemBuilder: (context, index) {
                      final game =
                          allAppGames
                              .where((g) => g['modes'].contains('multi'))
                              .toList()[index];
                      return ListTile(
                        leading: Icon(game['icon'], color: Colors.cyanAccent),
                        title: Text(game['name']),
                        onTap: () {
                          Navigator.pop(ctx);
                          final ps = Provider.of<PlayerState>(
                            context,
                            listen: false,
                          );
                          Navigator.push(
                            context,
                            MaterialPageRoute(
                              builder:
                                  (_) => CreateGameScreen(
                                    playerName: ps.userName ?? "HÃ´te",
                                    playerId: widget.playerId,
                                    initialGame: game['name'],
                                    loungeId: widget.loungeId,
                                    loungePlayers: currentPlayers,
                                  ),
                            ),
                          );
                        },
                      );
                    },
                  ),
                ),
              ],
            ),
          ),
    );
  }

  Future<void> _replayGame(
    String oldGameCode,
    Map<String, dynamic> currentPlayers,
  ) async {
    final ps = Provider.of<PlayerState>(context, listen: false);
    final doc =
        await FirebaseFirestore.instance
            .collection('games')
            .doc(oldGameCode)
            .get();
    if (!doc.exists) return;

    final data = doc.data() as Map<String, dynamic>;
    String newGameCode = randomNumeric(6);

    Map<String, dynamic> hostOnly = {
      widget.playerId: {'name': ps.userName ?? 'HÃ´te', 'score': 0},
    };

    await _firebaseService.createGameWithAllPlayers(
      gameCode: newGameCode,
      hostId: widget.playerId,
      allPlayers: hostOnly,
      gameType: data['gameType'] ?? 'Gribouillis',
      difficulty: data['difficulty'] ?? 'N/A',
      playerCount: currentPlayers.length,
      isPremiumLobby: data['isPremiumLobby'] ?? false,
      videoEnabled: data['videoEnabled'] ?? false,
      audioEnabled: data['audioEnabled'] ?? false,
      aiWords:
          data['aiWords'] != null ? List<String>.from(data['aiWords']) : null,
      cadavreVariant: data['cadavreVariant'],
      cadavrePassingMode: data['cadavrePassingMode'],
      scope: data['scope'],
      dobbleSymbolsPerCard: data['dobbleSymbolsPerCard'] ?? false,
      isSimplifiedLiar: data['isSimplifiedLiar'] ?? false,
      liarVoteMode: data['liarVoteMode'] ?? 'simultaneous',
      petitBacCategories:
          data['petitBacCategories'] != null
              ? List<String>.from(data['petitBacCategories'])
              : null,
      petitBacTime: data['petitBacTime'],
      presidentRevolution: data['presidentRevolution'] ?? false,
      pictionaryOnly30Strokes: data['pictionaryOnly30Strokes'] ?? false,
      pictionaryUseTeams: data['pictionaryUseTeams'],
      justOneAllowInvalidClues: data['justOneAllowInvalidClues'] ?? false,
      selectedLoupGarouRoles:
          data['selectedLoupGarouRoles'] != null
              ? Map<String, int>.from(data['selectedLoupGarouRoles'])
              : null,
      unoStartingCards: data['unoStartingCards'],
      unoStackDraws: data['unoStackDraws'],
      zeroPointeTargetScore: data['zeroPointeTargetScore'],
      pokerStartChips: data['pokerStartChips'],
      pokerSmallBlind: data['pokerSmallBlind'],
      pokerBigBlind: data['pokerBigBlind'],
      hotPotatoUseGlobalTimer: data['hotPotatoUseGlobalTimer'],
      hotPotatoGlobalDuration: data['hotPotatoGlobalDuration'],
      gribouillisMode: data['gribouillisMode'],
      gribouillisAjouter1: data['gribouillisAjouter1'],
      photoRouletteRounds: data['photoRouletteRounds'],
      photoRoulettePhotosPerPlayer: data['photoRoulettePhotosPerPlayer'],
      photoRouletteMediaType: data['photoRouletteMediaType'],
      photoRouletteTime: data['photoRouletteTime'],
      undercoverRoleSettings:
          data['undercoverRoleSettings'] != null
              ? Map<String, bool>.from(data['undercoverRoleSettings'])
              : null,
      infiltreCount: data['infiltreCount'],
      mrWhiteCount: data['mrWhiteCount'],
      aiInstructions: data['aiInstructions'],
      turnTimerSeconds: data['turnTimerSeconds'],
      resultTimerSeconds: data['resultTimerSeconds'],
      petitsChevauxTeamMode: data['petitsChevauxTeamMode'] ?? false,
      timesUpTotalRounds: data['timesUpTotalRounds'],
      dominoesMode: data['dominoesMode'],
      dominoesTargetScore: data['dominoesTargetScore'],
    );

    await FirebaseFirestore.instance
        .collection('games')
        .doc(newGameCode)
        .update({'loungeId': widget.loungeId});

    await FirebaseFirestore.instance
        .collection('lounges')
        .doc(widget.loungeId)
        .update({
          'pendingGame': {
            'gameCode': newGameCode,
            'gameName': data['gameType'] ?? 'Gribouillis',
            'hostId': widget.playerId,
            'status': 'waiting',
            'joinedPlayers': [widget.playerId],
          },
        });

    await _firebaseService.sendLoungeMessage(
      widget.loungeId,
      widget.playerId,
      ps.userName ?? 'HÃ´te',
      "J'ai lancÃ© une partie de ${data['gameType'] ?? 'Gribouillis'} !",
      type: 'game_invite',
      extraData: {
        'gameCode': newGameCode,
        'gameName': data['gameType'] ?? 'Gribouillis',
        'hostId': widget.playerId,
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<DocumentSnapshot>(
      stream:
          FirebaseFirestore.instance
              .collection('lounges')
              .doc(widget.loungeId)
              .snapshots(),
      builder: (context, snapshot) {
        if (!snapshot.hasData || !snapshot.data!.exists) {
          return Scaffold(
            body: Center(child: Text("Ce salon a Ã©tÃ© fermÃ©.")),
          );
        }
        final data = snapshot.data!.data() as Map<String, dynamic>;
        final players = data['players'] as Map<String, dynamic>? ?? {};
        final isHost = data['hostId'] == widget.playerId;
        final pendingGame = data['pendingGame'];

        bool isHostOfPendingGame =
            pendingGame != null &&
            pendingGame['hostId'] == widget.playerId &&
            pendingGame['status'] == 'waiting';

        if (pendingGame != null &&
            pendingGame['status'] == 'started' &&
            !_isNavigating) {
          List<dynamic> joinedPlayers = pendingGame['joinedPlayers'] ?? [];
          if (joinedPlayers.contains(widget.playerId)) {
            _isNavigating = true;
            WidgetsBinding.instance.addPostFrameCallback((_) {
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder:
                      (_) => MultiplayerGameScreen(
                        gameCode: pendingGame['gameCode'],
                        playerId: widget.playerId,
                        loungeId: widget.loungeId,
                      ),
                ),
              ).then((_) async {
                _isNavigating = false;
                // Nettoyer localement la présence dans le pendingGame à la sortie du jeu
                await FirebaseFirestore.instance
                    .collection('lounges')
                    .doc(widget.loungeId)
                    .update({
                      'pendingGame.joinedPlayers': FieldValue.arrayRemove([
                        widget.playerId,
                      ]),
                    });
              });
            });
          }
        }

        List<dynamic> streamers = data['streamers'] ?? [];

        return PopScope(
          canPop: !isHostOfPendingGame,
          onPopInvokedWithResult: (didPop, result) async {
            if (didPop) {
              await _firebaseService.leaveLounge(
                widget.loungeId,
                widget.playerId,
              );
              return;
            }
            if (isHostOfPendingGame) {
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(
                  content: Text(
                    "Veuillez commencer ou annuler la partie avant de quitter le salon.",
                  ),
                ),
              );
            }
          },
          child: Scaffold(
            appBar: AppBar(title: Text("Salon")),
            body: Column(
              children: [
                // Info du salon
                Container(
                  color: Colors.deepPurple[900],
                  padding: EdgeInsets.all(12),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Text(
                        data['name'] ?? 'Salon',
                        style: TextStyle(
                          fontWeight: FontWeight.bold,
                          fontSize: 18,
                        ),
                      ),
                      if (data['isPrivate'] == true)
                        SelectableText(
                          "Code: ${widget.loungeId.substring(0, 6)}",
                          style: TextStyle(color: Colors.amber),
                        ),
                    ],
                  ),
                ),
                // PrÃ©sences en ligne
                StreamBuilder<QuerySnapshot>(
                  stream:
                      FirebaseFirestore.instance
                          .collection('lounges')
                          .doc(widget.loungeId)
                          .collection('presences')
                          .snapshots(),
                  builder: (context, presenceSnap) {
                    if (!presenceSnap.hasData) return SizedBox(height: 60);
                    final now = DateTime.now();
                    List<String> onlineIds = [];
                    for (var doc in presenceSnap.data!.docs) {
                      final pData = doc.data() as Map<String, dynamic>;
                      final ts = pData['lastHeartbeat'] as Timestamp?;
                      if (ts != null &&
                          now.difference(ts.toDate()).inSeconds < 30) {
                        onlineIds.add(doc.id);
                      }
                    }
                    return Container(
                      height: 65,
                      padding: EdgeInsets.symmetric(vertical: 8),
                      child: ListView(
                        scrollDirection: Axis.horizontal,
                        children:
                            onlineIds.map((id) {
                              String name = players[id]?['name'] ?? 'Joueur';
                              return GestureDetector(
                                onTap: () {
                                  showUserProfileDialog(
                                    context,
                                    targetUid: id,
                                    currentUserId: widget.playerId,
                                  );
                                },
                                child: Padding(
                                  padding: const EdgeInsets.symmetric(
                                    horizontal: 8.0,
                                  ),
                                  child: Column(
                                    children: [
                                      Stack(
                                        children: [
                                          CircleAvatar(
                                            radius: 16,
                                            child: Text(
                                              name.isNotEmpty
                                                  ? name[0].toUpperCase()
                                                  : '?',
                                            ),
                                          ),
                                          Positioned(
                                            right: 0,
                                            bottom: 0,
                                            child: Container(
                                              width: 12,
                                              height: 12,
                                              decoration: BoxDecoration(
                                                color: Colors.green,
                                                shape: BoxShape.circle,
                                                border: Border.all(
                                                  color: Colors.black,
                                                ),
                                              ),
                                            ),
                                          ),
                                        ],
                                      ),
                                      Text(
                                        name,
                                        style: TextStyle(fontSize: 10),
                                        overflow: TextOverflow.ellipsis,
                                      ),
                                    ],
                                  ),
                                ),
                              );
                            }).toList(),
                      ),
                    );
                  },
                ),
                // Boutons d'action du salon
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 16.0),
                  child: Row(
                    children: [
                      Expanded(
                        child: ElevatedButton.icon(
                          icon: Icon(Icons.videocam),
                          label: Text(
                            streamers.isEmpty
                                ? "Lancer un Stream"
                                : "Rejoindre le Stream (${streamers.length})",
                          ),
                          style: ElevatedButton.styleFrom(
                            backgroundColor: Colors.blueAccent,
                          ),
                          onPressed: () {
                            Navigator.push(
                              context,
                              MaterialPageRoute(
                                builder:
                                    (_) => LoungeStreamingScreen(
                                      loungeId: widget.loungeId,
                                      playerId: widget.playerId,
                                    ),
                              ),
                            );
                          },
                        ),
                      ),
                      if (isHost && pendingGame == null) ...[
                        SizedBox(width: 10),
                        ElevatedButton(
                          onPressed: () => _openGameLauncher(players),
                          child: Icon(Icons.videogame_asset),
                          style: ElevatedButton.styleFrom(
                            backgroundColor: Colors.green,
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
                Divider(),
                // Liste de messages de chat avec logique game_invite et game_result
                Expanded(
                  child: StreamBuilder<QuerySnapshot>(
                    stream: _firebaseService.getLoungeChatStream(
                      widget.loungeId,
                    ),
                    builder: (context, chatSnap) {
                      if (!chatSnap.hasData) return SizedBox.shrink();
                      final messages = chatSnap.data!.docs;
                      return ListView.builder(
                        reverse: true,
                        itemCount: messages.length,
                        itemBuilder: (context, index) {
                          var msg =
                              messages[index].data() as Map<String, dynamic>;

                          if (msg['type'] == 'game_invite' ||
                              (msg['text'] != null &&
                                  msg['text'].toString().contains(
                                    "J'ai lancÃ© une partie",
                                  ))) {
                            String gameCode =
                                msg['extraData']?['gameCode'] ??
                                (pendingGame != null
                                    ? pendingGame['gameCode'] ?? ''
                                    : '');
                            String gameName =
                                msg['extraData']?['gameName'] ??
                                (pendingGame != null
                                    ? pendingGame['gameName'] ?? ''
                                    : '');
                            String hostId =
                                msg['extraData']?['hostId'] ??
                                (pendingGame != null
                                    ? pendingGame['hostId'] ?? ''
                                    : '');

                            bool isGameFinished =
                                (pendingGame == null ||
                                    pendingGame['gameCode'] != gameCode);
                            bool isGameHost = hostId == widget.playerId;
                            List<dynamic> joinedPlayers =
                                pendingGame != null
                                    ? (pendingGame['joinedPlayers'] ?? [])
                                    : [];
                            bool hasJoined = joinedPlayers.contains(
                              widget.playerId,
                            );
                            bool isStarted =
                                pendingGame != null &&
                                pendingGame['status'] == 'started';

                            return Container(
                              margin: EdgeInsets.symmetric(
                                vertical: 8,
                                horizontal: 16,
                              ),
                              padding: EdgeInsets.all(12),
                              decoration: BoxDecoration(
                                color: Colors.deepPurple[800],
                                borderRadius: BorderRadius.circular(12),
                              ),
                              child: Column(
                                children: [
                                  Text(
                                    "${msg['senderName']} a crÃ©Ã© une partie de $gameName !",
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                      fontSize: 16,
                                    ),
                                  ),
                                  SizedBox(height: 10),
                                  Text(
                                    "${joinedPlayers.length} joueur(s) prÃªts",
                                  ),
                                  SizedBox(height: 10),
                                  if (isGameFinished)
                                    Padding(
                                      padding: const EdgeInsets.only(top: 8.0),
                                      child: Text(
                                        "Cette partie est terminÃ©e ou annulÃ©e.",
                                        style: TextStyle(
                                          fontStyle: FontStyle.italic,
                                          color: Colors.grey,
                                        ),
                                      ),
                                    ),
                                  if (!isGameFinished && isStarted)
                                    Padding(
                                      padding: const EdgeInsets.only(top: 8.0),
                                      child: Container(
                                        padding: EdgeInsets.symmetric(
                                          horizontal: 16,
                                          vertical: 8,
                                        ),
                                        decoration: BoxDecoration(
                                          color: Colors.green,
                                          borderRadius: BorderRadius.circular(
                                            20,
                                          ),
                                        ),
                                        child: Text(
                                          "EN PARTIE",
                                          style: TextStyle(
                                            color: Colors.white,
                                            fontWeight: FontWeight.bold,
                                          ),
                                        ),
                                      ),
                                    ),
                                  if (!isGameFinished &&
                                      !isStarted &&
                                      isGameHost)
                                    Row(
                                      mainAxisAlignment:
                                          MainAxisAlignment.spaceEvenly,
                                      children: [
                                        ElevatedButton(
                                          style: ElevatedButton.styleFrom(
                                            backgroundColor: Colors.red,
                                          ),
                                          onPressed: () async {
                                            await FirebaseFirestore.instance
                                                .collection('games')
                                                .doc(gameCode)
                                                .delete();
                                            await FirebaseFirestore.instance
                                                .collection('lounges')
                                                .doc(widget.loungeId)
                                                .update({
                                                  'pendingGame':
                                                      FieldValue.delete(),
                                                });
                                          },
                                          child: Text("Annuler"),
                                        ),
                                        ElevatedButton(
                                          style: ElevatedButton.styleFrom(
                                            backgroundColor: Colors.green,
                                          ),
                                          onPressed: () async {
                                            await FirebaseFirestore.instance
                                                .collection('lounges')
                                                .doc(widget.loungeId)
                                                .update({
                                                  'pendingGame.status':
                                                      'started',
                                                });
                                            await _firebaseService.startGame(
                                              gameCode,
                                            );
                                          },
                                          child: Text("Commencer"),
                                        ),
                                      ],
                                    ),
                                  if (!isGameFinished &&
                                      !isStarted &&
                                      !isGameHost)
                                    ElevatedButton(
                                      onPressed:
                                          hasJoined
                                              ? null
                                              : () async {
                                                final ps =
                                                    Provider.of<PlayerState>(
                                                      context,
                                                      listen: false,
                                                    );
                                                await FirebaseFirestore.instance
                                                    .collection('lounges')
                                                    .doc(widget.loungeId)
                                                    .update({
                                                      'pendingGame.joinedPlayers':
                                                          FieldValue.arrayUnion(
                                                            [widget.playerId],
                                                          ),
                                                    });
                                                await _firebaseService.joinGame(
                                                  gameCode,
                                                  ps.userName ?? 'Joueur',
                                                  widget.playerId,
                                                );
                                              },
                                      child: Text(
                                        hasJoined
                                            ? "En attente du lancement..."
                                            : "Rejoindre",
                                      ),
                                    ),
                                ],
                              ),
                            );
                          } else if (msg['type'] == 'game_result') {
                            return Container(
                              margin: EdgeInsets.symmetric(
                                vertical: 8,
                                horizontal: 16,
                              ),
                              padding: EdgeInsets.all(12),
                              decoration: BoxDecoration(
                                color: Colors.amber[900],
                                borderRadius: BorderRadius.circular(12),
                              ),
                              child: Column(
                                children: [
                                  Text(
                                    "Partie de ${msg['extraData']['gameName']} terminÃ©e !",
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                      fontSize: 16,
                                    ),
                                  ),
                                  SizedBox(height: 8),
                                  Row(
                                    mainAxisAlignment: MainAxisAlignment.center,
                                    children: [
                                      ElevatedButton(
                                        onPressed: () {
                                          showDialog(
                                            context: context,
                                            builder:
                                                (_) => AlertDialog(
                                                  title: Text(
                                                    "Statistiques - ${msg['extraData']['gameName']}",
                                                  ),
                                                  content: Text(
                                                    "Vainqueur : ${msg['extraData']['winnerName'] ?? 'Inconnu'}\n${msg['extraData']['reason'] ?? ''}",
                                                  ),
                                                  actions: [
                                                    TextButton(
                                                      onPressed:
                                                          () => Navigator.pop(
                                                            context,
                                                          ),
                                                      child: Text("Fermer"),
                                                    ),
                                                  ],
                                                ),
                                          );
                                        },
                                        child: Text("Voir les stats"),
                                      ),
                                      if (isHost &&
                                          msg['extraData']['oldGameCode'] !=
                                              null) ...[
                                        SizedBox(width: 10),
                                        ElevatedButton.icon(
                                          icon: Icon(Icons.refresh),
                                          label: Text("Relancer"),
                                          style: ElevatedButton.styleFrom(
                                            backgroundColor: Colors.green,
                                          ),
                                          onPressed: () {
                                            _replayGame(
                                              msg['extraData']['oldGameCode'],
                                              players,
                                            );
                                          },
                                        ),
                                      ],
                                    ],
                                  ),
                                ],
                              ),
                            );
                          }

                          bool isMe = msg['senderId'] == widget.playerId;
                          return Align(
                            alignment:
                                isMe
                                    ? Alignment.centerRight
                                    : Alignment.centerLeft,
                            child: Container(
                              margin: EdgeInsets.symmetric(
                                vertical: 4,
                                horizontal: 8,
                              ),
                              padding: EdgeInsets.all(10),
                              decoration: BoxDecoration(
                                color:
                                    isMe
                                        ? Colors.blueAccent[700]
                                        : Colors.grey[800],
                                borderRadius: BorderRadius.circular(12),
                              ),
                              child: Column(
                                crossAxisAlignment:
                                    isMe
                                        ? CrossAxisAlignment.end
                                        : CrossAxisAlignment.start,
                                children: [
                                  GestureDetector(
                                    onTap: () {
                                      if (msg['senderId'] != null) {
                                        showUserProfileDialog(
                                          context,
                                          targetUid: msg['senderId'],
                                          currentUserId: widget.playerId,
                                        );
                                      }
                                    },
                                    child: Text(
                                      isMe
                                          ? "Moi"
                                          : (msg['senderName'] ?? 'Joueur'),
                                      style: const TextStyle(
                                        fontSize: 10,
                                        color: Colors.white70,
                                        decoration: TextDecoration.underline,
                                      ),
                                    ),
                                  ),
                                  Text(
                                    msg['text'],
                                    style: TextStyle(fontSize: 16),
                                  ),
                                ],
                              ),
                            ),
                          );
                        },
                      );
                    },
                  ),
                ),
                Container(
                  padding: EdgeInsets.symmetric(horizontal: 8, vertical: 8),
                  color: Colors.black26,
                  child: Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: _chatCtrl,
                          decoration: InputDecoration(
                            hintText: "Message...",
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(20),
                            ),
                            contentPadding: EdgeInsets.symmetric(
                              horizontal: 16,
                            ),
                          ),
                          onSubmitted: (_) => _sendMessage(),
                        ),
                      ),
                      IconButton(
                        icon: Icon(Icons.send, color: Colors.deepPurpleAccent),
                        onPressed: _sendMessage,
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

class LoungeStreamingScreen extends StatefulWidget {
  final String loungeId;
  final String playerId;
  LoungeStreamingScreen({required this.loungeId, required this.playerId});

  @override
  _LoungeStreamingScreenState createState() => _LoungeStreamingScreenState();
}

class _LoungeStreamingScreenState extends State<LoungeStreamingScreen> {
  late LivekitService _livekitService;
  bool _joined = false;
  final PageController _pageController = PageController();

  @override
  void initState() {
    super.initState();
    _livekitService = Provider.of<LivekitService>(context, listen: false);
    _initStream();
  }

  Future<void> _initStream() async {
    await _livekitService.initialize();
    await _livekitService.joinChannel(
      widget.loungeId,
      identity: widget.playerId,
      videoEnabled: true, // Force l'activation de la vidÃ©o pour le stream
      audioEnabled: true, // Force l'activation de l'audio pour le stream
    );
    await FirebaseService().joinLoungeStream(widget.loungeId, widget.playerId);
    if (mounted) {
      setState(() => _joined = true);
      Provider.of<PlayerState>(
        context,
        listen: false,
      ).recordBadgeEvent('social_stream_join');
    }
  }

  @override
  void dispose() {
    _pageController.dispose();
    _livekitService.leaveChannel();
    FirebaseService().leaveLoungeStream(widget.loungeId, widget.playerId);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      body: SafeArea(
        child: Stack(
          children: [
            if (_joined)
              Consumer<LivekitService>(
                builder: (context, livekit, _) {
                  List<String> participants = [livekit.localIdentity];
                  participants.addAll(livekit.remoteUsers.keys);

                  int itemsPerPage = 8;
                  int pages = (participants.length / itemsPerPage).ceil();
                  if (pages == 0) pages = 1;

                  return Stack(
                    children: [
                      PageView.builder(
                        controller: _pageController,
                        itemCount: pages,
                        itemBuilder: (ctx, pageIndex) {
                          var pageParticipants =
                              participants
                                  .skip(pageIndex * itemsPerPage)
                                  .take(itemsPerPage)
                                  .toList();
                          return GridView.builder(
                            physics: NeverScrollableScrollPhysics(),
                            gridDelegate:
                                SliverGridDelegateWithFixedCrossAxisCount(
                                  crossAxisCount:
                                      pageParticipants.length <= 2 ? 1 : 2,
                                  childAspectRatio:
                                      pageParticipants.length <= 2 ? 1.5 : 1.0,
                                ),
                            itemCount: pageParticipants.length,
                            itemBuilder: (ctx, idx) {
                              String identity = pageParticipants[idx];
                              bool isLocal = identity == livekit.localIdentity;

                              VideoTrack? videoTrack = livekit.getVideoTrack(
                                identity,
                              );

                              return Container(
                                margin: EdgeInsets.all(4),
                                decoration: BoxDecoration(
                                  color: Colors.grey[900],
                                  borderRadius: BorderRadius.circular(12),
                                ),
                                child: ClipRRect(
                                  borderRadius: BorderRadius.circular(12),
                                  child:
                                      videoTrack != null
                                          ? VideoTrackRenderer(videoTrack)
                                          : Center(
                                            child: Icon(
                                              Icons.person,
                                              color: Colors.white54,
                                              size: 50,
                                            ),
                                          ),
                                ),
                              );
                            },
                          );
                        },
                      ),
                      if (pages > 1) ...[
                        Positioned(
                          left: 5,
                          top: 0,
                          bottom: 0,
                          child: Center(
                            child: IconButton(
                              icon: Icon(
                                Icons.arrow_back_ios,
                                color: Colors.white54,
                                size: 30,
                              ),
                              onPressed:
                                  () => _pageController.previousPage(
                                    duration: Duration(milliseconds: 300),
                                    curve: Curves.easeInOut,
                                  ),
                            ),
                          ),
                        ),
                        Positioned(
                          right: 5,
                          top: 0,
                          bottom: 0,
                          child: Center(
                            child: IconButton(
                              icon: Icon(
                                Icons.arrow_forward_ios,
                                color: Colors.white54,
                                size: 30,
                              ),
                              onPressed:
                                  () => _pageController.nextPage(
                                    duration: Duration(milliseconds: 300),
                                    curve: Curves.easeInOut,
                                  ),
                            ),
                          ),
                        ),
                      ],
                    ],
                  );
                },
              ),
            Positioned(
              top: 10,
              right: 10,
              child: IconButton(
                icon: Icon(Icons.close, color: Colors.white, size: 30),
                onPressed: () => Navigator.pop(context),
              ),
            ),
            Positioned(
              bottom: 80,
              right: 10,
              width: 220,
              height: 250,
              child: IgnorePointer(
                child: LoungeFloatingChatOverlay(loungeId: widget.loungeId),
              ),
            ),
            Positioned(
              bottom: 20,
              left: 0,
              right: 0,
              child: Consumer<LivekitService>(
                builder: (context, livekit, _) {
                  return Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      FloatingActionButton(
                        heroTag: "mic_stream",
                        backgroundColor:
                            livekit.isLocalMuted
                                ? Colors.red
                                : Colors.grey[800],
                        child: Icon(
                          livekit.isLocalMuted ? Icons.mic_off : Icons.mic,
                          color: Colors.white,
                        ),
                        onPressed: () => livekit.toggleLocalAudio(),
                      ),
                      SizedBox(width: 20),
                      FloatingActionButton(
                        heroTag: "cam_stream",
                        backgroundColor:
                            livekit.isLocalVideoOff
                                ? Colors.red
                                : Colors.grey[800],
                        child: Icon(
                          livekit.isLocalVideoOff
                              ? Icons.videocam_off
                              : Icons.videocam,
                          color: Colors.white,
                        ),
                        onPressed: () => livekit.toggleLocalVideo(),
                      ),
                    ],
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class LoungeFloatingChatOverlay extends StatelessWidget {
  final String loungeId;
  const LoungeFloatingChatOverlay({Key? key, required this.loungeId})
    : super(key: key);

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot>(
      stream:
          FirebaseFirestore.instance
              .collection('lounges')
              .doc(loungeId)
              .collection('chat')
              .orderBy('timestamp', descending: true)
              .limit(6)
              .snapshots(),
      builder: (context, snapshot) {
        if (!snapshot.hasData) return SizedBox.shrink();
        final messages = snapshot.data!.docs;

        return ListView.builder(
          reverse: true,
          itemCount: messages.length,
          itemBuilder: (context, index) {
            final data = messages[index].data() as Map<String, dynamic>;
            if (data['type'] != null && data['type'] != 'text')
              return SizedBox.shrink();

            return Padding(
              padding: const EdgeInsets.symmetric(vertical: 4.0),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Text(
                    data['senderName'],
                    style: TextStyle(
                      color: Colors.amber,
                      fontWeight: FontWeight.bold,
                      fontSize: 13,
                      shadows: [Shadow(color: Colors.black, blurRadius: 4)],
                    ),
                  ),
                  Text(
                    data['text'] ?? '',
                    textAlign: TextAlign.right,
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 14,
                      shadows: [Shadow(color: Colors.black, blurRadius: 4)],
                    ),
                  ),
                ],
              ),
            );
          },
        );
      },
    );
  }
}

// =============================================================================
// 🎴 WIDGET DE CARTE ZÉRO POINTÉ / SKYJO (CODE COULEUR OFFICIEL)
// =============================================================================
class _ZeroPointeCardWidget extends StatelessWidget {
  final int value;
  final bool isRevealed;
  final bool isSelected;
  final double scale;

  const _ZeroPointeCardWidget({
    Key? key,
    required this.value,
    required this.isRevealed,
    this.isSelected = false,
    this.scale = 1.0,
  }) : super(key: key);

  @override
  Widget build(BuildContext context) {
    // DOS DE CARTE (FACE CACHÉE)
    if (!isRevealed) {
      return AnimatedContainer(
        duration: const Duration(milliseconds: 200),
        decoration: BoxDecoration(
          gradient: const LinearGradient(
            colors: [Color(0xFF2E1065), Color(0xFF1E1B4B), Color(0xFF0F172A)],
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
          ),
          borderRadius: BorderRadius.circular(10 * scale),
          border: Border.all(
            color: isSelected ? Colors.amberAccent : Colors.white24,
            width: isSelected ? 2.5 : 1.2,
          ),
          boxShadow: [
            BoxShadow(
              color:
                  isSelected
                      ? Colors.amberAccent.withOpacity(0.4)
                      : Colors.black45,
              blurRadius: isSelected ? 8 : 4,
              offset: const Offset(1, 2),
            ),
          ],
        ),
        child: Center(
          child: Container(
            width: 32 * scale,
            height: 32 * scale,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              border: Border.all(
                color: Colors.white.withOpacity(0.3),
                width: 1.5,
              ),
            ),
            child: Center(
              child: Text(
                "0",
                style: TextStyle(
                  fontSize: 16 * scale,
                  fontWeight: FontWeight.w900,
                  color: Colors.white.withOpacity(0.5),
                ),
              ),
            ),
          ),
        ),
      );
    }

    // FACE VISIBLE : COULEURS PAR TRANCHE SKYJO
    final _SkyjoCardTheme theme = _getSkyjoCardTheme(value);

    return AnimatedContainer(
      duration: const Duration(milliseconds: 200),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: theme.gradient,
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
        ),
        borderRadius: BorderRadius.circular(10 * scale),
        border: Border.all(
          color: isSelected ? Colors.white : theme.borderColor,
          width: isSelected ? 2.5 : 1.5,
        ),
        boxShadow: [
          BoxShadow(
            color:
                isSelected ? Colors.white.withOpacity(0.5) : theme.shadowColor,
            blurRadius: isSelected ? 10 : 4,
            offset: const Offset(1, 2),
          ),
        ],
      ),
      child: Stack(
        children: [
          // Valeur centrale imposante
          Center(
            child: Text(
              "$value",
              style: TextStyle(
                fontSize: 28 * scale,
                fontWeight: FontWeight.w900,
                color: theme.textColor,
                shadows: [
                  Shadow(
                    color: Colors.black.withOpacity(0.3),
                    blurRadius: 3,
                    offset: const Offset(1, 1),
                  ),
                ],
              ),
            ),
          ),

          // Mini-chiffre en haut à gauche
          Positioned(
            top: 4 * scale,
            left: 5 * scale,
            child: Text(
              "$value",
              style: TextStyle(
                fontSize: 11 * scale,
                fontWeight: FontWeight.w900,
                color: theme.textColor.withOpacity(0.85),
              ),
            ),
          ),

          // Mini-chiffre inversé en bas à droite
          Positioned(
            bottom: 4 * scale,
            right: 5 * scale,
            child: Transform.rotate(
              angle: pi,
              child: Text(
                "$value",
                style: TextStyle(
                  fontSize: 11 * scale,
                  fontWeight: FontWeight.w900,
                  color: theme.textColor.withOpacity(0.85),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  // Code couleur officiel par tranche de points
  _SkyjoCardTheme _getSkyjoCardTheme(int val) {
    if (val < 0) {
      // -2 et -1 : Bleu nuit / Violet (très avantageux)
      return _SkyjoCardTheme(
        gradient: const [
          Color(0xFF6B21A8),
          Color(0xFF4C1D95),
          Color(0xFF2E1065),
        ],
        borderColor: const Color(0xFFA855F7),
        textColor: Colors.white,
        shadowColor: const Color(0xFF6B21A8).withOpacity(0.4),
      );
    } else if (val == 0) {
      // 0 : Cyan / Turquoise
      return _SkyjoCardTheme(
        gradient: const [
          Color(0xFF06B6D4),
          Color(0xFF0891B2),
          Color(0xFF0E7490),
        ],
        borderColor: const Color(0xFF67E8F9),
        textColor: Colors.white,
        shadowColor: const Color(0xFF06B6D4).withOpacity(0.4),
      );
    } else if (val >= 1 && val <= 4) {
      // 1 à 4 : Vert franc
      return _SkyjoCardTheme(
        gradient: const [
          Color(0xFF10B981),
          Color(0xFF059669),
          Color(0xFF047857),
        ],
        borderColor: const Color(0xFF6EE7B7),
        textColor: Colors.white,
        shadowColor: const Color(0xFF10B981).withOpacity(0.4),
      );
    } else if (val >= 5 && val <= 8) {
      // 5 à 8 : Jaune / Orange chaud
      return _SkyjoCardTheme(
        gradient: const [
          Color(0xFFF59E0B),
          Color(0xFFD97706),
          Color(0xFFB45309),
        ],
        borderColor: const Color(0xFFFCD34D),
        textColor: Colors.white,
        shadowColor: const Color(0xFFF59E0B).withOpacity(0.4),
      );
    } else {
      // 9 à 12 : Rouge vif (danger)
      return _SkyjoCardTheme(
        gradient: const [
          Color(0xFFEF4444),
          Color(0xFFDC2626),
          Color(0xFF991B1B),
        ],
        borderColor: const Color(0xFFFCA5A5),
        textColor: Colors.white,
        shadowColor: const Color(0xFFEF4444).withOpacity(0.4),
      );
    }
  }
}

class _SkyjoCardTheme {
  final List<Color> gradient;
  final Color borderColor;
  final Color textColor;
  final Color shadowColor;

  const _SkyjoCardTheme({
    required this.gradient,
    required this.borderColor,
    required this.textColor,
    required this.shadowColor,
  });
}

