// 🧟 CARTE SURVIVANT OU CARTE ZOMBIE MENAÇANTE
// =============================================================================
class _ZombieSurvivorCardWidget extends StatelessWidget {
  final String card;

  const _ZombieSurvivorCardWidget({Key? key, required this.card})
    : super(key: key);

  @override
  Widget build(BuildContext context) {
    final bool isZombie = card == 'Zombie';

    // --- 1. CARTE ZOMBIE TOXIQUE ET MENAÇANTE ---
    if (isZombie) {
      return Container(
        width: 68,
        height: 104,
        margin: const EdgeInsets.symmetric(horizontal: 5),
        decoration: BoxDecoration(
          gradient: const LinearGradient(
            colors: [Color(0xFF881337), Color(0xFF4C0519), Color(0xFF1A0208)],
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
          ),
          borderRadius: BorderRadius.circular(12),
          border: Border.all(color: const Color(0xFFEF4444), width: 2.2),
          boxShadow: [
            BoxShadow(
              color: const Color(0xFFEF4444).withOpacity(0.55),
              blurRadius: 14,
              spreadRadius: 2,
            ),
          ],
        ),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(10),
          child: Stack(
            alignment: Alignment.center,
            children: [
              // Motif d'avertissement de danger
              Positioned(
                top: 4,
                child: Text(
                  "INFECTÉ",
                  style: TextStyle(
                    fontSize: 8,
                    fontWeight: FontWeight.w900,
                    color: Colors.redAccent.shade100,
                    letterSpacing: 1.5,
                  ),
                ),
              ),
              Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Container(
                    padding: const EdgeInsets.all(6),
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: Colors.red.withOpacity(0.2),
                    ),
                    child: const Icon(
                      Icons.coronavirus_rounded,
                      color: Color(0xFFEF4444),
                      size: 32,
                    ),
                  ),
                  const SizedBox(height: 4),
                  const Text(
                    "ZOMBIE",
                    style: TextStyle(
                      fontSize: 10,
                      fontWeight: FontWeight.w900,
                      color: Colors.white,
                      letterSpacing: 1.2,
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
      );
    }

    // --- 2. CARTE SURVIVANT STANDARD (RANG + COULEUR) ---
    final String rank = card.substring(0, card.length - 1);
    final String suit = card.substring(card.length - 1);
    final bool isRed = (suit == 'H' || suit == 'D');
    final Color suitColor =
        isRed ? const Color(0xFFE11D48) : const Color(0xFF0F172A);
    final String suitSymbol =
        {'H': '♥', 'D': '♦', 'C': '♣', 'S': '♠'}[suit] ?? '?';

    // Rôle ou équipement thématique par rang
    final String itemLabel = _getSurvivorEquipment(rank);

    return Container(
      width: 66,
      height: 102,
      margin: const EdgeInsets.symmetric(horizontal: 4),
      decoration: BoxDecoration(
        color: const Color(0xFFF8FAFC),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: const Color(0xFFCBD5E1), width: 1.2),
        boxShadow: const [
          BoxShadow(color: Colors.black38, blurRadius: 5, offset: Offset(1, 3)),
        ],
      ),
      child: Stack(
        children: [
          // Valeur et Symbole Coin Supérieur Gauche
          Positioned(
            top: 4,
            left: 5,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  rank,
                  style: TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w900,
                    color: suitColor,
                  ),
                ),
                Text(
                  suitSymbol,
                  style: TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.bold,
                    color: suitColor,
                  ),
                ),
              ],
            ),
          ),

          // Illustration centrale
          Center(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Icon(
                  _getSurvivorIcon(rank),
                  size: 24,
                  color: suitColor.withOpacity(0.85),
                ),
                const SizedBox(height: 2),
                Text(
                  itemLabel,
                  style: TextStyle(
                    fontSize: 7.5,
                    fontWeight: FontWeight.bold,
                    color: Colors.grey.shade700,
                  ),
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),

          // Valeur et Symbole Coin Inférieur Droit Inversé
          Positioned(
            bottom: 4,
            right: 5,
            child: Transform.rotate(
              angle: pi,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    rank,
                    style: TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w900,
                      color: suitColor,
                    ),
                  ),
                  Text(
                    suitSymbol,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.bold,
                      color: suitColor,
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }

  String _getSurvivorEquipment(String rank) {
    switch (rank) {
      case 'A':
        return "Lampe";
      case '2':
        return "Pied-de-biche";
      case '3':
        return "Trousse soin";
      case '4':
        return "Hache";
      case '5':
        return "Arbalète";
      case '6':
        return "Fusil";
      case '7':
        return "Talkie";
      case '8':
        return "Tronçonneuse";
      default:
        return "Survie";
    }
  }

  IconData _getSurvivorIcon(String rank) {
    switch (rank) {
      case 'A':
        return Icons.flashlight_on_rounded;
      case '2':
        return Icons.hardware_rounded;
      case '3':
        return Icons.medical_services_rounded;
      case '4':
        return Icons.carpenter_rounded;
      case '5':
        return Icons.gps_fixed_rounded;
      case '6':
        return Icons.shield_rounded;
      case '7':
        return Icons.cell_tower_rounded;
      case '8':
        return Icons.electric_bolt_rounded;
      default:
        return Icons.security_rounded;
    }
  }
}

// =============================================================================
// 📜 PAINTER : LIGNES DE FEUILLE DE CAHIER ET MARGE ROUGE
// =============================================================================
class _LinedParchmentPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    // 1. Marge rouge verticale à gauche
    final marginPaint =
        Paint()
          ..color = const Color(0xFFEF4444).withOpacity(0.28)
          ..strokeWidth = 1.2;
    canvas.drawLine(const Offset(22, 0), Offset(22, size.height), marginPaint);

    // 2. Lignes horizontales bleues pâles
    final linePaint =
        Paint()
          ..color = const Color(0xFF64748B).withOpacity(0.18)
          ..strokeWidth = 1.0;

    const double lineSpacing = 30.0;
    for (double y = 45; y < size.height; y += lineSpacing) {
      canvas.drawLine(Offset(0, y), Offset(size.width, y), linePaint);
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

// =============================================================================
// 🎭 ACTION OU VÉRITÉ - WIDGET DE JEU MULTIJOUEUR EN LIGNE
// =============================================================================

class ActionOuVeriteGameView extends StatefulWidget {
  final Map<String, dynamic> gameData;
  final String playerId;
  final String gameCode;
  final FirebaseService firebaseService;

  const ActionOuVeriteGameView({
    Key? key,
    required this.gameData,
    required this.playerId,
    required this.gameCode,
    required this.firebaseService,
  }) : super(key: key);

  @override
  State<ActionOuVeriteGameView> createState() => _ActionOuVeriteGameViewState();
}

class _ActionOuVeriteGameViewState extends State<ActionOuVeriteGameView>
    with SingleTickerProviderStateMixin {
  late AnimationController _wheelController;
  late Animation<double> _wheelAnimation;
  final TextEditingController _challengeInputController =
      TextEditingController();
  bool _isSubmitting = false;
  double _currentWheelAngle = 0.0;

  static const List<Color> _sliceColors = [
    Color(0xFFFF5722),
    Color(0xFF9C27B0),
    Color(0xFF2196F3),
    Color(0xFF4CAF50),
    Color(0xFFFFB300),
    Color(0xFFE91E63),
    Color(0xFF00BCD4),
    Color(0xFFFF9800),
    Color(0xFF3F51B5),
    Color(0xFF009688),
  ];

  @override
  void initState() {
    super.initState();
    _wheelController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2500),
    );
    _wheelAnimation = CurvedAnimation(
      parent: _wheelController,
      curve: Curves.easeOutCubic,
    );

    final currentIndex = widget.gameData['aoVCurrentPlayerIndex'] as int? ?? -1;
    final playerOrder = List<String>.from(
      widget.gameData['aoVPlayerOrder'] ?? [],
    );
    if (playerOrder.isNotEmpty && currentIndex >= 0) {
      final sweepAngle = (2 * pi) / playerOrder.length;
      _currentWheelAngle =
          -pi / 2 - (currentIndex * sweepAngle + sweepAngle / 2);
    }
  }

  @override
  void didUpdateWidget(covariant ActionOuVeriteGameView oldWidget) {
    super.didUpdateWidget(oldWidget);
    final oldIndex = oldWidget.gameData['aoVCurrentPlayerIndex'];
    final newIndex = widget.gameData['aoVCurrentPlayerIndex'];
    final newPhase = widget.gameData['aoVPhase'];

    if (newIndex != null && newIndex != oldIndex && newPhase == 'spin_result') {
      _spinToPlayer(newIndex as int);
    }
  }

  void _spinToPlayer(int targetIndex) {
    final playerOrder = List<String>.from(
      widget.gameData['aoVPlayerOrder'] ?? [],
    );
    if (playerOrder.isEmpty) return;

    final sweepAngle = (2 * pi) / playerOrder.length;
    final targetBase = -pi / 2 - (targetIndex * sweepAngle + sweepAngle / 2);
    final totalRotation =
        (4 * 2 * pi) + (targetBase - (_currentWheelAngle % (2 * pi)));

    final startAngle = _currentWheelAngle;
    final endAngle = _currentWheelAngle + totalRotation;

    _wheelController.reset();
    _wheelAnimation = Tween<double>(begin: startAngle, end: endAngle).animate(
      CurvedAnimation(parent: _wheelController, curve: Curves.easeOutCubic),
    )..addListener(() {
      setState(() {
        _currentWheelAngle = _wheelAnimation.value;
      });
    });

    HapticFeedback.mediumImpact();
    _wheelController.forward();
  }

  @override
  void dispose() {
    _wheelController.dispose();
    _challengeInputController.dispose();
    super.dispose();
  }

  Future<void> _handleSpinWheel() async {
    if (_isSubmitting) return;
    setState(() => _isSubmitting = true);
    try {
      HapticFeedback.lightImpact();
      await widget.firebaseService.aoVSpinWheel(
        widget.gameCode,
        widget.playerId,
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text("Erreur : $e")));
      }
    } finally {
      if (mounted) setState(() => _isSubmitting = false);
    }
  }

  Future<void> _handleDrawChallenge() async {
    if (_isSubmitting) return;
    setState(() => _isSubmitting = true);
    try {
      HapticFeedback.mediumImpact();
      await widget.firebaseService.aoVDrawChallengeType(
        widget.gameCode,
        widget.playerId,
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text("Erreur : $e")));
      }
    } finally {
      if (mounted) setState(() => _isSubmitting = false);
    }
  }

  Future<void> _handleSubmitWrittenChallenge() async {
    final text = _challengeInputController.text.trim();
    if (text.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text("Veuillez saisir un défi ou une question."),
        ),
      );
      return;
    }
    if (_isSubmitting) return;
    setState(() => _isSubmitting = true);
    try {
      HapticFeedback.mediumImpact();
      await widget.firebaseService.aoVSubmitWrittenChallenge(
        widget.gameCode,
        widget.playerId,
        text,
      );
      _challengeInputController.clear();
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text("Erreur : $e")));
      }
    } finally {
      if (mounted) setState(() => _isSubmitting = false);
    }
  }

  Future<void> _handleConfirmPerformed() async {
    if (_isSubmitting) return;
    setState(() => _isSubmitting = true);
    try {
      HapticFeedback.heavyImpact();
      await widget.firebaseService.aoVConfirmPerformed(
        widget.gameCode,
        widget.playerId,
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text("Erreur : $e")));
      }
    } finally {
      if (mounted) setState(() => _isSubmitting = false);
    }
  }

  Future<void> _handleVote(bool isValid) async {
    if (_isSubmitting) return;
    setState(() => _isSubmitting = true);
    try {
      HapticFeedback.mediumImpact();
      await widget.firebaseService.aoVSubmitVote(
        widget.gameCode,
        widget.playerId,
        isValid,
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text("Erreur de vote : $e")));
      }
    } finally {
      if (mounted) setState(() => _isSubmitting = false);
    }
  }

  Future<void> _handleNextTurn() async {
    if (_isSubmitting) return;
    setState(() => _isSubmitting = true);
    try {
      HapticFeedback.lightImpact();
      await widget.firebaseService.aoVNextTurn(
        widget.gameCode,
        widget.playerId,
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text("Erreur : $e")));
      }
    } finally {
      if (mounted) setState(() => _isSubmitting = false);
    }
  }

  Future<void> _handleEndRound() async {
    final confirm = await showDialog<bool>(
      context: context,
      builder:
          (ctx) => AlertDialog(
            title: const Text("Terminer la manche ?"),
            content: const Text(
              "Voulez-vous clôturer la manche immédiatement ? Le joueur avec le plus d'XP deviendra l'Admin.",
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: const Text("Annuler"),
              ),
              ElevatedButton(
                style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
                onPressed: () => Navigator.pop(ctx, true),
                child: const Text("Terminer"),
              ),
            ],
          ),
    );

    if (confirm == true) {
      await widget.firebaseService.aoVEndRound(
        widget.gameCode,
        widget.playerId,
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final gameData = widget.gameData;
    final players = Map<String, dynamic>.from(gameData['players'] ?? {});
    final playerOrder = List<String>.from(gameData['aoVPlayerOrder'] ?? []);
    final phase = gameData['aoVPhase'] ?? 'waiting_spin';
    final currentPlayerId = gameData['aoVCurrentPlayerId'];
    final currentPlayerName = players[currentPlayerId]?['name'] ?? 'Joueur';
    final isCurrentPlayer = (widget.playerId == currentPlayerId);
    final hostId = gameData['hostId'];
    final isHost = (widget.playerId == hostId);
    final int currentRound =
        (gameData['aoVCurrentRound'] as num?)?.toInt() ?? 1;
    final int spinsRemaining =
        (gameData['aoVSpinsRemaining'] as num?)?.toInt() ?? 10;
    final String? challengeType = gameData['aoVChallengeType'];
    final String? currentChallenge = gameData['aoVCurrentChallenge'];
    final String? challengeAuthor = gameData['aoVChallengeAuthor'];
    final authorName = players[challengeAuthor]?['name'] ?? 'Un joueur';
    final isAuthor = (widget.playerId == challengeAuthor);
    final votes = Map<String, dynamic>.from(gameData['aoVVotes'] ?? {});
    final votersCount = playerOrder.where((p) => p != currentPlayerId).length;
    final bool hasVoted = votes.containsKey(widget.playerId);

    return Scaffold(
      backgroundColor: Colors.transparent,
      body: SafeArea(
        child: Column(
          children: [
            // BARRE SUPÉRIEURE : Round, Tours restants, Bouton Admin
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
              child: Row(
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 12,
                      vertical: 6,
                    ),
                    decoration: BoxDecoration(
                      gradient: LinearGradient(
                        colors: [
                          Colors.deepPurple.shade700,
                          Colors.pink.shade600,
                        ],
                      ),
                      borderRadius: BorderRadius.circular(20),
                      boxShadow: [
                        BoxShadow(
                          color: Colors.pink.withOpacity(0.3),
                          blurRadius: 8,
                          offset: const Offset(0, 2),
                        ),
                      ],
                    ),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        const Icon(
                          Icons.flash_on,
                          color: Colors.amber,
                          size: 18,
                        ),
                        const SizedBox(width: 4),
                        Text(
                          "Tour $currentRound",
                          style: const TextStyle(
                            color: Colors.white,
                            fontWeight: FontWeight.bold,
                            fontSize: 13,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(width: 8),
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 10,
                      vertical: 6,
                    ),
                    decoration: BoxDecoration(
                      color: Colors.white.withOpacity(0.12),
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(color: Colors.white24),
                    ),
                    child: Text(
                      "$spinsRemaining tour${spinsRemaining > 1 ? 's' : ''} restant${spinsRemaining > 1 ? 's' : ''}",
                      style: const TextStyle(
                        color: Colors.white70,
                        fontSize: 12,
                        fontWeight: FontWeight.w500,
                      ),
                    ),
                  ),
                  const Spacer(),
                  if (isHost)
                    OutlinedButton.icon(
                      style: OutlinedButton.styleFrom(
                        foregroundColor: Colors.redAccent,
                        side: const BorderSide(color: Colors.redAccent),
                        padding: const EdgeInsets.symmetric(
                          horizontal: 10,
                          vertical: 4,
                        ),
                        visualDensity: VisualDensity.compact,
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(16),
                        ),
                      ),
                      icon: const Icon(Icons.flag, size: 14),
                      label: const Text(
                        "Fin manche",
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      onPressed: _handleEndRound,
                    ),
                ],
              ),
            ),

            // LISTE HORIZONTALE DES JOUEURS AVEC XP
            SizedBox(
              height: 72,
              child: ListView.builder(
                scrollDirection: Axis.horizontal,
                padding: const EdgeInsets.symmetric(horizontal: 12),
                itemCount: playerOrder.length,
                itemBuilder: (context, index) {
                  final pId = playerOrder[index];
                  final pData = players[pId] ?? {};
                  final pName = pData['name'] ?? 'Joueur';
                  final pXp = (pData['xp'] as num?)?.toInt() ?? 0;
                  final isSelected = (pId == currentPlayerId);

                  return AnimatedContainer(
                    duration: const Duration(milliseconds: 300),
                    margin: const EdgeInsets.symmetric(
